{ 'Blizzard_SharedXMLBase\\FunctionUtil.lua', [[
function ExecuteFrameScript(frame, scriptName, ...)
	local script = frame:GetScript(scriptName);
	if script then
		xpcall(script, CallErrorHandler, frame, ...);
	end
end

function CallMethodOnNearestAncestor(self, methodName, ...)
	local ancestor = self:GetParent();
	while ancestor and not ancestor[methodName] do
		ancestor = ancestor:GetParent();
	end

	if ancestor then
		return true, ancestor[methodName](ancestor, ...);
	end

	return false;
end

function GetValueOrCallFunction(tbl, key, ...)
	if not tbl then
		return;
	end

	local value = tbl[key];
	if type(value) == "function" then
		return value(...);
	else
		return value;
	end
end

local function CompositeIterator(iteratorCallbackArray)
	if #iteratorCallbackArray == 0 then
		return nop;
	end

	local iteratorIndex = 1;
	local currentIterator, currentTable, iteratorKey = iteratorCallbackArray[1]();
	local function AdvanceIterators()
		if currentIterator == nil then
			return nil;
		end

		local nextKey = currentIterator(currentTable, iteratorKey);
		if nextKey ~= nil then
			iteratorKey = nextKey;
			return nextKey;
		end

		if iteratorIndex < #iteratorCallbackArray then
			iteratorIndex = iteratorIndex + 1;
			currentIterator, currentTable, iteratorKey = iteratorCallbackArray[iteratorIndex]();
			return AdvanceIterators();
		end

		currentIterator = nil;
		return nil;
	end

	return AdvanceIterators;
end

function IteratePools(...)
	local callbackArray = {};
	for i = 1, select("#", ...) do
		local pool = select(i, ...);
		table.insert(callbackArray, GenerateClosure(pool.EnumerateActive, pool));
	end

	return CompositeIterator(callbackArray);
end

function IterateTables(iteratorFunction, ...)
	local callbackArray = {};
	for i = 1, select("#", ...) do
		local tbl = select(i, ...);
		table.insert(callbackArray, GenerateClosure(iteratorFunction, tbl));
	end

	return CompositeIterator(callbackArray);
end

local s_passThroughClosureGenerators = {
	function(f) return function(...) return f(...); end; end,
	function(f, a) return function(...) return f(a, ...); end; end,
	function(f, a, b) return function(...) return f(a, b, ...); end; end,
	function(f, a, b, c) return function(...) return f(a, b, c, ...); end; end,
	function(f, a, b, c, d) return function(...) return f(a, b, c, d, ...); end; end,
	function(f, a, b, c, d, e) return function(...) return f(a, b, c, d, e, ...); end; end,
};

local s_flatClosureGenerators = {
	function(f) return function() return f(); end; end,
	function(f, a) return function() return f(a); end; end,
	function(f, a, b) return function() return f(a, b); end; end,
	function(f, a, b, c) return function() return f(a, b, c); end; end,
	function(f, a, b, c, d) return function() return f(a, b, c, d); end; end,
	function(f, a, b, c, d, e) return function() return f(a, b, c, d, e); end; end,
};

local function GenerateClosureInternal(generatorArray, f, ...)
	local count = select("#", ...);
	local generator = generatorArray[count + 1];
	if generator then
		return generator(f, ...);
	end

	assertsafe("Closure generation does not support more than " .. (#generatorArray - 1) .. " parameters");
	return nil;
end

-- Syntactic sugar for function(...) return f(a, b, c, ...); end
function GenerateClosure(f, ...)
	return GenerateClosureInternal(s_passThroughClosureGenerators, f, ...);
end

-- Generates a closure with the specified arguments that will ignore extra arguments when called later. Useful for passing
-- through callbacks to APIs where we don't want extra arguments to be passed through, i.e. simple OnClick scripts.
-- This is equivalent to: function() return f(a, b, c); end INSTEAD OF function(...) return f(a, b, c, ...); end
function GenerateFlatClosure(f, ...)
	return GenerateClosureInternal(s_flatClosureGenerators, f, ...);
end

function RunNextFrame(callback)
	C_Timer.After(0, callback);
end

FunctionUtil = {};

function FunctionUtil.CheckInvokeMethod(table, methodName, ...)
	if table then
		return table[methodName](table, ...);
	end

	return nil;
end

function FunctionUtil.SafeInvokeMethod(table, methodName, ...)
	local method = table[methodName];
	if method then
		return method(table, ...);
	end

	return nil;
end
]] },
{ 'Blizzard_SharedXMLBase\\ObjectUpdater.lua', [[

local States = EnumUtil.MakeEnum("Ready", "Begin", "Update", "End");

local ObjectUpdaterMixin = {};
function ObjectUpdaterMixin:Init(data, updateFunc, isCompleteFunc, finishFunc)
	self.data = data;
	self:SetUpdateFunction(updateFunc);
	self:SetIsCompleteFunction(isCompleteFunc);
	self:SetFinishFunction(finishFunc);
	self.state = States.Begin;
	self.ticker = C_Timer.NewTicker(0.01, GenerateClosure(self.Advance, self));
end

function ObjectUpdaterMixin:SetUpdateFunction(updateFunc)
	self.updateFunc = updateFunc;
end

function ObjectUpdaterMixin:SetIsCompleteFunction(isCompleteFunc)
	self.isCompleteFunc = isCompleteFunc;
end

function ObjectUpdaterMixin:SetFinishFunction(finishFunc)
	self.finishFunc = finishFunc;
end

function ObjectUpdaterMixin:Cancel()
	self.ticker:Cancel();
	self.state = States.Ready;
end

function ObjectUpdaterMixin:Finished()
	self:Cancel();
	if self.finishFunc then
		self.finishFunc(self.data);	
	end
end

function ObjectUpdaterMixin:Advance()
	if self.state == States.Begin then
		if self.isCompleteFunc(self.data) then
			self.state = States.End;
		else
			self.state = States.Update;
		end
	elseif self.state == States.Update then
		self.updateFunc(self.data);
		if self.isCompleteFunc(self.data) then
			self.state = States.End;
		end
	elseif self.state == States.End then
		self:Finished();		
		return;
	end
end

function CreateObjectUpdater(data, updateFunc, isCompleteFunc, finishFunc)
	return CreateAndInitFromMixin(ObjectUpdaterMixin, data, updateFunc, isCompleteFunc, finishFunc);
end]] },
{ 'Blizzard_SharedXMLBase\\MathUtil.lua', [[

MathUtil = 
{
	Epsilon = .000001,
};

MathUtil.ApproxZero = MathUtil.Epsilon;
MathUtil.ApproxOne = 1.0 - MathUtil.Epsilon;

local securecallfunction = securecallfunction;
function CreateCounter(initialCount, step)
	local count = initialCount or 0;
	step = step or 1;
	local counter = function()
		count = count + step;
		return count;
	end;
    return function()
        return securecallfunction(counter);
    end;
end

function Lerp(startValue, endValue, amount)
	return (1 - amount) * startValue + amount * endValue;
end

function Clamp(value, min, max)
	if value > max then
		return max;
	elseif value < min then
		return min;
	end
	return value;
end

function Saturate(value)
	return Clamp(value, 0.0, 1.0);
end

function Wrap(value, max)
	return (value - 1) % max + 1;
end

function ClampDegrees(value)
	return ClampMod(value, 360);
end

function ClampMod(value, mod)
	return ((value % mod) + mod) % mod;
end

function NegateIf(value, condition)
	return condition and -value or value;
end

function PercentageBetween(value, startValue, endValue)
	if startValue == endValue then
		return 0.0;
	end
	return (value - startValue) / (endValue - startValue);
end

function ClampedPercentageBetween(value, startValue, endValue)
	return Saturate(PercentageBetween(value, startValue, endValue));
end

local TARGET_FRAME_PER_SEC = 60.0;
function DeltaLerp(startValue, endValue, amount, timeSec)
	return Lerp(startValue, endValue, Saturate(amount * timeSec * TARGET_FRAME_PER_SEC));
end

function FrameDeltaLerp(startValue, endValue, amount)
	return DeltaLerp(startValue, endValue, amount, GetTickTime());
end

function RandomFloatInRange(minValue, maxValue)
	return Lerp(minValue, maxValue, math.random());
end

function Round(value)
	if value < 0.0 then
		return math.ceil(value - .5);
	end
	return math.floor(value + .5);
end

function RoundToSignificantDigits(value, numDigits)
	local multiplier = 10 ^ numDigits;
	return Round(value * multiplier) / multiplier;
end

-- Rounds the value to to the closest multiple of the passed multiplier
-- Ex: (55, 50) => 50, (85, 50) => 100
function RoundToNearestMultiple(value, multiplier)
	return Round(value / multiplier) * multiplier;
end

function Square(value)
	return value * value;
end

function Sign(value)
	return value > 0 and 1 or (value == 0 and 0 or -1);
end

function WithinRange(value, min, max)
	return value >= min and value <= max;
end

function WithinRangeExclusive(value, min, max)
	return value > min and value < max;
end

function ApproximatelyEqual(v1, v2, epsilon)
	return math.abs(v1 - v2) < (epsilon or MathUtil.Epsilon);
end

function CalculateDistanceSq(x1, y1, x2, y2)
	local dx = x2 - x1;
	local dy = y2 - y1;
	return (dx * dx) + (dy * dy);
end

function CalculateDistance(x1, y1, x2, y2)
	return math.sqrt(CalculateDistanceSq(x1, y1, x2, y2));
end

function CalculateAngleBetween(x1, y1, x2, y2)
	return math.atan2(y2 - y1, x2 - x1);
end

AccumulatorMixin = {};

function AccumulatorMixin:Init(initialCount)
	self.count = initialCount or 0;
end

function AccumulatorMixin:Add(count)
	self.count = self.count + count;
	return self.count;
end

function AccumulatorMixin:Subtract(count)
	self.count = self.count - count;
	return self.count;
end

function AccumulatorMixin:Count()
	return self.count;
end

function AccumulatorMixin:Reset(resetCount)
	self.count = resetCount or 0;
end

function CreateAccumulator(initialCount)
	return CreateAndInitFromMixin(AccumulatorMixin, initialCount);
end
]] },
{ 'Blizzard_SharedXMLBase\\ExportUtil.lua', [[

-- Utility for compressing and uncompressing data into strings for export and import.

ExportUtil = {};

local BitsPerChar = 6;

local function MakeBase64ConversionTable()
	local base64ConversionTable = {};
	base64ConversionTable[0] = 'A';
	for num = 1, 25 do
		table.insert(base64ConversionTable, string.char(65 + num));
	end

	for num = 0, 25 do
		table.insert(base64ConversionTable, string.char(97 + num));
	end

	for num = 0, 9 do
		table.insert(base64ConversionTable, tostring(num));
	end

	table.insert(base64ConversionTable, '+');
	table.insert(base64ConversionTable, '/');
	return base64ConversionTable;
end

local NumberToBase64CharConversionTable = MakeBase64ConversionTable();
local Base64CharToNumberConversionTable = tInvert(MakeBase64ConversionTable());

function ExportUtil.ConvertToBase64(dataEntries)
	local exportString = "";
	local currentValue = 0;
	local currentReservedBits = 0;
	local totalBits = 0;
	for i, dataEntry in ipairs(dataEntries) do
		local remainingValue = dataEntry.value;
		local remainingRequiredBits = dataEntry.bitWidth;
		-- TODO: bit.lshift doesnt work with > 32 bits.  Maybe use maxValue = 2^X instead?
		local maxValue = bit.lshift(1, remainingRequiredBits);
		if remainingValue >= maxValue then
			error(("Data entry has higher value than storable in bitWidth. (%d in %d bits)"):format(remainingValue, remainingRequiredBits));
			return "";
		end

		totalBits = totalBits + remainingRequiredBits;
		while remainingRequiredBits > 0 do
			local spaceInCurrentValue = (BitsPerChar - currentReservedBits);
			local maxStorableValue = bit.lshift(1, spaceInCurrentValue);
			local remainder = remainingValue % maxStorableValue;
			remainingValue = bit.rshift(remainingValue, spaceInCurrentValue);
			currentValue = currentValue + bit.lshift(remainder, currentReservedBits);

			if spaceInCurrentValue > remainingRequiredBits then
				currentReservedBits = (currentReservedBits + remainingRequiredBits) % BitsPerChar;
				remainingRequiredBits = 0;
			else
				exportString = exportString..NumberToBase64CharConversionTable[currentValue];
				currentValue = 0;
				currentReservedBits = 0;
				remainingRequiredBits = remainingRequiredBits - spaceInCurrentValue;
			end
		end
	end

	if currentReservedBits > 0 then
		exportString = exportString..NumberToBase64CharConversionTable[currentValue];
	end

	return exportString;
end

function ExportUtil.ConvertFromBase64(exportString)
	local dataValues = {};
	for i = 1, #exportString do
		table.insert(dataValues, Base64CharToNumberConversionTable[string.sub(exportString, i, i)]);
	end

	return dataValues;
end

function ExportUtil.MakeExportDataStream()
	return CreateAndInitFromMixin(ExportDataStreamMixin);
end

function ExportUtil.MakeImportDataStream(exportString)
	return CreateAndInitFromMixin(ImportDataStreamMixin, exportString);
end


ExportDataStreamMixin = {};

function ExportDataStreamMixin:Init()
	self.dataEntries = {};
end

function ExportDataStreamMixin:AddValue(bitWidth, value)
	table.insert(self.dataEntries, { bitWidth = bitWidth, value = value, });
end

function ExportDataStreamMixin:GetExportString()
	return ExportUtil.ConvertToBase64(self.dataEntries);
end

ImportDataStreamMixin = {};

function ImportDataStreamMixin:Init(exportString)
	self.dataValues = ExportUtil.ConvertFromBase64(exportString);
	self.currentIndex = 1;
	self.currentExtractedBits = 0;
	self.currentRemainingValue = self.dataValues[1];
end

function ImportDataStreamMixin:ExtractValue(bitWidth)
	if self.currentIndex > #self.dataValues then
		return nil;
	end

	local value = 0;
	local bitsNeeded = bitWidth;
	local extractedBits = 0;
	while bitsNeeded > 0 do
		local remainingBits = BitsPerChar - self.currentExtractedBits;
		local bitsToExtract = math.min(remainingBits, bitsNeeded);
		self.currentExtractedBits = self.currentExtractedBits + bitsToExtract;
		local maxStorableValue = bit.lshift(1, bitsToExtract);
		local remainder = self.currentRemainingValue % maxStorableValue;
		self.currentRemainingValue = bit.rshift(self.currentRemainingValue, bitsToExtract);
		value = value + bit.lshift(remainder, extractedBits);
		extractedBits = extractedBits + bitsToExtract;
		bitsNeeded = bitsNeeded - bitsToExtract;

		if bitsToExtract < remainingBits then
			break;
		elseif bitsToExtract >= remainingBits then
			self.currentIndex = self.currentIndex + 1;
			self.currentExtractedBits = 0;
			self.currentRemainingValue = self.dataValues[self.currentIndex];
		end
	end

	return value;
end

function ImportDataStreamMixin:GetNumberOfBits()
	return BitsPerChar * getn(self.dataValues);
end

]] },
{ 'Blizzard_SharedXMLBase\\Rectangle.lua', [[
RectangleMixin = {};

function CreateRectangle(left, right, top, bottom)
	local rectangle = CreateFromMixins(RectangleMixin);
	rectangle:OnLoad(left, right, top,  bottom);
	return rectangle;
end

function RectangleMixin:OnLoad(left, right, top, bottom)
	self:SetSides(left or 0.0, right or 0.0, top or 0.0, bottom or 0.0);
end

function RectangleMixin:SetSides(left, right, top, bottom)
	self.left = left;
	self.right = right;
	self.top = top;
	self.bottom = bottom;
end

function RectangleMixin:Reset()
	self.left = 0.0;
	self.right = 0.0;
	self.top = 0.0;
	self.bottom = 0.0;
end

function RectangleMixin:Stretch(x, y)
	self:Adjust(-x, x, -y, y);
end

function RectangleMixin:Move(x, y)
	self:Adjust(x, x, y, y);
end

function RectangleMixin:Adjust(left, right, top, bottom)
	self.left = self.left + left;
	self.right = self.right + right;
	self.top = self.top + top;
	self.bottom = self.bottom + bottom;
end

function RectangleMixin:IsEmpty()
	return self.left == self.right or self.top == self.bottom;
end

function RectangleMixin:IsInsideOut()
	return self.left > self.right or self.top > self.bottom;
end

function RectangleMixin:EnclosesPoint(x, y)
	return x >= self.left and x <= self.right and y >= self.top and y <= self.bottom;
end

function RectangleMixin:EnclosesRect(otherRect)
	return self:EnclosesPoint(otherRect:GetLeft(), otherRect:GetTop()) and self:EnclosesPoint(otherRect:GetRight(), otherRect:GetBottom());
end

function RectangleMixin:IntersectsRect(otherRect)
	return not (
		self.left > otherRect.right or
		self.right < otherRect.left or
		self.top > otherRect.bottom or
		self.bottom < otherRect.top
	);
end

function RectangleMixin:GetTop()
	return self.top;
end

function RectangleMixin:GetBottom()
	return self.bottom;
end

function RectangleMixin:GetLeft()
	return self.left;
end

function RectangleMixin:GetRight()
	return self.right;
end

function RectangleMixin:GetWidth()
	return self.right - self.left;
end

function RectangleMixin:GetHeight()
	return self.bottom - self.top;
end

function RectangleMixin:GetCenter()
	return Lerp(self.left, self.right, .5), Lerp(self.top, self.bottom, .5);
end

function RectangleMixin:GetCenterH()
	return Lerp(self.left, self.right, .5);
end

function RectangleMixin:GetCenterV()
	return Lerp(self.top, self.bottom, .5);
end

function RectangleMixin:SetTop(top)
	self.top = top;
end

function RectangleMixin:SetBottom(bottom)
	self.bottom = bottom;
end

function RectangleMixin:SetLeft(left)
	self.left = left;
end

function RectangleMixin:SetRight(right)
	self.right = right;
end

function RectangleMixin:SetWidth(width)
	self.right = self.left + width;
end

function RectangleMixin:SetHeight(height)
	self.bottom = self.top + height;
end

function RectangleMixin:SetSize(width, height)
	self:SetWidth(width);
	self:SetHeight(height);
end

function RectangleMixin:SetCenter(x, y)
	local width = self:GetWidth();
	local height = self:GetHeight();

	self.left = x - width * .5;
	self.right = x + width * .5;

	self.top = y - height * .5;
	self.bottom = y + height * .5;
end]] },
{ 'Blizzard_SharedXMLBase\\TextureUtil.lua', [=[
TextureUtil = {};

function GetTextureInfo(obj)
	if obj:GetObjectType() == "Texture" then
		local assetName = obj:GetAtlas();
		local assetType = "Atlas";

		if not assetName then
			assetName = obj:GetTextureFilePath();
			assetType = "File";
		end

		if not assetName then
			assetName = obj:GetTextureFileID();
			assetType = "FileID";
		end

		if not assetName then
			assetName = "UnknownAsset";
			assetType = "Unknown";
		end

		local ulX, ulY, blX, blY, urX, urY, brX, brY = obj:GetTexCoord();
		return assetName, assetType, ulX, ulY, blX, blY, urX, urY, brX, brY;
	end
end

function SetClampedTextureRotation(texture, rotationDegrees)
	if (rotationDegrees ~= 0 and rotationDegrees ~= 90 and rotationDegrees ~= 180 and rotationDegrees ~= 270) then
		error("SetRotation: rotationDegrees must be 0, 90, 180, or 270");
		return;
	end

	if not (texture.rotationDegrees) then
		texture.origTexCoords = {texture:GetTexCoord()};
		texture.origWidth = texture:GetWidth();
		texture.origHeight = texture:GetHeight();
	end

	if (texture.rotationDegrees == rotationDegrees) then
		return;
	end

	texture.rotationDegrees = rotationDegrees;

	if (rotationDegrees == 0 or rotationDegrees == 180) then
		texture:SetWidth(texture.origWidth);
		texture:SetHeight(texture.origHeight);
	else
		texture:SetWidth(texture.origHeight);
		texture:SetHeight(texture.origWidth);
	end

	if (rotationDegrees == 0) then
		texture:SetTexCoord( texture.origTexCoords[1], texture.origTexCoords[2],
											texture.origTexCoords[3], texture.origTexCoords[4],
											texture.origTexCoords[5], texture.origTexCoords[6],
											texture.origTexCoords[7], texture.origTexCoords[8] );
	elseif (rotationDegrees == 90) then
		texture:SetTexCoord( texture.origTexCoords[3], texture.origTexCoords[4],
											texture.origTexCoords[7], texture.origTexCoords[8],
											texture.origTexCoords[1], texture.origTexCoords[2],
											texture.origTexCoords[5], texture.origTexCoords[6] );
	elseif (rotationDegrees == 180) then
		texture:SetTexCoord( texture.origTexCoords[7], texture.origTexCoords[8],
											texture.origTexCoords[5], texture.origTexCoords[6],
											texture.origTexCoords[3], texture.origTexCoords[4],
											texture.origTexCoords[1], texture.origTexCoords[2] );
	elseif (rotationDegrees == 270) then
		texture:SetTexCoord( texture.origTexCoords[5], texture.origTexCoords[6],
											texture.origTexCoords[1], texture.origTexCoords[2],
											texture.origTexCoords[7], texture.origTexCoords[8],
											texture.origTexCoords[3], texture.origTexCoords[4] );
	end
end

function ClearClampedTextureRotation(texture)
	if (texture.rotationDegrees) then
		SetClampedTextureRotation(texture, 0);
		texture.origTexCoords = nil;
		texture.origWidth = nil;
		texture.origHeight = nil;
	end
end

local LFGRoleEnumToString = {
	[Enum.LFGRole.Tank] = "TANK",
	[Enum.LFGRole.Healer] = "HEALER",
	[Enum.LFGRole.Damage] = "DAMAGER",
	[Constants.LFG_ROLEConstants.LFG_ROLE_NO_ROLE] = "GUIDE",
};

local LFGRoleIcons = {
	["GUIDE"] = "UI-LFG-RoleIcon-Leader",
	["TANK"] = "UI-LFG-RoleIcon-Tank",
	["HEALER"] = "UI-LFG-RoleIcon-Healer",
	["DAMAGER"] = "UI-LFG-RoleIcon-DPS",
	["NONE"] = "UI-LFG-RoleIcon-DPS",
};

local DisabledLFGRoleIcons = {
	["GUIDE"] = "UI-LFG-RoleIcon-Leader-Disabled",
	["TANK"] = "UI-LFG-RoleIcon-Tank-Disabled",
	["HEALER"] = "UI-LFG-RoleIcon-Healer-Disabled",
	["DAMAGER"] = "UI-LFG-RoleIcon-DPS-Disabled",
	["NONE"] = "UI-LFG-RoleIcon-DPS-Disabled",
};

function GetIconForRole(role, showDisabled)
	if LFGRoleIcons[role] == nil or DisabledLFGRoleIcons[role] == nil then
		error("Unknown role: " .. tostring(role));
		return;
	end

	return showDisabled and DisabledLFGRoleIcons[role] or LFGRoleIcons[role];
end

function GetIconForRoleEnum(role, showDisabled)
	if not LFGRoleEnumToString[role] then
		assertsafe(false, "Unknown role: " .. tostring(role));
		return;
	end

	return GetIconForRole(LFGRoleEnumToString[role], showDisabled);
end

local SmallLFGRoleIcons = {
	["GUIDE"] = "UI-LFG-RoleIcon-Leader-Micro",
	["TANK"] = "UI-LFG-RoleIcon-Tank-Micro",
	["HEALER"] = "UI-LFG-RoleIcon-Healer-Micro",
	["DAMAGER"] = "UI-LFG-RoleIcon-DPS-Micro",
	["NONE"] = "UI-LFG-RoleIcon-DPS-Micro",
};

function TextureUtil.GetSmallIconForRole(role)
	if not SmallLFGRoleIcons[role] then
		error("Unknown role: " .. tostring(role));
		return;
	end

	return SmallLFGRoleIcons[role];
end

function TextureUtil.GetSmallIconForRoleEnum(role)
	if not LFGRoleEnumToString[role] then
		assertsafe(false, "Unknown role: " .. tostring(role));
		return;
	end

	return TextureUtil.GetSmallIconForRole(LFGRoleEnumToString[role]);
end

local MicroLFGRoleIcons = {
