		[GameRulesUtil.QueueStatusModeKey.TeleportInText] = QUEUE_STATUS_WOWHACK_TELEPORT_IN,
		[GameRulesUtil.QueueStatusModeKey.LeaveText] = QUEUE_STATUS_WOWHACK_LEAVE,
		[GameRulesUtil.QueueStatusModeKey.OverrideLFGLabelText] = "",
		[GameRulesUtil.QueueStatusModeKey.OverrideLFGNumEncounters] = 0,
	},
};

GameRulesUtil.GameModeToAccountStore = {
	[Enum.GameMode.Plunderstorm] = Constants.AccountStoreConsts.PlunderstormStoreFrontID,
	[Enum.GameMode.WoWHack] = Constants.AccountStoreConsts.WowhackStoreFrontID,
};

function GameRulesUtil.ShouldShowPlayerCastBar()
	return not C_GameRules.IsGameRuleActive(Enum.GameRule.PlayerCastBarDisabled);
end

function GameRulesUtil.ShouldShowTargetCastBar()
	return GetCVar("showTargetCastbar") and not C_GameRules.IsGameRuleActive(Enum.GameRule.TargetCastBarDisabled);
end

function GameRulesUtil.ShouldShowNamePlateCastBar()
	return GetCVarBool("nameplateShowCastBars") and not C_GameRules.IsGameRuleActive(Enum.GameRule.NameplateCastBarDisabled);
end

function GameRulesUtil.ShouldShowAddOns()
	if C_AddOns.GetNumAddOns() <= 0 then
		return false;
	end

	if IsTestBuild() then
		return true;
	end

	return not C_GameRules.IsGameRuleActive(Enum.GameRule.UserAddonsDisabled);
end

function GameRulesUtil.ShouldShowSplashScreen()
	if not C_GameRules.IsStandard() then
		return false;
	end

	return C_SplashScreen and C_SplashScreen.CanViewSplashScreen() and not IsCharacterNewlyBoosted();
end

function GameRulesUtil.EJIsDisabled()
	if C_GameRules.IsGameRuleActive(Enum.GameRule.EncounterJournalDisabled) then
		return true;
	end

	-- At least one tab needs to be active for the Encounter Journal to be enabled.
	local tabFunctions = {
		GameRulesUtil.EJShouldShowJourneys,
		GameRulesUtil.EJShouldShowTravelersLog,
		GameRulesUtil.EJShouldShowSuggestedContent,
		GameRulesUtil.EJShouldShowDungeons,
		GameRulesUtil.EJShouldShowRaids,
		GameRulesUtil.EJShouldShowItemSets,
	};

	for _, func in ipairs(tabFunctions) do
		if func() then
			return false;
		end
	end

	return true;
end

function GameRulesUtil.EJShouldShowJourneys()
	return not C_GameRules.IsGameRuleActive(Enum.GameRule.EjJourneysDisabled);
end

function GameRulesUtil.EJShouldShowTravelersLog()
	return C_PlayerInfo.IsTradingPostAvailable();
end

function GameRulesUtil.EJShouldShowSuggestedContent()
	if PlayerIsTimerunning() then
		return false;
	end

	return not C_GameRules.IsGameRuleActive(Enum.GameRule.EjSuggestedContentDisabled);
end

function GameRulesUtil.EJShouldShowDungeons()
	return not C_GameRules.IsGameRuleActive(Enum.GameRule.EjDungeonsDisabled);
end

function GameRulesUtil.EJShouldShowRaids()
	return not C_GameRules.IsGameRuleActive(Enum.GameRule.EjRaidsDisabled);
end

function GameRulesUtil.EJShouldShowItemSets()
	return not C_GameRules.IsGameRuleActive(Enum.GameRule.EjItemSetsDisabled);
end

function GameRulesUtil.EJShouldShowTutorials()
	return C_PlayerInfo.IsTutorialsTabAvailable();
end

function GameRulesUtil.CanShowExperienceBar()
	return not IsPlayerAtEffectiveMaxLevel() and not IsXPUserDisabled() and not C_GameRules.IsGameRuleActive(Enum.GameRule.ExperienceBarDisabled);
end

function GameRulesUtil.GetActionButtonTypeOverlayStrategy()
	if not C_GameRules.IsGameRuleActive(Enum.GameRule.ActionButtonTypeOverlayStrategy) then
		return GameRulesUtil.ActionButtonTypeOverlayStrategy.None;
	end

	return C_GameRules.GetGameRuleAsFloat(Enum.GameRule.ActionButtonTypeOverlayStrategy);
end

function GameRulesUtil.AllowBelowMinimumActionBarIcons()
	local activeGameMode = C_GameRules.GetActiveGameMode();
	return (activeGameMode == Enum.GameMode.Plunderstorm) or (activeGameMode == Enum.GameMode.WoWHack);
end

function GameRulesUtil.GetQueueStatusModeInfo()
	local activeGameMode = C_GameRules.GetActiveGameMode();
	return GameRulesUtil.QueueStatusModeInfo[activeGameMode] or GameRulesUtil.QueueStatusModeInfo[Enum.GameMode.Standard];
end

function GameRulesUtil.GetQueueStatusInfo(key)
	local modeInfo = GameRulesUtil.GetQueueStatusModeInfo();
	return modeInfo[key];
end

function GameRulesUtil.GetOverrideLFGCategoryName(category)
	local titleOrCategoryCallback = GameRulesUtil.GetQueueStatusInfo(GameRulesUtil.QueueStatusModeKey.TitleOrCategoryCallback);
	if type(titleOrCategoryCallback) == "function" then
		return titleOrCategoryCallback(category);
	end

	return titleOrCategoryCallback;
end

function GameRulesUtil.GetActiveAccountStore()
	local activeGameMode = C_GameRules.GetActiveGameMode();
	return GameRulesUtil.GameModeToAccountStore[activeGameMode];
end

-- System callbacks can be registered here to be called when game rules change.
local registeredSystemCallbacks = {};
function GameRulesUtil.RegisterSystemCallback(systemCallback)
	table.insert(registeredSystemCallbacks, systemCallback);
end

-- As of adding this comment, game rules are only updated when the active game mode changes.
function GameRulesUtil.OnActiveGameModeUpdated()
	for _, systemCallback in ipairs(registeredSystemCallbacks) do
		systemCallback();
	end
end

function GameRulesUtil.GetEffectiveMaxLevelForPlayer()
	-- Timerunners levels can go above the purchased max level to the max current expansion level
	local maxLevelForExpansion = (PlayerIsTimerunning() and not IsTrialAccount()) and GetMaxLevelForLatestExpansion() or GetMaxLevelForPlayerExpansion();
	local maxPlayerLevel = GetMaxPlayerLevel(); -- In case this particular player's max level is capped for some reason. (This is how Classic pre-patches work.)
	return math.min(maxLevelForExpansion, maxPlayerLevel);
end

EventRegistry:RegisterFrameEventAndCallback("ACTIVE_GAME_MODE_UPDATED", GameRulesUtil.OnActiveGameModeUpdated, GameRulesUtil);
]] },
{ 'Blizzard_SharedXML\\TabGroup.lua', [[
TabGroupMixin = {};

function TabGroupMixin:OnLoad(...)
	self.isTabGroup = true;
	self.frames = { ... };
end

function TabGroupMixin:AddFrame(frame)
	table.insert(self.frames, frame);
end

function TabGroupMixin:HasFocus()
	return self:GetFocusIndex() ~= nil;
end

function TabGroupMixin:SetFocus()
	-- focusing the first frame/subgroup for now...actually depends on whether or not we were going backwards or forwards through the groups
	local frame = self.frames[1];
	if frame then
		frame:SetFocus();
	end
end

function TabGroupMixin:GetFocusIndex()
	return self.focusIndex or self:DiscoverFocusIndex();
end

function TabGroupMixin:DiscoverFocusIndex()
	self.focusIndex = nil;

	for focusIndex, frame in ipairs(self.frames) do
		if frame:HasFocus() then
			self.focusIndex = focusIndex;
			return focusIndex;
		end
	end
end

function TabGroupMixin:IsValidFocusIndex(focusIndex)
	return focusIndex > 0 and focusIndex <= #self.frames;
end

function TabGroupMixin:WrapFocusIndex(focusIndex)
	if focusIndex == 0 then
		return #self.frames;
	elseif focusIndex > #self.frames then
		return 1;
	end

	return focusIndex;
end

function TabGroupMixin:OnTabPressed(preventFocusWrap)
	local focusIndex = self:GetFocusIndex();

	local frameAtIndex = self.frames[focusIndex];
	if frameAtIndex.isTabGroup then
		if frameAtIndex:OnTabPressed(true) then
			return true;
		end
	end

	local nextFocusIndex = IsShiftKeyDown() and (focusIndex - 1) or (focusIndex + 1);

	if preventFocusWrap and not self:IsValidFocusIndex(nextFocusIndex) then
		return false;
	end

	nextFocusIndex = Wrap(nextFocusIndex, #self.frames);
	self.focusIndex = nextFocusIndex;
	self.frames[nextFocusIndex]:SetFocus();
end

function CreateTabGroup(...)
	local tabGroup = CreateFromMixins(TabGroupMixin);
	tabGroup:OnLoad(...);
	return tabGroup;
end]] },
{ 'Blizzard_SharedXML\\SmoothStatusBar.lua', [[
local g_updatingBars = {};

local function IsCloseEnough(bar, newValue, targetValue)
	local min, max = bar:GetMinMaxValues();
	local range = max - min;
	if range > 0.0 then
		return math.abs((newValue - targetValue) / range) < .00001;
	end

	return true;
end

local function ProcessSmoothStatusBars()
	for bar, targetValue in pairs(g_updatingBars) do
		local effectiveTargetValue = Clamp(targetValue, bar:GetMinMaxValues());
		local newValue = FrameDeltaLerp(bar:GetValue(), effectiveTargetValue, .25);

		if IsCloseEnough(bar, newValue, effectiveTargetValue) then
			g_updatingBars[bar] = nil;
			bar:SetValue(effectiveTargetValue);
		else
			bar:SetValue(newValue);
		end
	end
end

C_Timer.NewTicker(0, ProcessSmoothStatusBars);

SmoothStatusBarMixin = {};

function SmoothStatusBarMixin:ResetSmoothedValue(value) --If nil, tries to set to the last target value
	local targetValue = g_updatingBars[self];
	if targetValue then
		g_updatingBars[self] = nil;
		self:SetValue(value or targetValue);
	elseif value then
		self:SetValue(value);
	end
end

function SmoothStatusBarMixin:SetSmoothedValue(value)
	g_updatingBars[self] = value;
end

function SmoothStatusBarMixin:SetMinMaxSmoothedValue(min, max)
	self:SetMinMaxValues(min, max);

	local targetValue = g_updatingBars[self];
	if targetValue then
		local ratio = 1;
		if max ~= 0 and self.lastSmoothedMax and self.lastSmoothedMax ~= 0 then
			ratio = max / self.lastSmoothedMax;
		end

		g_updatingBars[self] = targetValue * ratio;
	end

	self.lastSmoothedMin = min;
	self.lastSmoothedMax = max;
end]] },
{ 'Blizzard_SharedXML\\PredictedSetting.lua', [[
PredictedSettingBaseMixin = {};

-- The wrapTable here should have functions to specific keys based on which type of setting you are wrapping.
-- All tables must have a getFunction key that returns the "real" value.
-- The PredictedSetting wrapTable should have a setFunction key with a function that takes a value and sets the real value to this value.
--   This function can return a true/false value noting if the set succeeded or not.
-- The PredictedToggle wrapTable should have a toggleFunction key that is the function to call to toggle the real value.
function PredictedSettingBaseMixin:SetUp(wrapTable)
	self.wrapTable = wrapTable;
end

function PredictedSettingBaseMixin:Clear()
	self.predictedValue = nil;
end

function PredictedSettingBaseMixin:Get()
	if (self.predictedValue ~= nil) then
		return self.predictedValue;
	end
	return self.wrapTable.getFunction();
end

PredictedSettingMixin = CreateFromMixins(PredictedSettingBaseMixin);

function PredictedSettingMixin:Set(value)
	local validated = self.wrapTable.setFunction(value);
	if (validated ~= false) then
		self.predictedValue = value;
	end
end

function CreatePredictedSetting(wrapTable)
	local predictedSetting = CreateFromMixins(PredictedSettingMixin);
	predictedSetting:SetUp(wrapTable);
	return predictedSetting;
end

PredictedToggleMixin = CreateFromMixins(PredictedSettingBaseMixin)

function PredictedToggleMixin:SetUp(wrapTable)
	PredictedSettingBaseMixin.SetUp(self, wrapTable);
	self.currentValue = self.wrapTable.getFunction();
end

function PredictedToggleMixin:Toggle()
	self.predictedValue = not self.currentValue;
	self.wrapTable.toggleFunction();
end

function PredictedToggleMixin:UpdateCurrentValue()
	self.currentValue = self.wrapTable.getFunction();
end

function CreatePredictedToggle(wrapTable)
	local predictedToggle = CreateFromMixins(PredictedToggleMixin);
	predictedToggle:SetUp(wrapTable);
	return predictedToggle;
end]] },
{ 'Blizzard_SharedXML\\SecureUtil.lua', [[
-- Mix this into a FontString to have it keep trying smaller font objects until it stops truncating, or gets too small.
ShrinkUntilTruncateFontStringMixin = {};

-- From largest to smallest
function ShrinkUntilTruncateFontStringMixin:SetFontObjectsToTry(...)
	self.fontObjectsToTry = { ... };
	if self:GetText() then
		self:ApplyFontObjects();
	end
end

function ShrinkUntilTruncateFontStringMixin:ApplyFontObjects()
	if not self.fontObjectsToTry then
		error("No fonts applied to ShrinkUntilTruncateFontStringMixin, call SetFontObjectsToTry first");
	end

	for i, fontObject in ipairs(self.fontObjectsToTry) do
		self:SetFontObject(fontObject);
		if not self:IsTruncated() then
			break;
		end
	end
end

function ShrinkUntilTruncateFontStringMixin:SetText(text)
	if not self:GetFont() then
		if not self.fontObjectsToTry then
			error("No fonts applied to ShrinkUntilTruncateFontStringMixin, call SetFontObjectsToTry first");
		end
		self:SetFontObject(self.fontObjectsToTry[1]);
	end

	GetFontStringMetatable().__index.SetText(self, text);
	self:ApplyFontObjects();
end

function ShrinkUntilTruncateFontStringMixin:SetFormattedText(format, ...)
	if not self:GetFont() then
		if not self.fontObjectsToTry then
			error("No fonts applied to ShrinkUntilTruncateFontStringMixin, call SetFontObjectsToTry first");
		end
		self:SetFontObject(self.fontObjectsToTry[1]);
	end

	GetFontStringMetatable().__index.SetFormattedText(self, format, ...);
	self:ApplyFontObjects();
end

-- Mix this into a FontString to shrink text to fit the provided space without truncating by scaling it down until it fits or gets too small.
-- If you're looking for a ShrinkToFit or ShrinkTextToFit mixin this is what you want.
AutoScalingFontStringMixin = { }

local DEFAULT_AUTO_SCALING_MIN_LINE_HEIGHT = 10;

function AutoScalingFontStringMixin:SetText(text)
	GetFontStringMetatable().__index.SetText(self, text);
	self:ScaleTextToFit();
end

function AutoScalingFontStringMixin:SetFormattedText(format, ...)
	GetFontStringMetatable().__index.SetFormattedText(self, format, ...);
	self:ScaleTextToFit();
end

function AutoScalingFontStringMixin:SetMinLineHeight(minLineHeight)
	self.minLineHeight = minLineHeight;
	self:ScaleTextToFit();
end

function AutoScalingFontStringMixin:ScaleTextToFit()
	if not self.baseLineHeight then
		-- store the initial line height for calculating scaling
		self.baseLineHeight = Round(self:GetLineHeight());
	end
	local baseLineHeight = self.baseLineHeight;
	local tryHeight = baseLineHeight;
	local minLineHeight = self.minLineHeight or DEFAULT_AUTO_SCALING_MIN_LINE_HEIGHT;
	local stringWidth = self:GetUnboundedStringWidth() / self:GetTextScale();
	if stringWidth > 0 then
		local maxLines = self:GetMaxLines();
		if maxLines == 0 then
			maxLines = Round(self:GetHeight() / (baseLineHeight + self:GetSpacing()));
		end
		local targetScale = self:GetWidth() * maxLines / stringWidth;
		if targetScale >= 1 then
			tryHeight = baseLineHeight;
		else
			tryHeight = Round(targetScale * baseLineHeight);
			if tryHeight < minLineHeight then
				tryHeight = minLineHeight;
			end
		end
	end

	while tryHeight >= minLineHeight do
		local scale = tryHeight / baseLineHeight;
		self:SetTextScale(scale);
		if self:IsTruncated() then
			tryHeight = tryHeight - 1;
		else
			break;
		end
	end
end

--------------------------------------------------
function SetupPlayerForModelScene(modelScene, overrideActorName, itemModifiedAppearanceIDs, sheatheWeapons, autoDress, hideWeapons, useNativeForm, playerRaceName, playerGender)
	if not modelScene then
		return;
	end

	local forceAlternateForm = nil;
	local actor = modelScene:GetPlayerActor(overrideActorName, forceAlternateForm, playerRaceName, playerGender);
	if actor then
		sheatheWeapons = (sheatheWeapons == nil) or sheatheWeapons;
		hideWeapons = (hideWeapons == nil) or hideWeapons;
		useNativeForm = (useNativeForm == nil) or useNativeForm;
		if C_Glue.IsOnGlueScreen() then
			local characterIndex = nil;  -- defaults to selected character.
			actor:SetPlayerModelFromGlues(characterIndex, sheatheWeapons, autoDress, hideWeapons, useNativeForm);
		else
			actor:SetModelByUnit("player", sheatheWeapons, autoDress, hideWeapons, useNativeForm);
		end

		if itemModifiedAppearanceIDs then
			for i, itemModifiedAppearanceID in ipairs(itemModifiedAppearanceIDs) do
				actor:TryOn(itemModifiedAppearanceID);
			end
		end
		actor:SetAnimationBlendOperation(Enum.ModelBlendOperation.None);
	end
end

function SetupItemPreviewActor(actor, displayID)
	if actor then
		actor:SetModelByCreatureDisplayID(displayID);
		actor:SetAnimationBlendOperation(Enum.ModelBlendOperation.None);
	end
end
]] },
