{ 'Blizzard_SharedXML\\ScriptedAnimations\\ScriptAnimatedModelSceneActor.lua', [[

ScriptAnimatedModelSceneActorMixin = {};

function ScriptAnimatedModelSceneActorMixin:IsActive()
	-- A duration of 0 is used for effects that last until canceled.
	return not self.elapsedTime or (self.duration == 0) or (self.elapsedTime < self.duration);
end

function ScriptAnimatedModelSceneActorMixin:GetModelScene()
	return self:GetParent();
end

function ScriptAnimatedModelSceneActorMixin:OnFinish()
	self.effectControl:FinishEffect();
end

-- This isn't a frame so its update function is called through its parent.
function ScriptAnimatedModelSceneActorMixin:DeltaUpdate(elapsed)
	self.elapsedTime = (self.elapsedTime or 0) + elapsed;
	if self:IsActive() then
		if self.trajectory then
			local positionX, positionY, newTrajectory = self.trajectory(self.source, self.target, self.elapsedTime, self.duration);
			
			if newTrajectory then
				self.trajectory = newTrajectory;
			end

			if positionX and positionY then
				self:GetModelScene():SetActorPositionFromPixels(self, positionX + self.dynamicOffsetX, positionY + self.dynamicOffsetY, self.dynamicOffsetZ);
				self:Show();
			else
				self:Hide();
			end
		end

		if self.fadeInTime ~= nil then
			if self.elapsedTime	< self.fadeInTime then
				local progress =  self.elapsedTime / self.fadeInTime;
				self:SetAlpha(Lerp(self.startAlpha, self.targetAlpha, progress));
			else
				self.fadeInTime = nil;
				self:SetAlpha(self.targetAlpha);
			end
		elseif (self.fadeOutStart ~= nil) and (self.elapsedTime > self.fadeOutStart) then
			local progress = (self.elapsedTime - self.fadeOutStart) / self.fadeOutTime;
			self:SetAlpha(Lerp(self.targetAlpha, self.endAlpha, progress));
		end
	end
end

local function GetAngleForModel(source, target)
	local sourceX, sourceY = GetScaledCenter(source);
	local targetX, targetY = GetScaledCenter(target);
	local direction = CreateVector2D(targetX - sourceX, targetY - sourceY);

	-- Missiles face right by default, so calculate the angle between the right normal (1, 0), and the direction we'd like to face.
	local radians = Vector2D_CalculateAngleBetween(1, 0, direction:GetXY());

	return radians;
end

function ScriptAnimatedModelSceneActorMixin:SetEffect(effectDescription, source, target, scaleMultiplier)
	if not effectDescription then
		return;
	end

	self:SetModelByFileID(effectDescription.visual);
	
	self:SetPitch(effectDescription.pitchRadians);
	self:SetRoll(effectDescription.rollRadians);

	self.baseOffsetX = effectDescription.offsetX;
	self.baseOffsetY = effectDescription.offsetY;
	self.baseOffsetZ = effectDescription.offsetZ;
	self:SetDynamicOffsets(0, 0, 0);

	local effectAnimationSpeed = effectDescription.animationSpeed;
	if effectAnimationSpeed == 0 then
		-- Note: we could alternatively calculate the animation speed to complete 1 full cycle in the effect's duration.
		effectAnimationSpeed = 1.0;
	end

	local animationSpeed = self:GetModelScene():GetEffectSpeed() * effectAnimationSpeed;
	self:SetAnimation(effectDescription.animation or 0, 0, animationSpeed, effectDescription.animationStartOffset);

	self.elapsedTime = nil;

	self.source = source;
	self.target = target;

	self.effectDescription = effectDescription;
	self.trajectory = effectDescription.trajectory;
	self.duration = effectDescription.duration;
	self:SetScale(effectDescription.visualScale * (scaleMultiplier or 1.0));

	self:SetParticleOverrideScale(effectDescription.particleOverrideScale);

	if self.source and self.target and self.source ~= self.target and not effectDescription.useTargetAsSource then
		self:SetYaw(GetAngleForModel(self.source, self.target));
	else
		self:SetYaw(effectDescription.yawRadians);
	end

	self.targetAlpha = effectDescription.alpha or 1.0;

	self.fadeInTime = effectDescription.startAlphaFadeDuration;
	if self.fadeInTime == nil then
		self.startAlpha = nil;
	else
		self.startAlpha = effectDescription.startAlphaFade or 0;
	end

	self.fadeOutTime = effectDescription.endAlphaFadeDuration;
	if self.fadeOutTime == nil then
		self.endAlpha = nil;
		self.fadeOutStart = nil;
	else
		self.endAlpha = effectDescription.endAlphaFade or 0;
		self.fadeOutStart = effectDescription.duration - self.fadeOutTime;
	end

	self:SetAlpha(effectDescription.startAlpha or self.targetAlpha);

	self:DeltaUpdate(0);
end

function ScriptAnimatedModelSceneActorMixin:SetDynamicOffsets(pixelX, pixelY, pixelZ)
	self.dynamicOffsetX = pixelX or 0;
	self.dynamicOffsetY = pixelY or 0;
	self.dynamicOffsetZ = pixelZ or 0;
end

function ScriptAnimatedModelSceneActorMixin:SetEffectActorOffset(x, y, z)
	self:SetPosition(self.baseOffsetX + x, self.baseOffsetY + y, self.baseOffsetZ + z);
end
]] },
{ 'Blizzard_SharedXML\\ScriptedAnimations\\ScriptAnimatedEffectController.lua', [[

ScriptAnimatedEffectControllerMixin = {};

function ScriptAnimatedEffectControllerMixin:Init(modelScene, effectID, source, target, onEffectFinish, onEffectResolution, scaleMultiplier)
	self.modelScene = modelScene;
	self.effectID = effectID;
	self.initialEffectID = effectID;
	self.source = source;
	self.target = target;
	self.onEffectFinish = onEffectFinish;
	self.onEffectResolution = onEffectResolution;
	self.scaleMultiplier = scaleMultiplier;

	self.activeBehaviors = {};
	self.effectCount = 0;

	self.loopingSoundEmitter = nil;
	self.soundEnabled = true;
end

function ScriptAnimatedEffectControllerMixin:GetEffect()
	return ScriptedAnimationEffectsUtil.GetEffectByID(self.effectID);
end

function ScriptAnimatedEffectControllerMixin:GetCurrentEffectID()
	return self.effectID;
end

function ScriptAnimatedEffectControllerMixin:GetInitialEffectID()
	return self.initialEffectID;
end

function ScriptAnimatedEffectControllerMixin:IsSoundEnabled()
	return self.soundEnabled;
end

function ScriptAnimatedEffectControllerMixin:SetSoundEnabled(enabled)
	self.soundEnabled = enabled;
end

function ScriptAnimatedEffectControllerMixin:StartEffect()
	if self.cancelDelayedStart then
		self.cancelDelayedStart = nil;
		return;
	end

	local effect = self:GetEffect();
	if effect then
		self.effectStarted = true;

		self.effectCount = self.effectCount + 1;

		self.actor = self.modelScene:InternalAddEffect(self.effectID, self.source, self.target, self, self.scaleMultiplier);

		if effect.startBehavior then
			self:BeginBehavior(effect.startBehavior);
		end

		if self:IsSoundEnabled() and effect.loopingSoundKitID then
			local startingSound = nil;
			local loopingSound = effect.loopingSoundKitID;

			local endingSound = nil;
			local loopStartDelay = 0;
			local loopEndDelay = 0;
			local loopFadeTime = 0;
			self.loopingSoundEmitter = CreateLoopingSoundEffectEmitter(startingSound, loopingSound, endingSound, loopStartDelay, loopEndDelay, loopFadeTime);
			self.loopingSoundEmitter:StartLoopingSound();
		end
	
		if self:IsSoundEnabled() and effect.startSoundKitID then
			PlaySound(effect.startSoundKitID);
		end
	end

	-- Actor doesn't exist until after InternalAddEffect is called, so we have to wait until now to set the dynamic offsets
	self:UpdateActorDynamicOffsets();
end

function ScriptAnimatedEffectControllerMixin:DeltaUpdate(elapsedTime)
	if self.actor then
		if self.actor:IsActive() then
			self.actor:DeltaUpdate(elapsedTime);
		end

		-- Delta Update can change the state, if it did, we want to play the finish effect before doing the rest of the loop
		if not self.actor:IsActive() then
			self:FinishEffect();
		end
	end

	local behaviorFinished = false;
	local currentTime = GetTime();
	local i = 1;
	while i <= #self.activeBehaviors do
		local activeBehaviors = self.activeBehaviors[i];
		if currentTime < activeBehaviors.finishTime then
			i = i + 1;
		else
			behaviorFinished = true;
			tUnorderedRemove(self.activeBehaviors, i);
		end
	end

	if behaviorFinished then
		self:CheckResolution();
	end
end

function ScriptAnimatedEffectControllerMixin:IsActive()
	return self.actor or #self.activeBehaviors > 0;
end

function ScriptAnimatedEffectControllerMixin:CancelLoopingSound()
	if self.loopingSoundEmitter then
		self.loopingSoundEmitter:CancelLoopingSound();
	end
end

function ScriptAnimatedEffectControllerMixin:FinishLoopingSound()
	if self.loopingSoundEmitter then
		self.loopingSoundEmitter:FinishLoopingSound();
	end
end

function ScriptAnimatedEffectControllerMixin:FinishEffect()
	local effect = self:GetEffect();
	if effect.finishBehavior then
		self:BeginBehavior(effect.finishBehavior);
	end

	if self:IsSoundEnabled() and effect.finishSoundKitID then
		PlaySound(effect.finishSoundKitID);
	end

	self:RunEffectFinish();

	if self.actor then
		self.modelScene:ReleaseActor(self.actor);
		self.actor = nil;
	end

	self:FinishLoopingSound();

	if effect.finishEffectID then
		self.effectID = effect.finishEffectID;
		self:StartEffect();
		self.actor:DeltaUpdate(0);
	end

	self:CheckResolution();
end

function ScriptAnimatedEffectControllerMixin:CheckResolution()
	if not self:IsActive() then
		self:RunEffectResolution();
	end
end

function ScriptAnimatedEffectControllerMixin:RunEffectResolution(cancelled)
	if self.onEffectResolution then
		self.onEffectResolution(self.effectCount, not not cancelled);
	end
end

function ScriptAnimatedEffectControllerMixin:RunEffectFinish(cancelled)
	if self.onEffectFinish then
		if not self.onEffectFinish(self.effectCount, not not cancelled) then
			self.onEffectFinish = nil;
		end
	end
end

function ScriptAnimatedEffectControllerMixin:SetDynamicOffsets(pixelX, pixelY, pixelZ)
	self.dynamicPixelX = pixelX;
	self.dynamicPixelY = pixelY;
	self.dynamicPixelZ = pixelZ;
	self:UpdateActorDynamicOffsets();
end

function ScriptAnimatedEffectControllerMixin:UpdateActorDynamicOffsets()
	if self.actor then
		self.actor:SetDynamicOffsets(self.dynamicPixelX, self.dynamicPixelY, self.dynamicPixelZ);
	end
end

function ScriptAnimatedEffectControllerMixin:CancelEffect()
	self:InternalCancelEffect();
end

function ScriptAnimatedEffectControllerMixin:InternalCancelEffect(skipRemovingController)
	if not self.effectStarted then
		self.cancelDelayedStart = true;
		return;
	end

	if not skipRemovingController then
		self.modelScene:RemoveEffectController(self);
	end

	if self.actor then
		self.modelScene:ReleaseActor(self.actor);
		self.actor = nil;
	end

	for i, activeBehavior in ipairs(self.activeBehaviors) do
		activeBehavior.cancelFunction();
	end

	self.activeBehaviors = {};

	self:CancelLoopingSound();
	local cancelled = true;
	self:RunEffectFinish(cancelled);
	self:RunEffectResolution(cancelled);
end

function ScriptAnimatedEffectControllerMixin:BeginBehavior(behavior)
	local effect = self:GetEffect();
	local cancelFunction, duration = behavior(effect, self.source, self.target, self.modelScene:GetEffectSpeed());
	local finishTime = GetTime() + duration;
	table.insert(self.activeBehaviors, { cancelFunction = cancelFunction, finishTime = finishTime });
end
]] },
{ 'Blizzard_SharedXML\\ScriptedAnimations\\ScriptAnimatedModelScene.lua', [[

local ScriptedAnimationModelSceneID = 343;

-- Experimentally determined.
local SceneUnitDivisor = 612.5;

-- These are (somewhat) arbitrary values. With these, many standard effects with look correct with a scale of 1.0.
-- To change these, we'd have to update all existing effects that play in scenes with useViewInsetNormalization.
local TargetViewWidth = 600;
local TargetViewHeight = 680;


ScriptAnimatedModelSceneMixin = {};

function ScriptAnimatedModelSceneMixin:OnLoad()
	ModelSceneMixin.OnLoad(self);

	self.centerX = 0;
	self.centerY = 0;
	self.effectControllers = {};
	self.pixelsPerSceneUnit = math.huge;
	self.delayedActions = {};

	-- Automatically allow overlapped models for these types of scenes.
	-- Could be optimized to only enable when there are multiple models.
	self:SetAllowOverlappedModels(true);
end

function ScriptAnimatedModelSceneMixin:OnShow()
	self:RefreshModelScene();
	self:RegisterEvent("DISPLAY_SIZE_CHANGED");
	self:RegisterEvent("UI_SCALE_CHANGED");
	self:SetScript("OnSizeChanged", self.OnSizeChanged);
end

function ScriptAnimatedModelSceneMixin:OnHide()
	self:UnregisterEvent("DISPLAY_SIZE_CHANGED");
	self:UnregisterEvent("UI_SCALE_CHANGED");
	self:SetScript("OnSizeChanged", nil);
end

function ScriptAnimatedModelSceneMixin:OnSizeChanged()
	self:RefreshModelScene();
end

function ScriptAnimatedModelSceneMixin:OnEvent(event)
	if event == "DISPLAY_SIZE_CHANGED" or event == "UI_SCALE_CHANGED" then
		self:RefreshModelScene();
	end
end

function ScriptAnimatedModelSceneMixin:RefreshModelScene()
	if not self:GetRect() then
		return;
	end

	self.centerX, self.centerY = self:GetCenter();

	local sceneShouldBeSet = not self:IsModelSceneSet();
	if sceneShouldBeSet then
		self:SetFromModelSceneID(ScriptedAnimationModelSceneID);
		self.modelSceneSet = true;
	end

	if self.useViewInsetNormalization then
		local currentWidth, currentHeight = self:GetSize();
		local adjustmentX = (currentWidth - TargetViewWidth) / 2;
		local adjustmentY = (currentHeight - TargetViewHeight) / 2;
		self:SetViewInsets(adjustmentX, adjustmentX, adjustmentY, adjustmentY);
	end

	self:CalculatePixelsPerSceneUnit();

	-- Now that the scene is set, and we've calculated pixels per scene unit, we can execute the
	-- actions that were delayed until we had a proper scene set up.
	if sceneShouldBeSet then
		for i, action in ipairs(self.delayedActions) do
			action();
		end

		self.delayedActions = nil;
	end
end

function ScriptAnimatedModelSceneMixin:IsModelSceneSet()
	return self.modelSceneSet;
end

function ScriptAnimatedModelSceneMixin:ExecuteOrDelayUntilSceneSet(action)
	-- If we're still resolving sizing and anchoring and we don't have a proper model scene set up,
	-- we need to delay adding effects as they won't be initialized properly.
	if self:IsModelSceneSet() then
		action();
		return;
	end

	table.insert(self.delayedActions, action);
end

function ScriptAnimatedModelSceneMixin:OnUpdate(elapsed, ...)
	if #self.effectControllers == 0 then
		return;
	end

	ModelSceneMixin.OnUpdate(self, elapsed, ...);

	self.centerX, self.centerY = self:GetCenter();

	local modifiedElapsed = elapsed * self:GetEffectSpeed();
	for i, effectController in ipairs(self.effectControllers) do
		effectController:DeltaUpdate(modifiedElapsed, ...);
	end

	local i = 1;
	while i <= #self.effectControllers do
		local effectController = self.effectControllers[i];
		if effectController:IsActive() then
			i = i + 1;
		else
			tUnorderedRemove(self.effectControllers, i);
		end
	end
end

function ScriptAnimatedModelSceneMixin:SetActiveCamera(...)
	ModelSceneMixin.SetActiveCamera(self, ...);

	self:CalculatePixelsPerSceneUnit();
end

function ScriptAnimatedModelSceneMixin:GetSceneSize()
	local left, right, top, bottom = self:GetViewInsets();
	local width, height = self:GetSize();
	return (width - left) - right, (height - bottom) - top;
end

function ScriptAnimatedModelSceneMixin:CalculatePixelsPerSceneUnit()
	local width, height = self:GetSceneSize();
	local sceneSize = Vector2D_GetLength(width, height);
	local activeCamera = self:GetActiveCamera();
	if not activeCamera then
		return;
	end

	local zoomDistance = activeCamera:GetZoomDistance();
	self.pixelsPerSceneUnit = (sceneSize * zoomDistance) / SceneUnitDivisor;
end

function ScriptAnimatedModelSceneMixin:GetPixelsPerSceneUnit()
	return self.pixelsPerSceneUnit;
end

function ScriptAnimatedModelSceneMixin:AddEffect(effectID, source, target, onEffectFinish, onEffectResolution, scaleMultiplier)
	local effectController = CreateAndInitFromMixin(ScriptAnimatedEffectControllerMixin, self, effectID, source, target, onEffectFinish, onEffectResolution, scaleMultiplier);

	local function StartEffectController()
		effectController:StartEffect();
	end

	self:ExecuteOrDelayUntilSceneSet(StartEffectController);
	
	return effectController; 
end

function ScriptAnimatedModelSceneMixin:AddDynamicEffect(dynamicEffectDescription, source, target, onEffectFinish, onEffectResolution, scaleMultiplier)
	local effectController = CreateAndInitFromMixin(ScriptAnimatedEffectControllerMixin, self, dynamicEffectDescription.effectID, source, target, onEffectFinish, onEffectResolution, scaleMultiplier);

	local function StartEffectController()
		effectController:SetSoundEnabled(dynamicEffectDescription.soundEnabled);
		effectController:SetDynamicOffsets(dynamicEffectDescription.offsetX, dynamicEffectDescription.offsetY, dynamicEffectDescription.offsetZ);
		effectController:StartEffect();
	end

	self:ExecuteOrDelayUntilSceneSet(StartEffectController);
	
	return effectController; 
end

function ScriptAnimatedModelSceneMixin:InternalAddEffect(effectID, source, target, effectController, scaleMultiplier)
	local effect = ScriptedAnimationEffectsUtil.GetEffectByID(effectID);

	local actor = self:AcquireActor();
	
	if not actor.SetEffect then
		Mixin(actor, ScriptAnimatedModelSceneActorMixin);
	end

	actor:SetEffect(effect, source, target, scaleMultiplier);
	actor:Show();

	if not tContains(self.effectControllers, effectController) then
		table.insert(self.effectControllers, effectController);
	end

	return actor;
end

function ScriptAnimatedModelSceneMixin:SetEffectSpeed(speed)
	self.effectSpeed = speed;
end

function ScriptAnimatedModelSceneMixin:GetEffectSpeed()
	return self.effectSpeed or 1.0;
end

function ScriptAnimatedModelSceneMixin:ClearEffects()
	local skipRemovingController = true;
	for i, effectController in ipairs(self.effectControllers) do
		effectController:InternalCancelEffect(skipRemovingController);
	end

	self.effectControllers = {};
end

function ScriptAnimatedModelSceneMixin:HasActiveEffects()
	return #self.effectControllers > 0;
end

function ScriptAnimatedModelSceneMixin:RemoveEffectController(effectControllerToRemove)
	for i, effectController in ipairs(self.effectControllers) do
		if effectController == effectControllerToRemove then
			tUnorderedRemove(self.effectControllers, i);
			break;
		end
	end
