{ 'Blizzard_SharedXML\\DataProvider.lua', [[

DataProviderMixin = CreateFromMixins(CallbackRegistryMixin);

DataProviderMixin:GenerateCallbackEvents(
	{
		"OnSizeChanged",
		"OnInsert",
		"OnRemove",
		"OnSort",
		"OnMove",
	}
);

function DataProviderMixin:Init(tbl)
	CallbackRegistryMixin.OnLoad(self);
	
	self.collection = {};

	if tbl then
		self:InsertTable(tbl);
	end
end

function DataProviderMixin:IsVirtual()
	return false;
end

function DataProviderMixin:Enumerate(indexBegin, indexEnd)
	return CreateTableEnumerator(self.collection, indexBegin, indexEnd);
end

function DataProviderMixin:EnumerateEntireRange()
	local indexBegin, indexEnd = nil, nil;
	return self:Enumerate(indexBegin, indexEnd);
end

function DataProviderMixin:ReverseEnumerate(indexBegin, indexEnd)
	return CreateTableReverseEnumerator(self.collection, indexBegin, indexEnd);
end

function DataProviderMixin:ReverseEnumerateEntireRange()
	local indexBegin, indexEnd = nil, nil;
	return self:ReverseEnumerate(indexBegin, indexEnd);
end

function DataProviderMixin:GetCollection()
	return self.collection;
end

function DataProviderMixin:GetSize()
	return #self.collection;
end

function DataProviderMixin:IsEmpty()
	return self:GetSize() == 0;
end

function DataProviderMixin:InsertInternal(elementData, insertIndex)
	if insertIndex == nil then
		table.insert(self.collection, elementData);
		insertIndex = #self.collection;
	else
		table.insert(self.collection, insertIndex, elementData);
	end

	self:TriggerEvent(DataProviderMixin.Event.OnInsert, insertIndex, elementData, self:HasSortComparator());
end

function DataProviderMixin:InsertAtIndex(elementData, insertIndex)
	self:InsertInternal(elementData, insertIndex);

	self:TriggerEvent(DataProviderMixin.Event.OnSizeChanged, self:HasSortComparator());

	self:Sort();
end

function DataProviderMixin:Insert(...)
	local count = select("#", ...);
	for index = 1, count do
		local value = select(index, ...);
		self:InsertInternal(value);
	end

	if count > 0 then
		self:TriggerEvent(DataProviderMixin.Event.OnSizeChanged, self:HasSortComparator());
	end

	self:Sort();
end

function DataProviderMixin:InsertTable(tbl)
	self:InsertTableRange(tbl, 1, #tbl);
end

function DataProviderMixin:InsertTableRange(tbl, indexBegin, indexEnd)
	if indexEnd - indexBegin < 0 then
		return;
	end

	for index = indexBegin, indexEnd do
		self:InsertInternal(tbl[index]);
	end

	self:TriggerEvent(DataProviderMixin.Event.OnSizeChanged, self:HasSortComparator());

	self:Sort();
end

function DataProviderMixin:MoveElementDataToIndex(elementData, newIndex)
	local currentIndex = self:FindIndex(elementData);
	if not currentIndex then
		error("MoveElementDataToIndex requires elementData to exist.");
	end

	if currentIndex == newIndex then
		return;
	end

	self:RemoveIndex(currentIndex);
	self:InsertAtIndex(elementData, newIndex);

	self:TriggerEvent(DataProviderMixin.Event.OnMove, elementData, currentIndex, newIndex);
end

function DataProviderMixin:Remove(...)
	local removedIndex = nil;
	local originalSize = self:GetSize();
	local count = select("#", ...);
	while count >= 1 do
		local elementData = select(count, ...);
		local index = tIndexOf(self.collection, elementData);
		if index then
			table.remove(self.collection, index);
			self:TriggerEvent(DataProviderMixin.Event.OnRemove, elementData, index);
			removedIndex = index;
		end
		count = count - 1;
	end

	if self:GetSize() ~= originalSize then
		local sorting = false;
		self:TriggerEvent(DataProviderMixin.Event.OnSizeChanged, sorting);
	end

	return removedIndex;
end

function DataProviderMixin:RemoveAllByPredicate(predicate)
	local index = self:GetSize();
	while index >= 1 do
		local elementData = self:Find(index);
		if predicate(elementData) then
			self:RemoveIndex(index);
		end
		index = index - 1;
	end
end

function DataProviderMixin:RemoveByPredicate(predicate)
	local index, elementData = self:FindByPredicate(predicate);
	if elementData then
		self:Remove(elementData);
	end
end

function DataProviderMixin:RemoveIndex(index)
	self:RemoveIndexRange(index, index);
end

function DataProviderMixin:RemoveIndexRange(indexBegin, indexEnd)
	local originalSize = self:GetSize();

	indexBegin = math.max(1, indexBegin);
	indexEnd = math.min(self:GetSize(), indexEnd);
	while indexEnd >= indexBegin do
		local elementData = self.collection[indexEnd];
		table.remove(self.collection, indexEnd);
		self:TriggerEvent(DataProviderMixin.Event.OnRemove, elementData, indexEnd);
		indexEnd = indexEnd - 1;
	end

	if self:GetSize() ~= originalSize then
		local sorting = false;
		self:TriggerEvent(DataProviderMixin.Event.OnSizeChanged, sorting);
	end
end

function DataProviderMixin:ReplaceAtIndex(index, newElementData)
	self:RemoveIndex(index);
	self:InsertAtIndex(newElementData, index);
end

function DataProviderMixin:SetSortComparator(sortComparator, skipSort)
	self.sortComparator = sortComparator;
	if not skipSort then
		self:Sort();
	end
end

function DataProviderMixin:ClearSortComparator()
	self.sortComparator = nil;
end

function DataProviderMixin:HasSortComparator()
	return self.sortComparator ~= nil;
end

function DataProviderMixin:Sort(sortComparator)
	local comparator = self.sortComparator or sortComparator;
	if comparator then
		table.sort(self.collection, comparator);
		self:TriggerEvent(DataProviderMixin.Event.OnSort);
	end
end

function DataProviderMixin:Find(index)
	return self.collection[index];
end

function DataProviderMixin:FindLast()
	return self.collection[self:GetSize()];
end

function DataProviderMixin:FindIndex(elementData)
	for index, elementDataIter in self:Enumerate() do
		if elementDataIter == elementData then
			return index, elementDataIter;
		end
	end
end

function DataProviderMixin:FindByPredicate(predicate)
	for index, elementData in self:Enumerate() do
		if predicate(elementData) then
			return index, elementData;
		end
	end
end

function DataProviderMixin:FindElementDataByPredicate(predicate)
	local index, elementData = self:FindByPredicate(predicate);
	return elementData;
end

function DataProviderMixin:FindIndexByPredicate(predicate)
	local index, elementData = self:FindByPredicate(predicate);
	return index;
end

function DataProviderMixin:ContainsByPredicate(predicate)
	local index, elementData = self:FindByPredicate(predicate);
	return index ~= nil;
end

function DataProviderMixin:ForEach(func)
	for index, elementData in self:Enumerate() do
		func(elementData);
	end
end

function DataProviderMixin:ReverseForEach(func)
	for index, elementData in self:ReverseEnumerate() do
		func(elementData);
	end
end

function DataProviderMixin:Flush()
	local oldCollection = self.collection;
	self.collection = {};
	for index, elementData in ipairs(oldCollection) do
		self:TriggerEvent(DataProviderMixin.Event.OnRemove, elementData, index);
	end
	local sorting = false;
	self:TriggerEvent(DataProviderMixin.Event.OnSizeChanged, sorting);
end

function CreateDataProvider(tbl)
	local dataProvider = CreateFromMixins(DataProviderMixin);
	dataProvider:Init(tbl);
	return dataProvider;
end

local function CreateDefaultIndicesTable(indexCount)
	local tbl = {};
	for index = 1, indexCount do
		table.insert(tbl, {index = index});
	end
	return tbl;
end

function CreateDataProviderByIndexCount(indexCount)
	return CreateDataProvider(CreateDefaultIndicesTable(indexCount));
end

function CreateDataProviderWithAssignedKey(tbl, key)
	local dataProvider = CreateDataProvider();
	for index, value in ipairs(tbl) do
		dataProvider:Insert({[key]=value});
	end
	return dataProvider;
end
]] },
{ 'Blizzard_SharedXML\\IndexRangeDataProvider.lua', [[
-- IndexRangeDataProviderMixin originally written for parity with ScrollBox API to 
-- simulate extremely large ranges (i.e. 20,000 macro icons). As a result, this
-- data provider has a minimal API.
IndexRangeDataProviderMixin = CreateFromMixins(CallbackRegistryMixin);

IndexRangeDataProviderMixin:GenerateCallbackEvents(
	{
		"OnSizeChanged",
	}
);

function IndexRangeDataProviderMixin:Init(size)
	CallbackRegistryMixin.OnLoad(self);

	self:SetSize(size);
end

function IndexRangeDataProviderMixin:IsVirtual()
	return true;
end

function IndexRangeDataProviderMixin:Enumerate(indexBegin, indexEnd)
	indexBegin = indexBegin and (indexBegin - 1) or 0;
	indexEnd = indexEnd or self.size;

	local function Enumerator(invariant, index)
		index = index + 1;
		if index <= indexEnd then
			return index, index;
		end
	end
	
	local invariant = nil;
	return Enumerator, invariant, indexBegin;
end

function IndexRangeDataProviderMixin:EnumerateEntireRange()
	local indexBegin, indexEnd = nil, nil;
	return self:Enumerate(indexBegin, indexEnd);
end

function IndexRangeDataProviderMixin:GetSize()
	return self.size;
end

function IndexRangeDataProviderMixin:SetSize(size)
	self.size = math.max(0, size);

	local pendingSort = false;
	self:TriggerEvent(IndexRangeDataProviderMixin.Event.OnSizeChanged, pendingSort);
end

function IndexRangeDataProviderMixin:Flush()
	self:SetSize(0);
end

function IndexRangeDataProviderMixin:Find(index)
	if index <= self:GetSize() then
		return index;
	end
end

function IndexRangeDataProviderMixin:FindByPredicate(predicate)
	for index = 1, self:GetSize() do
		if predicate(index) then
			return index;
		end
	end
end

function IndexRangeDataProviderMixin:ContainsByPredicate(predicate)
	return self:FindByPredicate(predicate) ~= nil;
end

function CreateIndexRangeDataProvider(size)
	return CreateAndInitFromMixin(IndexRangeDataProviderMixin, size or 0);
end
]] },
{ 'Blizzard_SharedXML\\TreeListDataProvider.lua', [=[

local explicitParameterMsg = "Parameter 'excludeCollapsed' is required.";

TreeDataProviderConstants =
{
	Collapsed = true,
	Uncollapsed = false,
	SetChildCollapse = true,
	RetainChildCollapse = false,
	SkipInvalidation = true,
	DoInvalidation = false,
	ExcludeCollapsed = true,
	IncludeCollapsed = false,
};

local TreeNodeMixin = {};

local function CreateTreeNode(dataProvider, parent, data)
	local node = CreateFromMixins(TreeNodeMixin);
	node:Init(dataProvider, parent, data);
	return node;
end


function TreeNodeMixin:Init(dataProvider, parent, data)
	self.nodes = {};
	self.dataProvider = dataProvider;
	self.parent = parent;
	self.data = data;
end

function TreeNodeMixin:GetNodes()
	return self.nodes;
end

function TreeNodeMixin:GetDepth()
	return self.parent and self.parent:GetDepth() + 1 or 0;
end

function TreeNodeMixin:GetData()
	return self.data;
end

function TreeNodeMixin:GetSize()
	return #self.nodes;
end

function TreeNodeMixin:GetFirstNode()
	return self.nodes[1];
end

function TreeNodeMixin:MoveNode(node)
	local skipInvalidation = true;
	self.dataProvider:Remove(node, skipInvalidation);
	local previousParent = node.parent;
	node.parent = self;
	
	self:InsertNode(node);

	self.dataProvider:TriggerEvent(TreeDataProviderMixin.Event.OnMove, node, previousParent, self);	

	return node;
end

function TreeNodeMixin:MoveNodeRelativeTo(node, referenceNode, offset)
	if not tContains(self.nodes, referenceNode) then
		error("MoveNodeRelativeToNode requires reference node to exist.");
	end

	if self:HasSortComparator() then
		error("MoveNodeRelativeToNode cannot move a node into a sorted node.");
	end

	local skipInvalidation = true;
	self.dataProvider:Remove(node, skipInvalidation);
	local previousParent = node.parent;
	node.parent = self;
	
	local referenceNodeIndex = tIndexOf(self.nodes, referenceNode);
	local newNodeIndex = referenceNodeIndex + offset;
	table.insert(self.nodes, newNodeIndex, node);
	
	self:Invalidate();

	self.dataProvider:TriggerEvent(TreeDataProviderMixin.Event.OnMove, node, previousParent, self);	

	return node;
end

function TreeNodeMixin:GetParent()
	return self.parent;
end

function TreeNodeMixin:Flush()
	self.nodes = {};
	self:Invalidate();
end

function TreeNodeMixin:Insert(data)
	local node = CreateTreeNode(self.dataProvider, self, data);
	return self:InsertNode(node);
end

function TreeNodeMixin:InsertNodeAtIndex(data, insertIndex)
	local node = CreateTreeNode(self.dataProvider, self, data);
	return self:InsertNode(node, insertIndex);
end

function TreeNodeMixin:InsertNode(node, insertIndex)
	if insertIndex then
		table.insert(self.nodes, insertIndex, node);
	else
		table.insert(self.nodes, node);
	end

	self:Invalidate();

	self:Sort();

	return node;
end

function TreeNodeMixin:Remove(node, skipInvalidation)
	for index, node2 in ipairs(self.nodes) do
		if node2 == node then
			local removed = table.remove(self.nodes, index);
			if not skipInvalidation then
				self:Invalidate();
			end
			return removed;
		end
	end
end

function TreeNodeMixin:SetSortComparator(sortComparator, affectChildren, skipSort)
	self.sortComparator = sortComparator;
	
	if affectChildren then
		for index, child in ipairs(self.nodes) do
			child:SetSortComparator(sortComparator, affectChildren, skipSort);
		end
	end

	if not skipSort then
		self:Sort();
	end
end

function TreeNodeMixin:HasSortComparator()
	return self.sortComparator ~= nil;
end

function TreeNodeMixin:Sort()
	if self.sortComparator then
		table.sort(self.nodes, self.sortComparator);
		self.dataProvider:TriggerEvent(TreeDataProviderMixin.Event.OnSort);
	end
end

function TreeNodeMixin:Invalidate()
	self.dataProvider:Invalidate();
end

function TreeNodeMixin:SetChildrenCollapsed(collapsed, affectChildren, skipInvalidate)
	for index, child in ipairs(self.nodes) do
		child:SetCollapsed(collapsed, affectChildren, skipInvalidate);
	end
end

function TreeNodeMixin:SetCollapsed(collapsed, affectChildren, skipInvalidate)
	self.collapsed = collapsed;
	if affectChildren then
		self:SetChildrenCollapsed(collapsed, TreeDataProviderConstants.SetChildCollapse, TreeDataProviderConstants.SkipInvalidation);
	end
	if not skipInvalidate then
		self:Invalidate();
	end
end

function TreeNodeMixin:ToggleCollapsed(affectChildren, skipInvalidate)
	local newCollapsed = not self:IsCollapsed();
	self:SetCollapsed(newCollapsed, affectChildren, skipInvalidate);
	return newCollapsed;
end

function TreeNodeMixin:IsCollapsed()
	return self.collapsed;
end

local function EnumerateTreeListNode(root, excludeCollapsed)
	local stack = {};
	for _, node in ipairs_reverse(root.nodes) do
		table.insert(stack, node);
	end

	local index = 0;
	local function Enumerator()
		index = index + 1;
		local top = table.remove(stack);
		if top then
			if not excludeCollapsed or not top.collapsed then
				for _, node in ipairs_reverse(top.nodes) do
					table.insert(stack, node);
				end
			end

			return index, top;
		end
	end
	
	return Enumerator;
