		return 0;
	end

	local size = self:GetDataProviderSize();
	if size == 0 then
		return 0;
	end

	local stride = self:GetStride();
	local spacing = self:GetExtentSpacing();
	local extent = 0;
	if self:HasIdenticalStrideExtent() then
