		stepper.leave = true;
	end, self);

	stepper:RegisterCallback("OnMouseUp", self.onButtonMouseUp, self);
end

function ScrollBarMixin:OnTrackMouseDown(button, buttonName)
	if buttonName ~= "LeftButton" then
		return;
	end

	if not self:HasScrollableExtent() or not self:IsScrollAllowed() then
		return;
	end

	local direction;
	if self:CanCursorStepInDirection(ScrollControllerMixin.Directions.Decrease) then
		direction = ScrollControllerMixin.Directions.Decrease;
	elseif self:CanCursorStepInDirection(ScrollControllerMixin.Directions.Increase) then
		direction = ScrollControllerMixin.Directions.Increase;
	end
	
	if direction then
		self:ScrollPageInDirection(direction);
	
		self.requireInternalScope = true;

		local function ScrollPageInDirection()
			self:ScrollPageInDirection(direction);
		end

		local elapsed = 0;
		local repeatTime = self:GetPanRepeatTime();
		local delay = self:GetPanRepeatDelay();
		local stepCount = 0;
		self:SetScript("OnUpdate", function(tbl, dt)
			elapsed = elapsed + dt;
			if elapsed > delay then
				elapsed = 0;

				if self:CanCursorStepInDirection(direction) then
					self:CallInternalScope(ScrollPageInDirection);
				end

				if stepCount < 1 then
					stepCount = stepCount + 1;
					delay = repeatTime;
				end
			end
		end);

		self:GetTrack():SetScript("OnMouseUp", self.onButtonMouseUp);
	end
end

function ScrollBarMixin:OnThumbMouseDown(button, buttonName)
	if buttonName ~= "LeftButton" then
		return;
	end

	self.requireInternalScope = true;
	
	local c = self:SelectCursorComponent(self);
	local scrollPercentage = self:GetScrollPercentage();
	local extentRemaining = self:GetTrackExtent() - self:GetFrameExtent(self:GetThumb());
	
	local min, max;
	if self.isHorizontal then
		min = c - scrollPercentage * extentRemaining;
		max = c + (1.0 - scrollPercentage) * extentRemaining;
	else
		min = c - (1.0 - scrollPercentage) * extentRemaining;
		max = c + scrollPercentage * extentRemaining;
	end

	local function SetScrollPercentage(scrollPercentage)
		self:SetScrollPercentage(scrollPercentage);
	end

	self:SetScript("OnUpdate", function()
		local c = Clamp(self:SelectCursorComponent(self), min, max);
		local scrollPercentage;
		if self.isHorizontal then
			scrollPercentage = PercentageBetween(c, min, max);
		else
			scrollPercentage = 1.0 - PercentageBetween(c, min, max);
		end

		self:CallInternalScope(SetScrollPercentage, scrollPercentage);
	end);

	self:GetThumb():RegisterCallback("OnMouseUp", self.onButtonMouseUp, self);
end
]] },
{ 'Blizzard_SharedXML\\Shared\\Scroll\\MinimalScrollBar.lua', [[

MinimalScrollBarStepperScriptsMixin = CreateFromMixins(ButtonStateBehaviorMixin);

function MinimalScrollBarStepperScriptsMixin:OnLoad()
	ButtonStateBehaviorMixin.OnLoad(self);

	local x, y = 1, -1;
	self:SetDisplacedRegions(x, y, self.Texture);

	self:DesaturateIfDisabled();
end

function MinimalScrollBarStepperScriptsMixin:GetAtlas()
	if self:IsEnabled() then
		if self.down then
			return self.downTexture;
		elseif self.over then
			return self.overTexture;
		end
	end
	return self.normalTexture;
end

function MinimalScrollBarStepperScriptsMixin:OnButtonStateChanged()
	self.Texture:SetAtlas(self:GetAtlas(), TextureKitConstants.UseAtlasSize);
end

MinimalScrollBarThumbScriptsMixin = CreateFromMixins(ButtonStateBehaviorMixin);

function MinimalScrollBarThumbScriptsMixin:OnLoad()
	ButtonStateBehaviorMixin.OnLoad(self);

	self:DesaturateIfDisabled();
end

function MinimalScrollBarThumbScriptsMixin:GetAtlas()
	if self:IsEnabled() then
		if self.down then
			return self.downMiddleTexture, self.downBeginTexture, self.downEndTexture;
		elseif self.over then
			return self.overMiddleTexture, self.overBeginTexture, self.overEndTexture;
		end
	end
	return self.upMiddleTexture, self.upBeginTexture, self.upEndTexture;
end

function MinimalScrollBarThumbScriptsMixin:OnButtonStateChanged()
	local middleAtlas, beginAtlas, endAtlas = self:GetAtlas();
	self.Middle:SetAtlas(middleAtlas, TextureKitConstants.UseAtlasSize);
	self.Begin:SetAtlas(beginAtlas, TextureKitConstants.UseAtlasSize);
	self.End:SetAtlas(endAtlas, TextureKitConstants.UseAtlasSize);
end

function MinimalScrollBarThumbScriptsMixin:OnSizeChanged(width, height)
	local info = C_Texture.GetAtlasInfo(self.Middle:GetAtlas());
	if self.isHorizontal then
		self.Middle:SetWidth(width);
		local u = math.min(width / info.width, 1);
		self.Middle:SetTexCoord(0, u, 0, 1);
	else
		self.Middle:SetHeight(height);
		local v = math.min(height / info.height, 1);
		self.Middle:SetTexCoord(0, 1, 0, v);
	end
end]] },
