-- Globals: DEVTOOLS_DEPTH_CUTOFF, DEVTOOLS_INDENT
-- Globals: DEVTOOLS_USE_TABLE_CACHE, DEVTOOLS_USE_FUNCTION_CACHE
-- Globals: DEVTOOLS_USE_USERDATA_CACHE
---------------------------------------------------------------------------

local forceinsecure = forceinsecure;

local DT = {};

DEVTOOLS_MAX_ENTRY_CUTOFF = 30;    -- Maximum table entries shown
DEVTOOLS_LONG_STRING_CUTOFF = 200; -- Maximum string size shown
DEVTOOLS_DEPTH_CUTOFF = 10;        -- Maximum table depth
DEVTOOLS_USE_TABLE_CACHE = true;   -- Look up table names
DEVTOOLS_USE_FUNCTION_CACHE = true;-- Look up function names
DEVTOOLS_USE_USERDATA_CACHE = true;-- Look up userdata names
DEVTOOLS_USE_THREAD_CACHE = true;  -- Look up coroutine names
DEVTOOLS_INDENT='  ';              -- Indentation string

local DEVTOOLS_TYPE_COLOR="|cff88ff88";
local DEVTOOLS_TABLEREF_COLOR="|cffffcc00";
local DEVTOOLS_CUTOFF_COLOR="|cffff0000";
local DEVTOOLS_TABLEKEY_COLOR="|cff88ccff";
local DEVTOOLS_SECRET_COLOR="|cff88ff88";

local FORMATS = {};
-- prefix type suffix
FORMATS["opaqueTypeVal"] = "%s" .. DEVTOOLS_TYPE_COLOR .. "<%s>|r%s";
-- prefix type name suffix
FORMATS["opaqueTypeValName"] = "%s" .. DEVTOOLS_TYPE_COLOR .. "<%s %s>|r%s";
-- prefix type suffix
FORMATS["opaqueTypeValSecret"] = "%s" .. DEVTOOLS_TYPE_COLOR .. "<secret %s>|r%s";
-- type
FORMATS["opaqueTypeKey"] = "<%s>";
-- type name
FORMATS["opaqueTypeKeyName"] = "<%s %s>";
-- type
FORMATS["opaqueTypeKeySecret"] = "<secret %s>";
-- value
FORMATS["bracketTableKey"] = "[%s]";
-- prefix value
FORMATS["tableKeyAssignPrefix"] = DEVTOOLS_TABLEKEY_COLOR .. "%s%s|r=";
-- prefix cutoff
FORMATS["tableEntriesSkipped"] = "%s" .. DEVTOOLS_CUTOFF_COLOR .. "<skipped %s>|r";
-- prefix suffix
FORMATS["tableTooDeep"] = "%s" .. DEVTOOLS_CUTOFF_COLOR .. "<table (too deep)>|r%s";
-- prefix value suffix
FORMATS["simpleValue"] = "%s%s%s";
-- prefix value suffix
FORMATS["simpleValueSecret"] = "%s" .. DEVTOOLS_SECRET_COLOR .. "<secret>|r %s%s";
-- prefix tablename suffix
FORMATS["tableReference"] = "%s" .. DEVTOOLS_TABLEREF_COLOR .. "%s|r%s";

-- Grab a copy various oft-used functions
local rawget = rawget;
local type = type;
local table_insert = table.insert;
local secureexecuterange = secureexecuterange;

local messageHandlers = {};

local function CallCallback(index, callback, msg)
	callback(msg);
end

local function WriteMessage(msg)
	secureexecuterange(messageHandlers, CallCallback, msg);
end

local function DevTools_Write(self, msg)
	WriteMessage(msg);
end

function DevTools_AddMessageHandler(callback)
	table_insert(messageHandlers, callback);
end

local function IsLuaIdentifier(str)
	return string.find(str, "^[a-zA-Z_][a-zA-Z0-9_]*$") ~= nil;
end

local function IsSimpleType(valueType)
	return valueType == "nil" or valueType == "number" or valueType == "boolean" or valueType == "string";
end

local function ShouldTruncateString(str)
	return DEVTOOLS_LONG_STRING_CUTOFF > 0 and #str > DEVTOOLS_LONG_STRING_CUTOFF;
end

local function prepSimple(val, context)
	local valType = type(val);
	if (valType == "nil")  then
		return "nil";
	elseif (valType == "number") then
		return tostring(val);
	elseif (valType == "boolean") then
		return tostring(val);
	elseif (valType == "string") then
		if (canaccessvalue(val) and ShouldTruncateString(val)) then
			local more = #val - DEVTOOLS_LONG_STRING_CUTOFF;
			val = string.sub(val, 1, DEVTOOLS_LONG_STRING_CUTOFF);
			return C_StringUtil.EscapeQuotedCodes(string.format("%q...+%s",val,more));
		else
			return C_StringUtil.EscapeQuotedCodes(string.format("%q",val));
		end
	elseif (not canaccessvalue(val)) then
		return string.format(FORMATS.opaqueTypeKeySecret, valType);
	elseif (valType == "function") then
		local functionName = context:GetFunctionName(val);
		if (functionName) then
			return string.format(FORMATS.opaqueTypeKeyName, valType, functionName);
		else
			return string.format(FORMATS.opaqueTypeKey, valType);
		end
	elseif (valType == "userdata") then
		local userdataName = context:GetUserdataName(val);
		if (userdataName) then
			return string.format(FORMATS.opaqueTypeKeyName, valType, userdataName);
		else
			return string.format(FORMATS.opaqueTypeKey, valType);
		end
	elseif (valType == "thread") then
		local threadName = context:GetThreadName(val);
		if (threadName) then
			return string.format(FORMATS.opaqueTypeKeyName, valType, threadName);
		else
			return string.format(FORMATS.opaqueTypeKey, valType);
		end
	elseif (valType == 'table') then
		local tableName = context:GetTableName(val);
		if (tableName) then
			return string.format(FORMATS.opaqueTypeKeyName, valType, tableName);
		else
			return string.format(FORMATS.opaqueTypeKey, valType);
		end
	end
	assertsafe(false, "Bad type '" .. valType .. "' to prepSimple");
	return string.format(FORMATS.opaqueTypeKey, valType);
end

local function prepSimpleKey(val, context)
	local valType = type(val);
	if (valType == "string") then
		if (canaccessvalue(val) and IsLuaIdentifier(val) and not ShouldTruncateString(val)) then
			return val;
		end
	end
	return string.format(FORMATS.bracketTableKey, prepSimple(val, context));
end

local function DevTools_InitFunctionCache(context)
	local ret = {};

	for _,k in ipairs(DT.functionSymbols) do
		local v = getglobal(k);
		if (type(v) == 'function') then
			ret[v] = '[' .. k .. ']';
		end
	end

	for k,v in pairs(getfenv(0)) do
		if (type(v) == 'function') then
			if (not ret[v]) then
				ret[v] = '[' .. k .. ']';
			end
		end
	end

	return ret;
end

local function DevTools_InitUserdataCache(context)
	local ret = {};

	-- Table access checks are required here because there exist a few tables
	-- in the environment with secret keys. Dump infrastructure is tainted
	-- and promptly is told that it cannot run head-first into tables with
	-- secret keys, which breaks population of these caches and prevents any
	-- value with a userdata handle being dumped.
	for _,k in ipairs(DT.userdataSymbols) do
		local v = getglobal(k);
		if (type(v) == 'table') and canaccesstable(v) then
			local u = rawget(v,0);
			if (type(u) == 'userdata') then
				ret[u] = k .. '[0]';
			end
		end
	end

	for k,v in pairs(getfenv(0)) do
		if (type(v) == 'table') and canaccesstable(v) then
			local u = rawget(v, 0);
			if (type(u) == 'userdata') then
				if (not ret[u]) then
					ret[u] = k .. '[0]';
				end
			end
		end
	end

	return ret;
end

local function DevTools_Cache_Nil(self, value, newName)
	return nil;
end

local function DevTools_Cache_Function(self, value, newName)
	if (not self.functionCache) then
		self.functionCache = DevTools_InitFunctionCache(self);
	end
	local name = self.functionCache[value];
	if ((not name) and newName) then
		self.functionCache[value] = newName;
	end
	return name;
end

local function DevTools_Cache_Userdata(self, value, newName)
	if (not self.userdataCache) then
		self.userdataCache = DevTools_InitUserdataCache(self);
	end
	local name = self.userdataCache[value];
	if ((not name) and newName) then
		self.userdataCache[value] = newName;
	end
	return name;
end

local function DevTools_Cache_Thread(self, value, newName)
	if (not self.threadCache) then
		self.threadCache = {};
	end
	local name = self.threadCache[value];
	if ((not name) and newName) then
		self.threadCache[value] = newName;
	end
	return name;
end

local function DevTools_Cache_Table(self, value, newName)
	if (not self.tableCache) then
		self.tableCache = {};
	end
	local name = self.tableCache[value];
	if ((not name) and newName) then
		self.tableCache[value] = newName;
	end
	return name;
end

local DevTools_DumpValue;

local function DevTools_DumpTableContents(val, prefix, firstPrefix, context)
	local showCount = 0;
	local oldDepth = context.depth;
	local oldKey = context.key;

	-- Use this to set the cache name
	context:GetTableName(val, oldKey or 'value');

	local iter = pairs(val);
	local nextK, nextV = iter(val, nil);

	while (nextK) do
		local k,v = nextK, nextV;
		nextK, nextV = iter(val, k);

		showCount = showCount + 1;
		if ((showCount <= DEVTOOLS_MAX_ENTRY_CUTOFF) or
			(DEVTOOLS_MAX_ENTRY_CUTOFF <= 0)) then
			local prepKey = prepSimpleKey(k, context);
			if (oldKey == nil) then
				context.key = prepKey;
			elseif (string.sub(prepKey, 1, 1) == "[") then
				context.key = oldKey .. prepKey
			else
				context.key = oldKey .. "." .. prepKey
			end
			context.depth = oldDepth + 1;

			local rp = string.format(FORMATS.tableKeyAssignPrefix, firstPrefix,
									 prepKey);
			firstPrefix = prefix;
			DevTools_DumpValue(v, prefix, rp,
							   (nextK and ",") or '',
							   context);
		end
	end
	local cutoff = showCount - DEVTOOLS_MAX_ENTRY_CUTOFF;
	if ((cutoff > 0) and (DEVTOOLS_MAX_ENTRY_CUTOFF > 0)) then
		context:Write(string.format(FORMATS.tableEntriesSkipped,firstPrefix,
									cutoff));
	end
	context.key = oldKey;
	context.depth = oldDepth;
	return (showCount > 0)
end

-- Return the specified value
function DevTools_DumpValue(val, prefix, firstPrefix, suffix, context)
	local valType = type(val);

	if (IsSimpleType(valType)) then
		local format = issecretvalue(val) and FORMATS.simpleValueSecret or FORMATS.simpleValue;
		context:Write(string.format(format, firstPrefix,prepSimple(val, context), suffix));
		return;
	elseif (not canaccessvalue(val) or (valType == "table" and not canaccesstable(val))) then
		-- Opaque secret values will error if passed to the GetName functions,
		-- so handle them specially first.
		--
		-- For tables that are internally secret and inacessible, also consider
		-- them opaque. Ideally we'd dump their contents but the write callbacks
		-- being one-call-per-value could be used as a channel to work out the
		-- length of such tables.

		context:Write(string.format(FORMATS.opaqueTypeValSecret,
										firstPrefix, valType, suffix));
		return;
	elseif (valType == "userdata") then
		local userdataContents = dumpobject(val);
		local userdataName = context:GetUserdataName(val, 'value');
		if (userdataContents ~= nil) then
			local userdataIdentifier;
			if (userdataName) then
				userdataIdentifier = string.format(FORMATS.opaqueTypeValName, "", valType, userdataName, " ");
			else
				userdataIdentifier = string.format(FORMATS.opaqueTypeVal, "", valType, " ");
			end
			DevTools_DumpValue(userdataContents, prefix, firstPrefix .. userdataIdentifier, suffix, context);
		elseif (userdataName) then
			context:Write(string.format(FORMATS.opaqueTypeValName, firstPrefix, valType, userdataName, suffix));
		else
			context:Write(string.format(FORMATS.opaqueTypeVal, firstPrefix, valType, suffix));
		end
		return;
	elseif (valType == "function") then
		local functionName = context:GetFunctionName(val, 'value');
		if (functionName) then
			context:Write(string.format(FORMATS.opaqueTypeValName,
										firstPrefix, valType, functionName, suffix));
		else
			context:Write(string.format(FORMATS.opaqueTypeVal,
										firstPrefix, valType, suffix));
		end
		return;
	elseif (valType == "thread") then
		local threadName = context:GetThreadName(val, 'value');
		if (threadName) then
			context:Write(string.format(FORMATS.opaqueTypeValName,
										firstPrefix, valType, threadName, suffix));
		else
			context:Write(string.format(FORMATS.opaqueTypeVal,
										firstPrefix, valType, suffix));
		end
		return;
	elseif (valType ~= "table") then
		assertsafe(false, "Bad type '" .. valType .. "' to DevTools_DumpValue");
		context:Write(string.format(FORMATS.opaqueTypeVal, firstPrefix, valType, suffix));
		return;
	end

	local cacheName = context:GetTableName(val);
	if (cacheName) then
		context:Write(string.format(FORMATS.tableReference,
									firstPrefix, cacheName, suffix));
		return;
	end

	if ((context.depth >= DEVTOOLS_DEPTH_CUTOFF) and
		(DEVTOOLS_DEPTH_CUTOFF > 0)) then
		context:Write(string.format(FORMATS.tableTooDeep,
									firstPrefix, suffix));
		return;
	end

	firstPrefix = firstPrefix .. "{";
	local oldPrefix = prefix;
	prefix = prefix .. DEVTOOLS_INDENT;

	context:Write(firstPrefix);
	firstPrefix = prefix;
	local anyContents = DevTools_DumpTableContents(val, prefix, firstPrefix, context);
	context:Write(oldPrefix .. "}" .. suffix);
end

local function Pick_Cache_Function(func, setting)
	if (setting) then
		return func;
	else
		return DevTools_Cache_Nil;
	end
end

function DevTools_RunDump(value, context)
	local prefix = "";
	local firstPrefix = prefix;

	local valType = type(value);
	if (valType == 'table' and canaccesstable(value)) then
		local any =
			DevTools_DumpTableContents(value, prefix, firstPrefix, context);
		if (context.Result) then
			return context:Result();
		end
		if (not any) then
			context:Write("empty result");
		end
		return;
	end

	DevTools_DumpValue(value, '', '', '', context);
	if (context.Result) then
		return context:Result();
	end
end

function DevTools_CreateDumpContext(startKey)
	local context = {
		depth = 0,
		key = startKey,
	};

	context.GetTableName = Pick_Cache_Function(DevTools_Cache_Table, DEVTOOLS_USE_TABLE_CACHE);
	context.GetFunctionName = Pick_Cache_Function(DevTools_Cache_Function, DEVTOOLS_USE_FUNCTION_CACHE);
	context.GetUserdataName = Pick_Cache_Function(DevTools_Cache_Userdata, DEVTOOLS_USE_USERDATA_CACHE);
	context.GetThreadName = Pick_Cache_Function(DevTools_Cache_Thread, DEVTOOLS_USE_THREAD_CACHE)
	context.Write = DevTools_Write;
	return context;
end

-- Dump the specified list of value
function DevTools_Dump(value, startKey)
	local context = DevTools_CreateDumpContext(startKey);
	DevTools_RunDump(value, context);
end

function DevTools_DumpCommand(msg, editBox)
	forceinsecure();
	if (IsLuaIdentifier(msg)) then
		WriteMessage("Dump: " .. msg);
		local val = _G[msg];
		local tmp = {};
		if (type(val) == "nil") then
			local key = string.format(FORMATS.tableKeyAssignPrefix,
									  '', prepSimpleKey(msg, {}));
			WriteMessage(key .. "nil,");
		else
			tmp[msg] = val;
		end
		DevTools_Dump(tmp);
		return;
	end

	WriteMessage("Dump: value=" .. msg);
	local func,err = loadstring("return " .. msg);
	if (not func) then
		WriteMessage("Dump: ERROR: " .. err);
	else
		DevTools_Dump({ func() }, "value");
	end
end

DT.functionSymbols = {};
DT.userdataSymbols = {};

local funcSyms = DT.functionSymbols;
local userSyms = DT.userdataSymbols;

for k,v in pairs(getfenv(0)) do
	if (type(v) == 'function') then
		table.insert(funcSyms, k);
	elseif (type(v) == 'table') then
		if (type(rawget(v,0)) == 'userdata') then
			table.insert(userSyms, k);
		end
	end
end

]] },
{ 'Blizzard_SharedXML\\Shared\\TabSystem\\TabSystemTemplates.lua', [[

local TabSideExtraSpacing = 20;

TabSystemButtonArtMixin = {};

function TabSystemButtonArtMixin:HandleRotation()
	if self.isTabOnTop then
		for _, texture in ipairs(self.RotatedTextures) do
			texture:ClearAllPoints();
			texture:SetRotation(math.pi);
		end

		self.RightActive:SetPoint("BOTTOMLEFT", self, "BOTTOMLEFT", -7, 0);
		self.LeftActive:SetPoint("BOTTOMRIGHT");
		self.MiddleActive:SetPoint("LEFT", self.RightActive, "RIGHT");
		self.MiddleActive:SetPoint("RIGHT", self.LeftActive, "LEFT");

		self.Right:SetPoint("BOTTOMLEFT", self, "BOTTOMLEFT", -6, 0);
		self.Left:SetPoint("BOTTOMRIGHT");
		self.Middle:SetPoint("LEFT", self.Right, "RIGHT");
		self.Middle:SetPoint("RIGHT", self.Left, "LEFT");

		self.LeftHighlight:SetPoint("TOPRIGHT", self.Left);
		self.RightHighlight:SetPoint("TOPLEFT", self.Right);
		self.MiddleHighlight:SetPoint("LEFT", self.Middle, "LEFT");
		self.MiddleHighlight:SetPoint("RIGHT", self.Middle, "RIGHT");
	end
end

function TabSystemButtonArtMixin:GetTextYOffset(isSelected)
	local offset = self.textOffsetY or 0;
	if self.isTabOnTop then
		offset = offset + (isSelected and 0 or -3);
	else
		offset = offset + (isSelected and -3 or 2);
	end

	return offset;
end

function TabSystemButtonArtMixin:SetTabSelected(isSelected)
	self.isSelected = isSelected;

	self.Left:SetShown(not isSelected);
	self.Middle:SetShown(not isSelected);
	self.Right:SetShown(not isSelected);
	self.LeftActive:SetShown(isSelected);
	self.MiddleActive:SetShown(isSelected);
	self.RightActive:SetShown(isSelected);

	local selectedFontObject = self.selectedFontObject or GameFontHighlightSmall;
	local unselectedFontObject = self.unselectedFontObject or GameFontNormalSmall;
	self:SetNormalFontObject(isSelected and selectedFontObject or unselectedFontObject);

	self:SetEnabled(not isSelected and not self:IsForceDisabled());

	self.Text:SetPoint("CENTER", self, "CENTER", 0, self:GetTextYOffset(isSelected));

	local tooltip = GetAppropriateTooltip();
	if tooltip:IsOwned(self) then
		tooltip:Hide();
	end
end

function TabSystemButtonArtMixin:SetTabWidth(width)
	self:SetWidth(width);
end

function TabSystemButtonArtMixin:IsForceDisabled()
	-- Override in your derived Mixin.
	return false, nil;
end

TabSystemButtonMixin = {};

function TabSystemButtonMixin:OnEnter()
	local showErrorText = not self:IsEnabled() and self.errorReason ~= nil and self:GetTabID() ~= self:GetTabSystem().selectedTabID;
	if showErrorText then
		GameTooltip:SetOwner(self, self.tooltipAnchor, self.tooltipAnchorX, self.tooltipAnchorY);
		GameTooltip_AddErrorLine(GameTooltip, self.errorReason);
		if self.tooltipText then
			GameTooltip_AddBlankLineToTooltip(GameTooltip);
			GameTooltip_AddNormalLine(GameTooltip, self.tooltipText);
		end
		GameTooltip:Show();
	elseif self.tooltipText then
		GameTooltip:SetOwner(self, self.tooltipAnchor, self.tooltipAnchorX, self.tooltipAnchorY);
		GameTooltip_AddNormalLine(GameTooltip, self.tooltipText);
		GameTooltip:Show();
	elseif self.Text:IsTruncated() then
		local text = self.Text:GetText();
		if text then
			GameTooltip:SetOwner(self, self.tooltipAnchor, self.tooltipAnchorX, self.tooltipAnchorY);
			GameTooltip_AddNormalLine(GameTooltip, text);
			GameTooltip:Show();
		end
	end
end

function TabSystemButtonMixin:OnLeave()
	GameTooltip_Hide();
end

function TabSystemButtonMixin:OnClick()
	local tabSystem = self:GetTabSystem();

	local wasSelected = self.isSelected;
	local isUserAction = true;
	tabSystem:SetTab(self:GetTabID(), isUserAction);

	-- Only play the sound if the tab was actually selected
	if not wasSelected and self.isSelected then
		tabSystem:PlayTabSelectSound();
	end
end

function TabSystemButtonMixin:Init(tabID, tabText)
	self.tabID = tabID;
	self:HandleRotation();
	self.tabText = tabText;
	self:SetText(tabText);
	self:UpdateTabWidth();
	self:SetTabSelected(false);
end

function TabSystemButtonMixin:SetTooltipText(tooltipText)
	self.tooltipText = tooltipText;
end

function TabSystemButtonMixin:SetTabEnabled(enabled, errorReason)
	self.forceDisabled = not enabled;
	self:SetEnabled(not self:IsForceDisabled() and not self.isSelected);
	local text = not self:IsForceDisabled() and self.tabText or DISABLED_FONT_COLOR:WrapTextInColorCode(self.tabText);
	self.Text:SetText(text);
	self.errorReason = errorReason;
end

function TabSystemButtonMixin:SetTabNotification(showNotification)
	if showNotification then
		if not self.notificationFrame then
			if self.isTabOnTop then
				self.notificationFrame = NotificationUtil.AcquireNotification("TOP", self, "TOP", 0, 10);
			else
				self.notificationFrame = NotificationUtil.AcquireNotification("BOTTOM", self, "BOTTOM", 0, -10);
			end
		end

	elseif self.notificationFrame then
		NotificationUtil.ReleaseNotification(self.notificationFrame);
		self.notificationFrame = nil;
	end
end

function TabSystemButtonMixin:UpdateTabWidth()
	local sidesWidth = self.Left:GetWidth() + self.Right:GetWidth();
	local width = sidesWidth + TabSideExtraSpacing;
	local minTabWidth, maxTabWidth = self:GetTabSystem():GetTabWidthConstraints();
	local textWidth = self.Text:GetWidth() + (self.textPadding or 0);

	if width < textWidth then
		width = textWidth + 10;
	end

	if maxTabWidth and width > maxTabWidth then
		width = maxTabWidth;
		textWidth = width - 10;
	end

	if minTabWidth and width < minTabWidth then
		width = minTabWidth;
		textWidth = width - 10;
	end

	self.Text:SetWidth(textWidth or 0);

	self:SetTabWidth(width);
end

function TabSystemButtonMixin:IsSelected()
	return not not self.isSelected;
end

function TabSystemButtonMixin:IsForceDisabled()
	-- Note: this will intentionally override TabSystemButtonArtMixin.
	return self.forceDisabled, self.errorReason;
end

function TabSystemButtonMixin:GetTooltipText()
	return self.tooltipText;
end

function TabSystemButtonMixin:GetNotificationFrame()
	return self.notificationFrame;
end

function TabSystemButtonMixin:GetTabID()
	return self.tabID;
end

function TabSystemButtonMixin:GetTabSystem()
	return self:GetParent();
end


TabSystemMixin = {};

function TabSystemMixin:OnLoad()
	self.tabs = {};
	self.tabPool = CreateFramePool("BUTTON", self, self.tabTemplate);
end

function TabSystemMixin:AddTab(tabText)
	local tabID = #self.tabs + 1;
	local newTab = self.tabPool:Acquire();
	table.insert(self.tabs, newTab);
	newTab.layoutIndex = tabID;
	newTab:Init(tabID, tabText);
	newTab:Show();
	self:MarkDirty();
	return tabID;
end

-- tabSelectedCallback: function (tabID, isUserAction) -> suppressVisualSelection
function TabSystemMixin:SetTabSelectedCallback(tabSelectedCallback)
	self.tabSelectedCallback = tabSelectedCallback;
end

function TabSystemMixin:SetTab(tabID, isUserAction)
	if not self.tabSelectedCallback(tabID, isUserAction) then
		self:SetTabVisuallySelected(tabID);
	end
end

function TabSystemMixin:SetTabVisuallySelected(tabID)
	self.selectedTabID = tabID;

	for i, tab in ipairs(self.tabs) do
		tab:SetTabSelected(tab:GetTabID() == tabID);
	end
end

function TabSystemMixin:SetTabNotification(tabID, showNotification)
	self.tabs[tabID]:SetTabNotification(showNotification);
end

function TabSystemMixin:SetTabShown(tabID, isShown)
	self.tabs[tabID]:SetShown(isShown);
	self:MarkDirty();
end

function TabSystemMixin:IsTabShown(tabID)
	return self.tabs[tabID]:IsShown();
end

function TabSystemMixin:SetTabEnabled(tabID, enabled, errorReason)
	self.tabs[tabID]:SetTabEnabled(enabled, errorReason);
	self:MarkDirty();
end

function TabSystemMixin:IsTabEnabled(tabID)
	return not self.tabs[tabID]:IsForceDisabled();
end

function TabSystemMixin:GetTabWidthConstraints()
	return self.minTabWidth, self.maxTabWidth;
end

function TabSystemMixin:GetTabButton(tabID)
	return self.tabs[tabID];
end

function TabSystemMixin:PlayTabSelectSound()
	if self.tabSelectSound then
		PlaySound(self.tabSelectSound);
	end
end
]] },
{ 'Blizzard_SharedXML\\Shared\\TabSystem\\TabSystemOwner.lua', [[

TabSystemTrackerMixin = {};

function TabSystemTrackerMixin:OnLoad()
	self:Init();
end

function TabSystemTrackerMixin:Init()
	self.tabbedElements = {};
	self.tabIDToElementSet = {};
	self.tabIDToTabCallback = {};
	self.tabIDToTabDeselectCallback = {};
end

function TabSystemTrackerMixin:AddTab(tabID, ...)
	self.tabIDToElementSet[tabID] = {};

	for i = 1, select("#", ...) do
		self:AddElementToTab(tabID, select(i, ...));
	end
end

function TabSystemTrackerMixin:AddElementToTab(tabID, element)
	table.insert(self.tabbedElements, element);

	local elementSet = GetOrCreateTableEntry(self.tabIDToElementSet, tabID);
	elementSet[element] = true;
end

function TabSystemTrackerMixin:SetTabCallback(tabID, callback)
	self.tabIDToTabCallback[tabID] = callback;
end

function TabSystemTrackerMixin:SetTabDeselectCallback(tabID, callback)
	self.tabIDToTabDeselectCallback[tabID] = callback;
end

function TabSystemTrackerMixin:SetTab(tabID, isUserAction)
	if self.tabID and tabID ~= self.tabID then
		local deselectCallback = self.tabIDToTabDeselectCallback[self.tabID];
		if deselectCallback then
			deselectCallback(isUserAction);
		end
	end

	self.tabID = tabID;

	local elementSet = self.tabIDToElementSet[tabID];
	for i, tabbedElement in ipairs(self.tabbedElements) do
		tabbedElement:SetShown(elementSet and elementSet[tabbedElement]);
	end

	local tabCallback = self.tabIDToTabCallback[tabID];
	if tabCallback then
		tabCallback(isUserAction);
	end
end

function TabSystemTrackerMixin:GetTab()
	return self.tabID;
end

function TabSystemTrackerMixin:GetTabSet()
	return GetKeysArray(self.tabIDToElementSet);
end

function TabSystemTrackerMixin:GetElementsForTab(tabID)
	return GetKeysArray(self.tabIDToElementSet[tabID]);
end


TabSystemOwnerMixin = {};

function TabSystemOwnerMixin:OnLoad()
	self.internalTabTracker = CreateAndInitFromMixin(TabSystemTrackerMixin);
end

function TabSystemOwnerMixin:SetTabSystem(tabSystem)
	self.tabSystem = tabSystem;
	tabSystem:SetTabSelectedCallback(GenerateClosure(self.SetTab, self));
end

function TabSystemOwnerMixin:AddNamedTab(tabName, ...)
	local tabID = self.tabSystem:AddTab(tabName);
	self.internalTabTracker:AddTab(tabID, ...);

	return tabID;
end

function TabSystemOwnerMixin:SetTabCallback(tabID, callback)
	self.internalTabTracker:SetTabCallback(tabID, callback);
end

function TabSystemOwnerMixin:SetTabDeselectCallback(tabID, callback)
	self.internalTabTracker:SetTabDeselectCallback(tabID, callback);
end

function TabSystemOwnerMixin:SetTab(tabID, isUserAction)
	self.internalTabTracker:SetTab(tabID, isUserAction);
	self.tabSystem:SetTabVisuallySelected(tabID);
end

function TabSystemOwnerMixin:GetTab()
	return self.internalTabTracker:GetTab();
end

function TabSystemOwnerMixin:GetTabSet()
	return self.internalTabTracker:GetTabSet();
end

function TabSystemOwnerMixin:GetElementsForTab(tabID)
	return self.internalTabTracker:GetElementsForTab(tabID);
end

function TabSystemOwnerMixin:GetTabButton(tabID)
	return self.tabSystem:GetTabButton(tabID);
end
]] },
{ 'Blizzard_SharedXML\\Shared\\Selector\\Blizzard_SelectorUI.lua', [[

SelectorMixin = {};

function SelectorMixin:OnSelection(selectionIndex)
	if self.selectedCallback ~= nil then
		self.selectedCallback(selectionIndex, self:GetSelection(selectionIndex));
	end

	self:SetSelectedIndex(selectionIndex);
end

function SelectorMixin:SetSelectedIndex(selectionIndex)
	self.selectedIndex = selectionIndex;
	self:UpdateAllSelectedTextures();
end

function SelectorMixin:GetSelectedIndex()
	return self.selectedIndex;
end

function SelectorMixin:UpdateAllSelectedTextures()
	if self.initialized then
		for button in self:EnumerateButtons() do
			button:UpdateSelectedTexture();
		end
	end
end

function SelectorMixin:IsSelected(selectionIndex)
	return selectionIndex == self.selectedIndex;
end

-- callback takes the selectionIndex and the selection.
function SelectorMixin:SetSelectedCallback(callback)
	self.selectedCallback = callback;
end

function SelectorMixin:SetSelectionsArray(selectionsArray)
	local function SelectorGetArraySelectionByIndex(selectionIndex)
		return selectionsArray[selectionIndex];
	end

	local function SelectorGetNumArraySelections()
		return #selectionsArray;
	end

	self:SetSelectionsDataProvider(SelectorGetArraySelectionByIndex, SelectorGetNumArraySelections);
end

function SelectorMixin:SetSelectionsDataProvider(getSelectionByIndex, getNumSelections)
	self.getSelectionByIndex = getSelectionByIndex;
	self.getNumSelections = getNumSelections;
	self:UpdateSelections();
end

function SelectorMixin:GetNumSelections()
	return (self.getNumSelections ~= nil) and self.getNumSelections() or 0;
end

function SelectorMixin:GetSelection(selectionIndex)
	return self.getSelectionByIndex(selectionIndex);
end

function SelectorMixin:SetCustomButtonTemplate(customTemplateType, customButtonTemplate)
	self.templateType = customTemplateType;
	self.buttonTemplate = customButtonTemplate;
end

function SelectorMixin:GetButtonTemplate()
	return self.templateType, self.buttonTemplate;
end

-- Takes the button to setup, the selectionIndex, and the selection.
function SelectorMixin:SetSetupCallback(setupCallback)
	self.setupCallback = setupCallback;
end

function SelectorMixin:GetSetupCallback()
	return self.setupCallback;
end

function SelectorMixin:RunSetup(button, selectionIndex)
	button:Init(self);

	button:SetSelectionIndex(selectionIndex);

	if self.setupCallback ~= nil then
		self.setupCallback(button, selectionIndex, self:GetSelection(selectionIndex));
	end
end

-- Override in your derived mixin.
function SelectorMixin:EnumerateButtons()
	return nil;
end

-- Override in your derived mixin.
function SelectorMixin:UpdateSelections()
end


SelectorButtonMixin = {};

function SelectorButtonMixin:Init(selectorFrame)
	self.selectorFrame = selectorFrame;
end

function SelectorButtonMixin:SetSelectionIndex(selectionIndex)
	self.selectionIndex = selectionIndex;
	self:UpdateSelectedTexture();
end

function SelectorButtonMixin:GetSelectionIndex()
	return self.selectionIndex;
end

function SelectorButtonMixin:SetIconTexture(iconTexture)
	self.Icon:SetTexture(iconTexture);
end

function SelectorButtonMixin:GetIconTexture()
	return self.Icon:GetTexture();
end

function SelectorButtonMixin:UpdateSelectedTexture()
	self.SelectedTexture:SetShown(self:GetSelectorFrame():IsSelected(self.selectionIndex));
end

function SelectorButtonMixin:OnClick()
	self:GetSelectorFrame():OnSelection(self.selectionIndex);
end

function SelectorButtonMixin:GetSelection()
	return self:GetSelectorFrame():GetSelection(self.selectionIndex);
end

function SelectorButtonMixin:GetSelectorFrame()
	return self.selectorFrame;
end
]] },
{ 'Blizzard_SharedXML\\Shared\\Selector\\Blizzard_GridSelectorUI.lua', [[

GridSelectorFrameMixin = {};

function GridSelectorFrameMixin:SetLayout(initialAnchor, layout, count)
	if (self.initialAnchor ~= initialAnchor) or (self.layout ~= layout) or (self.count ~= count) then
		self.initialAnchor = initialAnchor;
		self.layout = layout;
		self.count = count;
		self:MarkGridDirty();
	end
end

function GridSelectorFrameMixin:MarkGridDirty()
	if not self.gridDirty then
		self.gridDirty = true;
		RunNextFrame(GenerateClosure(self.UpdateSelections, self));
	end
end

function GridSelectorFrameMixin:UpdateSelections()
	self:ReleaseAllButtons();

	local selectors = {};
	for selectionIndex = 1, self:GetNumSelections() do
		local selector = self:AcquireButton();
		self:RunSetup(selector, selectionIndex);
		selector:Show();
		table.insert(selectors, selector);
	end

	GridLayoutUtil.ApplyGridLayout(selectors, self.initialAnchor, self.layout);

	self.gridDirty = false;
end

function GridSelectorFrameMixin:AcquireButton()
	if self.selectorButtonPool == nil then
		local templateType, buttonTemplate = self:GetButtonTemplate();
		self.selectorButtonPool = CreateFramePool(templateType, self, buttonTemplate);
	end

	return self.selectorButtonPool:Acquire();
end

function GridSelectorFrameMixin:ReleaseAllButtons()
	if self.selectorButtonPool ~= nil then
		self.selectorButtonPool:ReleaseAll();
	end
end

function GridSelectorFrameMixin:EnumerateButtons()
	return self.selectorButtonPool:EnumerateActive();
end
]] },
{ 'Blizzard_SharedXML\\Shared\\Selector\\Blizzard_ScrollBoxSelector.lua', [[

ScrollBoxSelectorMixin = {};

function ScrollBoxSelectorMixin:OnShow()
	if not self.initialized then
		self:Init();
	end
end

function ScrollBoxSelectorMixin:Init()
	local view = CreateScrollBoxListGridView(self:GetStride());

	local buttonWidth = self:GetButtonWidth();
	local buttonHeight = self:GetButtonHeight();
	view:SetElementSize(buttonWidth, buttonHeight);
	view:SetPadding(self:GetPadding());

	local function InitializeGridSelectorScrollButton(button, selectionIndex)
		self:RunSetup(button, selectionIndex);
	end

	local templateType, buttonTemplate = self:GetButtonTemplate();
	view:SetElementInitializer(buttonTemplate, InitializeGridSelectorScrollButton);

	ScrollUtil.InitScrollBoxListWithScrollBar(self.ScrollBox, self.ScrollBar, view);

	self.initialized = true;

	self:UpdateSelections();
end

function ScrollBoxSelectorMixin:UpdateSelections()
	if self.initialized then
		local dataProvider = CreateIndexRangeDataProvider(self:GetNumSelections());
		self.ScrollBox:SetDataProvider(dataProvider, self.retainScrollPosition);
	end
end

function ScrollBoxSelectorMixin:EnumerateButtons()
	local enumerateFramesIteratorFunction, table, initialIteratorKey = self.ScrollBox:EnumerateFrames();
	local savedKey = initialIteratorKey;
	local function GridSelectorScrollEnumerateButtons(tbl)
		local nextKey, nextValue = enumerateFramesIteratorFunction(tbl, savedKey);
		savedKey = nextKey;
		return nextValue;
	end

	return GridSelectorScrollEnumerateButtons, table, initialIteratorKey;
end

function ScrollBoxSelectorMixin:SetCustomButtonHeight(customButtonHeight)
	self.customButtonHeight = customButtonHeight;
end

function ScrollBoxSelectorMixin:SetCustomButtonWidth(customButtonWidth)
	self.customButtonWidth = customButtonWidth;
end

function ScrollBoxSelectorMixin:GetButtonWidth()
	return self.customButtonWidth or self:GetButtonHeight();
end

function ScrollBoxSelectorMixin:GetButtonHeight()
	return self.customButtonHeight or 36;
end

function ScrollBoxSelectorMixin:SetCustomStride(customStride)
	self.customStride = customStride;
end

function ScrollBoxSelectorMixin:GetStride()
	return self.customStride or 10;
end

function ScrollBoxSelectorMixin:SetCustomPadding(top, bottom, left, right, horizontalSpacing, verticalSpacing)
	self.top = top;
	self.bottom = bottom;
	self.left = left;
	self.right = right;
	self.horizontalSpacing = horizontalSpacing;
	self.verticalSpacing = verticalSpacing;
end

function ScrollBoxSelectorMixin:GetPadding()
	return self.top or 5, self.bottom or 5, self.left or 5, self.right or 5, self.horizontalSpacing or 10, self.verticalSpacing or 10;
end

function ScrollBoxSelectorMixin:AdjustScrollBarOffsets(offsetX, topOffset, bottomOffset)
	self.ScrollBar:SetPoint("TOPRIGHT", offsetX or 0, topOffset or 0);
	self.ScrollBar:SetPoint("BOTTOMRIGHT", offsetX or 0, bottomOffset or 0);
end

function ScrollBoxSelectorMixin:ScrollToSelectedIndex()
	local targetIndex = self:GetSelectedIndex() or 1;
	self:ScrollToElementDataIndex(targetIndex, ScrollBoxConstants.AlignCenter);
end

function ScrollBoxSelectorMixin:ScrollToElementDataIndex(...)
	self.ScrollBox:ScrollToElementDataIndex(...);
end
]] },
{ 'Blizzard_SharedXML\\HelpTip.lua', [=[
--[[
	infoTable = {
		text,									-- also acts as a key for various API, MUST BE SET
		textColor = HIGHLIGHT_FONT_COLOR,
		textJustifyH = "LEFT",
		buttonStyle = HelpTip.ButtonStyle.None	-- button to close the helptip, or no button at all
		targetPoint = HelpTip.Point.BottomEdgeCenter,	-- where at the parent/relativeRegion the helptip should point
		alignment = HelpTip.Alignment.Center,	-- alignment of the helptip relative to the parent/relativeRegion (basically where the arrow is located)
		hideArrow = false,						-- whether to hide the arrow
		offsetX = 0,
		offsetY	= 0,
		cvar, cvarValue,						-- cvar to set when closed by user or from HelpTip:Acknowledge()
		cvarBitfield, bitfieldFlag,				-- cvarbitfield to set when closed by user or from HelpTip:Acknowledge()
		onHideCallback, callbackArg,			-- callback whenever the helptip is closed:  onHideCallback(acknowledged, callbackArg)
		onAcknowledgeCallback					-- callback whenever the helptip is closed by the user clicking its button: onAcknowledgeCallback(callbackArg)
		checkCVars = false,						-- on: helptip will only be shown if the cvar or cvarBitfield is not set
		autoEdgeFlipping = false,				-- on: will flip helptip to opposite edge based on relative region's center vs helptip's center during OnUpdate
		autoHorizontalSlide = false,			-- on: will change the alignment to fit helptip on screen during OnUpdate
		useParentStrata	= false,				-- whether to use parent framestrata
		system = ""								-- reference string
		systemPriority = 0,						-- if a system and a priority is specified, higher priority helptips will close another helptip in that system
		extraRightMarginPadding = 0,			--  extra padding on the right side of the helptip
		acknowledgeOnHide = false,				-- whether to treat a hide as an acknowledge
		handlesGlobalMouseEventCallback	= nil,	-- if a helptip is tied to a drop down set a global mouse callback on the helptip info
		appendFrame = nil,						-- if a helptip needs a custom display you can append your own frame to the text
		appendFrameYOffset = nil,				-- the offset for the vertical anchor for appendFrame
		autoHideWhenTargetHides = false,		-- if the target frame hides, the helptip will hide if this is set and call the onHideCallback with an apprpropriate reason
		ignoreInParentLayout = true,			-- off: if the parent is a layoutFrame helptip will no longer be ignored in the layout process
	}
]]--

HelpTip = { };

-- external use enums

HelpTip.Point = {
	TopEdgeLeft = 1,
	TopEdgeCenter = 2,
	TopEdgeRight = 3,
	BottomEdgeLeft = 4,	
	BottomEdgeCenter = 5,
	BottomEdgeRight = 6,
	RightEdgeTop = 7,
	RightEdgeCenter = 8,
	RightEdgeBottom = 9,
	LeftEdgeTop = 10,
	LeftEdgeCenter = 11,
	LeftEdgeBottom = 12,
};

HelpTip.Alignment = {
	Left = 1,
	Center = 2,
	Right = 3,
	-- Intentional re-use of indices, really just need 3 settings but 5 makes it easier to visualize
	Top = 1,
	Bottom = 3,
};

HelpTip.ButtonStyle = {
	None = 1,
	Close = 2,
	Okay = 3,
	GotIt = 4,
	Next = 5,
	Exit = 6,
};

HelpTip.HideReason = {
	Closed = 1,
	Acknowledged = 2,
	TargetHidden = 3,
}

-- internal use enums

HelpTip.ArrowRotation = {
	Down = 1,
	Left = 2,
	Up = 3,
	Right = 4,
};

-- data

HelpTip.PointInfo = {
	[HelpTip.Point.TopEdgeLeft]		= { arrowRotation = HelpTip.ArrowRotation.Down,	 relativeAnchor = "TOPLEFT",	oppositePoint = HelpTip.Point.BottomEdgeLeft },
	[HelpTip.Point.TopEdgeCenter]	= { arrowRotation = HelpTip.ArrowRotation.Down,  relativeAnchor = "TOP",		oppositePoint = HelpTip.Point.BottomEdgeCenter },
	[HelpTip.Point.TopEdgeRight]	= { arrowRotation = HelpTip.ArrowRotation.Down,  relativeAnchor = "TOPRIGHT",	oppositePoint = HelpTip.Point.BottomEdgeRight },

	[HelpTip.Point.RightEdgeTop]	= { arrowRotation = HelpTip.ArrowRotation.Left,  relativeAnchor = "TOPRIGHT",	oppositePoint = HelpTip.Point.LeftEdgeTop },
	[HelpTip.Point.RightEdgeCenter] = { arrowRotation = HelpTip.ArrowRotation.Left,  relativeAnchor = "RIGHT",		oppositePoint = HelpTip.Point.LeftEdgeCenter },
	[HelpTip.Point.RightEdgeBottom] = { arrowRotation = HelpTip.ArrowRotation.Left,  relativeAnchor = "BOTTOMRIGHT",oppositePoint = HelpTip.Point.LeftEdgeBottom },

	[HelpTip.Point.BottomEdgeRight] = { arrowRotation = HelpTip.ArrowRotation.Up,	 relativeAnchor = "BOTTOMRIGHT",oppositePoint = HelpTip.Point.TopEdgeRight },
	[HelpTip.Point.BottomEdgeCenter]= { arrowRotation = HelpTip.ArrowRotation.Up,	 relativeAnchor = "BOTTOM",		oppositePoint = HelpTip.Point.TopEdgeCenter },
	[HelpTip.Point.BottomEdgeLeft]	= { arrowRotation = HelpTip.ArrowRotation.Up,	 relativeAnchor = "BOTTOMLEFT",	oppositePoint = HelpTip.Point.TopEdgeLeft },

	[HelpTip.Point.LeftEdgeBottom]	= { arrowRotation = HelpTip.ArrowRotation.Right, relativeAnchor = "BOTTOMLEFT",	oppositePoint = HelpTip.Point.RightEdgeBottom },
	[HelpTip.Point.LeftEdgeCenter]	= { arrowRotation = HelpTip.ArrowRotation.Right, relativeAnchor = "LEFT",		oppositePoint = HelpTip.Point.RightEdgeCenter },
	[HelpTip.Point.LeftEdgeTop]		= { arrowRotation = HelpTip.ArrowRotation.Right, relativeAnchor = "TOPLEFT",	oppositePoint = HelpTip.Point.RightEdgeTop },
};

HelpTip.ArrowOffsets = {
	[HelpTip.Alignment.Center]	= { 0,	 5 };
	[HelpTip.Alignment.Left]	= { 35,  5 };
	[HelpTip.Alignment.Right]	= { -35, 5 };
};

HelpTip.ArrowGlowOffsets = { 0, 4 };

HelpTip.DistanceOffsets = {
	[HelpTip.Alignment.Center]	= { 0,	 -20 };
	[HelpTip.Alignment.Left]	= { -35, -20 };
	[HelpTip.Alignment.Right]	= { 35,  -20 };
};

HelpTip.Rotations = {
	[HelpTip.ArrowRotation.Down]	= { modOffsetX = 1,  modOffsetY = -1, swapOffsets = false,	degrees = 0,	anchors = { "BOTTOMLEFT", "BOTTOM", "BOTTOMRIGHT" } },
	[HelpTip.ArrowRotation.Left]	= { modOffsetX = -1, modOffsetY = -1, swapOffsets = true,	degrees = 90,	anchors = { "TOPLEFT", "LEFT", "BOTTOMLEFT" } },
	[HelpTip.ArrowRotation.Up]		= { modOffsetX = 1,	 modOffsetY = 1,  swapOffsets = false,	degrees = 180,	anchors = { "TOPLEFT", "TOP", "TOPRIGHT"}  },
	[HelpTip.ArrowRotation.Right]	= { modOffsetX = 1,	 modOffsetY = -1, swapOffsets = true,	degrees = 270,	anchors = { "TOPRIGHT", "RIGHT", "BOTTOMRIGHT" } },
};

HelpTip.Buttons = {
	[HelpTip.ButtonStyle.None]	= { textWidthAdj = 0,	heightAdj = 0,	parentKey = nil },
	[HelpTip.ButtonStyle.Close]	= { textWidthAdj = -6,	heightAdj = 0,	parentKey = "CloseButton" },
	[HelpTip.ButtonStyle.Okay]	= { textWidthAdj = 0,	heightAdj = 30,	parentKey = "OkayButton", text = OKAY },
	[HelpTip.ButtonStyle.GotIt]	= { textWidthAdj = 0,	heightAdj = 30,	parentKey = "OkayButton", text = HELP_TIP_BUTTON_GOT_IT },
	[HelpTip.ButtonStyle.Next]	= { textWidthAdj = 0,	heightAdj = 30,	parentKey = "OkayButton", text = NEXT },
	[HelpTip.ButtonStyle.Exit]	= { textWidthAdj = 0,	heightAdj = 30,	parentKey = "OkayButton", text = HELP_TIP_EXIT },
};

HelpTip.verticalPadding	 = 31;
HelpTip.minimumHeight	 = 72;
HelpTip.defaultTextWidth = 196;
HelpTip.width = 226;
HelpTip.halfWidth = HelpTip.width / 2;

HelpTip.supressHelpTips = {};

do
	local function HelpTipReset(framePool, frame)
		frame:ClearAllPoints();
		frame:Hide();
		frame:Reset();
	end

	HelpTip.framePool = CreateFramePool("FRAME", nil, "HelpTipTemplate", HelpTipReset);
end

function HelpTip:SetHelpTipsEnabled(flag, enabled)
	HelpTip.supressHelpTips[flag] = enabled or false;
end

function HelpTip:AreHelpTipsEnabled()
	if Kiosk.IsEnabled() then
		return false;
	end

	if GetCVarBool("hideHelptips") then
		return false;
	end

	for flagType, flagValue in pairs(self.supressHelpTips) do
		if not flagValue then
			return false;
		end
	end
	return true;
end

function HelpTip:Show(parent, info, relativeRegion)
	assert(info and info.text, "Invalid helptip info");
	assert((info.bitfieldFlag ~= nil and info.cvarBitfield ~= nil) or (info.bitfieldFlag == nil and info.cvarBitfield == nil));

	if not self:CanShow(info) then
		return false;
	end

	if self:IsShowing(parent, info.text) then
		return true;
	end

	local frame = self.framePool:Acquire();
	frame.width = HelpTip.width + (info.extraRightMarginPadding or 0);
	frame:SetWidth(frame.width);
	frame:Init(parent, info, relativeRegion or parent);
	frame:Show();

	return true;
end

function HelpTip:CanShow(info)
	if not self:AreHelpTipsEnabled() then
		return false;
	end

	if self:IsRestricted(info) then
		return false;
	end

	if info.checkCVars then
		if info.cvar then
			if GetCVar(info.cvar) == info.cvarValue then
				return false;
			end
		end
		if info.cvarBitfield then
			if GetCVarBitfield(info.cvarBitfield, info.bitfieldFlag) then
				return false;
			end
		end
	end

	-- priority
	if info.system and info.systemPriority then
		for frame in self.framePool:EnumerateActive() do
			if frame.info.system == info.system and frame.info.systemPriority then
				if info.systemPriority > frame.info.systemPriority then
					frame:Close();
					-- by design there can only be one such frame, no need to keep going
					break;
				else
					-- higher or equal priority is already shown
					return false;
				end
			end
		end
	end

	return true;
end

function HelpTip:IsRestricted(info)
	if C_PlayerInfo and C_PlayerInfo.IsPlayerInRPE() then
		-- in RPE block almost all helptips
		if info.system == "TutorialSoftTargetInteraction" or info.system == "EditMode" then
			return false;
		end
		if info.text == TALENT_MICRO_BUTTON_NO_HERO_SPEC
		or info.text == TALENT_MICRO_BUTTON_UNSPENT_TALENTS
		or info.text == NPEV2_TALENTS_STARTER_BUILD
		or info.text == TUTORIAL_SUPERTRACK_STEP_1 then
			return false;
		end
		return true;
	end

	return false;
end

function HelpTip:ForceHideAll()
	self:SetHelpTipsEnabled("ForceHideAll", false);
	self.framePool:ReleaseAll();
	self:SetHelpTipsEnabled("ForceHideAll", true);
end

function HelpTip:HideAllSystem(system, text)
	local framesToClose = { };

	for frame in self.framePool:EnumerateActive() do
		if frame:MatchesSystem(system, text) then
			tinsert(framesToClose, frame);
		end
	end

	for i, frame in ipairs(framesToClose) do
		frame:Close();
	end	
end

function HelpTip:HideAll(parent)
	local framesToClose = { };

	for frame in self.framePool:EnumerateActive() do
		if frame:Matches(parent) then
			tinsert(framesToClose, frame);
		end
	end

	for i, frame in ipairs(framesToClose) do
		frame:Close();
	end
end

function HelpTip:Hide(parent, text)
	for frame in self.framePool:EnumerateActive() do
		if frame:Matches(parent, text) then
			frame:Close();
			break;
		end
	end
end

function HelpTip:IsShowing(parent, text)
	for frame in self.framePool:EnumerateActive() do
		if frame:Matches(parent, text) then
			return true;
		end
	end
	return false;
end

function HelpTip:IsShowingAny(parent)
	for frame in self.framePool:EnumerateActive() do
		if frame:Matches(parent) then
			return true;
		end
	end
	return false;
end

function HelpTip:IsShowingAnyInSystem(system)
	for frame in self.framePool:EnumerateActive() do
		if frame.info.system == system then
			return true;
		end
	end
	return false;
end

function HelpTip:Acknowledge(parent, text)
	for frame in self.framePool:EnumerateActive() do
		if frame:Matches(parent, text) then
			frame:Acknowledge();
			break;
		end
	end
end

function HelpTip:AcknowledgeSystem(system, text)
	for frame in self.framePool:EnumerateActive() do
		if frame:MatchesSystem(system, text) then
			frame:Acknowledge();
		end
	end
end

function HelpTip:Release(helpTip)
	self.framePool:Release(helpTip);
end

function HelpTip:IsPointVertical(point)
	return point <= HelpTip.Point.BottomEdgeRight;
end

HelpTipCloseButtonMixin = CreateFromMixins(ButtonStateBehaviorMixin);

function HelpTipCloseButtonMixin:GetAtlas()
	if self:IsDown() then
		return "common-icon-yellowx-down";
	end
	return "common-icon-yellowx";
end

function HelpTipCloseButtonMixin:OnButtonStateChanged()
	self.Texture:SetAtlas(self:GetAtlas(), TextureKitConstants.UseAtlasSize);
end


HelpTipTemplateMixin = { };

local function TransformOffsetsForRotation(offsets, rotationInfo)
	local offsetX = offsets[1];
	local offsetY = offsets[2];
	if rotationInfo.swapOffsets then
		offsetX, offsetY = offsetY, offsetX;
	end
	offsetX = offsetX * rotationInfo.modOffsetX;
	offsetY = offsetY * rotationInfo.modOffsetY;
	return offsetX, offsetY;
end

function HelpTipTemplateMixin:OnLoad()
	self.Arrow.Arrow:ClearAllPoints();
	self.Arrow.Arrow:SetPoint("CENTER");
	self.Arrow.Glow:ClearAllPoints();
	self.acknowledged = false;

	self.OkayButton:SetScript("OnClick", function()
		PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON);
		self:Acknowledge();
	end);

	self.CloseButton:SetScript("OnClick", function()
		PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON);
		self:Acknowledge();
	end);
end

function HelpTipTemplateMixin:OnShow()
	self:RegisterEvent("UI_SCALE_CHANGED");
	self:RegisterEvent("DISPLAY_SIZE_CHANGED");
end

local function AssertMissingInfo(infoText)
	return string.format("Missing info table for helptip: %s", infoText);
end

function HelpTipTemplateMixin:OnHide()
	self:UnregisterEvent("UI_SCALE_CHANGED");
	self:UnregisterEvent("DISPLAY_SIZE_CHANGED");
	
	local info = self.info;
	assertsafe(info, AssertMissingInfo, self.lastInfoText);

	local relativeRegion = self.relativeRegion;
	if relativeRegion then
		FrameWatcher:StopWatchingFrame(relativeRegion);
	end

	if info then
		if not self.acknowledged and info.acknowledgeOnHide then
			self:HandleAcknowledge();
		end
	end

	local hideReason = self:GetHideReason();
	self:SetHideReason(nil);

	-- Have to release before doing callbacks or reentry could happen because of deferred OnShow/OnHide
	local acknowledged = self.acknowledged;
	HelpTip:Release(self);

	if info then
		local appendFrame = info.appendFrame;
		if appendFrame then
			appendFrame:Hide();
			appendFrame:ClearAllPoints();
			appendFrame:SetParent(UIParent);
		end

		if info.onHideCallback then
			info.onHideCallback(acknowledged, info.callbackArg, hideReason);
		end

		if acknowledged and info.onAcknowledgeCallback then
			info.onAcknowledgeCallback(info.callbackArg);
		end
	end
end

function HelpTipTemplateMixin:OnEvent()
	self:Layout();
end

-- this exists because OnHide can be deferred
function HelpTipTemplateMixin:Close()
	self.closed = true;
	self:Hide();
end

function HelpTipTemplateMixin:OnUpdate()
	local rx, ry = self.relativeRegion:GetCenter();

	-- skip this update if relativeRegion's Rect info isn't valid
	-- this can occur if relativeRegion was just instantiated from a pool the same frame as showing this HelpTip
	if not rx or not ry then
		return;
	end

	local targetPoint = self.info.targetPoint;
	local targetAlignment = self.info.alignment;

	if self.info.autoHorizontalSlide then
		-- check right edge first
		local rightEdge = UIParent:GetRight();
		local canFitOnRight = rx + self.width + HelpTip.ArrowOffsets[HelpTip.Alignment.Right][1] < rightEdge;
		if not canFitOnRight then
			if rx + HelpTip.halfWidth < rightEdge then
				targetAlignment = HelpTip.Alignment.Center;
			else
				targetAlignment = HelpTip.Alignment.Right;
			end
		else
			-- left edge
			local leftEdge = UIParent:GetLeft();
			local canFitOnLeft = rx - self.width + HelpTip.ArrowOffsets[HelpTip.Alignment.Left][1] > leftEdge;
			if not canFitOnLeft then
				if rx - HelpTip.halfWidth > leftEdge then
					targetAlignment = HelpTip.Alignment.Center;
				else
					targetAlignment = HelpTip.Alignment.Left;
				end
			end
		end
	end

	if self.info.autoEdgeFlipping then
		local ux, uy = UIParent:GetCenter();
		local useMin;
		if HelpTip:IsPointVertical(targetPoint) then
			useMin = ry <= uy;
		else
			useMin = rx <= ux;
		end
		if useMin then
			targetPoint = min(self.flippedTargetPoint, targetPoint);
		else
			targetPoint = max(self.flippedTargetPoint, targetPoint);
		end
	end

	self:AnchorAndRotate(targetPoint, targetAlignment);
end

function HelpTipTemplateMixin:Init(parent, info, relativeRegion)
	self:SetParent(parent);
	if info.useParentStrata then
		self:SetFrameLevel(9000);
	else
		self:SetFrameStrata("DIALOG");
	end
	self.info = info;
	self.lastInfoText = info.text;
	self.relativeRegion = relativeRegion;
	self.ignoreInLayout = (info.ignoreInParentLayout ~= false);

	if info.autoEdgeFlipping then
		local targetPoint = self:GetTargetPoint();
		local pointInfo = HelpTip.PointInfo[targetPoint];
		self.flippedTargetPoint = pointInfo.oppositePoint;
		self:SetScript("OnUpdate", function() self:OnUpdate(); end);
	end
	if info.autoHorizontalSlide then
		self:SetScript("OnUpdate", function() self:OnUpdate(); end);
	end

	self:AnchorAndRotate();
	self:Layout();
	self:CheckWatchRelativeRegion();
end

function HelpTipTemplateMixin:GetTargetPoint()
	return self.info.targetPoint or HelpTip.Point.BottomEdgeCenter;
end

function HelpTipTemplateMixin:GetAlignment()
	return self.info.alignment or HelpTip.Alignment.Center;
end

function HelpTipTemplateMixin:GetButtonInfo()
	local buttonStyle = self.info.buttonStyle or HelpTip.ButtonStyle.None;
	return HelpTip.Buttons[buttonStyle];
end

function HelpTipTemplateMixin:AnchorAndRotate(overrideTargetPoint, overrideAlignment)
	local baseTargetPoint = self:GetTargetPoint();
	local targetPoint = overrideTargetPoint or baseTargetPoint;
	local alignment = overrideAlignment or self:GetAlignment();
	if targetPoint == self.appliedTargetPoint and alignment == self.appliedAlignment then
		return;
	end

	local pointInfo = HelpTip.PointInfo[targetPoint];
	local rotationInfo = HelpTip.Rotations[pointInfo.arrowRotation];
	-- anchor
	local arrowAnchor = rotationInfo.anchors[alignment];
	local offsetX, offsetY = TransformOffsetsForRotation(HelpTip.DistanceOffsets[alignment], rotationInfo);
	local baseOffsetX = self.info.offsetX or 0;
	local baseOffsetY = self.info.offsetY or 0;
	if overrideTargetPoint and overrideTargetPoint ~= baseTargetPoint then
		if HelpTip:IsPointVertical(targetPoint) then
			baseOffsetY = -baseOffsetY;
		else
			baseOffsetX = -baseOffsetX;
		end
	end
	offsetX = offsetX + baseOffsetX;
	offsetY = offsetY + baseOffsetY;
	self:ClearAllPoints();
	self:SetPoint(arrowAnchor, self.relativeRegion, pointInfo.relativeAnchor, offsetX, offsetY);
	-- arrow
	if self.info.hideArrow then
		self.Arrow:Hide();
	else
		self.Arrow:Show();
		self:RotateArrow(pointInfo.arrowRotation);
		self:AnchorArrow(rotationInfo, alignment);
	end
	self.appliedAlignment = alignment;
	self.appliedTargetPoint = targetPoint;
end

function HelpTipTemplateMixin:Layout()
	local targetPoint = self:GetTargetPoint();
	local pointInfo = HelpTip.PointInfo[targetPoint];
	local buttonInfo = self:GetButtonInfo();

	-- starting defaults
	local textOffsetX = 15;
	local textOffsetY = 1;
	local textWidth = HelpTip.defaultTextWidth;
	local height = HelpTip.verticalPadding;
	-- button
	textWidth = textWidth + buttonInfo.textWidthAdj;
	textOffsetY = textOffsetY + buttonInfo.heightAdj / 2;
	height = height + buttonInfo.heightAdj;
	if buttonInfo.parentKey then
		self[buttonInfo.parentKey]:Show();

		if buttonInfo.text then
			self[buttonInfo.parentKey]:SetText(buttonInfo.text);
		end
		self[buttonInfo.parentKey].HandlesGlobalMouseEvent = self.info.handlesGlobalMouseEventCallback;
	end
	-- set height based on the text
	self:ApplyText();
	self.Text:SetWidth(textWidth);

	local info = self.info;
	local appendFrame = info.appendFrame;
	self.Text:ClearAllPoints();
	if appendFrame then
		self.Text:SetPoint("TOPLEFT", textOffsetX, textOffsetY - 16);
	else
		self.Text:SetPoint("LEFT", textOffsetX, textOffsetY);
	end

	height = height + self.Text:GetHeight();

	if appendFrame then
		appendFrame:ClearAllPoints();
		appendFrame:SetParent(self);

		local anchorOffset = info.appendFrameYOffset or 0;
		appendFrame:SetPoint("TOP", self.Text, "BOTTOM", 0, anchorOffset);
		appendFrame:SetPoint("LEFT", self.Text, "LEFT");
		appendFrame:SetPoint("RIGHT", self.Text, "RIGHT");
		appendFrame:Show();
		height = (height + appendFrame:GetHeight()) - anchorOffset;
	end

	if pointInfo.arrowRotation == HelpTip.ArrowRotation.Left or pointInfo.arrowRotation == HelpTip.ArrowRotation.Right then
		height = max(height, HelpTip.minimumHeight);
	end
	self:SetHeight(height);
end

function HelpTipTemplateMixin:ApplyText()
	local info = self.info;

	self.Text:SetText(info.text);

	local color = info.textColor or HIGHLIGHT_FONT_COLOR;
	self.Text:SetTextColor(color:GetRGB());

	local justifyH = info.textJustifyH;
	if not justifyH then
		if self.Text:GetNumLines() == 1 then
			justifyH = "CENTER";
		else
			justifyH = "LEFT";
		end
	end
	self.Text:SetJustifyH(justifyH);
end

function HelpTipTemplateMixin:AnchorArrow(rotationInfo, alignment)
	local arrowAnchor = rotationInfo.anchors[alignment];
	local offsetX, offsetY = TransformOffsetsForRotation(HelpTip.ArrowOffsets[alignment], rotationInfo);
	self.Arrow:ClearAllPoints();
	self.Arrow:SetPoint("CENTER", self, arrowAnchor, offsetX, offsetY);
end

function HelpTipTemplateMixin:RotateArrow(rotation)
	if self.Arrow.rotation == rotation then
		return;
	end

	local rotationInfo = HelpTip.Rotations[rotation];
	SetClampedTextureRotation(self.Arrow.Arrow, rotationInfo.degrees);
	SetClampedTextureRotation(self.Arrow.Glow, rotationInfo.degrees);
	local offsetX, offsetY = TransformOffsetsForRotation(HelpTip.ArrowGlowOffsets, rotationInfo);
	self.Arrow.Glow:SetPoint("CENTER", self.Arrow.Arrow, "CENTER", offsetX, offsetY);

	self.Arrow.rotation = rotation;
end

function HelpTipTemplateMixin:Acknowledge()
	self:HandleAcknowledge();
	self:Close();
end

function HelpTipTemplateMixin:HandleAcknowledge()
	local info = self.info;
	if info.cvar then
		SetCVar(info.cvar, info.cvarValue);
	end
	if info.cvarBitfield then
		SetCVarBitfield(info.cvarBitfield, info.bitfieldFlag, true);
	end
	self.acknowledged = true;
	self:SetHideReason(HelpTip.HideReason.Acknowledged);
end

function HelpTipTemplateMixin:Reset()
	self.info = nil;
	self.relativeRegion = nil;
	self.closed = false;
	self.acknowledged = false;
	self.CloseButton:Hide();
	self.OkayButton:Hide();
	-- flippity flip settings
	self.appliedTargetPoint = nil;
	self.flippedTargetPoint = nil;
	self.appliedAlignment = nil;
	self:SetScript("OnUpdate", nil);
end

function HelpTipTemplateMixin:Matches(parent, text)
	if self.closed then
		return false;
	end
	local textMatched = not text or self.info.text == text;
	return textMatched and self:GetParent() == parent;
end

function HelpTipTemplateMixin:MatchesSystem(system, text)
	if self.closed then
		return false;
	end
	local textMatched = not text or self.info.text == text;
	return textMatched and self.info.system == system;
end

function HelpTipTemplateMixin:CheckWatchRelativeRegion()
	local relativeRegion = self.relativeRegion;
	if self.info.autoHideWhenTargetHides and relativeRegion then
		FrameWatcher:WatchFrame(relativeRegion, nil, function()
			self:SetHideReason(HelpTip.HideReason.TargetHidden);
			self:Close();
		end);
	end
end

function HelpTipTemplateMixin:GetHideReason()
	return self.hideReason or HelpTip.HideReason.Closed;
end

function HelpTipTemplateMixin:SetHideReason(reason)
	self.hideReason = reason;
end
