	ScrollingEdit_OnTextChanged(self, scrollFrame);
	self.Instructions:SetShown(self:GetText() == "");

	scrollFrame.CharCount:SetText(self:GetMaxLetters() - self:GetNumLetters());

	if scrollFrame.ScrollBar then
