{ 'Blizzard_SharedXML\\MixinUtil.lua', [[
-- The following function is used with permission from Daniel Stephens
-- texture			- Texture
-- canvasFrame      - Canvas Frame (for anchoring)
-- startX,startY    - Coordinate of start of line
-- endX,endY		- Coordinate of end of line
-- lineWidth        - Width of line
-- relPoint			- Relative point on canvas to interpret coords (Default BOTTOMLEFT)
function DrawLine(texture, canvasFrame, startX, startY, endX, endY, lineWidth, lineFactor, relPoint)
	if (not relPoint) then relPoint = "BOTTOMLEFT"; end
	lineFactor = lineFactor * .5;

	-- Determine dimensions and center point of line
	local dx,dy = endX - startX, endY - startY;
	local cx,cy = (startX + endX) / 2, (startY + endY) / 2;

	-- Normalize direction if necessary
	if (dx < 0) then
		dx,dy = -dx,-dy;
	end

	-- Calculate actual length of line
	local lineLength = sqrt((dx * dx) + (dy * dy));

	-- Quick escape if it'sin zero length
	if (lineLength == 0) then
		texture:SetTexCoord(0,0,0,0,0,0,0,0);
		texture:SetPoint("BOTTOMLEFT", canvasFrame, relPoint, cx,cy);
		texture:SetPoint("TOPRIGHT",   canvasFrame, relPoint, cx,cy);
		return;
	end

	-- Sin and Cosine of rotation, and combination (for later)
	local sin, cos = -dy / lineLength, dx / lineLength;
	local sinCos = sin * cos;

	-- Calculate bounding box size and texture coordinates
	local boundingWidth, boundingHeight, bottomLeftX, bottomLeftY, topLeftX, topLeftY, topRightX, topRightY, bottomRightX, bottomRightY;
	if (dy >= 0) then
		boundingWidth = ((lineLength * cos) - (lineWidth * sin)) * lineFactor;
		boundingHeight = ((lineWidth * cos) - (lineLength * sin)) * lineFactor;

		bottomLeftX = (lineWidth / lineLength) * sinCos;
		bottomLeftY = sin * sin;
		bottomRightY = (lineLength / lineWidth) * sinCos;
		bottomRightX = 1 - bottomLeftY;

		topLeftX = bottomLeftY;
		topLeftY = 1 - bottomRightY;
		topRightX = 1 - bottomLeftX;
		topRightY = bottomRightX;
	else
		boundingWidth = ((lineLength * cos) + (lineWidth * sin)) * lineFactor;
		boundingHeight = ((lineWidth * cos) + (lineLength * sin)) * lineFactor;

		bottomLeftX = sin * sin;
		bottomLeftY = -(lineLength / lineWidth) * sinCos;
		bottomRightX = 1 + (lineWidth / lineLength) * sinCos;
		bottomRightY = bottomLeftX;

		topLeftX = 1 - bottomRightX;
		topLeftY = 1 - bottomLeftX;
		topRightY = 1 - bottomLeftY;
		topRightX = topLeftY;
	end

	-- Set texture coordinates and anchors
	texture:ClearAllPoints();
	texture:SetTexCoord(topLeftX, topLeftY, bottomLeftX, bottomLeftY, topRightX, topRightY, bottomRightX, bottomRightY);
	texture:SetPoint("BOTTOMLEFT", canvasFrame, relPoint, cx - boundingWidth, cy - boundingHeight);
	texture:SetPoint("TOPRIGHT",   canvasFrame, relPoint, cx + boundingWidth, cy + boundingHeight);
end

-- Mix this into a Texture to be able to treat it like a line
LineMixin = {};

function LineMixin:SetStartPoint(x, y)
	self.startX, self.startY = x, y;
end

function LineMixin:SetEndPoint(x, y)
	self.endX, self.endY = x, y;
end

function LineMixin:SetThickness(thickness)
	self.thickness = thickness;
end

function LineMixin:Draw()
	local parent = self:GetParent();
	local x, y = parent:GetLeft(), parent:GetBottom();

	self:ClearAllPoints();
	DrawLine(self, parent, self.startX - x, self.startY - y, self.endX - x, self.endY - y, self.thickness or 32, 1);
end

-- Mix this into a FontString to have it animate towards its value, call UpdateAnimatedValue every frame
AnimatedNumericFontStringMixin = {};

-- How long should it take to animate
function AnimatedNumericFontStringMixin:SetAnimatedDurationTimeSec(animatedDurationTimeSec)
	self.animatedDurationTimeSec = animatedDurationTimeSec;
end

function AnimatedNumericFontStringMixin:GetAnimatedDurationTimeSec()
	return self.animatedDurationTimeSec or 1.0;
end

function AnimatedNumericFontStringMixin:SetAnimatedValue(value)
	self.targetAnimatedValue = value;
	if not self.currentAnimatedValue then
		self.currentAnimatedValue = self.targetAnimatedValue;
	end
	self.initialAnimatedValueDelta = math.abs(self.targetAnimatedValue - self.currentAnimatedValue);
end

-- Stops animating the value and just snaps to it
function AnimatedNumericFontStringMixin:SnapToTarget()
	if self.targetAnimatedValue then
		self:SetText(BreakUpLargeNumbers(Round(self.targetAnimatedValue)));
		self.currentAnimatedValue = self.targetAnimatedValue;
		self.targetAnimatedValue = nil;
	end
end

-- Call this every frame
function AnimatedNumericFontStringMixin:UpdateAnimatedValue(elapsed)
	if self.targetAnimatedValue then
		local change = self.initialAnimatedValueDelta * (elapsed / self:GetAnimatedDurationTimeSec());
		if math.abs(self.targetAnimatedValue - self.currentAnimatedValue) <= change then
			self:SnapToTarget();
		else
			local direction = self.targetAnimatedValue > self.currentAnimatedValue and 1 or -1;
			self.currentAnimatedValue = self.currentAnimatedValue + direction * change;

			self:SetText(BreakUpLargeNumbers(Round(self.currentAnimatedValue)));
		end
	end
end

SparseGridMixin = {};

function SparseGridMixin:OnLoad(width, height)
	self.width = width;
	self.height = height;
	self.cells = {};
end

function SparseGridMixin:SetCell(x, y, data)
	if not self:IsInRange(x, y) then
		error("index of out of range");
	end

	local linearIndex = self:CalculateLinearIndex(x, y);
	self.cells[linearIndex] = data;
end

function SparseGridMixin:GetCell(x, y)
	if not self:IsInRange(x, y) then
		error("index of out of range");
	end

	local linearIndex = self:CalculateLinearIndex(x, y);
	return self.cells[linearIndex];
end

function SparseGridMixin:IsInRange(x, y)
	return x > 0 and x <= self.width and y > 0 and y <= self.height;
end

function SparseGridMixin:Clear()
	wipe(self.cells);
end

function SparseGridMixin:CalculateLinearIndex(x, y)
	return x + self.width * (y - 1);
end

-- Mix this in to make an object a doublyLinkedList
DoublyLinkedListMixin = {nodeCount = 0};

function DoublyLinkedListMixin:PushFront(nodeToInsert)
	self:InsertBefore(nodeToInsert, self.front);
end

function DoublyLinkedListMixin:PushBack(nodeToInsert)
	self:InsertAfter(nodeToInsert, self.back);
end

function DoublyLinkedListMixin:PopFront()
	return self:Remove(self.front);
end

function DoublyLinkedListMixin:PopBack()
	return self:Remove(self.back);
end

function DoublyLinkedListMixin:EnumerateNodes()
	local index = 0;
	local currentNode = self.front;

	return function()
		index = index + 1;
		if currentNode then
			local returnNode = currentNode;
			currentNode = currentNode.next;
			return index, returnNode;
		else
			return nil;
		end
	end;
end

function DoublyLinkedListMixin:EnumerateNodesReverse()
	local index = 0;
	local currentNode = self.back;

	return function()
		index = index + 1;
		if currentNode then
			local returnNode = currentNode;
			currentNode = currentNode.prev;
			return index, returnNode;
		else
			return nil;
		end
	end;
end

function DoublyLinkedListMixin:InsertBefore(nodeToInsert, listNode)
	nodeToInsert.next = listNode;

	if listNode then
		if listNode.prev then
			listNode.prev.next = nodeToInsert;
		end

		nodeToInsert.prev = listNode.prev;
		listNode.prev = nodeToInsert;
	end

	if self.front == listNode then
		self.front = nodeToInsert;
	end

	if not self.back then
		self.back = nodeToInsert;
	end

	self.nodeCount = self.nodeCount + 1;
end

function DoublyLinkedListMixin:InsertAfter(nodeToInsert, listNode)
	nodeToInsert.prev = listNode;

	if listNode then
		if listNode.next then
			listNode.next.prev = nodeToInsert;
		end

		nodeToInsert.next = listNode.next;
		listNode.next = nodeToInsert;
	end

	if self.back == listNode then
		self.back = nodeToInsert;
	end

	if not self.front then
		self.front = nodeToInsert;
	end

	self.nodeCount = self.nodeCount + 1;
end

function DoublyLinkedListMixin:Remove(node)
	if node then
		if self.front == node then
			self.front = node.next;
		end

		if self.back == node then
			self.back = node.prev;
		end

		if node.prev then
			node.prev.next = node.next;
		end

		if node.next then
			node.next.prev = node.prev;
		end

		node.prev = nil;
		node.next = nil;

		self.nodeCount = self.nodeCount - 1;
	end

	return node;
end

TextureLoadingGroupMixin = {};

function TextureLoadingGroupMixin:AddTexture(texture)
	self.textures = self.textures or {};
	self.textures[texture] = true;
end

function TextureLoadingGroupMixin:RemoveTexture(texture)
	if self.textures then
		self.textures[texture] = nil;
	end
end

function TextureLoadingGroupMixin:Reset()
	self.textures = nil;
end

function TextureLoadingGroupMixin:EnumerateTextures()
	if self.textures then
		return pairs(self.textures);
	end
	return nop;
end

function TextureLoadingGroupMixin:IsFullyLoaded()
	if self.textures then
		for texture in pairs(self.textures) do
			if not texture:IsObjectLoaded() then
				return false;
			end
		end
	end
	return true;
end

DirtiableMixin = {};

function DirtiableMixin:SetDirtyMethod(method)
	self.dirtyCallback = function()
		method(self);
		self.dirty = nil;
	end;
end

function DirtiableMixin:MarkDirty()
	if not self.dirty then
		RunNextFrame(self.dirtyCallback);
	end

	self.dirty = true;
end

MixinUtil = {};

-- Calls an owned function on each entry of a table of mixin instances, checking that the instance does define that function
function MixinUtil.CallMethodOnAllSafe(instances, methodName, ...)
	if not instances then
		return;
	end

	for _, instance in ipairs(instances) do
		if instance[methodName] then
			instance[methodName](instance, ...);
		end
	end
end

-- Check existence of an element, then invoke the provided method by name with its arguments if it exists.
-- e.g. frame.Text:SetText("text") -> CallMethodSafe(frame.Text, "SetText", "text");
function MixinUtil.CallMethodSafe(element, methodName, ...)
	if element then
		element[methodName](element, ...);
	end
end
]] },
{ 'Blizzard_SharedXML\\DebugBarManager.lua', [[
-- Prevent the DebugBarManager from loading into the secure environment and responding
-- to DISPLAY_SIZE_CHANGED events, calling UpdateUIParentPosition and giving UIParent
-- improper anchoring via GetTotalHeight: this is done in the toc file

DebugBarManager = { };

local debugBars = { };

function DebugBarManager:AddBar(debugBar, priority)
	assert(debugBar and debugBar.GetDebugBarDisplayProperties, "Must have GetDebugBarDisplayProperties function");

	local debugBarInfo = { bar = debugBar, priority = priority or 0 };
	table.insert(debugBars, debugBarInfo);

	self:UpdateAnchors();
end

local sortFunc = function(lhs, rhs)
	if lhs.isAboveWorldFrame ~= rhs.isAboveWorldFrame then
		return lhs.isAboveWorldFrame;
	end
	if lhs.priority ~= rhs.priority then
		return lhs.priority > rhs.priority;
	end
	-- tie breaker
	return tostring(lhs.bar) < tostring(rhs.bar);
end

function DebugBarManager:GetScreenScale()
	if C_Glue.IsOnGlueScreen() then
		return PixelUtil.GetPixelToUIUnitFactor();
	else
		return UIParent:GetScale();
	end
end

function DebugBarManager:GetInternalBarsHeight()
	local debugMenuHeight = DebugMenu and DebugMenu.IsVisible() and DebugMenu.GetMenuHeight() or 0;
	local revealTimeTrackHeight = C_Reveal and C_Reveal:IsCapturing() and C_Reveal:GetTimeTrackHeight() or 0;
	return debugMenuHeight + revealTimeTrackHeight;
end

function DebugBarManager:GetScaledInternalBarsHeight()
	return self:GetInternalBarsHeight() * self:GetScreenScale();
end

function DebugBarManager:CalculatePositions()
	for i, debugBarInfo in ipairs(debugBars) do
		local isShown, isAboveWorldFrame = debugBarInfo.bar:GetDebugBarDisplayProperties();
		debugBarInfo.isShown = isShown;
		debugBarInfo.isAboveWorldFrame = isAboveWorldFrame;
	end

	table.sort(debugBars, sortFunc);

	local scale = self:GetScreenScale();
	scale = math.min(scale, 1);
	local internalHeight = self:GetInternalBarsHeight();
	local addedHeight = 0;
	local aboveWorldFrameHeight = 0;

	for i, debugBarInfo in ipairs(debugBars) do
		if debugBarInfo.isShown then
			debugBarInfo.bar:SetScale(scale);
			debugBarInfo.bar:ClearAllPoints();
			debugBarInfo.bar:SetPoint("TOPLEFT", 0, -internalHeight - addedHeight);
			debugBarInfo.bar:SetPoint("TOPRIGHT", 0, -internalHeight - addedHeight);
			local height = debugBarInfo.bar:GetHeight();
			addedHeight = addedHeight + height;
			if debugBarInfo.isAboveWorldFrame then
				aboveWorldFrameHeight = aboveWorldFrameHeight + height;
			end
		end
	end

	if WorldFrame then
		if aboveWorldFrameHeight > 0 then
			local offset = internalHeight + aboveWorldFrameHeight;
			WorldFrame:SetPoint("TOPLEFT", 0, -offset * scale);
		else
			WorldFrame:SetPoint("TOPLEFT");
		end
	end

	self.totalHeight = internalHeight + addedHeight;
end

function DebugBarManager:GetTotalHeight()
	if not self.totalHeight then
		self:CalculatePositions();
	end
	return self.totalHeight;
end

function DebugBarManager:UpdateAnchors()
	self:CalculatePositions();
	if UpdateUIParentPosition then
		UpdateUIParentPosition();
	end
	if DeveloperConsole then
		DeveloperConsole:UpdateAnchors();
	end
end

do
	if DebugMenu or C_Reveal then
		EventRegistry:RegisterFrameEvent("UI_SCALE_CHANGED");
		EventRegistry:RegisterCallback("UI_SCALE_CHANGED", DebugBarManager.UpdateAnchors, DebugBarManager);
		EventRegistry:RegisterFrameEvent("DISPLAY_SIZE_CHANGED");
		EventRegistry:RegisterCallback("DISPLAY_SIZE_CHANGED", DebugBarManager.UpdateAnchors, DebugBarManager);
		if C_Glue.IsOnGlueScreen() then
			local watcherFrame = CreateFrame("FRAME");
			watcherFrame:SetScript("OnUpdate", function() DebugBarManager:UpdateAnchors(); end);
		else
			if C_EventUtils.IsEventValid("DEBUG_MENU_TOGGLED") then
				EventRegistry:RegisterFrameEvent("DEBUG_MENU_TOGGLED");
				EventRegistry:RegisterCallback("DEBUG_MENU_TOGGLED", DebugBarManager.UpdateAnchors, DebugBarManager);
			end
			if C_EventUtils.IsEventValid("REVEAL_CAPTURE_TOGGLED") then
				EventRegistry:RegisterFrameEvent("REVEAL_CAPTURE_TOGGLED");
				EventRegistry:RegisterCallback("REVEAL_CAPTURE_TOGGLED", DebugBarManager.UpdateAnchors, DebugBarManager);
			end
		end
	end
end
]] },
{ 'Blizzard_SharedXML\\PropertyBindingMixin.lua', [[
PropertyBindingMixin = {};

function PropertyBindingMixin:RegisterStateUpdateEvent(event, optionalCallback)
	self.stateUpdateEvents = self.stateUpdateEvents or {};
	self.stateUpdateEvents[event] = optionalCallback or self.UpdateVisibleState;
	self:RegisterEvent(event); -- NOTE: Depends on this being mixed into a frame
end

function PropertyBindingMixin:UnregisterStateUpdateEvent(event)
	local events = self.stateUpdateEvents;
	if events then
		events[event] = nil;
		self:UnregisterEvent(event); -- NOTE: Depends on this being mixed into a frame
	end
end

function PropertyBindingMixin:RegisterPropertyChangeHandler(event, optionalCallback)
	self.propertyChangeEvents = self.propertyChangeEvents or {};
	self.propertyChangeEvents[event] = optionalCallback or self.UpdateVisibleState;
end

function PropertyBindingMixin:UnregisterPropertyChangeHandler(event)
	local events = self.propertyChangeEvents;
	if events then
		self.propertyChangeEvents[event] = nil;
	end
end

do
	local function FireCallback(propertyBinding, call, ...)
		if call then
			-- TODO: Handle re-entrancy (cannot register, unregister at this point, need to queue)
			call(propertyBinding, ...);
		end
	end

	local function CheckFireCallback(propertyBinding, container, containerKey, ...)
		local call = container and container[containerKey];
		if call then
			FireCallback(propertyBinding, call, ...);
		end
	end

	-- NOTE: Depends on this being mixed into a frame
	function PropertyBindingMixin:OnEvent(event, ...)
		CheckFireCallback(self, self.stateUpdateEvents, event, ...);
	end

	function PropertyBindingMixin:OnPropertyChanged(event, ...)
		CheckFireCallback(self, self.propertyChangeEvents, event, ...);
	end
end

function PropertyBindingMixin:AddStateTooltipString(stateValue, tooltipString)
	self.tooltipStrings = self.tooltipStrings or {};
	self.tooltipStrings[stateValue] = tooltipString;
end

function PropertyBindingMixin:GetStateTooltipString(stateValue)
	return self.tooltipStrings and self.tooltipStrings[stateValue] or "";
end

function PropertyBindingMixin:SetTooltipFunction(tooltipFunction)
	self.tooltipFunction = tooltipFunction;
end

function PropertyBindingMixin:GetTooltipFunction()
	return self.tooltipFunction;
end

function PropertyBindingMixin:SetAccessorFunction(accessor)
	self.shouldPassSelfToAccessor = false;
	self.accessor = accessor;
end

function PropertyBindingMixin:SetAccessorFunctionThroughSelf(accessor)
	self.shouldPassSelfToAccessor = true;
	self.accessor = accessor;
end

function PropertyBindingMixin:SetMutatorFunction(mutator)
	self.shouldPassSelfToMutator = false;
	self.mutator = mutator;
end

function PropertyBindingMixin:SetMutatorFunctionThroughSelf(mutator)
	self.shouldPassSelfToMutator = true;
	self.mutator = mutator;
end

function PropertyBindingMixin:CallMutator(...)
	if self.shouldPassSelfToMutator then
		return self:mutator(...);
	else
		return self.mutator(...);
	end
end

function PropertyBindingMixin:CallAccessor(...)
	if self.shouldPassSelfToAccessor then
		return self:accessor(...);
	else
		return self.accessor(...);
	end
end

function PropertyBindingMixin:SetVisibilityQueryFunction(isVisible)
	assert(type(isVisible) == "function");
	self.isVisible = isVisible;
end

function PropertyBindingMixin:CallVisibilityQuery()
	if self.isVisible then
		return self:isVisible();
	end

	return true;
end

function PropertyBindingMixin:UpdateVisibleState()
	local show = self:CallVisibilityQuery();
	self:SetShown(show);
	return show;
end

function PropertyBindingMixin:SetTooltip(state)
	self.tooltipFrame:ClearLines();
	self.tooltipFrame:SetOwner(self, self.tooltipPoint or "ANCHOR_RIGHT");

	local tooltipFunction = self:GetTooltipFunction();
	local tooltipText = tooltipFunction and tooltipFunction(state) or self:GetStateTooltipString(state);

	GameTooltip_SetTitle(self.tooltipFrame, tooltipText);
	self.tooltipFrame:Show();
end

function PropertyBindingMixin:UpdateTooltipForState(state)
	if self.tooltipFrame and self.tooltipFrame:GetOwner() == self then
		self:SetTooltip(state);
	end
end

function PropertyBindingMixin:OnEnter()
	if self.tooltipFrame then
		self:SetTooltip(self:CallAccessor());
	end
end

function PropertyBindingMixin:OnLeave()
	if self.tooltipFrame then
		self.tooltipFrame:Hide();
	end
end]] },
{ 'Blizzard_SharedXML\\PropertyButton.lua', [[
PropertyButtonMixin = {};

function PropertyButtonMixin:OnLoad()
	if self.fixedWidth then
		self:SetWidth(self.fixedWidth);
	end

	if self.fixedHeight then
		self:SetHeight(self.fixedHeight);
	end

	if self.iconKey then
		self.Icon = self:CreateTexture(nil, "OVERLAY");

		if self.fixedIconWidth and self.fixedIconHeight then
			self.Icon:SetSize(self.fixedIconWidth, self.fixedIconHeight);
		end

		self.Icon:SetPoint("CENTER");
	end

	if self.normalAtlas then
		self:SetNormalAtlas(self.normalAtlas);
	end

	if self.pushedAtlas then
		self:SetPushedAtlas(self.pushedAtlas);
	end

	self:UpdateHighlight();
end

function PropertyButtonMixin:AddStateAtlas(stateValue, atlas)
	self.stateAtlases = self.stateAtlases or {};
	self.stateAtlases[stateValue] = atlas;
end

function PropertyButtonMixin:AddStateAtlasFallback(atlas)
	self.stateAtlasFallback = atlas;
end

function PropertyButtonMixin:GetStateAtlas(stateValue)
	if self.stateAtlases and self.stateAtlases[stateValue] then
		return self.stateAtlases[stateValue];
	elseif self.stateAtlasFallback then
		return self.stateAtlasFallback;
	else
		return "";
	end
end

function PropertyButtonMixin:SetIconToState(state)
	if self.Icon then
		self.Icon:SetAtlas(self:GetStateAtlas(state));
	end

	self:UpdateHighlight(state);
end

function PropertyButtonMixin:UpdateHighlight(state)
	-- If this wasn't already using a fixed highlight, potentially set up highlight from this icon
	if self:HasHighlightAtlas() then
		self:SetHighlight(self.highlightAtlas);
	else
		if self:IsUsingIconAsHighlight() then
			self:SetHighlight(self:GetStateAtlas(state));
			self:GetHighlightTexture():SetAlpha(.7); -- TODO: Drive from property on frame?  All icon highlights currently at 70%
		else
			self:ClearHighlight();
		end
	end

	-- Highlight may not exist, see if this is actually required
	if self.needsHighlightAnchorUpdate then
		self.needsHighlightAnchorUpdate = nil;
		local highlightTexture = self:GetHighlightTexture();
		if highlightTexture then
			highlightTexture:ClearAllPoints();
			highlightTexture:SetAllPoints(self:IsUsingIconAsHighlight() and self.Icon or self);
		end
	end
end

function PropertyButtonMixin:SetHighlight(highlight)
	if highlight then
		self:SetHighlightAtlas(highlight, "ADD");
	else
		self:ClearHighlight();
	end
end

function PropertyButtonMixin:ClearHighlight()
	self:ClearHighlightTexture();
end

function PropertyButtonMixin:SetIconStateQueryFunction(iconStateQuery)
	self.iconStateQuery = iconStateQuery;
end

function PropertyButtonMixin:SetUseIconAsHighlight(useIconAsHighlight)
	if self.useIconAsHighlight ~= useIconAsHighlight then
		self.useIconAsHighlight = useIconAsHighlight;
		self.needsHighlightAnchorUpdate = true;
	end
end

function PropertyButtonMixin:IsUsingIconAsHighlight()
	return self.useIconAsHighlight;
end

function PropertyButtonMixin:HasHighlightAtlas()
	return self.highlightAtlas ~= nil and self.highlightAtlas ~= "";
end

function PropertyButtonMixin:OnClick()
	if self.customToggleFunctionName then
		self[self.customToggleFunctionName](self);
	else
		self:CallMutator(not self:CallAccessor());
	end
end

function PropertyButtonMixin:OnMouseDown()
	if self.Icon then
		local alpha = self.iconPushedAlpha or 1;
		local offsetX = self.iconPushedOffsetX or -1;
		local offsetY = self.iconPushedOffsetY or -1;

		self.Icon:SetAlpha(alpha);
		self.Icon:SetPoint("CENTER", self, "CENTER", offsetX, offsetY);
	end
end

function PropertyButtonMixin:OnMouseUp()
	if self.Icon then
		local alpha = self.iconNormalAlpha or 1;

		self.Icon:SetAlpha(alpha);
		self.Icon:SetPoint("CENTER", self, "CENTER", 0, 0);
	end
end

function PropertyButtonMixin:UpdateVisibleState()
	if PropertyBindingMixin.UpdateVisibleState(self) then
		local state = self:CallAccessor();
		self:SetIconToState(state);
		self:UpdateTooltipForState(state);
	end
end]] },
