{ 'Blizzard_SharedXMLBase\\ErrorUtil.lua', [[
function CallErrorHandler(...)
	SetErrorCallstackHeight(GetCallstackHeight() - 1); -- report error from the previous function
	local result = geterrorhandler()(...);
	SetErrorCallstackHeight(nil);
	return result;
end

function assertsafe(cond, msgStringOrFunction, ...)
	if not cond then
		local error = msgStringOrFunction or "non-fatal assertion failed";
		if type(msgStringOrFunction) == 'string' and select('#', ...) > 0 then
			error = msgStringOrFunction:format(...);
		elseif type(msgStringOrFunction) == 'function' then
			error = msgStringOrFunction(...);
		end

		SetErrorCallstackHeight(GetCallstackHeight() - 1); -- report error from the previous function
		if geterrorhandler() then
			geterrorhandler()(error);
		elseif ProcessExceptionClient then
			local framesToSkip = 1;
			ProcessExceptionClient(error, error, framesToSkip);

		end
		SetErrorCallstackHeight(nil);
	end

	-- Parity with regular 'assert' which returns the input.
	return cond;
end

function assertf(cond, msgStringOrFunction, ...)
	if not cond then
		local error = msgStringOrFunction or "non-fatal assertion failed";
		if type(msgStringOrFunction) == 'string' and select('#', ...) > 0 then
			error = msgStringOrFunction:format(...);
		elseif type(msgStringOrFunction) == 'function' then
			error = msgStringOrFunction(...);
		end

		assert(cond, error);
	end

	-- Parity with regular 'assert' which returns the input.
	return cond;
end
]] },
{ 'Blizzard_SharedXMLBase\\Mixin.lua', [[

local select = select;
local pairs = pairs;

local PrivateMixin = Mixin;
local PrivateCreateFromMixins = CreateFromMixins;

function CreateAndInitFromMixin(mixin, ...)
	local object = PrivateCreateFromMixins(mixin);
	object:Init(...);
	return object;
end

-- Note: This should only be used for security purposes during the initial load process in-game.
function CreateSecureMixinCopy(mixin)
	local mixinCopy = PrivateMixin({}, mixin);
	setmetatable(mixinCopy, { __metatable = false, });
	return mixinCopy;
end

-- Secure Mixins
-- where ... are the mixins to mixin
function SecureMixin(object, ...)
	if ( not issecure() ) then
		return;
	end

	for i = 1, select("#", ...) do
		local mixin = select(i, ...);
		for k, v in pairs(mixin) do
			object[k] = v;
		end
	end

	return object;
end

-- This is Private because we need a pristine copy to reference in CreateFromSecureMixins.
local SecureMixinPrivate = SecureMixin;

-- where ... are the mixins to mixin
function CreateFromSecureMixins(...)
	if ( not issecure() ) then
		return;
	end

	return SecureMixinPrivate({}, ...)
end

function ApplySecureDelegatesToTable(tbl)
	for key, value in pairs(tbl) do
		if type(value) == "function" then
			local originalFunction = value;
			tbl[key] = CreateSecureDelegate(originalFunction);
		end
	end
end
]] },
{ 'Blizzard_SharedXMLBase\\TableUtil.lua', [=[

local tRemove = table.remove;
local tInsert = table.insert;
local tWipe = table.wipe;

TableUtil = {};

TableUtil.Constants =
{
	AssociativePriorityTable = true,
	ArraylikePriorityTable = false,
	IsIndexTable = true,
};

-- Global aliases for backwards compatibility.
tIndexOf = table.indexof;
tContains = table.contains;
CountTable = table.count;
TableIsEmpty = table.isempty;
tUnorderedRemove = table.removeunordered;
tDeleteItem = table.removevalue;
GetKeysArray = table.keys;
GetValuesArray = table.values;

function ipairs_reverse(table)
	local function Enumerator(table, index)
		index = index - 1;
		local value = table[index];
		if value ~= nil then
			return index, value;
		end
	end
	return Enumerator, table, #table + 1;
end

function CreateTableEnumerator(tbl, minIndex, maxIndex)
	minIndex = minIndex and (minIndex - 1) or 0;
	maxIndex = maxIndex or math.huge;

	local function Enumerator(tbl, index)
		index = index + 1;
		if index <= maxIndex then
			local value = tbl[index];
			if value ~= nil then
				return index, value;
			end
		end
	end

	return Enumerator, tbl, minIndex;
end

function CreateTableReverseEnumerator(tbl, minIndex, maxIndex)
	minIndex = minIndex or 1;
	maxIndex = (maxIndex or #tbl) + 1;

	local function Enumerator(tbl, index)
		index = index - 1;
		if index >= minIndex then
			local value = tbl[index];
			if value ~= nil then
				return index, value;
			end
		end
	end

	return Enumerator, tbl, maxIndex;
end

function TableUtil.SafeCountTable(tbl, isIndexTable)
	if tbl == nil then
		return 0;
	end

	if isIndexTable then
		return #tbl;
	end

	return table.count(tbl);
end

function TableUtil.SafeCountIndexTable(tbl)
	local isIndexTable = true;
	return TableUtil.SafeCountTable(tbl, isIndexTable);
end

function TableUtil.ContainsAllKeys(lhsTable, rhsTable)
	for key, _ in pairs(lhsTable) do
		if rhsTable[key] == nil then
			return false;
		end
	end
	-- Check for any keys that are in rhsTable and not lhsTable.
	for key, _ in pairs(rhsTable) do
		if lhsTable[key] == nil then
			return false;
		end
	end
	return true;
end

function TableUtil.CompareValuesAsKeys(lhsTable, rhsTable, valueToKeyOp)
	local lhsKeys = CopyTransformedValuesAsKeys(lhsTable, valueToKeyOp);
	local rhsKeys = CopyTransformedValuesAsKeys(rhsTable, valueToKeyOp);
	return TableUtil.ContainsAllKeys(lhsKeys, rhsKeys)
end

-- This is a deep compare on the values of the table (based on depth) but not a deep comparison
-- of the keys, as this would be an expensive check and won't be necessary in most cases.
function tCompare(lhsTable, rhsTable, depth)
	depth = depth or 1;
	for key, value in pairs(lhsTable) do
		if type(value) == "table" then
			local rhsValue = rhsTable[key];
			if type(rhsValue) ~= "table" then
				return false;
			end
			if depth > 1 then
				if not tCompare(value, rhsValue, depth - 1) then
					return false;
				end
			end
		elseif value ~= rhsTable[key] then
			return false;
		end
	end

	-- Check for any keys that are in rhsTable and not lhsTable.
	for key, value in pairs(rhsTable) do
		if lhsTable[key] == nil then
			return false;
		end
	end

	return true;
end

function tInvert(tbl)
	local inverted = {};
	for k, v in pairs(tbl) do
		inverted[v] = k;
	end
	return inverted;
end

function tInvertToArray(tbl)
	local index = 1;
	local copy = {};
	for k in pairs(tbl) do
		copy[k] = index;
		index = index + 1;
	end
	return tInvert(copy);
end

function TableUtil.TrySet(tbl, key)
	if not tbl[key] then
		tbl[key] = true;
		return true;
	end
	return false;
end

function TableUtil.CopyUnique(tbl, isIndexTable)
	local found = {};
	local function FilterPredicate(value)
		return TableUtil.TrySet(found, value);
	end

	return tFilter(tbl, FilterPredicate, isIndexTable);
end

function TableUtil.CopyUniqueByPredicate(tbl, isIndexTable, unaryPredicate)
	local found = {};
	local function FilterPredicate(value)
		return TableUtil.TrySet(found, unaryPredicate(value));
	end

	return tFilter(tbl, FilterPredicate, isIndexTable);
end

function tFilter(tbl, pred, isIndexTable)
	local out = {};

	if (isIndexTable) then
		local currentIndex = 1;
		for i, v in ipairs(tbl) do
			if (pred(v)) then
				out[currentIndex] = v;
				currentIndex = currentIndex + 1;
			end
		end
	else
		for k, v in pairs(tbl) do
			if (pred(v)) then
				out[k] = v;
			end
		end
	end

	return out;
end

function tAppendAll(table, addedArray)
	for i, element in ipairs(addedArray) do
		tinsert(table, element);
	end
end

function tInsertUnique(tbl, item)
	if not tContains(tbl, item) then
		table.insert(tbl, item);
		return #tbl;
	end
	return nil;
