function Accumulate(tbl)
	local count = 0;
	for k, v in pairs(tbl) do
		count = count + v;
	end
	return count;
end

function AccumulateOp(tbl, op)
	local count = 0;
	for k, v in pairs(tbl) do
		count = count + op(v);
	end
	return count;
end

function TableUtil.Execute(tbl, op)
	for k, v in pairs(tbl) do
		op(v);
	end
end

function TableUtil.ExecuteUntil(tbl, op)
	for k, v in pairs(tbl) do
		local operationResult = op(v);
		if operationResult then
			return operationResult;
		end
	end

	return nil;
end

function TableUtil.Transform(tbl, op)
	local result = {};
	for k, v in pairs(tbl) do
		table.insert(result, op(v));
	end
	return result;
end

-- Returns the value in a table deemed smallest by evaluating each value returned by the op function parameter.
-- The return of the op function must return a number.
function TableUtil.FindMin(tbl, op)
	local result = nil;
	local min = math.huge;
	for k, v in pairs(tbl) do
		local value = op(v);
		if value < min then
			min = value;
			result = v;
		end
	end
	return result;
end

-- Returns the value in a table deemed largest by evaluating each value returned by the op function parameter.
-- The return of the op function must return a number.
function TableUtil.FindMax(tbl, op)
	local result = nil;
	local max = -math.huge;
	for k, v in pairs(tbl) do
		local value = op(v);
		if value > max then
			max = value;
			result = v;
		end
	end
	return result;
end

function ContainsIf(tbl, pred)
	for k, v in pairs(tbl) do
		if (pred(v)) then
			return true;
		end
	end

	return false;
end

function FindInTable(tbl, value)
	for k, v in pairs(tbl) do
		if v == value then
			return k, v;
		end
	end

	return nil;
end

function FindInTableIf(tbl, pred)
	for k, v in pairs(tbl) do
		if (pred(v)) then
