{ 'Blizzard_SharedXMLBase\\ExportUtil.lua', [[

-- Utility for compressing and uncompressing data into strings for export and import.

ExportUtil = {};

local BitsPerChar = 6;

local function MakeBase64ConversionTable()
	local base64ConversionTable = {};
	base64ConversionTable[0] = 'A';
	for num = 1, 25 do
		table.insert(base64ConversionTable, string.char(65 + num));
	end

	for num = 0, 25 do
		table.insert(base64ConversionTable, string.char(97 + num));
	end

	for num = 0, 9 do
		table.insert(base64ConversionTable, tostring(num));
	end

	table.insert(base64ConversionTable, '+');
	table.insert(base64ConversionTable, '/');
	return base64ConversionTable;
end

local NumberToBase64CharConversionTable = MakeBase64ConversionTable();
local Base64CharToNumberConversionTable = tInvert(MakeBase64ConversionTable());

function ExportUtil.ConvertToBase64(dataEntries)
	local exportString = "";
	local currentValue = 0;
	local currentReservedBits = 0;
	local totalBits = 0;
	for i, dataEntry in ipairs(dataEntries) do
		local remainingValue = dataEntry.value;
		local remainingRequiredBits = dataEntry.bitWidth;
		-- TODO: bit.lshift doesnt work with > 32 bits.  Maybe use maxValue = 2^X instead?
		local maxValue = bit.lshift(1, remainingRequiredBits);
		if remainingValue >= maxValue then
			error(("Data entry has higher value than storable in bitWidth. (%d in %d bits)"):format(remainingValue, remainingRequiredBits));
			return "";
		end

		totalBits = totalBits + remainingRequiredBits;
		while remainingRequiredBits > 0 do
			local spaceInCurrentValue = (BitsPerChar - currentReservedBits);
			local maxStorableValue = bit.lshift(1, spaceInCurrentValue);
			local remainder = remainingValue % maxStorableValue;
			remainingValue = bit.rshift(remainingValue, spaceInCurrentValue);
			currentValue = currentValue + bit.lshift(remainder, currentReservedBits);

			if spaceInCurrentValue > remainingRequiredBits then
				currentReservedBits = (currentReservedBits + remainingRequiredBits) % BitsPerChar;
				remainingRequiredBits = 0;
			else
				exportString = exportString..NumberToBase64CharConversionTable[currentValue];
				currentValue = 0;
				currentReservedBits = 0;
				remainingRequiredBits = remainingRequiredBits - spaceInCurrentValue;
			end
		end
	end

	if currentReservedBits > 0 then
		exportString = exportString..NumberToBase64CharConversionTable[currentValue];
	end

	return exportString;
end

function ExportUtil.ConvertFromBase64(exportString)
	local dataValues = {};
	for i = 1, #exportString do
		table.insert(dataValues, Base64CharToNumberConversionTable[string.sub(exportString, i, i)]);
	end

	return dataValues;
end

function ExportUtil.MakeExportDataStream()
	return CreateAndInitFromMixin(ExportDataStreamMixin);
end

function ExportUtil.MakeImportDataStream(exportString)
	return CreateAndInitFromMixin(ImportDataStreamMixin, exportString);
end


ExportDataStreamMixin = {};

function ExportDataStreamMixin:Init()
	self.dataEntries = {};
end

function ExportDataStreamMixin:AddValue(bitWidth, value)
	table.insert(self.dataEntries, { bitWidth = bitWidth, value = value, });
end

function ExportDataStreamMixin:GetExportString()
	return ExportUtil.ConvertToBase64(self.dataEntries);
end

ImportDataStreamMixin = {};

function ImportDataStreamMixin:Init(exportString)
	self.dataValues = ExportUtil.ConvertFromBase64(exportString);
	self.currentIndex = 1;
	self.currentExtractedBits = 0;
	self.currentRemainingValue = self.dataValues[1];
end

function ImportDataStreamMixin:ExtractValue(bitWidth)
	if self.currentIndex > #self.dataValues then
		return nil;
	end

	local value = 0;
	local bitsNeeded = bitWidth;
	local extractedBits = 0;
	while bitsNeeded > 0 do
		local remainingBits = BitsPerChar - self.currentExtractedBits;
		local bitsToExtract = math.min(remainingBits, bitsNeeded);
		self.currentExtractedBits = self.currentExtractedBits + bitsToExtract;
		local maxStorableValue = bit.lshift(1, bitsToExtract);
		local remainder = self.currentRemainingValue % maxStorableValue;
		self.currentRemainingValue = bit.rshift(self.currentRemainingValue, bitsToExtract);
		value = value + bit.lshift(remainder, extractedBits);
		extractedBits = extractedBits + bitsToExtract;
		bitsNeeded = bitsNeeded - bitsToExtract;

		if bitsToExtract < remainingBits then
			break;
		elseif bitsToExtract >= remainingBits then
			self.currentIndex = self.currentIndex + 1;
			self.currentExtractedBits = 0;
			self.currentRemainingValue = self.dataValues[self.currentIndex];
		end
	end

	return value;
end

function ImportDataStreamMixin:GetNumberOfBits()
	return BitsPerChar * getn(self.dataValues);
end

]] },
{ 'Blizzard_SharedXMLBase\\Rectangle.lua', [[
RectangleMixin = {};

function CreateRectangle(left, right, top, bottom)
	local rectangle = CreateFromMixins(RectangleMixin);
	rectangle:OnLoad(left, right, top,  bottom);
	return rectangle;
end

function RectangleMixin:OnLoad(left, right, top, bottom)
	self:SetSides(left or 0.0, right or 0.0, top or 0.0, bottom or 0.0);
end

function RectangleMixin:SetSides(left, right, top, bottom)
	self.left = left;
	self.right = right;
	self.top = top;
	self.bottom = bottom;
end

function RectangleMixin:Reset()
	self.left = 0.0;
	self.right = 0.0;
	self.top = 0.0;
	self.bottom = 0.0;
end

function RectangleMixin:Stretch(x, y)
	self:Adjust(-x, x, -y, y);
end

function RectangleMixin:Move(x, y)
	self:Adjust(x, x, y, y);
end

function RectangleMixin:Adjust(left, right, top, bottom)
	self.left = self.left + left;
	self.right = self.right + right;
	self.top = self.top + top;
	self.bottom = self.bottom + bottom;
end

function RectangleMixin:IsEmpty()
	return self.left == self.right or self.top == self.bottom;
end

function RectangleMixin:IsInsideOut()
	return self.left > self.right or self.top > self.bottom;
end

function RectangleMixin:EnclosesPoint(x, y)
	return x >= self.left and x <= self.right and y >= self.top and y <= self.bottom;
end

function RectangleMixin:EnclosesRect(otherRect)
	return self:EnclosesPoint(otherRect:GetLeft(), otherRect:GetTop()) and self:EnclosesPoint(otherRect:GetRight(), otherRect:GetBottom());
end

function RectangleMixin:IntersectsRect(otherRect)
	return not (
		self.left > otherRect.right or
		self.right < otherRect.left or
		self.top > otherRect.bottom or
		self.bottom < otherRect.top
	);
end

function RectangleMixin:GetTop()
	return self.top;
end

function RectangleMixin:GetBottom()
	return self.bottom;
end

function RectangleMixin:GetLeft()
	return self.left;
end

function RectangleMixin:GetRight()
	return self.right;
end

function RectangleMixin:GetWidth()
	return self.right - self.left;
end

function RectangleMixin:GetHeight()
	return self.bottom - self.top;
end

function RectangleMixin:GetCenter()
	return Lerp(self.left, self.right, .5), Lerp(self.top, self.bottom, .5);
end

function RectangleMixin:GetCenterH()
	return Lerp(self.left, self.right, .5);
end

function RectangleMixin:GetCenterV()
	return Lerp(self.top, self.bottom, .5);
end

function RectangleMixin:SetTop(top)
	self.top = top;
end

function RectangleMixin:SetBottom(bottom)
	self.bottom = bottom;
end

function RectangleMixin:SetLeft(left)
	self.left = left;
end

function RectangleMixin:SetRight(right)
	self.right = right;
end

function RectangleMixin:SetWidth(width)
	self.right = self.left + width;
end

function RectangleMixin:SetHeight(height)
	self.bottom = self.top + height;
end

function RectangleMixin:SetSize(width, height)
	self:SetWidth(width);
	self:SetHeight(height);
end

function RectangleMixin:SetCenter(x, y)
	local width = self:GetWidth();
	local height = self:GetHeight();

	self.left = x - width * .5;
	self.right = x + width * .5;

	self.top = y - height * .5;
	self.bottom = y + height * .5;
end]] },
{ 'Blizzard_SharedXMLBase\\TextureUtil.lua', [=[
TextureUtil = {};

function GetTextureInfo(obj)
	if obj:IsObjectType("Texture") then
		local assetName = obj:GetAtlas();
		local assetType = "Atlas";

		if not assetName then
			assetName = obj:GetTextureFilePath();
			assetType = "File";
		end

		if not assetName then
			assetName = obj:GetTextureFileID();
			assetType = "FileID";
		end

		if not assetName then
			assetName = "UnknownAsset";
			assetType = "Unknown";
		end

		local ulX, ulY, blX, blY, urX, urY, brX, brY = obj:GetTexCoord();
		return assetName, assetType, ulX, ulY, blX, blY, urX, urY, brX, brY;
	end
end

function TextureUtil.AnimateTexCoords(texture, textureWidth, textureHeight, frameWidth, frameHeight, numFrames, elapsed, throttle)
	if ( not texture.frame ) then
		texture.frame = 1;
		texture.throttle = throttle;
		texture.numColumns = floor(textureWidth / frameWidth);
		texture.numRows = floor(textureHeight / frameHeight);
		texture.columnWidth = frameWidth / textureWidth;
		texture.rowHeight = frameHeight / textureHeight;
	end

	local frame = texture.frame;
	if ( not texture.throttle or texture.throttle > throttle ) then
		local framesToAdvance = floor(texture.throttle / throttle);
		while ( frame + framesToAdvance > numFrames ) do
			frame = frame - numFrames;
		end

		frame = frame + framesToAdvance;
		texture.throttle = 0;

		local left = mod(frame - 1, texture.numColumns) * texture.columnWidth;
		local right = left + texture.columnWidth;
		local bottom = ceil(frame / texture.numColumns) * texture.rowHeight;
		local top = bottom - texture.rowHeight;
		texture:SetTexCoord(left, right, top, bottom);

		texture.frame = frame;
	else
		texture.throttle = texture.throttle + elapsed;
	end
end

function SetClampedTextureRotation(texture, rotationDegrees)
	if (rotationDegrees ~= 0 and rotationDegrees ~= 90 and rotationDegrees ~= 180 and rotationDegrees ~= 270) then
		error("SetRotation: rotationDegrees must be 0, 90, 180, or 270");
		return;
	end

	if not (texture.rotationDegrees) then
		texture.origTexCoords = {texture:GetTexCoord()};
		texture.origWidth = texture:GetWidth();
		texture.origHeight = texture:GetHeight();
	end

	if (texture.rotationDegrees == rotationDegrees) then
		return;
	end

	texture.rotationDegrees = rotationDegrees;

	if (rotationDegrees == 0 or rotationDegrees == 180) then
		texture:SetWidth(texture.origWidth);
		texture:SetHeight(texture.origHeight);
	else
		texture:SetWidth(texture.origHeight);
		texture:SetHeight(texture.origWidth);
	end

	if (rotationDegrees == 0) then
		texture:SetTexCoord( texture.origTexCoords[1], texture.origTexCoords[2],
											texture.origTexCoords[3], texture.origTexCoords[4],
											texture.origTexCoords[5], texture.origTexCoords[6],
											texture.origTexCoords[7], texture.origTexCoords[8] );
	elseif (rotationDegrees == 90) then
		texture:SetTexCoord( texture.origTexCoords[3], texture.origTexCoords[4],
											texture.origTexCoords[7], texture.origTexCoords[8],
											texture.origTexCoords[1], texture.origTexCoords[2],
											texture.origTexCoords[5], texture.origTexCoords[6] );
	elseif (rotationDegrees == 180) then
		texture:SetTexCoord( texture.origTexCoords[7], texture.origTexCoords[8],
											texture.origTexCoords[5], texture.origTexCoords[6],
											texture.origTexCoords[3], texture.origTexCoords[4],
											texture.origTexCoords[1], texture.origTexCoords[2] );
	elseif (rotationDegrees == 270) then
		texture:SetTexCoord( texture.origTexCoords[5], texture.origTexCoords[6],
											texture.origTexCoords[1], texture.origTexCoords[2],
											texture.origTexCoords[7], texture.origTexCoords[8],
											texture.origTexCoords[3], texture.origTexCoords[4] );
	end
end

function ClearClampedTextureRotation(texture)
	if (texture.rotationDegrees) then
		SetClampedTextureRotation(texture, 0);
		texture.origTexCoords = nil;
		texture.origWidth = nil;
		texture.origHeight = nil;
	end
end

local LFGRoleEnumToString = {
	[Enum.LFGRole.Tank] = "TANK",
	[Enum.LFGRole.Healer] = "HEALER",
	[Enum.LFGRole.Damage] = "DAMAGER",
	[Constants.LFG_ROLEConstants.LFG_ROLE_NO_ROLE] = "GUIDE",
};

local LFGRoleIcons = {
	["GUIDE"] = "UI-LFG-RoleIcon-Leader",
	["TANK"] = "UI-LFG-RoleIcon-Tank",
	["HEALER"] = "UI-LFG-RoleIcon-Healer",
	["DAMAGER"] = "UI-LFG-RoleIcon-DPS",
	["NONE"] = "UI-LFG-RoleIcon-DPS",
};

