end

function ColorManager.GetAtlasDataForGarrisonFollowerQuality(quality)
	-- Does not currently check color overrides, just return original lookup.
	return GARRISON_FOLLOWER_QUALITY_TEXTURE_SUFFIXES[quality];
end

