			return atlasData;
		end
	end

	atlasData.atlas = LOOT_JOURNAL_ITEM_SETS_QUALITY_ICON_BORDER_ATLASES[quality];
	return atlasData;
end

function ColorManager.GetColorDataForDressUpFrameQuality(quality)
	-- Does not currently check color overrides, just return original lookup.
	return DRESS_UP_FRAME_QUALITY_COLORS[quality];
end

function ColorManager.GetAtlasDataForGarrisonShipyardFollowerQuality(quality)
	-- Does not currently check color overrides, just return original lookup.
	return GARRISON_SHIPYARD_FOLLOWER_QUALITY_ATLASES[quality];
end

function ColorManager.GetAtlasDataForSpellDisplayColor(quality)
	local atlasData = {
		atlas = nil,
		overrideColor = nil
	};

	local overrideQuality = ITEM_QUALITY_OVERRIDES[quality];
	if overrideQuality then
		local overrideInfo = C_ColorOverrides.GetColorOverrideInfo(overrideQuality);
		if overrideInfo then
			atlasData.atlas = "wowlabs-in-world-item-common";
			atlasData.overrideColor = overrideInfo.overrideColor;
			return atlasData;
		end
	end

	atlasData.atlas = SPELL_DISPLAY_BORDER_COLOR_ATLASES[quality];
	return atlasData;
end

function ColorManager.GetAtlasDataForPlayerChoice(quality)
	local atlasData = {
		postfixData = nil,
		overrideColor = nil
	};

	local overrideQuality = ITEM_QUALITY_OVERRIDES[quality];
	if overrideQuality then
		local overrideInfo = C_ColorOverrides.GetColorOverrideInfo(overrideQuality);
		if overrideInfo then
			atlasData.postfixData = {
				circleBorder = "-border-white",
				portraitBackgroundGlow1 = "-portrait-qualitywhite-01",
				portraitBackgroundGlow2 = "-portrait-qualitywhite-02",
				portraitBackgroundTorghast = "",
				portraitBackgroundCypher = "-white"
			};
			atlasData.overrideColor = overrideInfo.overrideColor;
			return atlasData;
		end
	end

	atlasData.postfixData = PLAYER_CHOICE_ATLAS_POSTFIXES[quality];
	return atlasData;
end

function ColorManager.GetAtlasDataForMawBuff(quality)
	local atlasData = {
		atlas = nil,
		overrideColor = nil
	};

	local overrideQuality = ITEM_QUALITY_OVERRIDES[quality];
	if overrideQuality then
		local overrideInfo = C_ColorOverrides.GetColorOverrideInfo(overrideQuality);
		if overrideInfo then
			atlasData.atlas = "jailerstower-animapowerlist-powerborder-white";
			atlasData.overrideColor = overrideInfo.overrideColor;
		end
	end

	-- No need to set default atlas data here, as maw buffs know this already via API calls.
	return atlasData;
end

-- |cnIQ<ItemQuality>:<your text here>|r - Named color token specifically for Item Qualities (IQ) which takes override colors into account.
function ColorManager.GetFormattedStringForItemQuality(text, quality)
	return string.format("|cnIQ%d:%s|r", quality, text);
end

EventRegistry:RegisterFrameEventAndCallback("ACCOUNT_CVARS_LOADED", ColorManager.UpdateColorData, ColorManager);
EventRegistry:RegisterFrameEventAndCallback("VARIABLES_LOADED", ColorManager.UpdateColorData, ColorManager);

ColorManager.UpdateColorData();]=] },
{ 'Blizzard_SharedXML\\Shared\\LocalizationMachinery.lua', [[
local function CallLocalizationFunction(l10nTable, key)
	-- It's ok if things are missing, it just means that locale doesn't require any specific localization
	local localeTable = l10nTable[UI_LOCALE];
	if localeTable then
		local localizeFn = localeTable[key];
		if localizeFn then
			localizeFn();
		end
	end
end

local localizeFramesCallbacks = {};
local function AddLocalizeFramesCallback(l10nTable)
	table.insert(localizeFramesCallbacks, function()
		CallLocalizationFunction(l10nTable, "localizeFrames");
	end);
end

-- Intentionally global, this is called later when all of the UI that needs l10n is loaded.
function LocalizeFrames()
	for index, callback in ipairs(localizeFramesCallbacks) do
		-- If an error occurs (e.g. a frame in the original file was renamed) report the problem but don't stop execution so the loc teams aren't blocked.
		local ok, message = pcall(callback);
		if not ok then
			if ScriptErrorsFrame then
				ScriptErrorsFrame:Warn("Error in localization callback " .. message);
			end
		end
	end

	localizeFramesCallbacks = {};
end

function SetupLocalization(l10nTable)
	-- This is called immediately when l10n is set up to adjust strings and other constants that the rest of the UI setup depends on.
	CallLocalizationFunction(l10nTable, "localize");

	-- NOTE: The typical hook for this is VARIABLES_LOADED, so for LoadOnDemand addons, use the "localize" section.
	AddLocalizeFramesCallback(l10nTable);
end]] },
