{ 'Blizzard_SharedXML\\UnitUtil.lua', [[
function GetPlayerGuid()
	return UnitGUID("player");
end

function IsPlayerGuid(guid)
	return guid == GetPlayerGuid();
end

function IsInitialSpec(specializationIndex)
	if not specializationIndex then
		return false;
	end

	return specializationIndex > GetNumSpecializations();
end

function IsPlayerInitialSpec()
	return IsInitialSpec(C_SpecializationInfo.GetSpecialization());
end

function GetNameAndServerNameFromGUID(unitGUID)
	local _, _, _, _, _, name, normalizedRealmName = GetPlayerInfoByGUID(unitGUID);
	return name, normalizedRealmName;
end

function ConcatinateServerNameToPlayerName(unitGUID)
	local name, serverName = GetNameAndServerNameFromGUID(unitGUID);
	if (serverName ~= "") then
		serverName = "-"..serverName
	end
	return name..serverName;
end

PlayerUtil = {};

function PlayerUtil.GetCurrentSpecID()
	local currentSpecialization = C_SpecializationInfo.GetSpecialization();
	if currentSpecialization then
		local specId = C_SpecializationInfo.GetSpecializationInfo(currentSpecialization);
		return specId;
	end

	return nil;
end

function PlayerUtil.GetSpecName()
	local playerSpecID = PlayerUtil.GetCurrentSpecID()
	if playerSpecID then
		local playerSex = UnitSex("player");
		if playerSpecID and playerSex then
			return select(2, GetSpecializationInfoByID(playerSpecID, playerSex));
		end
	end

	return "";
end

function PlayerUtil.GetSpecNameBySpecID(specID, playerSex)
	playerSex = playerSex or UnitSex("player");
	if playerSex then
		return select(2, GetSpecializationInfoByID(specID, playerSex));
	end

	return "";
end

function PlayerUtil.GetSpecIconBySpecID(specID, playerSex)
	playerSex = playerSex or UnitSex("player");
	if playerSex then
		return select(4, GetSpecializationInfoByID(specID, playerSex));
	end

	return nil;
end

function PlayerUtil.ShouldUseNativeFormInModelScene()
	local _, raceFilename = UnitRace("player");
	return (raceFilename and (raceFilename ~= "Dracthyr" and raceFilename ~= "Worgen")) or C_UnitAuras.WantsAlteredForm("player");
end

function PlayerUtil.GetClassID()
	local classID = select(3, UnitClass("player"));
	return classID;
end

function PlayerUtil.GetClassName()
	local className = UnitClass("player");
	return className;
end

function PlayerUtil.GetClassInfo()
	local classID = PlayerUtil.GetClassID();
	return C_CreatureInfo.GetClassInfo(classID);
end

function PlayerUtil.GetClassFile()
	local classInfo = PlayerUtil.GetClassInfo();
	return classInfo.classFile;
end

function PlayerUtil.GetClassColor()
	return C_ClassColor.GetClassColor(PlayerUtil.GetClassFile());
end

function PlayerUtil.CanUseClassTalents()
	return C_SpecializationInfo.CanPlayerUseTalentUI() and not IsPlayerInitialSpec();
end

function PlayerUtil.IsPlayerEffectivelyTank()
	local assignedRole = UnitGroupRolesAssigned("player");
	if GetSpecializationSystem() == Enum.SpecializationSystem.ChrSpecialization and assignedRole == "NONE" then
		local spec = C_SpecializationInfo.GetSpecialization();
		return spec and GetSpecializationRole(spec) == "TANK";
	end

	return assignedRole == "TANK";
end
]] },
{ 'Blizzard_SharedXML\\AccountUtil.lua', [[
BNET_CLIENT_WOW = "WoW";
BNET_CLIENT_APP = "App";
BNET_CLIENT_HEROES = "Hero";
BNET_CLIENT_CLNT = "CLNT";

function GameLimitedMode_IsActive()
	return IsTrialAccount() or IsVeteranTrialAccount();
end

function GameLimitedMode_IsBankedXPActive()
	return GameLimitedMode_IsActive() or GetExpansionTrialInfo();
end

function GameLimitedMode_GetLevelLimit()
	if GetExpansionTrialInfo() then
		local level = GetMaxLevelForExpansionLevel(math.max(GetClampedCurrentExpansionLevel() - 1, 0) );
		return level;
	elseif GameLimitedMode_IsActive() then
		local level = GetRestrictedAccountData();
		return level;
	end

	local level = GetMaxLevelForPlayerExpansion();
	return level;
end

function GetClampedCurrentExpansionLevel()
	return math.min(GetClientDisplayExpansionLevel(), math.max(GetAccountExpansionLevel(), GetExpansionLevel()));
end

function IsValidEmailAddress(address)
	if address then
		local matchStart, matchEnd = string.find(address, ".+@.+%...+");
		return matchStart and matchEnd;
	end

	return false;
end

--Name can be a realID or plain battletag with no 4 digit number (e.g. Murky McGrill or LichKing).
function BNet_GetBNetIDAccount(name)
	return C_AutoComplete.GetAutoCompletePresenceID(name);
end

function BNet_GetBNetAccountName(accountInfo)
	if not accountInfo then
		return;
	end

	local name = accountInfo.accountName;
	if name == "" then
		name = BNet_GetTruncatedBattleTag(accountInfo.battleTag);
	end

	return name;
end

--Name must be a character name from your friends list.
function BNet_GetBNetIDAccountFromCharacterName(name)
	local _, numBNetOnline = BNGetNumFriends();
	for i = 1, numBNetOnline do
		local accountInfo = C_BattleNet.GetFriendAccountInfo(i);
		if accountInfo and accountInfo.gameAccountInfo.characterName and (strcmputf8i(name, accountInfo.gameAccountInfo.characterName) == 0) then
			return accountInfo.bnetAccountID;
		end
	end
end

function BNet_GetTruncatedBattleTag(battleTag)
	if battleTag then
		local symbol = string.find(battleTag, "#");
		if ( symbol ) then
			return string.sub(battleTag, 1, symbol - 1);
		else
			return battleTag;
		end
	else
		return "";
	end
end

function BNet_GetBattleTagSelf()
	local _deprecatedPresenceID, battleTag, _opaqueID, _broadcastText, _isAFK, _isBusy, _isRealIDEnabled = BNGetInfo();
	return battleTag or "";
end

function BNet_GetBroadcastTextSelf()
	local _deprecatedPresenceID, _battleTag, _opaqueID, broadcastText, _isAFK, _isBusy, _isRealIDEnabled = BNGetInfo();
	return broadcastText or "";
end

function BNet_GetBattleTagComponents(battleTag)
	if not battleTag then
		return;
	end

	local tagSplitSymbol = "#";
	local prefix, suffix = string.split(tagSplitSymbol, battleTag);
	return { prefix = prefix, tagSplitSymbol = tagSplitSymbol, suffix = suffix };
end

-- if we don't have a character name or it's for a game that doesn't have toons like Heroes, use the battletag
function BNet_GetValidatedCharacterName(characterName, battleTag, client, clientTextureSize)
	if (not characterName) or (characterName == "") or (client == BNET_CLIENT_HEROES) then
		return BNet_GetTruncatedBattleTag(battleTag);
	end
	return characterName;
end

function BNet_GetValidatedCharacterNameWithClientEmbeddedAtlas(characterName, battleTag, client, texWidth, texHeight, texXOffset, texYOffset)
	return BNet_GetClientEmbeddedAtlas(client, texWidth, texHeight, texXOffset, texYOffset)..BNet_GetValidatedCharacterName(characterName, battleTag, client);
end

function BNet_GetValidatedCharacterNameWithClientEmbeddedTexture(characterName, battleTag, texture, fileWidth, fileHeight, texWidth, texHeight, texXOffset, texYOffset)
	local width = texWidth or 0;
	local height = texHeight or width;
	local xOffset = texXOffset or 0;
	local yOffset = texYOffset or 0;
	
	return CreateTextureMarkup(texture, fileWidth, fileHeight, width, height, 0, 1, 0, 1, xOffset, yOffset).." "..BNet_GetValidatedCharacterName(characterName, battleTag, client);
end

local BATTLE_NET_FRIEND_LEVEL_RANK =
{
