	local friendRank = BATTLE_NET_FRIEND_LEVEL_RANK[friendLevel];
	local comparisonRank = BATTLE_NET_FRIEND_LEVEL_RANK[comparisonLevel];
	if not friendRank or not comparisonRank then
		return false;
	end

	return friendRank >= comparisonRank;
end
