{ 'Blizzard_SharedXML\\TimeUtil.lua', [=[
-- Set to false in some locale specific files.
TIME_UTIL_WHITE_SPACE_STRIPPABLE = true;

TimeUtil = TimeUtil or {};

SECONDS_PER_MIN = 60;
SECONDS_PER_HOUR = 60 * SECONDS_PER_MIN;
SECONDS_PER_DAY = 24 * SECONDS_PER_HOUR;
SECONDS_PER_MONTH = 30 * SECONDS_PER_DAY;
SECONDS_PER_YEAR = 12 * SECONDS_PER_MONTH;

function SecondsToMinutes(seconds)
	return seconds / SECONDS_PER_MIN;
end

function MinutesToSeconds(minutes)
	return minutes * SECONDS_PER_MIN;
end

function HasTimePassed(testTime, amountOfTime)
	return ((time() - testTime) >= amountOfTime);
end

function TimeUtil.GetRecentTimeDate(year, month, day, hour)
	local lastOnline;
	if ( (year == 0) or (year == nil) ) then
		if ( (month == 0) or (month == nil) ) then
			if ( (day == 0) or (day == nil) ) then
				if ( (hour == 0) or (hour == nil) ) then
					lastOnline = LASTONLINE_MINS;
				else
					lastOnline = format(LASTONLINE_HOURS, hour);
				end
			else
				lastOnline = format(LASTONLINE_DAYS, day);
			end
		else
			lastOnline = format(LASTONLINE_MONTHS, month);
		end
	else
		lastOnline = format(LASTONLINE_YEARS, year);
	end
	return lastOnline;
end

function TimeUtil.BetterDate(formatString, timeVal)
	local dateTable = date("*t", timeVal);
	local amString = (dateTable.hour >= 12) and TIMEMANAGER_PM or TIMEMANAGER_AM;

	formatString = gsub(formatString, "^%%p", amString);
	formatString = gsub(formatString, "([^%%])%%p", "%1"..amString);

	return date(formatString, timeVal);
end

SecondsFormatter = {};

SecondsFormatterConstants = 
{
	ZeroApproximationThreshold = 0,
	ConvertToLower = true,
	DontConvertToLower = false,
	RoundUpLastUnit = true,
	DontRoundUpLastUnit = false,
	RoundUpIntervals = true,
	DontRoundUpIntervals = false,
}

SecondsFormatter.Abbreviation = 
{
	None = 1, -- seconds, minutes, hours...
	Truncate = 2, -- sec, min, hr...
	OneLetter = 3, -- s, m, h...
}

SecondsFormatter.Interval = {
	Seconds = 1,
	Minutes = 2,
	Hours = 3,
	Days = 4,
}

SecondsFormatter.IntervalDescription = {
	[SecondsFormatter.Interval.Seconds] = {seconds = 1, formatString = { D_SECONDS, SECONDS_ABBR, SECOND_ONELETTER_ABBR}},
	[SecondsFormatter.Interval.Minutes] = {seconds = SECONDS_PER_MIN, formatString = {D_MINUTES, MINUTES_ABBR, MINUTE_ONELETTER_ABBR}},
	[SecondsFormatter.Interval.Hours] = {seconds = SECONDS_PER_HOUR, formatString = {D_HOURS, HOURS_ABBR, HOUR_ONELETTER_ABBR}},
	[SecondsFormatter.Interval.Days] = {seconds = SECONDS_PER_DAY, formatString = {D_DAYS, DAYS_ABBR, DAY_ONELETTER_ABBR}},
}

--[[ Seconds formatter to standardize representations of seconds. When adding a new formatter
please consider if a prexisting formatter suits your needs, otherwise, before adding a new formatter,
consider adding it to a file appropriate to it's intended use. For example, "WorldQuestsSecondsFormatter"
could be added to QuestUtil.h so it's immediately apparent the scenarios the formatter is appropriate.]]

SecondsFormatterMixin = {}
-- defaultAbbreviation: the default abbreviation for the format. Can be overrridden in SecondsFormatterMixin:Format()
-- approximationSeconds: threshold for representing the seconds as an approximation (ex. "< 2 hours").
-- roundUpLastUnit: determines if the last unit in the output format string is ceiled (floored by default).
-- convertToLower: converts the format string to lowercase.
-- roundUpIntervals: determines if units can be promoted to a higher interval after (ex. 60m -> 1h).
function SecondsFormatterMixin:Init(approximationSeconds, defaultAbbreviation, roundUpLastUnit, convertToLower, roundUpIntervals)
	self:SetApproximationSeconds(approximationSeconds or 0);
	self:SetMinInterval(SecondsFormatter.Interval.Seconds);
	self:SetDefaultAbbreviation(defaultAbbreviation or SecondsFormatter.Abbreviation.None);
	self:SetCanRoundUpLastUnit(roundUpLastUnit or SecondsFormatterConstants.DontRoundUpLastUnit);
	self:SetCanRoundUpIntervals(roundUpIntervals or SecondsFormatterConstants.DontRoundUpIntervals);
	self:SetDesiredUnitCount(2);
	self:SetStripIntervalWhitespace(false);
	self:SetConvertToLower(convertToLower or false);
end

function SecondsFormatterMixin:SetStripIntervalWhitespace(strip)
	self.stripIntervalWhitespace = strip;
end

function SecondsFormatterMixin:GetStripIntervalWhitespace()
	return self.stripIntervalWhitespace;
end

function SecondsFormatterMixin:SetConvertToLower(convertToLower)
	self.convertToLower = convertToLower;
end

function SecondsFormatterMixin:GetMaxInterval()
	return #SecondsFormatter.IntervalDescription;
end

function SecondsFormatterMixin:GetIntervalDescription(interval)
	return SecondsFormatter.IntervalDescription[interval];
end

function SecondsFormatterMixin:GetIntervalSeconds(interval)
	local intervalDescription = self:GetIntervalDescription(interval);
	return intervalDescription and intervalDescription.seconds or nil;
end

function SecondsFormatterMixin:CanApproximate(seconds)
	return (seconds > 0 and seconds < self:GetApproximationSeconds());
end

function SecondsFormatterMixin:SetDefaultAbbreviation(defaultAbbreviation)
	self.defaultAbbreviation = defaultAbbreviation;
end

function SecondsFormatterMixin:GetDefaultAbbreviation()
	return self.defaultAbbreviation;
end

function SecondsFormatterMixin:SetApproximationSeconds(approximationSeconds)
	self.approximationSeconds = approximationSeconds;
end

function SecondsFormatterMixin:GetApproximationSeconds()
	return self.approximationSeconds;
end

function SecondsFormatterMixin:SetCanRoundUpLastUnit(roundUpLastUnit)
	self.roundUpLastUnit = roundUpLastUnit;
end

function SecondsFormatterMixin:CanRoundUpLastUnit()
	return self.roundUpLastUnit;
end

function SecondsFormatterMixin:SetCanRoundUpIntervals(roundUpIntervals)
	self.roundUpIntervals = roundUpIntervals;
end

function SecondsFormatterMixin:CanRoundUpIntervals()
	return self.roundUpIntervals;
end

function SecondsFormatterMixin:SetDesiredUnitCount(unitCount)
	self.unitCount = unitCount;
end

function SecondsFormatterMixin:GetDesiredUnitCount(seconds)
	-- seconds ignored in base implementation, but instances of this mixin can override this function
	return self.unitCount;
end

function SecondsFormatterMixin:SetMinInterval(interval)
	self.minInterval = interval;
end

function SecondsFormatterMixin:GetMinInterval(seconds)
	-- seconds ignored in base implementation, but instances of this mixin can override this function
	return self.minInterval;
end

function SecondsFormatterMixin:GetFormatString(interval, abbreviation, convertToLower)
	local intervalDescription = self:GetIntervalDescription(interval);
	local formatString = intervalDescription.formatString[abbreviation];
	if convertToLower then
		formatString = formatString:lower();
	end
	local strip = TIME_UTIL_WHITE_SPACE_STRIPPABLE and self:GetStripIntervalWhitespace();
	return strip and formatString:gsub(" ", "") or formatString;
end

function SecondsFormatterMixin:FormatZero(abbreviation, convertToLower)
	local seconds = 0;
	local minInterval = self:GetMinInterval(seconds);
	local formatString = self:GetFormatString(minInterval, abbreviation, convertToLower);
	return formatString:format(0);
end

function SecondsFormatterMixin:FormatMillseconds(millseconds, abbreviation)
	return self:Format(millseconds/1000, abbreviation);
end

function SecondsFormatterMixin:Format(seconds, abbreviation)
	if (seconds == nil) then
		return "";
	end

	seconds = math.ceil(seconds);
	abbreviation = abbreviation or self:GetDefaultAbbreviation();

	if (seconds <= 0) then
		return self:FormatZero(abbreviation, self.convertToLower);
	end

	local minInterval = self:GetMinInterval(seconds);
	local maxInterval = self:GetMaxInterval();

	if (self:CanApproximate(seconds)) then
		local interval = math.max(minInterval, SecondsFormatter.Interval.Minutes);
		while (interval < maxInterval) do
			local nextInterval = interval + 1; 
			if (seconds > self:GetIntervalSeconds(nextInterval)) then
				interval = nextInterval;
			else
				break;
			end
		end

		local formatString = self:GetFormatString(interval, abbreviation, self.convertToLower);
		local unit = formatString:format(math.ceil(seconds / self:GetIntervalSeconds(interval)));
		return string.format(LESS_THAN_OPERAND, unit);
	end
	
	local output = "";
	local appendedCount = 0;
	local desiredCount = self:GetDesiredUnitCount(seconds);
	local convertToLower = self.convertToLower;

	local intervalUnits = {};
	for interval, value in pairs(SecondsFormatter.Interval) do
		intervalUnits[value] = 0;
	end

	local currentInterval = maxInterval;
	while ((appendedCount < desiredCount) and (currentInterval >= minInterval)) do
		local intervalDescription = self:GetIntervalDescription(currentInterval);
		local intervalSeconds = intervalDescription.seconds;
		if (seconds >= intervalSeconds) then
			appendedCount = appendedCount + 1;

			local quotient = seconds / intervalSeconds;
			if (quotient > 0) then
				if (self:CanRoundUpLastUnit() and ((minInterval == currentInterval) or (appendedCount == desiredCount))) then
					intervalUnits[currentInterval] = math.ceil(quotient);
				else
					intervalUnits[currentInterval] = math.floor(quotient);
				end
			else
				break;
			end

			seconds = math.fmod(seconds, intervalSeconds);
		end

		currentInterval = currentInterval - 1;
	end

	if self:CanRoundUpIntervals() then
		-- Intervals are promoted to a higher interval if possible (60m -> 1h) so that a value isn't expressed
		-- as 1h 60m as a result of individual interval round-up. This promotion can only happen within the
		-- min interval, max interval band so that we don't promote to an interval we don't intend to display.
		for interval, value in ipairs(intervalUnits) do
			local intervalDescription = self:GetIntervalDescription(interval);
			local intervalSeconds = intervalDescription.seconds;

			if value == intervalSeconds then
				local nextInterval = interval + 1;
				if nextInterval <= maxInterval then
					intervalUnits[nextInterval] = intervalUnits[nextInterval] + 1;
					intervalUnits[interval] = 0;
				end
			end
		end
	end

	for interval, value in ipairs_reverse(intervalUnits) do
		if value > 0 then
			if (output ~= "") then
				output = output..TIME_UNIT_DELIMITER;
			end

			local formatString = self:GetFormatString(interval, abbreviation, convertToLower);
			output = output..formatString:format(value);
		end
	end

	-- Return the zero format if an acceptable representation couldn't be formed.
	if (output == "") then
		return self:FormatZero(abbreviation, self.convertToLower);
	end

	return output;
end

function ConvertSecondsToUnits(timestamp)
	timestamp = math.max(timestamp, 0);
	local days = math.floor(timestamp / SECONDS_PER_DAY);
	timestamp = timestamp - (days * SECONDS_PER_DAY);
	local hours = math.floor(timestamp / SECONDS_PER_HOUR);
	timestamp = timestamp - (hours * SECONDS_PER_HOUR);
	local minutes = math.floor(timestamp / SECONDS_PER_MIN);
	timestamp = timestamp - (minutes * SECONDS_PER_MIN);
	local seconds = math.floor(timestamp);
	local milliseconds = timestamp - seconds;
	return {
		days=days,
		hours=hours,
		minutes=minutes,
		seconds=seconds,
		milliseconds=milliseconds,
	}
end

function SecondsToClock(seconds, displayZeroHours)
	local units = ConvertSecondsToUnits(seconds);
	if units.hours > 0 or displayZeroHours then
		return format(HOURS_MINUTES_SECONDS, units.hours, units.minutes, units.seconds);
	else
		return format(MINUTES_SECONDS, units.minutes, units.seconds);
	end
end

function GetTimeStringFromSeconds(timeAmount, hasMS, dropZeroHours)
	local seconds, ms;
	if ( hasMS ) then
		seconds = floor(timeAmount / 1000);
		ms = timeAmount - seconds * 1000;
	else
		seconds = timeAmount;
	end

	local hours = floor(seconds / 3600);
	local minutes = floor((seconds / 60) - (hours * 60));
	seconds = seconds - hours * 3600 - minutes * 60;
	if ( hasMS ) then
		return format(HOURS_MINUTES_SECONDS_MILLISECONDS, hours, minutes, seconds, ms);
	elseif ( dropZeroHours and hours == 0 ) then
		return format(MINUTES_SECONDS, minutes, seconds);
	else
		return format(HOURS_MINUTES_SECONDS, hours, minutes, seconds);
	end
end

-- Deprecated. See SecondsFormatter for intended replacement
function SecondsToTime(seconds, noSeconds, notAbbreviated, maxCount, roundUp)
	local time = "";
	local count = 0;
	local tempTime;
	seconds = roundUp and math.ceil(seconds) or math.floor(seconds);
	maxCount = maxCount or 2;

	-- When limited to a single term, use a higher threshold of 1.5 min/hr/day.
	-- If there are at least 2 terms, the higher threshold is unnecessary.
	local threshold = maxCount > 1 and 1.0 or 1.5

	if ( seconds >= SECONDS_PER_DAY * threshold ) then
		count = count + 1;
		if ( count == maxCount and roundUp ) then
			tempTime = math.ceil(seconds / SECONDS_PER_DAY);
		else
			tempTime = math.floor(seconds / SECONDS_PER_DAY);
		end
		if ( notAbbreviated ) then
			time = D_DAYS:format(tempTime);
		else
			time = DAYS_ABBR:format(tempTime);
		end
		seconds = seconds % SECONDS_PER_DAY;
	end
	if ( count < maxCount and seconds >= SECONDS_PER_HOUR * threshold ) then
		count = count + 1;
		if ( time ~= "" ) then
			time = time..TIME_UNIT_DELIMITER;
		end
		if ( count == maxCount and roundUp ) then
			tempTime = math.ceil(seconds / SECONDS_PER_HOUR);
		else
			tempTime = math.floor(seconds / SECONDS_PER_HOUR);
		end
		if ( notAbbreviated ) then
			time = time..D_HOURS:format(tempTime);
		else
			time = time..HOURS_ABBR:format(tempTime);
		end
		seconds = seconds % SECONDS_PER_HOUR;
	end
	if ( count < maxCount and seconds >= SECONDS_PER_MIN * threshold ) then
		count = count + 1;
		if ( time ~= "" ) then
			time = time..TIME_UNIT_DELIMITER;
		end
		if ( count == maxCount and roundUp ) then
			tempTime = math.ceil(seconds / SECONDS_PER_MIN);
		else
			tempTime = math.floor(seconds / SECONDS_PER_MIN);
		end
		if ( notAbbreviated ) then
			time = time..D_MINUTES:format(tempTime);
		else
			time = time..MINUTES_ABBR:format(tempTime);
		end
		seconds = seconds % SECONDS_PER_MIN;
	end
	if ( count < maxCount and seconds > 0 and not noSeconds ) then
		if ( time ~= "" ) then
			time = time..TIME_UNIT_DELIMITER;
		end
		if ( notAbbreviated ) then
			time = time..D_SECONDS:format(seconds);
		else
			time = time..SECONDS_ABBR:format(seconds);
		end
	end
	return time;
end

-- Deprecated. See SecondsFormatter for intended replacement
function MinutesToTime(mins, hideDays)
	local time = "";
	local count = 0;
	local tempTime;
	-- only show days if hideDays is false
	if ( mins > 1440 and not hideDays ) then
		tempTime = floor(mins / 1440);
		time = TIME_UNIT_DELIMITER .. format(DAYS_ABBR, tempTime);
		mins = mins % 1440;
		count = count + 1;
	end
	if ( mins > 60  ) then
		tempTime = floor(mins / 60);
		time = time .. TIME_UNIT_DELIMITER .. format(HOURS_ABBR, tempTime);
		mins = mins % 60;
		count = count + 1;
	end
	if ( count < 2 ) then
		tempTime = mins;
		time = time .. TIME_UNIT_DELIMITER .. format(MINUTES_ABBR, tempTime);
		count = count + 1;
	end
	return time;
end

-- Deprecated. See SecondsFormatter for intended replacement
function SecondsToTimeAbbrev(seconds, thresholdOverride)
	local tempTime;
	local threshold = 1.5;
	if thresholdOverride then
		threshold = thresholdOverride;
	end

	if ( seconds >= SECONDS_PER_DAY * threshold ) then
		tempTime = ceil(seconds / SECONDS_PER_DAY);
		return DAY_ONELETTER_ABBR, tempTime;
	end
	if ( seconds >= SECONDS_PER_HOUR * threshold ) then
		tempTime = ceil(seconds / SECONDS_PER_HOUR);
		return HOUR_ONELETTER_ABBR, tempTime;
	end
	if ( seconds >= SECONDS_PER_MIN * threshold ) then
		tempTime = ceil(seconds / SECONDS_PER_MIN);
		return MINUTE_ONELETTER_ABBR, tempTime;
	end
	return SECOND_ONELETTER_ABBR, seconds;
end

function FormatShortDate(day, month, year)
	if (year) then
		if (LOCALE_enGB) then
			return SHORTDATE_EU:format(day, month, year);
		else
			return SHORTDATE:format(day, month, year);
		end
	else
		if (LOCALE_enGB) then
			return SHORTDATENOYEAR_EU:format(day, month);
		else
			return SHORTDATENOYEAR:format(day, month);
		end
	end
end]=] },
{ 'Blizzard_SharedXML\\BenchmarkUtil.lua', [[
ScriptBenchmarkMixin = {};

function ScriptBenchmarkMixin:OnStart(_iterationCount)
	-- Derive and implement to run any logic before your benchmark has started.
end

function ScriptBenchmarkMixin:OnIterationStart(_iteration, _iterationCount)
	-- Derive and implement to run any logic before an iteration of your benchmark has started.
end

function ScriptBenchmarkMixin:OnIterationFinish(_iteration, _iterationCount, _iterationResults)
	-- Derive and implement to run any logic after an iteration of your benchmark has finished.
end

function ScriptBenchmarkMixin:OnFinish(_iterationCount, _benchmarkResults)
	-- Derive and implement to run any logic after your benchmark has finished.
end

function ScriptBenchmarkMixin:RunIteration(...)
	-- Derive and implement the actual details of your benchmark here.
end

ScriptBenchmarkGarbageCollectorControlMixin = {};

function ScriptBenchmarkGarbageCollectorControlMixin:OnIterationStart(_iteration, _iterationCount)
	collectgarbage("collect");
	collectgarbage("stop");
end

function ScriptBenchmarkGarbageCollectorControlMixin:OnIterationFinish(_iteration, _iterationCount, _iterationResults)
	collectgarbage("restart");
end

BenchmarkUtil = {};

function BenchmarkUtil.RunBenchmark(benchmark, iterationCount, ...)
	local benchmarkResults = table.create(iterationCount);

	benchmark:OnStart(iterationCount);

	for iteration = 1, iterationCount do
		benchmark:OnIterationStart(iteration, iterationCount);
		local iterationResults = C_AddOnProfiler.MeasureCall(benchmark.RunIteration, benchmark, ...);
		benchmark:OnIterationFinish(iteration, iterationCount, iterationResults);
		benchmarkResults[iteration] = iterationResults;
	end

	benchmark:OnFinish(iterationCount, benchmarkResults);
	return benchmarkResults;
end

function BenchmarkUtil.SummarizeResults(benchmarkResults)
	local summary = {};
	summary.results = benchmarkResults;
	summary.iterationCount = #benchmarkResults;

	for column, samples in pairs(BenchmarkUtil.TransposeResults(benchmarkResults)) do
		summary[column] = BenchmarkUtil.CalculateStatistics(samples);
	end

	return summary;
end

function BenchmarkUtil.TransposeResults(benchmarkResults)
	local columns = { "elapsedMilliseconds", "elapsedTicks", "allocatedBytes", "deallocatedBytes" };
	local data = {};

	for _, column in ipairs(columns) do
		data[column] = {};
	end

	for iteration = 1, #benchmarkResults do
		local iterationResults = benchmarkResults[iteration];

		for column, samples in pairs(data) do
			samples[iteration] = iterationResults[column];
		end
	end

	return data;
end

function BenchmarkUtil.CalculateMinMaxMean(samples)
	local min = math.huge;
	local max = -math.huge;
	local sum = 0;
	local count = #samples;

	if count <= 0 then
		return 0, 0, 0;
	end

	for i = 1, count do
		local v = samples[i];
		min = math.min(min, v);
		max = math.max(max, v);
		sum = sum + v;
	end

	local mean = sum / count;
	return min, max, mean;
end

function BenchmarkUtil.CalculateStandardDeviation(samples, mean)
	local variance = 0;
	local count = #samples;

	if count <= 1 then
		return 0;
	end

	for i = 1, count do
		local v = samples[i];
		variance = variance + ((v - mean)^2);
	end

	return math.sqrt(variance / (count - 1));
end

function BenchmarkUtil.CalculateConfidenceInterval(standardDeviation, sampleCount)
	-- 1.96 here represents the 97.5th percentile point (95% confidence interval).
	return sampleCount > 0 and (1.96 * (standardDeviation / math.sqrt(sampleCount))) or 0;
end

function BenchmarkUtil.CalculateStatistics(samples)
	local stats = {};
	stats.samples = samples;
	stats.sampleCount = #samples;
	stats.min, stats.max, stats.mean = BenchmarkUtil.CalculateMinMaxMean(samples);
	stats.standardDeviation = BenchmarkUtil.CalculateStandardDeviation(samples, stats.mean);
	stats.confidenceInterval = BenchmarkUtil.CalculateConfidenceInterval(stats.standardDeviation, stats.sampleCount);
	return stats;
end
]] },
{ 'Blizzard_SharedXML\\Vector2D.lua', [[
-- Protecting from addons since we use this in secure code.
local cos = math.cos;
local sin = math.sin;
local atan2 = math.atan2;
local sqrt = math.sqrt;

function Vector2D_ScaleBy(scalar, x, y)
	return x * scalar, y * scalar;
end

function Vector2D_DivideBy(divisor, x, y)
	return x / divisor, y / divisor;
end

function Vector2D_Add(leftX, leftY, rightX, rightY)
	return leftX + rightX, leftY + rightY;
end

function Vector2D_Subtract(leftX, leftY, rightX, rightY)
	return leftX - rightX, leftY - rightY;
end

function Vector2D_Cross(leftX, leftY, rightX, rightY)
	return leftX * rightY - leftY * rightX;
end

function Vector2D_Dot(leftX, leftY, rightX, rightY)
	return leftX * rightX + leftY * rightY;
end

function Vector2D_GetLengthSquared(x, y)
	return Vector2D_Dot(x, y, x, y);
end

function Vector2D_GetLength(x, y)
	return sqrt(Vector2D_GetLengthSquared(x, y));
end

function Vector2D_Normalize(x, y)
	return Vector2D_DivideBy(Vector2D_GetLength(x, y), x, y);
end

function Vector2D_CalculateAngleBetween(leftX, leftY, rightX, rightY)
	return atan2(Vector2D_Cross(leftX, leftY, rightX, rightY), Vector2D_Dot(leftX, leftY, rightX, rightY));
end

function Vector2D_RotateDirection(rotationRadians, x, y)
	local cosValue = cos(rotationRadians);
	local sinValue = sin(rotationRadians);
	return x * cosValue - y * sinValue, x * sinValue + y * cosValue;
end

Vector2DMixin = {};

function CreateVector2D(x, y)
	local vector = CreateFromMixins(Vector2DMixin);
	vector:OnLoad(x, y);
	return vector;
end

function AreVector2DEqual(left, right)
	if left and right then
		return left:IsEqualTo(right);
	end
	return left == right;
end

function Vector2DMixin:OnLoad(x, y)
	self:SetXY(x, y);
end

function Vector2DMixin:IsEqualTo(otherVector)
	return self.x == otherVector.x
	   and self.y == otherVector.y;
end

function Vector2DMixin:GetXY()
	return self.x, self.y;
end

function Vector2DMixin:SetXY(x, y)
	self.x = x;
	self.y = y;
end

function Vector2DMixin:ScaleBy(scalar)
	self:SetXY(Vector2D_ScaleBy(scalar, self:GetXY()));
	return self;
end

function Vector2DMixin:DivideBy(scalar)
	self:SetXY(Vector2D_DivideBy(scalar, self:GetXY()));
	return self;
end

function Vector2DMixin:Add(other)
	self:SetXY(Vector2D_Add(self.x, self.y, other:GetXY()));
	return self;
end

function Vector2DMixin:Subtract(other)
	self:SetXY(Vector2D_Subtract(self.x, self.y, other:GetXY()));
	return self;
end

function Vector2DMixin:Cross(other)
	self:SetXY(Vector2D_Cross(self.x, self.y, other:GetXY()));
	return self;
end

function Vector2DMixin:Dot(other)
	return Vector2D_Dot(self.x, self.y, other:GetXY());
end

function Vector2DMixin:IsZero()
	return self.x == 0 and self.y == 0;
end

function Vector2DMixin:GetLengthSquared()
	return Vector2D_GetLengthSquared(self:GetXY());
end

function Vector2DMixin:GetLength()
	return Vector2D_GetLength(self:GetXY());
end

function Vector2DMixin:Normalize()
	self:SetXY(Vector2D_Normalize(self:GetXY()));
	return self;
end

function Vector2DMixin:RotateDirection(rotationRadians)
	self:SetXY(Vector2D_RotateDirection(rotationRadians, self:GetXY()));
	return self;
end

function Vector2DMixin:Clone()
	return CreateVector2D(self:GetXY());
end]] },
{ 'Blizzard_SharedXML\\Vector3D.lua', [[
-- Protecting from addons since we use this in secure code.
local cos = math.cos;
local sin = math.sin;
local atan2 = math.atan2;
local asin = math.asin;
local sqrt = math.sqrt;

function Vector3D_ScaleBy(scalar, x, y, z)
	return x * scalar, y * scalar, z * scalar;
end

function Vector3D_DivideBy(divisor, x, y, z)
	return x / divisor, y / divisor, z / divisor;
end

function Vector3D_Add(leftX, leftY, leftZ, rightX, rightY, rightZ)
	return leftX + rightX, leftY + rightY, leftZ + rightZ;
end

function Vector3D_Subtract(leftX, leftY, leftZ, rightX, rightY, rightZ)
	return leftX - rightX, leftY - rightY, leftZ - rightZ;
end

function Vector3D_Cross(leftX, leftY, leftZ, rightX, rightY, rightZ)
	return leftY * rightZ - leftZ * rightY, leftZ * rightX - leftX * rightZ, leftX * rightY - leftY * rightX;
end

function Vector3D_Dot(leftX, leftY, leftZ, rightX, rightY, rightZ)
	return leftX * rightX + leftY * rightY + leftZ * rightZ;
end

function Vector3D_GetLengthSquared(x, y, z)
	return Vector3D_Dot(x, y, z, x, y, z);
end

function Vector3D_GetLength(x, y, z)
	return sqrt(Vector3D_GetLengthSquared(x, y, z));
end

function Vector3D_Normalize(x, y, z)
	return Vector3D_DivideBy(Vector3D_GetLength(x, y, z), x, y, z);
end

function Vector3D_AddVector(left, right)
	local clone = left:Clone();
	clone:Add(right);
	return clone;
end

function Vector3D_SubtractVector(left, right)
	local clone = left:Clone();
	clone:Subtract(right);
	return clone;
end

function Vector3D_NormalizeVector(vector)
	local clone = vector:Clone();
	clone:Normalize();
	return clone;
end

function Vector3D_ScaleVector(scalar, vector)
	local clone = vector:Clone();
	clone:ScaleBy(scalar);
	return clone;
end

function Vector3D_CalculateNormalFromYawPitch(yaw, pitch)
	return	cos(-pitch) * cos(yaw),
			cos(-pitch) * sin(yaw),
			sin(-pitch);
end

function Vector3D_CalculateYawPitchFromNormal(x, y, z)
	if x ~= 0 or y ~= 0 then
		return atan2(y, x), asin(-z);
	end

	return 0, asin(-z);
end

function Vector3D_CalculateYawPitchFromNormalVector(vector)
	return Vector3D_CalculateYawPitchFromNormal(vector:GetXYZ());
end


function Vector3D_CreateNormalVectorFromYawPitch(yawRadians, pitchRadians)
	return CreateVector3D(Vector3D_CalculateNormalFromYawPitch(yawRadians, pitchRadians));
end

Vector3DMixin = {};

function CreateVector3D(x, y, z)
	local vector = CreateFromMixins(Vector3DMixin);
	vector:OnLoad(x, y, z);
	return vector;
end

function AreVector3DEqual(left, right)
	if left and right then
		return left:IsEqualTo(right);
	end
	return left == right;
end

function Vector3DMixin:OnLoad(x, y, z)
	self:SetXYZ(x, y, z);
end

function Vector3DMixin:IsEqualTo(otherVector)
	return self.x == otherVector.x
	   and self.y == otherVector.y
	   and self.z == otherVector.z;
end

function Vector3DMixin:GetXYZ()
	return self.x, self.y, self.z;
end

function Vector3DMixin:SetXYZ(x, y, z)
	self.x = x;
	self.y = y;
	self.z = z;
end

function Vector3DMixin:ScaleBy(scalar)
	self:SetXYZ(Vector3D_ScaleBy(scalar, self:GetXYZ()));
	return self;
end

function Vector3DMixin:DivideBy(scalar)
	self:SetXYZ(Vector3D_DivideBy(scalar, self:GetXYZ()));
	return self;
end

function Vector3DMixin:Add(other)
	self:SetXYZ(Vector3D_Add(self.x, self.y, self.z, other:GetXYZ()));
	return self;
end

function Vector3DMixin:Subtract(other)
	self:SetXYZ(Vector3D_Subtract(self.x, self.y, self.z, other:GetXYZ()));
	return self;
end

function Vector3DMixin:Cross(other)
	self:SetXYZ(Vector3D_Cross(self.x, self.y, self.z, other:GetXYZ()));
	return self;
end

function Vector3DMixin:Dot(other)
	return Vector3D_Dot(self.x, self.y, self.z, other:GetXYZ());
end

function Vector3DMixin:GetLengthSquared()
	return Vector3D_GetLengthSquared(self:GetXYZ());
end

function Vector3DMixin:GetLength()
	return Vector3D_GetLength(self:GetXYZ());
end

function Vector3DMixin:Normalize()
	self:SetXYZ(Vector3D_Normalize(self:GetXYZ()));
	return self;
end

function Vector3DMixin:Clone()
	return CreateVector3D(self:GetXYZ());
end
]] },
