function GridLayoutUtilSectionStrategy.SplitRegionsIntoSectionsByCellSize(sectionSize, layoutManager, regions)
	local function GridRegionDataProviderByRow(i)
		return regions[i];
	end

	local function CellSectionSizeCalculator(region, currentSectionSize)
		return layoutManager:CalculateCellSize(region);
	end

	return GridLayoutUtilSectionStrategy.SplitRegionsIntoSectionsBySize(sectionSize, layoutManager, GridRegionDataProviderByRow, CellSectionSizeCalculator);
end

function GridLayoutUtilSectionStrategy.SplitRegionsIntoGridSectionsInternal(sectionSize, layoutManager, regionDataProvider)
	local function GridSectionSizeCalculator(region, currentSectionSize)
		return 1;
	end

	return GridLayoutUtilSectionStrategy.SplitRegionsIntoSectionsBySize(sectionSize, layoutManager, regionDataProvider, GridSectionSizeCalculator);
end

function GridLayoutUtilSectionStrategy.SplitRegionsIntoGridSections(sectionSize, layoutManager, regions)
	local function GridRegionDataProviderByRow(i)
		return regions[i];
	end

	return GridLayoutUtilSectionStrategy.SplitRegionsIntoGridSectionsInternal(sectionSize, layoutManager, GridRegionDataProviderByRow);
end

function GridLayoutUtilSectionStrategy.SplitRegionsIntoGridSectionsVertical(sectionSize, layoutManager, regions)
	local numRegions = #regions;
	local numCrossSections = math.ceil(numRegions / sectionSize);
	local function GridRegionDataProviderVertical(i)
		if i > numRegions then
			return nil;
		end

		local row = ((i - 1) % sectionSize) * numCrossSections;
		local column = math.ceil(i / sectionSize);
		return regions[row + column];
	end

	return GridLayoutUtilSectionStrategy.SplitRegionsIntoGridSectionsInternal(sectionSize, layoutManager, GridRegionDataProviderVertical);
end


GridLayoutUtilCrossSectionStrategy = {};

function GridLayoutUtilCrossSectionStrategy.CalculateGridCrossSections(layoutManager, sectionGroup)
	local crossSectionGroups = {};

	local infiniteGuard = INFINITE_GUARD;
	for crossSectionIndex = 1, infiniteGuard do
		local crossSection = CreateAndInitFromMixin(GridLayoutSectionGroupMixin, layoutManager);
		local crossSectionIsEmpty = true;
		for i, section in sectionGroup:EnumerateSections() do
			local sectionRegion = section:GetRegionEntry(crossSectionIndex);
			if sectionRegion then
				crossSection:AddToSection(i, sectionRegion);
				crossSectionIsEmpty = false;
			else
				crossSection:AddEmptySection();
			end
		end

		if crossSectionIsEmpty then
			break;
		end

		table.insert(crossSectionGroups, crossSection);
	end

	return crossSectionGroups;
end

function GridLayoutUtilCrossSectionStrategy.CalculateFlatCrossSections(layoutManager, sectionGroup)
	local crossSectionGroups = {};

	local crossSectionGroup = CreateAndInitFromMixin(GridLayoutSectionGroupMixin, layoutManager);
	for i, section in sectionGroup:EnumerateSections() do
		for j, region in section:EnumerateRegionEntries() do
			crossSectionGroup:AddToSection(i, region);
		end

	end
	table.insert(crossSectionGroups, crossSectionGroup);

	return crossSectionGroups;
end


GridLayoutUtilPrimaryPaddingStrategy = {};

function GridLayoutUtilPrimaryPaddingStrategy.AllPaddingToFirst(section, regionSizeCalculator, paddingSetter, spacingSetter, availableSize)
	local firstRegionEntry = section:GetRegionEntry(1);
	if firstRegionEntry ~= nil then
		paddingSetter(firstRegionEntry, availableSize);
	end
end

function GridLayoutUtilPrimaryPaddingStrategy.AllSpacingToLast(section, regionSizeCalculator, paddingSetter, spacingSetter, availableSize)
	local lastRegionIndex = section:GetNumRegionEntries();
	if lastRegionIndex ~= 0 then
		local lastRegionEntry = section:GetRegionEntry(lastRegionIndex);
		spacingSetter(lastRegionEntry, availableSize);
	end
end

function GridLayoutUtilPrimaryPaddingStrategy.EvenSpacing(section, regionSizeCalculator, paddingSetter, spacingSetter, availableSize)
	local numRegionEntries = section:GetNumRegionEntries();
	if numRegionEntries == 0 then
		return;
	end

	if numRegionEntries == 1 then
		local regionEntry = section:GetRegionEntry(1);
		local equalPadding = availableSize / 2;
		paddingSetter(regionEntry, equalPadding);
		spacingSetter(regionEntry, equalPadding);
		return;
	end

	local spacedEntries = numRegionEntries - 1;
	local equalSpacing = availableSize / spacedEntries;

	for i = 1, spacedEntries do
		local regionEntry = section:GetRegionEntry(i);
		spacingSetter(regionEntry, equalSpacing);
	end
end


GridLayoutUtilSecondaryPaddingStrategy = {};

function GridLayoutUtilSecondaryPaddingStrategy.Equal(section, regionSizeCalculator, paddingSetter, spacingSetter, sectionSecondarySize)
	for i, regionEntry in section:EnumerateRegionEntries() do
		local padding = (sectionSecondarySize - regionSizeCalculator(regionEntry)) / 2;
		paddingSetter(regionEntry, padding);
		spacingSetter(regionEntry, padding);
	end
end

function GridLayoutUtilSecondaryPaddingStrategy.AllPadding(section, regionSizeCalculator, paddingSetter, spacingSetter, sectionSecondarySize)
	for i, regionEntry in section:EnumerateRegionEntries() do
		local availableSize = sectionSecondarySize - regionSizeCalculator(regionEntry);
		paddingSetter(regionEntry, availableSize);
	end
end

function GridLayoutUtilSecondaryPaddingStrategy.AllSpacing(section, regionSizeCalculator, paddingSetter, spacingSetter, sectionSecondarySize)
	for i, regionEntry in section:EnumerateRegionEntries() do
		local availableSize = sectionSecondarySize - regionSizeCalculator(regionEntry);
		spacingSetter(regionEntry, availableSize);
	end
end
]] },
{ 'Blizzard_SharedXML\\ScriptAnimationUtil.lua', [[

local function NoEasing(progress)
	return progress;
end

ScriptAnimationUtil = {};

function ScriptAnimationUtil.GetScriptAnimationLock(region)
	if region.scriptedAnimatedAnchorLock then
		return false;
	end

	region.scriptedAnimatedAnchorLock = true;
	return true;
end

function ScriptAnimationUtil.ReleaseScriptAnimationLock(region)
	region.scriptedAnimatedAnchorLock = nil;
end

function ScriptAnimationUtil.IsScriptAnimationLockActive(region)
	return region.scriptedAnimatedAnchorLock ~= nil;
end

-- Returns a callback to cancel the animation.
function ScriptAnimationUtil.StartFadeAnimation(region, duration, onFinish, easingFunction)
	easingFunction = easingFunction or NoEasing;

	local distanceX = 0;
	local distanceY = 0;
	local alphaVariation = -region:GetAlpha();
	local scaleVariation = 0;
	local variationCallback = ScriptAnimationUtil.GenerateEasedVariationCallback(easingFunction, distanceX, distanceY, alphaVariation, scaleVariation);
	return ScriptAnimationUtil.StartScriptAnimation(region, variationCallback, duration, function()
		region:SetAlpha(0);
		if onFinish then
			onFinish(region);
		end
	end);
end

function ScriptAnimationUtil.ShakeFrameRandom(region, magnitude, duration, frequency)
	if duration == 0 then
		return nop;
	end

	if frequency <= 0 or ScriptAnimationUtil.IsScriptAnimationLockActive(region) then
		return nop;
	end

	local shake = {};
	for i = 1, math.ceil(duration / frequency) do
		local xVariation, yVariation = RandomFloatInRange(-magnitude, magnitude), RandomFloatInRange(-magnitude, magnitude);
		shake[i] = { x = xVariation, y = yVariation };
	end

	return ScriptAnimationUtil.ShakeFrame(region, shake, duration, frequency);
end

function ScriptAnimationUtil.ShakeFrame(region, shake, maximumDuration, frequency)
	local shakeStrength = tonumber(GetCVar("ShakeStrengthUI"));
	if shakeStrength <= 0 or not ScriptAnimationUtil.GetScriptAnimationLock(region) then
		return nop;
	end

	if shake[1] == nil then
		return nop;
	end

	local point, relativeRegion, relativePoint, x, y = region:GetPoint(1);
	local shakeIndex = 1;
	local endTime = GetTime() + maximumDuration;

	local function CancelShake()
		region:SetPoint(point, relativeRegion, relativePoint, x, y);
		region.shakeTicker:Cancel();
		region.shakeTicker = nil;
		ScriptAnimationUtil.ReleaseScriptAnimationLock(region);
	end

	region.shakeTicker = C_Timer.NewTicker(frequency, function()
		local xVariation, yVariation = shake[shakeIndex].x * shakeStrength, shake[shakeIndex].y * shakeStrength;
		region:SetPoint(point, relativeRegion, relativePoint, x + xVariation, y + yVariation);
		shakeIndex = shakeIndex + 1;
		if shakeIndex > #shake or GetTime() >= endTime then
			CancelShake();
		end
	end);

	return CancelShake;
end

function ScriptAnimationUtil.GenerateEasedVariationCallback(easingFunction, distanceX, distanceY, alpha, scale)
	distanceX = distanceX or 0;
	distanceY = distanceY or 0;
	alpha = alpha or 0;
	scale = scale or 0;

	local function VariationCallback(elapsedTime, duration)
		local progress = (easingFunction and easingFunction(elapsedTime / duration)) or (elapsedTime / duration);
		return distanceX * progress, distanceY * progress, alpha * progress, scale * progress;
	end

	return VariationCallback;
end


function ScriptAnimationUtil.StartScriptAnimation(region, variationCallback, duration, onFinish)
	if not ScriptAnimationUtil.GetScriptAnimationLock(region) then
		if onFinish then
			onFinish(region);
		end
		return nop;
	end

	variationCallback = variationCallback;

	local point, relativeRegion, relativePoint, x, y = region:GetPoint(1);
	local alpha = region:GetAlpha();
	local scale = region:GetScale();

	local function ApplyVariation(variationX, variationY, variationAlpha, variationScale)
		region:SetPoint(point, relativeRegion, relativePoint, x + (variationX or 0), y + (variationY or 0));
		region:SetAlpha(alpha + (variationAlpha or 0));
		region:SetScale(scale + (variationScale or 0));
	end

	local startTime = GetTime();
	local endTime = startTime + duration;
	local elapsedTime = 0;
	ApplyVariation(variationCallback(elapsedTime, duration));

	local function CancelScriptAnimation()
		ApplyVariation(variationCallback(duration, duration));
		region.translationTicker:Cancel();
		region.translationTicker = nil;
		ScriptAnimationUtil.ReleaseScriptAnimationLock(region);
		if onFinish then
			onFinish(region);
		end
	end

	local function TranslationTickerFunction()
		local currentTime = GetTime();

		local finished = GetTime() >= endTime;
		if finished then
			CancelScriptAnimation();
		else
			elapsedTime = currentTime - startTime;
			ApplyVariation(variationCallback(elapsedTime, duration));
		end
	end

	region.translationTicker = C_Timer.NewTicker(0.01, TranslationTickerFunction);

	return CancelScriptAnimation;
end

function ScriptAnimationUtil.StartScriptAnimationGeneric(region, variationCallback, duration, frequency, onFinish)
	if not ScriptAnimationUtil.GetScriptAnimationLock(region) then
		if onFinish then
			onFinish(region);
		end
		return nop;
	end

	local function CancelScriptAnimation()
		if region.scriptAnimationTicker then
			variationCallback(region, duration, duration);
			region.scriptAnimationTicker:Cancel();
			region.scriptAnimationTicker = nil;
			ScriptAnimationUtil.ReleaseScriptAnimationLock(region);
			if onFinish then
				onFinish(region);
			end
		end
	end

	local startTime = GetTime();
	local endTime = startTime + duration;

	local function TranslationTickerFunction()
		local currentTime = GetTime();
		local finished = currentTime >= endTime;
		if finished then
			CancelScriptAnimation();
		else
			local elapsedTime = currentTime - startTime;
			variationCallback(region, elapsedTime, duration);
		end
	end

	region.scriptAnimationTicker = C_Timer.NewTicker(frequency or 0.01, TranslationTickerFunction);

	return CancelScriptAnimation;
end
]] },
{ 'Blizzard_SharedXML\\StringUtil.lua', [[
function ConfirmationStringMatches(userInput, expectedText)
	return strupper(userInput) == strupper(expectedText);
end

function ConfirmationEditBoxMatches(editBox, expectedText)
	return ConfirmationStringMatches(editBox:GetText(), expectedText);
end

function UserInputNonEmpty(userInput)
	return userInput and strtrim(userInput) ~= "";
end

function UserEditBoxNonEmpty(editBox)
	return UserInputNonEmpty(editBox:GetText());
end

function StringSplitIntoTable(sep, string)
	return { strsplit(sep, string) };
end

StringUtil = {};

function StringUtil.RemoveTrailingSpaces(str)
	return str:match("^(.-)%s*$");
end

function StringUtil.JoinAlternatingConditionalColor(delimiter, unmetColor, ...)
	if ( select("#", ...) == 0 ) then
		return nil;
	end

	local text, meetsCondition = ...;
	local joinedString = meetsCondition and text or unmetColor:WrapTextInColorCode(text);
	for i = 3, select("#", ...), 2 do
		text, meetsCondition = select(i, ...);
		local formattedText = meetsCondition and text or unmetColor:WrapTextInColorCode(text);
		joinedString = joinedString .. delimiter .. formattedText;
	end

	return joinedString;
end
