		msg = BLIZZARD_STORE_ERROR_MESSAGE_PARENTAL_CONTROLS,
	},
	[Enum.StoreError.PurchaseDenied] = {
		title = BLIZZARD_STORE_ERROR_TITLE_PURCHASE_DENIED,
		msg = BLIZZARD_STORE_ERROR_MESSAGE_PURCHASE_DENIED,
	},
	[Enum.StoreError.ConsumableTokenOwned] = {
		title = BLIZZARD_STORE_ERROR_TITLE_CONSUMABLE_TOKEN_OWNED,
		msg = BLIZZARD_STORE_ERROR_MESSAGE_CONSUMABLE_TOKEN_OWNED,
	},
	[Enum.StoreError.TooManyTokens] = {
		title = BLIZZARD_STORE_ERROR_TITLE_CONSUMABLE_TOKEN_OWNED,
		msg = BLIZZARD_STORE_ERROR_YOU_OWN_TOO_MANY_OF_THIS,
	},
	[Enum.StoreError.ItemUnavailable] = {
		title = BLIZZARD_STORE_ERROR_TITLE_CONSUMABLE_TOKEN_OWNED,
		msg = BLIZZARD_STORE_ERROR_ITEM_UNAVAILABLE,
	},
	[Enum.StoreError.ClientRestricted] = {
		title = BLIZZARD_STORE_ERROR_TITLE_CLIENT_RESTRICTED,
		msg = BLIZZARD_STORE_ERROR_CLIENT_RESTRICTED,
	},
};

function VASErrorData_HasError(errorCode)
	return vasErrorData[errorCode] ~= nil;
end

function VASErrorData_IsUserFixableError(errorCode)
	local error = vasErrorData[errorCode];
	if error then
		return not error.notUserFixable;
	end

	return false; -- Not sure if an error we don't know about can be fixed, so it can't be.
end

function VASErrorData_GetMessage(errorCode, character)
	local errorData = vasErrorData[errorCode];
	if errorData then
		if type(errorData.msg) == "function" then
			return errorData.msg(character);
		end

		return errorData.msg;
	end

	return "";
end

function VASErrorData_GetCombinedMessage(characterGUID)
	local errors = C_StoreSecure.GetVASErrors();

	local msgTable = {};

	local character = C_StoreSecure.GetCharacterInfoByGUID(characterGUID);
	for index, errorID in ipairs(errors) do
		local error = VASErrorData_GetMessage(errorID, character);
		table.insert(msgTable, error);
	end

	local displayMsg = table.concat(msgTable, "\n");
	displayMsg = (displayMsg ~= "") and displayMsg or BLIZZARD_STORE_VAS_ERROR_OTHER;

	return displayMsg;
end

function StoreErrorData_GetMessage(errorCode)
	local info = storeErrorData[errorCode];
	if not info then
		info = storeErrorData[Enum.StoreError.Other];
	end

	return info.title, info.msg, info.link;
end

function VASAssignErrorData_GetMessage(errorCode)
	local info = vasAssignErrorData[errorCode];
	local errorText = info and info.msg or BLIZZARD_STORE_INTERNAL_ERROR;
	return errorText;
end
]] },
{ 'Blizzard_SharedXML\\SelectableButton.lua', [[
SelectableButtonMixin = {};

function SelectableButtonMixin:OnLoad()
	self.selected = false;
end

function SelectableButtonMixin:Reset()
	self.CanChangeSelectionOverride = nil;
	self.selected = false;
end

function SelectableButtonMixin:OnClick()
	return self:SetSelected(not self:IsSelected());
end

function SelectableButtonMixin:CanChangeSelection(newSelected)
	if self:IsSelected() == newSelected then
		return false;
	end

	if self.SelectionChangeInterrupt then
		return self.SelectionChangeInterrupt(self, newSelected);
	end

	return true;
end

function SelectableButtonMixin:SetSelectionChangeInterrupt(callback)
	self.SelectionChangeInterrupt = callback;
end

function SelectableButtonMixin:IsSelected()
	return not not self.selected;
end

function SelectableButtonMixin:SetSelected(newSelected)
	if self:CanChangeSelection(newSelected) then
		self:SetSelectedState(newSelected);
		self:OnSelected(newSelected);
	end
end

function SelectableButtonMixin:OnSelected(newSelected)
-- Derive
end

function SelectableButtonMixin:SetSelectedState(newSelected)
	-- Derive
	self.selected = newSelected;
end]] },
{ 'Blizzard_SharedXML\\ButtonGroup.lua', [=[
--[[
	Required Elements - all buttons in the group need to inherit from SelectableButtonMixin
	and have the OnClick handler defined in XML
]]

ButtonGroupBaseMixin = CreateFromMixins(CallbackRegistryMixin);

ButtonGroupBaseMixin:GenerateCallbackEvents(
	{
		"Selected",
		"Unselected",
	}
);

function ButtonGroupBaseMixin:Init()
	CallbackRegistryMixin.OnLoad(self);
	self.buttons = {};
end

function ButtonGroupBaseMixin:SetShown(shown)
	for index, button in ipairs(self.buttons) do
		button:SetShown(shown);
	end
end

function ButtonGroupBaseMixin:AddButton(button)
	self:AddInternal(button);
end

function ButtonGroupBaseMixin:AddButtons(buttons)
	for buttonIndex, button in ipairs(buttons) do
		self:AddInternal(button);
	end
end

function ButtonGroupBaseMixin:AddInternal(button, func, group)
	table.insert(self.buttons, button);

	-- NOTE: The SelectableButton that this is intended to be used with doesn't actually care about the mouseButton argument.
	local previousOnClickScript = button:GetScript("OnClick");
	assert(not button.previousOnClickScript);
	button.previousOnClickScript = previousOnClickScript;

	button:SetScript("OnClick", function(o, mouseButton)
		-- Only run our group's selection changed callback if the button object didn't have a mixin-OnClick method,
		-- or if the OnClick method indicated that selection state actually changed.
		local wasSelected = button:IsSelected();

		if previousOnClickScript then
			previousOnClickScript(button, mouseButton);
		end

		local isSelected = button:IsSelected();
		local selectionChanged = wasSelected ~= isSelected;

		if not previousOnClickScript or selectionChanged then
			func(group, button, button:IsSelected());
		end
	end);
end

function ButtonGroupBaseMixin:RemoveButton(button)
	self:RemoveInternal(button);
end

function ButtonGroupBaseMixin:RemoveButtons(buttons)
	if buttons == self.buttons then
		self:RemoveAllButtons();
	else
		for buttonIndex, button in ipairs(buttons) do
			self:RemoveInternal(button);
		end
	end
end

function ButtonGroupBaseMixin:RemoveInternal(button)
	tDeleteItem(self.buttons, button);

	-- Restore the button's OnClick to whatever it used to be.
	button:SetScript("OnClick", button.previousOnClickScript);
	button.previousOnClickScript = nil;
end

function ButtonGroupBaseMixin:SetButtons(buttons)
	self:RemoveAllButtons();
	self:AddButtons(buttons);
end

function ButtonGroupBaseMixin:RemoveAllButtons()
	for index, button in ipairs_reverse(self.buttons) do
		self:RemoveInternal(button);
	end
end

function ButtonGroupBaseMixin:GetButtons()
	return self.buttons;
end

function ButtonGroupBaseMixin:Reset()
	self:RemoveAllButtons();
	self:UnregisterEvents();
	self.callbacks = {};
end

function ButtonGroupBaseMixin:FindButtonByPredicate(pred)
	for buttonIndex, button in ipairs(self.buttons) do
		if pred(button) then
			return button;
		end
	end
	return nil;
end

function ButtonGroupBaseMixin:GetButtonsByPredicate(pred)
	local buttons = {};
	for buttonIndex, button in ipairs(self.buttons) do
		if pred(button) then
			table.insert(buttons, button);
		end
	end
	return buttons;
end

function ButtonGroupBaseMixin:Unselect(button)
	self:UnselectAtIndex(self:GetButtonIndex(button));
end

function ButtonGroupBaseMixin:Select(button)
	self:SelectAtIndex(self:GetButtonIndex(button));
end

function ButtonGroupBaseMixin:SelectAtIndex(index)
	self:SetSelectedAtIndex(index, true);
end

function ButtonGroupBaseMixin:UnselectAtIndex(index)
	self:SetSelectedAtIndex(index, false);
end

local function SetButtonSelectedAndGetWasChanged(button, selected)
	local wasSelected = button:IsSelected();
	button:SetSelected(selected);
	return wasSelected ~= button:IsSelected();
end

function ButtonGroupBaseMixin:SetSelectedAtIndex(index, selected)
	local button = self:GetAtIndex(index);
	if button then

		if SetButtonSelectedAndGetWasChanged(button, selected) then
			self:OnSelectionChange(button, selected);
		end
	end
end

function ButtonGroupBaseMixin:GetSelectedButtons()
	return self:GetButtonsByPredicate(
		function(button)
			return button:IsSelected();
		end
	);
end

function ButtonGroupBaseMixin:GetButtonIndex(button)
	return tIndexOf(self.buttons, button);
end

function ButtonGroupBaseMixin:GetAtIndex(index)
	return self.buttons[index];
end

ButtonGroupMixin = CreateFromMixins(ButtonGroupBaseMixin);

function ButtonGroupMixin:OnSelectionChange(button, newSelected)
	local event = newSelected and ButtonGroupBaseMixin.Event.Selected or ButtonGroupBaseMixin.Event.Unselected;
	self:TriggerEvent(event, button, self:GetButtonIndex(button));
end

function ButtonGroupMixin:AddInternal(button)
	ButtonGroupBaseMixin.AddInternal(self, button, self.OnSelectionChange, self);
end

function CreateButtonGroup()
	return CreateAndInitFromMixin(ButtonGroupMixin);
end

RadioButtonGroupMixin = CreateFromMixins(ButtonGroupBaseMixin);

function RadioButtonGroupMixin:CanChangeSelection(button, newSelected)
	return not (not newSelected and #self:GetSelectedButtons() == 1);
end

function RadioButtonGroupMixin:OnSelectionChange(button, newSelected)
	-- Deselect everything that was selected
	for selectedButtonIndex, selectedButton in ipairs(self:GetSelectedButtons()) do
		if selectedButton ~= button then
			selectedButton:SetSelected(false);
			self:TriggerEvent(ButtonGroupBaseMixin.Event.Unselected, selectedButton, self:GetButtonIndex(selectedButton));
		end
	end

	-- Select the new thing if appropriate
	if newSelected then
		self:TriggerEvent(ButtonGroupBaseMixin.Event.Selected, button, self:GetButtonIndex(button));
	else
		self:TriggerEvent(ButtonGroupBaseMixin.Event.Unselected, button, self:GetButtonIndex(button));
	end
end

function RadioButtonGroupMixin:AddInternal(button)
	button:SetSelectionChangeInterrupt(GenerateClosure(self.CanChangeSelection, self));
	ButtonGroupBaseMixin.AddInternal(self, button, self.OnSelectionChange, self);
end

function RadioButtonGroupMixin:RemoveInternal(button)
	button:SetSelectionChangeInterrupt(nil);
	ButtonGroupBaseMixin.RemoveInternal(self, button);
end

DeselectableRadioButtonGroupMixin = CreateFromMixins(RadioButtonGroupMixin);

function DeselectableRadioButtonGroupMixin:CanChangeSelection(button, newSelected)
	return true;
end

--[[
	Required Elements - all buttons in the group need to inherit from SelectableButtonTemplate
	and you CAN override the OnLoad, and OnClick handler if needed
]]--
function CreateRadioButtonGroup()
	return CreateAndInitFromMixin(RadioButtonGroupMixin);
end

function CreateDeselectableRadioButtonGroup()
	return CreateAndInitFromMixin(DeselectableRadioButtonGroupMixin);
end

]=] },
{ 'Blizzard_SharedXML\\Shared\\Button\\UIButtonTemplate.lua', [[

UIButtonMixin = {}

function UIButtonMixin:InitButton()
	if self.buttonArtKit then
		self:SetButtonArtKit(self.buttonArtKit);
	end

	self:SetDisabledTooltip(self.disabledTooltip);
end

function UIButtonMixin:OnClick(...)
	PlaySound(self.onClickSoundKit or SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON);

	if self.onClickHandler then
		self.onClickHandler(self, ...);
	end
end

function UIButtonMixin:OnEnter()
	self:RunCustomTextFormatter();

	if self.onEnterHandler and self.onEnterHandler(self) then
		return;
	end

	local defaultTooltipAnchor = "ANCHOR_RIGHT";
	if self:IsEnabled() then
		if self.tooltipTitle or self.tooltipText then
			local tooltip = GetAppropriateTooltip();
			tooltip:SetOwner(self, self.tooltipAnchor or defaultTooltipAnchor, self.tooltipOffsetX, self.tooltipOffsetY);

			if self.tooltipTitle then
				GameTooltip_SetTitle(tooltip, self.tooltipTitle, self.tooltipTitleColor);
			end

			if self.tooltipText then
				local wrap = true;
				if self.tooltipDisableWrapText then
					wrap = false;
				end

				GameTooltip_AddColoredLine(tooltip, self.tooltipText, self.tooltipTextColor or NORMAL_FONT_COLOR, wrap);
			end

			tooltip:Show();
		end
	else
		if self.disabledTooltip then
			local tooltip = GetAppropriateTooltip();
			GameTooltip_ShowDisabledTooltip(tooltip, self, self.disabledTooltip, self.disabledTooltipAnchor or defaultTooltipAnchor, self.disabledTooltipOffsetX, self.disabledTooltipOffsetY);
		end
	end
end

function UIButtonMixin:OnLeave()
	self:RunCustomTextFormatter();

	local tooltip = GetAppropriateTooltip();
	if not tooltip then
		return;
	end
	tooltip:Hide();
end

function UIButtonMixin:SetButtonArtKit(buttonArtKit)
	self.buttonArtKit = buttonArtKit;

	self:SetNormalAtlas(buttonArtKit);
	self:SetPushedAtlas(buttonArtKit.."-Pressed");
	self:SetDisabledAtlas(buttonArtKit.."-Disabled");
	self:SetHighlightAtlas(buttonArtKit.."-Highlight");
end

function UIButtonMixin:SetOnClickHandler(onClickHandler, onClickSoundKit)
	self.onClickHandler = onClickHandler;
	self.onClickSoundKit = onClickSoundKit;
end

function UIButtonMixin:GetOnClickSoundKit()
	return self.onClickSoundKit;
end

function UIButtonMixin:SetCustomTextFormatter(customTextFormatter)
	if self.customTextFormatter then
		self:ClearCustomTextFormatter();
	end

	self.customTextFormatter = customTextFormatter;

	local function OverrideScriptForFormatter(scriptName, scriptFunction)
		local originalHandler = self:GetScript(scriptName);
		self["original"..scriptName.."Script"] = originalHandler;
		self:SetScript(scriptName, function(...)
			if originalHandler then
				originalHandler(...);
			end

			scriptFunction(...);
		end);
	end

	OverrideScriptForFormatter("OnEnable", self.RunCustomTextFormatter);
	OverrideScriptForFormatter("OnDisable", self.RunCustomTextFormatter);

	self:RunCustomTextFormatter();
end

function UIButtonMixin:ClearCustomTextFormatter()
	self.customTextFormatter = nil;

	local function RestoreOriginalScriptHandler(scriptName)
		local memberName = "original"..scriptName.."Script";
		local originalHandler = self[memberName];
		self[memberName] = nil;
		if originalHandler then
			self:SetScript(scriptName, originalHandler);
		end
	end

	RestoreOriginalScriptHandler("OnEnable");
	RestoreOriginalScriptHandler("OnDisable");
end

function UIButtonMixin:RunCustomTextFormatter()
	if self.customTextFormatter then
		local highlight = self:IsMouseMotionFocus();
		local enabled = self:IsEnabled();
		self.Text:SetText(self.customTextFormatter(self, enabled, highlight));
		self:SetWidth(self:GetTextWidth() + 20); -- Add some padding to the width so that the text doesn't get cut off.
	end
end

function UIButtonMixin:SetOnEnterHandler(onEnterHandler)
	self.onEnterHandler = onEnterHandler;
end

function UIButtonMixin:SetTooltipInfo(tooltipTitle, tooltipText)
	self.tooltipTitle = tooltipTitle;
	self.tooltipText = tooltipText;
end

function UIButtonMixin:SetTooltipAnchor(tooltipAnchor, tooltipOffsetX, tooltipOffsetY)
	self.tooltipAnchor = tooltipAnchor;
	self.tooltipOffsetX = tooltipOffsetX;
	self.tooltipOffsetY = tooltipOffsetY;
end

function UIButtonMixin:SetDisabledTooltip(disabledTooltip, disabledTooltipAnchor, disabledTooltipOffsetX, disabledTooltipOffsetY)
	self.disabledTooltip = disabledTooltip;
	self.disabledTooltipAnchor = disabledTooltipAnchor;
	self.disabledTooltipOffsetX = disabledTooltipOffsetX;
	self.disabledTooltipOffsetY = disabledTooltipOffsetY;

	-- NOTE: Remains on to preserve previous behavior
	if self.disabledTooltip then
		self:SetMotionScriptsWhileDisabled(true);
	end
end
]] },
{ 'Blizzard_SharedXML\\Shared\\Button\\ThreeSliceButtonTemplate.lua', [[

ThreeSliceButtonMixin = CreateFromMixins(UIButtonMixin);

function ThreeSliceButtonMixin:GetLeftAtlasName()
	return self.atlasName.."-Left";
end

function ThreeSliceButtonMixin:GetRightAtlasName()
	return self.atlasName.."-Right";
end

function ThreeSliceButtonMixin:GetCenterAtlasName()
	return "_"..self.atlasName.."-Center";
end

function ThreeSliceButtonMixin:GetHighlightAtlasName()
	return self.atlasName.."-Highlight";
end

function ThreeSliceButtonMixin:InitButton()
	self.leftAtlasInfo = C_Texture.GetAtlasInfo(self:GetLeftAtlasName());
	self.rightAtlasInfo = C_Texture.GetAtlasInfo(self:GetRightAtlasName());

	self:SetHighlightAtlas(self:GetHighlightAtlasName());
end

function ThreeSliceButtonMixin:UpdateScale()
	local buttonHeight = self:GetHeight();
	local buttonWidth = self:GetWidth();
	local scale = buttonHeight / self.leftAtlasInfo.height;
	self.Left:SetScale(scale);
	self.Right:SetScale(scale);

	local leftWidth = self.leftAtlasInfo.width * scale;
	local rightWidth = self.rightAtlasInfo.width * scale;
	local leftAndRightWidth = leftWidth + rightWidth;

	if leftAndRightWidth > buttonWidth then
		-- At the current buttonHeight, the left and right textures are too big to fit within the button width
		-- So slice some width off of the textures and adjust texture coords accordingly
		local extraWidth = leftAndRightWidth - buttonWidth;
		local newLeftWidth = leftWidth;
		local newRightWidth = rightWidth;

		-- If one of the textures is sufficiently larger than the other one, we can remove all of the width from there
		if (leftWidth - extraWidth) > rightWidth then
			-- left is big enough to take the whole thing...deduct it all from there
			newLeftWidth = leftWidth - extraWidth;
		elseif (rightWidth - extraWidth) > leftWidth then
			-- right is big enough to take the whole thing...deduct it all from there
			newRightWidth = rightWidth - extraWidth;
		else
			-- neither side is sufficiently larger than the other to take the whole extra width
			if leftWidth ~= rightWidth then
				-- so set both widths equal to the smaller size and subtract the difference from extraWidth
				local unevenAmount = math.abs(leftWidth - rightWidth);
				extraWidth = extraWidth - unevenAmount;
				newLeftWidth = math.min(leftWidth, rightWidth);
				newRightWidth = newLeftWidth;
			end
			-- newLeftWidth and newRightWidth are now equal and we just need to remove half of extraWidth from each
			local equallyDividedExtraWidth = extraWidth / 2;
			newLeftWidth = newLeftWidth - equallyDividedExtraWidth;
			newRightWidth = newRightWidth - equallyDividedExtraWidth;
		end

		-- Now set the tex coords and widths of both textures
		local leftPercentage = newLeftWidth / leftWidth;
		self.Left:SetTexCoord(0, leftPercentage, 0, 1);
		self.Left:SetWidth(newLeftWidth / scale);

		local rightPercentage = newRightWidth / rightWidth;
		self.Right:SetTexCoord(1 - rightPercentage, 1, 0, 1);
		self.Right:SetWidth(newRightWidth / scale);
	else
		self.Left:SetTexCoord(0, 1, 0, 1);
		self.Left:SetWidth(self.leftAtlasInfo.width);
		self.Right:SetTexCoord(0, 1, 0, 1);
		self.Right:SetWidth(self.rightAtlasInfo.width);
	end
end

function ThreeSliceButtonMixin:UpdateButton(buttonState)
	buttonState = buttonState or self:GetButtonState();

	if not self:IsEnabled() then
		buttonState = "DISABLED";
	end

	local atlasNamePostfix = "";
	if buttonState == "DISABLED" then
		atlasNamePostfix = "-Disabled";
	elseif buttonState == "PUSHED" then
		atlasNamePostfix = "-Pressed";
	end

	local useAtlasSize = true;
	self.Left:SetAtlas(self:GetLeftAtlasName()..atlasNamePostfix, useAtlasSize);
	self.Center:SetAtlas(self:GetCenterAtlasName()..atlasNamePostfix);
	self.Right:SetAtlas(self:GetRightAtlasName()..atlasNamePostfix, useAtlasSize);

	self:UpdateScale();
end

function ThreeSliceButtonMixin:OnMouseDown()
	self:UpdateButton("PUSHED");
end

function ThreeSliceButtonMixin:OnMouseUp()
	self:UpdateButton("NORMAL");
end
]] },
{ 'Blizzard_SharedXML\\Shared\\Button\\IconButtonTemplate.lua', [[

IconButtonMixin = CreateFromMixins(UIButtonMixin);

function IconButtonMixin:OnLoad()
	if self.icon then
		self:SetIcon(self.icon);
	elseif self.iconAtlas then
		self:SetAtlas(self.iconAtlas, self.useAtlasSize);
	end

	if self.useIconAsHighlight then
		if self.icon then
			self:SetHighlightTexture(self.icon, "ADD");
		elseif self.iconAtlas then
			self:SetHighlightAtlas(self.iconAtlas, "ADD");
		end

		local highlightTexture = self:GetHighlightTexture();
		highlightTexture:SetPoint("TOPLEFT", self.Icon, "TOPLEFT");
		highlightTexture:SetPoint("BOTTOMRIGHT", self.Icon, "BOTTOMRIGHT");
	end

	if self.iconSize then
		self.Icon:SetSize(self.iconSize, self.iconSize);
	elseif self.iconWidth then
		self.Icon:SetSize(self.iconWidth, self.iconHeight);
	end
end

function IconButtonMixin:OnMouseDown()
	if self:IsEnabled() then
		self.Icon:SetPoint("CENTER", self, "CENTER", 1, -1);
	end
end

function IconButtonMixin:OnMouseUp()
	self.Icon:SetPoint("CENTER", self, "CENTER");
end

function IconButtonMixin:SetIcon(icon)
	self.Icon:SetTexture(icon);
end

function IconButtonMixin:SetAtlas(atlas, useAtlasSize)
	self.Icon:SetAtlas(atlas, useAtlasSize);
end

function IconButtonMixin:SetEnabledState(enabled)
	self:SetEnabled(enabled);
	self.Icon:SetDesaturated(not enabled);
end

SquareIconButtonMixin = CreateFromMixins(IconButtonMixin);

function SquareIconButtonMixin:OnMouseDown()
	-- Overrides IconButtonMixin.

	if self:IsEnabled() then
		-- Square icon button template still uses down-to-the-left depress behavior to match the existing art.
		self.Icon:SetPoint("CENTER", self, "CENTER", -2, -1);
	end
end

function SquareIconButtonMixin:OnMouseUp()
	-- Overrides IconButtonMixin.

	self.Icon:SetPoint("CENTER", self, "CENTER", -1, 0);
end
]] },
