{ 'Blizzard_SharedXML\\Interpolator.lua', [[

InterpolatorUtil = {};

function InterpolatorUtil.InterpolateLinear(v1, v2, t)
	return (v1 * (1 - t)) + (v2 * t);
end

function InterpolatorUtil.InterpolateEaseOut(v1, v2, t)
	local y = math.sin(t * (math.pi * .5));
	return (v1 * (1 - y)) + (v2 * y);
end

function InterpolatorUtil.GetSmoothProgressChange(value, displayedValue, range, elapsed, minPerSecond, maxPerSecond)
	maxPerSecond = maxPerSecond or 0.7;
	minPerSecond = minPerSecond or 0.3;
	minPerSecond = max(minPerSecond, 1 / range);

	local diff = displayedValue - value;
	local diffRatio = diff / range;
	local change = range * ((minPerSecond / abs(diffRatio) + maxPerSecond - minPerSecond) * diffRatio) * elapsed;
	if ( abs(change) > abs(diff) or abs(diffRatio) < 0.01 ) then
		return value;
	else
		return displayedValue - change;
	end
end

InterpolatorMixin = {}

function InterpolatorMixin:Interpolate(v1, v2, time, setter, finished)
	if self.interpolateTo and ApproximatelyEqual(v1, v2) then
		return;
	end
	self.interpolateTo = v2;

	if self.timer then
		self.timer:Cancel();
		self.timer = nil;
	end

	time = math.max(0, time);
	local elapsed = 0;
	local interpolate = function()
		elapsed = elapsed + GetTickTime();
		local u = (time > 0) and Saturate(elapsed / time) or 1;
		setter(self.interpolateFunc(v1, v2, u));
		if u >= 1 then
			if finished then
				finished();
			end

			self:Cancel();
			return false;
		end

		return true;
	end;

	local continue = interpolate();
	if continue then
		self.timer = C_Timer.NewTicker(0, interpolate);
	end
end

function InterpolatorMixin:GetInterpolateTo()
	return self.interpolateTo;
end

function InterpolatorMixin:Cancel()
	self.interpolateTo = nil;
	if self.timer then
		self.timer:Cancel();
		self.timer = nil;
	end
end

function CreateInterpolator(interpolateFunc)
	local interpolator = CreateFromMixins(InterpolatorMixin);
	interpolator.interpolateFunc = interpolateFunc or InterpolatorUtil.InterpolateEaseOut;
	return interpolator;
end]] },
{ 'Blizzard_SharedXML\\Sequencer.lua', [[
SequencerMixin = {};

function SequencerMixin:Init()
	self.original = {};
	self.onFinish = GenerateClosure(self.ExecuteNext, self);
end

function SequencerMixin:AddInterpolated(v1, v2, time, interpType, func)
	local interpolation = {v1 = v1, v2 = v2, time = time, interpType = interpType};
	table.insert(self.original, 1, {interpolation = interpolation, func = func});
end

function SequencerMixin:Add(func)
	table.insert(self.original, 1, {func = func});
end

function SequencerMixin:ExecuteNext()
	local sequence = table.remove(self.sequences);
	if sequence then
		local interpolation = sequence.interpolation;
		if interpolation then
			self.interpolator = CreateInterpolator(sequence.interpType);
			self.interpolator:Interpolate(interpolation.v1, interpolation.v2, interpolation.time, sequence.func, self.onFinish);
		else
			sequence.func();
			self:ExecuteNext();
		end
	end
end

function SequencerMixin:Cancel()
	if self.interpolator then
		self.interpolator:Cancel();
	end
	self.sequences = {};
end

function SequencerMixin:Play()
	local shallow = true;
	self.sequences = CopyTable(self.original, shallow);
	self:ExecuteNext();
end

function CreateSequencer()
	local sequencer = CreateFromMixins(SequencerMixin);
	sequencer:Init();
	return sequencer;
end]] },
{ 'Blizzard_SharedXML\\Shared\\Slider\\MinimalSlider.lua', [[

local STEPPER_DISABLED_ALPHA = 0.5;

MinimalSliderMixin = {};

function MinimalSliderMixin:OnLoad()
	self:SetObeyStepOnDrag(self.obeyStepOnDrag);
end

function MinimalSliderMixin:Release()
	self:SetScript("OnValueChanged", nil);
end

local function NoModification(value)
	return value;
end

function CreateMinimalSliderFormatter(labelType, value)
	local formatter = nil;
	if value == nil then
		formatter = NoModification;
	elseif type(value) == "function" then
		formatter = value;
	else
		-- Ignores the control value and returns the function argument instead.
		formatter = function(v)
			return value;
		end;
	end
	return formatter;
end

MinimalSliderWithSteppersMixin = CreateFromMixins(CallbackRegistryMixin);

MinimalSliderWithSteppersMixin:GenerateCallbackEvents(
	{
		"OnValueChanged",
		"OnInteractStart",
		"OnInteractEnd",
	}
);

MinimalSliderWithSteppersMixin.Label = EnumUtil.MakeEnum("Left", "Right", "Top", "Min", "Max");

local interactionFlags = {
	Hover = 1,
	Click = 2,
};

function MinimalSliderWithSteppersMixin:OnLoad()
	CallbackRegistryMixin.OnLoad(self);

	self.InteractionFlags = CreateFromMixins(FlagsMixin);
	self.InteractionFlags:OnLoad();

	local forward = false;
	self.Back:SetScript("OnClick", GenerateClosure(self.OnStepperClicked, self, forward));

	local backward = true;
	self.Forward:SetScript("OnClick", GenerateClosure(self.OnStepperClicked, self, backward));

	local function OnMouseDown(slider)
		if slider:IsEnabled() then
			self:SetInteractionFlag(interactionFlags.Click);
			PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON);
		end
	end
	self.Slider:SetScript("OnMouseDown", OnMouseDown);

	local function OnMouseUp(slider)
		if slider:IsEnabled() then
			self:ClearInteractionFlag(interactionFlags.Click);
		end
	end
	self.Slider:SetScript("OnMouseUp", OnMouseUp);

	local function OnEnter(slider)
		if slider:IsEnabled() then
			self:SetInteractionFlag(interactionFlags.Hover);
		end
	end
	self.Slider:SetScript("OnEnter", OnEnter);

	local function OnLeave(slider)
		if slider:IsEnabled() then
			self:ClearInteractionFlag(interactionFlags.Hover);
		end
	end
	self.Slider:SetScript("OnLeave", OnLeave);

	self:InitializeNarration();
end

function MinimalSliderWithSteppersMixin:OnStepperClicked(forward)
	local value = self.Slider:GetValue();
	local step = self.Slider:GetValueStep();
	if forward then
		self.Slider:SetValue(value + step);
	else
		self.Slider:SetValue(value - step);
	end

	PlaySound(SOUNDKIT.IG_MAINMENU_OPTION_CHECKBOX_ON);
end

local function SetStepperButtonEnabled(button, enabled)
	button:SetEnabled(enabled);
	button:SetAlpha(enabled and 1.0 or STEPPER_DISABLED_ALPHA);
	button:DesaturateHierarchy(enabled and 0 or 1);
end

function MinimalSliderWithSteppersMixin:UpdateStepperStates()
	if not self:IsSliderEnabled() then
		return;
	end

	local value = self.Slider:GetValue();
	local minValue, maxValue = self.Slider:GetMinMaxValues();
	local step = self.Slider:GetValueStep();
	local atMin = value <= minValue + (step * 0.5);
	local atMax = value >= maxValue - (step * 0.5);
	SetStepperButtonEnabled(self.Back, not atMin);
	SetStepperButtonEnabled(self.Forward, not atMax);
end

function MinimalSliderWithSteppersMixin:Init(value, minValue, maxValue, steps, formatters)
	self.Slider:SetMinMaxValues(minValue, maxValue);
	self.Slider:SetValueStep((maxValue - minValue) / steps);
	self.Slider:SetValue(value);

	self.formatters = formatters;
	self:FormatValue(value);
	self:UpdateStepperStates();

	local function OnValueChanged(slider, value)
		self:FormatValue(value);
		self:UpdateStepperStates();

		self:TriggerEvent(MinimalSliderWithSteppersMixin.Event.OnValueChanged, value);
	end
	self.Slider:SetScript("OnValueChanged", OnValueChanged);
end

function MinimalSliderWithSteppersMixin:SetInteractionFlag(flag)
	local wasAnySet = self.InteractionFlags:IsAnySet();
	self.InteractionFlags:Set(flag);
	if not wasAnySet then
		self:TriggerEvent(MinimalSliderWithSteppersMixin.Event.OnInteractStart);
	end
end

function MinimalSliderWithSteppersMixin:ClearInteractionFlag(flag)
	local wasAnySet = self.InteractionFlags:IsAnySet();
	self.InteractionFlags:Clear(flag);
	if wasAnySet and not self.InteractionFlags:IsAnySet() then
		self:TriggerEvent(MinimalSliderWithSteppersMixin.Event.OnInteractEnd);
	end
end

function MinimalSliderWithSteppersMixin:FormatValue(value)
	if not self.formatters then
		return;
	end

	for labelID, formatter in pairs(self.formatters) do
		local label = self.Labels[labelID];
		if label then
			label:SetText(formatter(value));
			label:Show();
		end
	end
end

