function ScrollBoxListMixin:ScrollToElementDataIndex(dataIndex, alignment, offset, noInterpolation)
	local view = self:GetView();
	if not view then
		return;
	end

	local elementData = self:FindElementData(dataIndex);
	if not elementData then
		return nil;
