	view:PrepareScrollToElementDataByPredicate(predicate);

	local dataIndex = self:FindElementDataIndexByPredicate(predicate);
	if dataIndex then
		return self:ScrollToElementDataIndex(dataIndex, alignment, offset, noInterpolation);
