{ 'Blizzard_SharedXML\\MixinUtil.lua', [[
-- The following function is used with permission from Daniel Stephens
-- texture			- Texture
-- canvasFrame      - Canvas Frame (for anchoring)
-- startX,startY    - Coordinate of start of line
-- endX,endY		- Coordinate of end of line
-- lineWidth        - Width of line
-- relPoint			- Relative point on canvas to interpret coords (Default BOTTOMLEFT)
function DrawLine(texture, canvasFrame, startX, startY, endX, endY, lineWidth, lineFactor, relPoint)
	if (not relPoint) then relPoint = "BOTTOMLEFT"; end
	lineFactor = lineFactor * .5;

	-- Determine dimensions and center point of line
	local dx,dy = endX - startX, endY - startY;
	local cx,cy = (startX + endX) / 2, (startY + endY) / 2;

	-- Normalize direction if necessary
	if (dx < 0) then
		dx,dy = -dx,-dy;
	end

	-- Calculate actual length of line
	local lineLength = sqrt((dx * dx) + (dy * dy));

	-- Quick escape if it'sin zero length
	if (lineLength == 0) then
		texture:SetTexCoord(0,0,0,0,0,0,0,0);
		texture:SetPoint("BOTTOMLEFT", canvasFrame, relPoint, cx,cy);
		texture:SetPoint("TOPRIGHT",   canvasFrame, relPoint, cx,cy);
		return;
	end

	-- Sin and Cosine of rotation, and combination (for later)
	local sin, cos = -dy / lineLength, dx / lineLength;
	local sinCos = sin * cos;

	-- Calculate bounding box size and texture coordinates
	local boundingWidth, boundingHeight, bottomLeftX, bottomLeftY, topLeftX, topLeftY, topRightX, topRightY, bottomRightX, bottomRightY;
	if (dy >= 0) then
		boundingWidth = ((lineLength * cos) - (lineWidth * sin)) * lineFactor;
		boundingHeight = ((lineWidth * cos) - (lineLength * sin)) * lineFactor;

		bottomLeftX = (lineWidth / lineLength) * sinCos;
		bottomLeftY = sin * sin;
		bottomRightY = (lineLength / lineWidth) * sinCos;
		bottomRightX = 1 - bottomLeftY;

		topLeftX = bottomLeftY;
		topLeftY = 1 - bottomRightY;
		topRightX = 1 - bottomLeftX;
		topRightY = bottomRightX;
	else
		boundingWidth = ((lineLength * cos) + (lineWidth * sin)) * lineFactor;
		boundingHeight = ((lineWidth * cos) + (lineLength * sin)) * lineFactor;

		bottomLeftX = sin * sin;
		bottomLeftY = -(lineLength / lineWidth) * sinCos;
		bottomRightX = 1 + (lineWidth / lineLength) * sinCos;
		bottomRightY = bottomLeftX;

		topLeftX = 1 - bottomRightX;
		topLeftY = 1 - bottomLeftX;
		topRightY = 1 - bottomLeftY;
		topRightX = topLeftY;
	end

	-- Set texture coordinates and anchors
	texture:ClearAllPoints();
	texture:SetTexCoord(topLeftX, topLeftY, bottomLeftX, bottomLeftY, topRightX, topRightY, bottomRightX, bottomRightY);
	texture:SetPoint("BOTTOMLEFT", canvasFrame, relPoint, cx - boundingWidth, cy - boundingHeight);
	texture:SetPoint("TOPRIGHT",   canvasFrame, relPoint, cx + boundingWidth, cy + boundingHeight);
end

-- Mix this into a Texture to be able to treat it like a line
LineMixin = {};

function LineMixin:SetStartPoint(x, y)
	self.startX, self.startY = x, y;
end

function LineMixin:SetEndPoint(x, y)
	self.endX, self.endY = x, y;
end

function LineMixin:SetThickness(thickness)
	self.thickness = thickness;
end

function LineMixin:Draw()
	local parent = self:GetParent();
	local x, y = parent:GetLeft(), parent:GetBottom();

	self:ClearAllPoints();
	DrawLine(self, parent, self.startX - x, self.startY - y, self.endX - x, self.endY - y, self.thickness or 32, 1);
end

-- Mix this into a FontString to have it animate towards its value, call UpdateAnimatedValue every frame
AnimatedNumericFontStringMixin = {};

-- How long should it take to animate
function AnimatedNumericFontStringMixin:SetAnimatedDurationTimeSec(animatedDurationTimeSec)
	self.animatedDurationTimeSec = animatedDurationTimeSec;
end

function AnimatedNumericFontStringMixin:GetAnimatedDurationTimeSec()
	return self.animatedDurationTimeSec or 1.0;
end

function AnimatedNumericFontStringMixin:SetAnimatedValue(value)
	self.targetAnimatedValue = value;
	if not self.currentAnimatedValue then
		self.currentAnimatedValue = self.targetAnimatedValue;
	end
	self.initialAnimatedValueDelta = math.abs(self.targetAnimatedValue - self.currentAnimatedValue);
end

-- Stops animating the value and just snaps to it
function AnimatedNumericFontStringMixin:SnapToTarget()
	if self.targetAnimatedValue then
		self:SetText(BreakUpLargeNumbers(Round(self.targetAnimatedValue)));
		self.currentAnimatedValue = self.targetAnimatedValue;
		self.targetAnimatedValue = nil;
	end
end

-- Call this every frame
function AnimatedNumericFontStringMixin:UpdateAnimatedValue(elapsed)
	if self.targetAnimatedValue then
		local change = self.initialAnimatedValueDelta * (elapsed / self:GetAnimatedDurationTimeSec());
		if math.abs(self.targetAnimatedValue - self.currentAnimatedValue) <= change then
			self:SnapToTarget();
		else
			local direction = self.targetAnimatedValue > self.currentAnimatedValue and 1 or -1;
			self.currentAnimatedValue = self.currentAnimatedValue + direction * change;

			self:SetText(BreakUpLargeNumbers(Round(self.currentAnimatedValue)));
		end
	end
end

SparseGridMixin = {};

function SparseGridMixin:OnLoad(width, height)
	self.width = width;
	self.height = height;
	self.cells = {};
end

function SparseGridMixin:SetCell(x, y, data)
	if not self:IsInRange(x, y) then
		error("index of out of range");
	end

	local linearIndex = self:CalculateLinearIndex(x, y);
	self.cells[linearIndex] = data;
end

function SparseGridMixin:GetCell(x, y)
	if not self:IsInRange(x, y) then
		error("index of out of range");
	end

	local linearIndex = self:CalculateLinearIndex(x, y);
	return self.cells[linearIndex];
end

function SparseGridMixin:IsInRange(x, y)
	return x > 0 and x <= self.width and y > 0 and y <= self.height;
end

function SparseGridMixin:Clear()
	wipe(self.cells);
end

function SparseGridMixin:CalculateLinearIndex(x, y)
	return x + self.width * (y - 1);
end

-- Mix this in to make an object a doublyLinkedList
DoublyLinkedListMixin = {nodeCount = 0};

function DoublyLinkedListMixin:PushFront(nodeToInsert)
	self:InsertBefore(nodeToInsert, self.front);
end

function DoublyLinkedListMixin:PushBack(nodeToInsert)
	self:InsertAfter(nodeToInsert, self.back);
end

function DoublyLinkedListMixin:PopFront()
	return self:Remove(self.front);
end

function DoublyLinkedListMixin:PopBack()
	return self:Remove(self.back);
end

function DoublyLinkedListMixin:EnumerateNodes()
	local index = 0;
	local currentNode = self.front;

	return function()
		index = index + 1;
		if currentNode then
			local returnNode = currentNode;
			currentNode = currentNode.next;
			return index, returnNode;
		else
			return nil;
		end
	end;
end

function DoublyLinkedListMixin:EnumerateNodesReverse()
	local index = 0;
	local currentNode = self.back;

	return function()
		index = index + 1;
		if currentNode then
			local returnNode = currentNode;
			currentNode = currentNode.prev;
			return index, returnNode;
		else
			return nil;
		end
	end;
end

function DoublyLinkedListMixin:InsertBefore(nodeToInsert, listNode)
	nodeToInsert.next = listNode;

	if listNode then
		if listNode.prev then
			listNode.prev.next = nodeToInsert;
		end

		nodeToInsert.prev = listNode.prev;
		listNode.prev = nodeToInsert;
	end

	if self.front == listNode then
		self.front = nodeToInsert;
	end

	if not self.back then
		self.back = nodeToInsert;
	end

	self.nodeCount = self.nodeCount + 1;
end

function DoublyLinkedListMixin:InsertAfter(nodeToInsert, listNode)
	nodeToInsert.prev = listNode;

	if listNode then
		if listNode.next then
			listNode.next.prev = nodeToInsert;
		end

		nodeToInsert.next = listNode.next;
		listNode.next = nodeToInsert;
	end

	if self.back == listNode then
		self.back = nodeToInsert;
	end

	if not self.front then
		self.front = nodeToInsert;
	end

	self.nodeCount = self.nodeCount + 1;
end

function DoublyLinkedListMixin:Remove(node)
	if node then
		if self.front == node then
			self.front = node.next;
		end

		if self.back == node then
			self.back = node.prev;
		end

		if node.prev then
			node.prev.next = node.next;
		end

		if node.next then
			node.next.prev = node.prev;
		end

		node.prev = nil;
		node.next = nil;

		self.nodeCount = self.nodeCount - 1;
	end

	return node;
end

TextureLoadingGroupMixin = {};

function TextureLoadingGroupMixin:AddTexture(texture)
	self.textures = self.textures or {};
	self.textures[texture] = true;
end

function TextureLoadingGroupMixin:RemoveTexture(texture)
	if self.textures then
		self.textures[texture] = nil;
	end
end

function TextureLoadingGroupMixin:Reset()
	self.textures = nil;
end

function TextureLoadingGroupMixin:EnumerateTextures()
	if self.textures then
		return pairs(self.textures);
	end
	return nop;
end

function TextureLoadingGroupMixin:IsFullyLoaded()
	if self.textures then
		for texture in pairs(self.textures) do
			if not texture:IsObjectLoaded() then
				return false;
			end
		end
	end
	return true;
end

DirtiableMixin = {};

function DirtiableMixin:SetDirtyMethod(method)
	self.dirtyCallback = function()
		method(self);
		self.dirty = nil;
	end;
end

function DirtiableMixin:MarkDirty()
	if not self.dirty then
		RunNextFrame(self.dirtyCallback);
	end

	self.dirty = true;
end

-- This mixin implements a small ordered dirty-update runner. Consumers
-- define their own dirty flags and phase order. Phase methods return any
-- downstream flags that should be processed later in the same pass.
DirtyPhaseMixin = {};

function DirtyPhaseMixin:InitDirtyPhases()
	self.dirty = false;
	self.dirtyFlags = CreateFlags();
	self.dirtyPhases = {};
end

function DirtyPhaseMixin:OnDirtyChanged(_dirty)
	-- Override in the consumer to schedule or cancel dirty processing.
end

function DirtyPhaseMixin:SetDirtyPhases(phases)
	assert(type(phases) == "table", "phases must be a table.");

	for _index, phase in ipairs(phases) do
		assert(phase.flag ~= nil, "phase.flag must be provided.");
		assert(type(phase.handler) == "function", "phase.handler must be a function.");
	end

	self.dirtyPhases = phases;
end

function DirtyPhaseMixin:IsDirty(mask)
	if mask == nil then
		return self.dirty;
	end

	return self.dirtyFlags:IsSet(mask);
end

function DirtyPhaseMixin:UpdateDirtyState()
	local dirty = self.dirtyFlags:IsAnySet();

	if self.dirty ~= dirty then
		self.dirty = dirty;
		self:OnDirtyChanged(dirty);
	end
end

function DirtyPhaseMixin:MarkDirty(mask)
	self.dirtyFlags:Set(mask);

	if not self.dirty then
		self:UpdateDirtyState();
	end
end

function DirtyPhaseMixin:MarkClean(mask)
	self.dirtyFlags:Clear(mask);

	if self.dirty then
		self:UpdateDirtyState();
	end
end

function DirtyPhaseMixin:ProcessDirtyFlags()
	if not self:IsDirty() then
		return;
	end

	-- Dirty processing is single-pass; phases should only return later phases.
	for _index, phase in ipairs(self.dirtyPhases) do
		if self.dirtyFlags:IsSet(phase.flag) then
			self.dirtyFlags:Clear(phase.flag);

			local downstreamMask = phase.handler();
			if downstreamMask ~= nil then
				self.dirtyFlags:Set(downstreamMask);
			end
		end
	end

	self:UpdateDirtyState();

	if self:IsDirty() then
		assertsafe(false, "Dirty flags were not fully cleared during update pass (remaining flags: %d)", self.dirtyFlags:GetFlags());
	end
end

MixinUtil = {};

-- Calls an owned function on each entry of a table of mixin instances, checking that the instance does define that function
function MixinUtil.CallMethodOnAllSafe(instances, methodName, ...)
	if not instances then
		return;
	end

	for _, instance in ipairs(instances) do
		if instance[methodName] then
			instance[methodName](instance, ...);
		end
	end
end

-- Check existence of an element, then invoke the provided method by name with its arguments if it exists.
-- e.g. frame.Text:SetText("text") -> CallMethodSafe(frame.Text, "SetText", "text");
function MixinUtil.CallMethodSafe(element, methodName, ...)
	if element then
		element[methodName](element, ...);
	end
end
]] },
{ 'Blizzard_SharedXML\\DebugBarManager.lua', [[
-- Prevent the DebugBarManager from loading into the secure environment and responding
-- to DISPLAY_SIZE_CHANGED events, calling UpdateUIParentPosition and giving UIParent
-- improper anchoring via GetTotalHeight: this is done in the toc file

DebugBarManager = { };

local debugBars = { };

function DebugBarManager:AddBar(debugBar, priority)
	assert(debugBar and debugBar.GetDebugBarDisplayProperties, "Must have GetDebugBarDisplayProperties function");

	local debugBarInfo = { bar = debugBar, priority = priority or 0 };
	table.insert(debugBars, debugBarInfo);

	self:UpdateAnchors();
end

local sortFunc = function(lhs, rhs)
	if lhs.isAboveWorldFrame ~= rhs.isAboveWorldFrame then
		return lhs.isAboveWorldFrame;
	end
	if lhs.priority ~= rhs.priority then
		return lhs.priority > rhs.priority;
	end
	-- tie breaker
	return tostring(lhs.bar) < tostring(rhs.bar);
end

function DebugBarManager:GetScreenScale()
	if C_Glue.IsOnGlueScreen() then
		return PixelUtil.GetPixelToUIUnitFactor();
	else
		return UIParent:GetScale();
	end
end

function DebugBarManager:GetInternalBarsHeight()
	local debugMenuHeight = DebugMenu and DebugMenu.IsVisible() and DebugMenu.GetMenuHeight() or 0;
	local revealTimeTrackHeight = C_Reveal and C_Reveal:IsCapturing() and C_Reveal:GetTimeTrackHeight() or 0;
	return debugMenuHeight + revealTimeTrackHeight;
end

function DebugBarManager:GetScaledInternalBarsHeight()
	return self:GetInternalBarsHeight() * self:GetScreenScale();
end

function DebugBarManager:CalculatePositions()
	for i, debugBarInfo in ipairs(debugBars) do
		local isShown, isAboveWorldFrame = debugBarInfo.bar:GetDebugBarDisplayProperties();
		debugBarInfo.isShown = isShown;
		debugBarInfo.isAboveWorldFrame = isAboveWorldFrame;
	end

	table.sort(debugBars, sortFunc);

	local scale = self:GetScreenScale();
	scale = math.min(scale, 1);
	local internalHeight = self:GetInternalBarsHeight();
	local addedHeight = 0;
	local aboveWorldFrameHeight = 0;

	for i, debugBarInfo in ipairs(debugBars) do
		if debugBarInfo.isShown then
			debugBarInfo.bar:SetScale(scale);
			debugBarInfo.bar:ClearAllPoints();
			debugBarInfo.bar:SetPoint("TOPLEFT", 0, -internalHeight - addedHeight);
			debugBarInfo.bar:SetPoint("TOPRIGHT", 0, -internalHeight - addedHeight);
			local height = debugBarInfo.bar:GetHeight();
			addedHeight = addedHeight + height;
			if debugBarInfo.isAboveWorldFrame then
				aboveWorldFrameHeight = aboveWorldFrameHeight + height;
			end
		end
	end

	if WorldFrame then
		if aboveWorldFrameHeight > 0 then
			local offset = internalHeight + aboveWorldFrameHeight;
			WorldFrame:SetPoint("TOPLEFT", 0, -offset * scale);
		else
			WorldFrame:SetPoint("TOPLEFT");
		end
	end

	self.totalHeight = internalHeight + addedHeight;
end

function DebugBarManager:GetTotalHeight()
	if not self.totalHeight then
		self:CalculatePositions();
	end
	return self.totalHeight;
end

function DebugBarManager:UpdateAnchors()
	self:CalculatePositions();
	if UpdateUIParentPosition then
		UpdateUIParentPosition();
	end
	if DeveloperConsole then
		DeveloperConsole:UpdateAnchors();
	end
end

do
	if DebugMenu or C_Reveal then
		EventRegistry:RegisterFrameEvent("UI_SCALE_CHANGED");
		EventRegistry:RegisterCallback("UI_SCALE_CHANGED", DebugBarManager.UpdateAnchors, DebugBarManager);
		EventRegistry:RegisterFrameEvent("DISPLAY_SIZE_CHANGED");
		EventRegistry:RegisterCallback("DISPLAY_SIZE_CHANGED", DebugBarManager.UpdateAnchors, DebugBarManager);
		if C_Glue.IsOnGlueScreen() then
			local watcherFrame = CreateFrame("FRAME");
			watcherFrame:SetScript("OnUpdate", function() DebugBarManager:UpdateAnchors(); end);
		else
			if C_EventUtils.IsEventValid("DEBUG_MENU_TOGGLED") then
				EventRegistry:RegisterFrameEvent("DEBUG_MENU_TOGGLED");
				EventRegistry:RegisterCallback("DEBUG_MENU_TOGGLED", DebugBarManager.UpdateAnchors, DebugBarManager);
			end
			if C_EventUtils.IsEventValid("REVEAL_CAPTURE_TOGGLED") then
				EventRegistry:RegisterFrameEvent("REVEAL_CAPTURE_TOGGLED");
				EventRegistry:RegisterCallback("REVEAL_CAPTURE_TOGGLED", DebugBarManager.UpdateAnchors, DebugBarManager);
			end
		end
	end
end
]] },
{ 'Blizzard_SharedXML\\ScrollableTabsContainer.lua', [[
ScrollableTabsContainerMixin = { };

function ScrollableTabsContainerMixin:OnSizeChanged()
	if self.headIndex then
		self:Update();
		self:TryFitMoreFrames();
	end
end

function ScrollableTabsContainerMixin:Init(template, initializer, controlsUpdateFunc)
	local templateInfo = C_XMLUtil.GetTemplateInfo(template);
	assert(templateInfo and initializer);
	self.framePool = CreateFramePool(templateInfo.type, self.Contents, template);

	self.initializer = initializer;
	self.leftPadding = self.leftPadding or 2;
	self.rightPadding = self.rightPadding or 2;
	self.frameSpacing = self.frameSpacing or 4;
	self.verticalOffset = self.verticalOffset or 0;
	
	self.controlsUpdateFunc = controlsUpdateFunc;
	self.controlWidthLeft = 0;
	self.controlWidthRight = 0;
	
	self.tabs = { };
	
	self.Contents:SetScript("OnMouseWheel", function(frame, delta) self:Scroll(delta * -1); end);
end

function ScrollableTabsContainerMixin:AddTab(tabInfo)
	if not self.headIndex then
		self.headIndex = 1;
	end

	local frame = self.framePool:Acquire();	
	-- anchor now for sizing calculations
	frame:SetPoint("LEFT");
	local t = { tabInfo = tabInfo, frame = frame };
	table.insert(self.tabs, t);

	frame:Show();	
	self.initializer(frame, tabInfo);
	
	self:Update();
end

function ScrollableTabsContainerMixin:RemoveTab(tabInfo)
	for i, tab in ipairs(self.tabs) do
		if tab.tabInfo == tabInfo then
			-- remove tab
			tab.frame:Hide();
			self.framePool:Release(tab.frame);
			table.remove(self.tabs, i);
			-- need adjustment if tab removed is the first visible one ("head") or before it
			if i <= self.headIndex and i ~= 1 then
				self.headIndex = self.headIndex - 1;
			end
			-- update, then check for fit
			self:Update();
			self:TryFitMoreFrames();
			return;
		end
	end
end

function ScrollableTabsContainerMixin:RemoveAllTabs()
	self.framePool:ReleaseAll();
	self.tabs = { };
	self.headIndex = 1;	
	self:Update();
end

function ScrollableTabsContainerMixin:GetAllTabs()
	local info = { };
	for i, tab in ipairs(self.tabs) do
		table.insert(info, tab.tabInfo);
	end
	return info;
end

function ScrollableTabsContainerMixin:GetTabIndex(tabInfo)
	for i, tab in ipairs(self.tabs) do
		if tab.tabInfo == tabInfo then
			return i;
		end
	end
	return nil;
end

function ScrollableTabsContainerMixin:GetNumTabs()
	return #self.tabs;
end

function ScrollableTabsContainerMixin:HasTab(tabInfo)
	return self:GetTabIndex(tabInfo) ~= nil;
end

function ScrollableTabsContainerMixin:GetTab(index)
	local tab = self.tabs[index];
	return tab and tab.frame;
end

function ScrollableTabsContainerMixin:GetLastTab()
	local tab = self.tabs[#self.tabs];
	return tab and tab.frame;
end

function ScrollableTabsContainerMixin:Scroll(delta)
	if delta == 1 and not self.canScrollRight then
		return;
	end

	if delta ~= 0 then
		self.headIndex = Clamp(self.headIndex + delta, 1, #self.tabs);
		self:Update();
	end
end

function ScrollableTabsContainerMixin:TryFitMoreFrames()
	-- if any frames are scrolled off to the left, check if enough room exists now to make them visible
	if self.headIndex and self.headIndex > 1 then
		local scrollDelta = 0;
		local availableSpace = self:GetRightEdgeMargin();
		for i = self.headIndex - 1, 1, -1 do
			-- if at the first frame, also consider controls width because it can be removed if it all ends up fitting
			if i == 1 then
				availableSpace = availableSpace + self:GetVisibleControlsWidth();
			end			
			local frame = self.tabs[i].frame;
			local width = frame:GetWidth() + self.frameSpacing;
			if width < availableSpace then
				availableSpace = availableSpace - width;
				scrollDelta = scrollDelta - 1;
			else
				break;
			end
		end
		self:Scroll(scrollDelta);
	end
end

function ScrollableTabsContainerMixin:ScrollIntoView(tabInfo)
	local tabIndex = self:GetTabIndex(tabInfo);
	if not tabIndex or tabIndex == self.headIndex then
		-- should already fit as much as possible
		return;
	end

	local scrollDelta = 0;

	if tabIndex < self.headIndex then
		scrollDelta = tabIndex - self.headIndex;
	else
		local tab = self.tabs[tabIndex];
		local margin = self:GetRightEdgeMargin(tab);
		if margin >= 0 then
			-- it already fits
			return;
		end

		for i = self.headIndex, #self.tabs - 1 do
			scrollDelta = scrollDelta + 1;		
			local frame = self.tabs[i].frame;
			local width = frame:GetWidth() + self.frameSpacing;		
			margin = margin + width;
			if margin >= 0 then
				break;
			end
		end
	end

	self:Scroll(scrollDelta);
end

-- distance to the end of container from the tab's right edge
-- defaults to last tab, positive distance is space that might fit more frames, negative distance means frame is not fully visible 
function ScrollableTabsContainerMixin:GetRightEdgeMargin(tab)
	-- default to last tab
	tab = tab or self.tabs[#self.tabs];
	local frame = tab and tab.frame;
	local furthestRight = (frame and frame:GetRight()) or 0;
	local contentsRight = self.Contents:GetRight() or 0;
	return Round(contentsRight - furthestRight);
end

function ScrollableTabsContainerMixin:GetVisibleControlsWidth()
	return self.controlWidthLeft + self.controlWidthRight;
end

function ScrollableTabsContainerMixin:UpdateControls()
	if not self.controlsUpdateFunc then
		return;
	end

	local canScrollLeft = self.headIndex > 1;
	local spaceRight = self:GetRightEdgeMargin();
	-- if it's not possible to scroll left, add the controls space because the controls can be removed to fit the last frame if needed
	if not canScrollLeft then
		spaceRight = spaceRight + self:GetVisibleControlsWidth();
	end
	self.canScrollRight = spaceRight < 0;

	self.controlWidthLeft, self.controlWidthRight = self.controlsUpdateFunc(self, canScrollLeft, self.canScrollRight);
	
	self.Contents:SetPoint("TOPLEFT", self.leftPadding + self.controlWidthLeft, 0);
	self.Contents:SetPoint("BOTTOMRIGHT", -self.rightPadding - self.controlWidthRight, 0);
end

function ScrollableTabsContainerMixin:Update()
	local firstFrameOffset = 0;
	local anchor;
	for i, tab in ipairs(self.tabs) do
		local frame = tab.frame;
		if anchor then
			frame:SetPoint("LEFT", anchor, "RIGHT", self.frameSpacing, 0);
		else
			frame:SetPoint("LEFT", self.Contents, 0, self.verticalOffset);
		end
		if i < self.headIndex then
			firstFrameOffset = firstFrameOffset - frame:GetWidth() - self.frameSpacing;
		end
		anchor = frame;
	end
	
	-- adjust first frame so the head frame is in the first visible position
	if anchor then
		self.tabs[1].frame:SetPoint("LEFT", firstFrameOffset, self.verticalOffset);
	end
	-- adjust contents frame
	self:UpdateControls();
end

function ScrollableTabsContainerMixin:ForEachTab(func)
	for i, tab in ipairs(self.tabs) do
		local frame = tab.frame;
		func(frame, tab.tabInfo);
	end
end]] },
{ 'Blizzard_SharedXML\\Shared\\TabSystem\\TabSystemTemplates.lua', [[

local TabSideExtraSpacing = 20;

TabSystemButtonArtMixin = {};

function TabSystemButtonArtMixin:HandleRotation()
	if self.isTabOnTop then
		for _, texture in ipairs(self.RotatedTextures) do
			texture:ClearAllPoints();
			texture:SetRotation(math.pi);
		end

		self.RightActive:SetPoint("BOTTOMLEFT", self, "BOTTOMLEFT", -7, 0);
		self.LeftActive:SetPoint("BOTTOMRIGHT");
		self.MiddleActive:SetPoint("LEFT", self.RightActive, "RIGHT");
		self.MiddleActive:SetPoint("RIGHT", self.LeftActive, "LEFT");

		self.Right:SetPoint("BOTTOMLEFT", self, "BOTTOMLEFT", -6, 0);
		self.Left:SetPoint("BOTTOMRIGHT");
		self.Middle:SetPoint("LEFT", self.Right, "RIGHT");
		self.Middle:SetPoint("RIGHT", self.Left, "LEFT");

		self.LeftHighlight:SetPoint("TOPRIGHT", self.Left);
		self.RightHighlight:SetPoint("TOPLEFT", self.Right);
		self.MiddleHighlight:SetPoint("LEFT", self.Middle, "LEFT");
		self.MiddleHighlight:SetPoint("RIGHT", self.Middle, "RIGHT");
	end
end

function TabSystemButtonArtMixin:GetTextYOffset(isSelected)
	local offset = self.textOffsetY or 0;
	if self.isTabOnTop then
		offset = offset + (isSelected and 0 or -3);
	else
		offset = offset + (isSelected and -3 or 2);
	end

	return offset;
end

function TabSystemButtonArtMixin:SetTabSelected(isSelected)
	self.isSelected = isSelected;

	self.Left:SetShown(not isSelected);
	self.Middle:SetShown(not isSelected);
	self.Right:SetShown(not isSelected);
	self.LeftActive:SetShown(isSelected);
	self.MiddleActive:SetShown(isSelected);
	self.RightActive:SetShown(isSelected);

	local selectedFontObject = self.selectedFontObject or GameFontHighlightSmall;
	local unselectedFontObject = self.unselectedFontObject or GameFontNormalSmall;
	self:SetNormalFontObject(isSelected and selectedFontObject or unselectedFontObject);

	self:SetEnabled(not isSelected and not self:IsForceDisabled());

	self.Text:SetPoint("CENTER", self, "CENTER", 0, self:GetTextYOffset(isSelected));

	local tooltip = GetAppropriateTooltip();
	if tooltip:IsOwned(self) then
		tooltip:Hide();
	end
end

function TabSystemButtonArtMixin:SetTabWidth(width)
	self:SetWidth(width);
end

function TabSystemButtonArtMixin:IsForceDisabled()
	-- Override in your derived Mixin.
	return false, nil;
end

TabSystemButtonMixin = {};

function TabSystemButtonMixin:OnEnter()
	local showErrorText = not self:IsEnabled() and self.errorReason ~= nil and self:GetTabID() ~= self:GetTabSystem().selectedTabID;
	if showErrorText then
		GameTooltip:SetOwner(self, self.tooltipAnchor, self.tooltipAnchorX, self.tooltipAnchorY);
		GameTooltip_AddErrorLine(GameTooltip, self.errorReason);
		if self.tooltipText then
			GameTooltip_AddBlankLineToTooltip(GameTooltip);
			GameTooltip_AddNormalLine(GameTooltip, self.tooltipText);
		end
		GameTooltip:Show();
	elseif self.tooltipText then
		GameTooltip:SetOwner(self, self.tooltipAnchor, self.tooltipAnchorX, self.tooltipAnchorY);
		GameTooltip_AddNormalLine(GameTooltip, self.tooltipText);
		GameTooltip:Show();
	elseif self.Text:IsTruncated() then
		local text = self.Text:GetText();
		if text then
			GameTooltip:SetOwner(self, self.tooltipAnchor, self.tooltipAnchorX, self.tooltipAnchorY);
			GameTooltip_AddNormalLine(GameTooltip, text);
			GameTooltip:Show();
		end
	end
end

function TabSystemButtonMixin:OnLeave()
	GameTooltip_Hide();
end

function TabSystemButtonMixin:OnClick()
	local tabSystem = self:GetTabSystem();

	local wasSelected = self.isSelected;
	local isUserAction = true;
	tabSystem:SetTab(self:GetTabID(), isUserAction);

	-- Only play the sound if the tab was actually selected
	if not wasSelected and self.isSelected then
		tabSystem:PlayTabSelectSound();
	end
end

function TabSystemButtonMixin:Init(tabID, tabText)
	self.tabID = tabID;
	self:HandleRotation();
	self.tabText = tabText;
	self:SetText(tabText);
	self:UpdateTabWidth();
	self:SetTabSelected(false);
end

function TabSystemButtonMixin:SetTooltipText(tooltipText)
	self.tooltipText = tooltipText;
end

function TabSystemButtonMixin:SetTabEnabled(enabled, errorReason)
	self.forceDisabled = not enabled;
	self:SetEnabled(not self:IsForceDisabled() and not self.isSelected);
	local text = not self:IsForceDisabled() and self.tabText or DISABLED_FONT_COLOR:WrapTextInColorCode(self.tabText);
	self.Text:SetText(text);
	self.errorReason = errorReason;
end

function TabSystemButtonMixin:SetTabNotification(showNotification)
	if showNotification then
		if not self.notificationFrame then
			if self.isTabOnTop then
				self.notificationFrame = NotificationUtil.AcquireNotification("TOP", self, "TOP", 0, 10);
			else
				self.notificationFrame = NotificationUtil.AcquireNotification("BOTTOM", self, "BOTTOM", 0, -10);
			end
		end

	elseif self.notificationFrame then
		NotificationUtil.ReleaseNotification(self.notificationFrame);
		self.notificationFrame = nil;
	end
end

function TabSystemButtonMixin:UpdateTabWidth()
	local sidesWidth = self.Left:GetWidth() + self.Right:GetWidth();
	local width = sidesWidth + TabSideExtraSpacing;
	local minTabWidth, maxTabWidth = self:GetTabSystem():GetTabWidthConstraints();
	local textWidth = self.Text:GetWidth() + (self.textPadding or 0);

	if width < textWidth then
		width = textWidth + 10;
	end

	if maxTabWidth and width > maxTabWidth then
		width = maxTabWidth;
		textWidth = width - 10;
	end

	if minTabWidth and width < minTabWidth then
		width = minTabWidth;
		textWidth = width - 10;
	end

	self.Text:SetWidth(textWidth or 0);

	self:SetTabWidth(width);
end

function TabSystemButtonMixin:IsSelected()
	return not not self.isSelected;
end

function TabSystemButtonMixin:IsForceDisabled()
	-- Note: this will intentionally override TabSystemButtonArtMixin.
	return self.forceDisabled, self.errorReason;
end

function TabSystemButtonMixin:GetTooltipText()
	return self.tooltipText;
end

function TabSystemButtonMixin:GetNotificationFrame()
	return self.notificationFrame;
end

function TabSystemButtonMixin:GetTabID()
	return self.tabID;
end

function TabSystemButtonMixin:GetTabSystem()
	return self:GetParent();
end


TabSystemMixin = {};

function TabSystemMixin:OnLoad()
	self.tabs = {};
	self.tabPool = CreateFramePool("BUTTON", self, self.tabTemplate);
end

function TabSystemMixin:AddTab(tabText)
	local tabID = #self.tabs + 1;
	local newTab = self.tabPool:Acquire();
	table.insert(self.tabs, newTab);
	newTab.layoutIndex = tabID;
	newTab:Init(tabID, tabText);
	newTab:Show();
	self:MarkDirty();
	return tabID;
end

-- tabSelectedCallback: function (tabID, isUserAction) -> suppressVisualSelection
function TabSystemMixin:SetTabSelectedCallback(tabSelectedCallback)
	self.tabSelectedCallback = tabSelectedCallback;
end

function TabSystemMixin:SetTab(tabID, isUserAction)
	if not self.tabSelectedCallback(tabID, isUserAction) then
		self:SetTabVisuallySelected(tabID);
	end
end

function TabSystemMixin:SetTabVisuallySelected(tabID)
	self.selectedTabID = tabID;

	for i, tab in ipairs(self.tabs) do
		tab:SetTabSelected(tab:GetTabID() == tabID);
	end
end

function TabSystemMixin:SetTabNotification(tabID, showNotification)
	self.tabs[tabID]:SetTabNotification(showNotification);
end

function TabSystemMixin:SetTabShown(tabID, isShown)
	self.tabs[tabID]:SetShown(isShown);
	self:MarkDirty();
end

function TabSystemMixin:IsTabShown(tabID)
	return self.tabs[tabID]:IsShown();
end

function TabSystemMixin:SetTabEnabled(tabID, enabled, errorReason)
	self.tabs[tabID]:SetTabEnabled(enabled, errorReason);
	self:MarkDirty();
end

function TabSystemMixin:IsTabEnabled(tabID)
	return not self.tabs[tabID]:IsForceDisabled();
end

function TabSystemMixin:GetTabWidthConstraints()
	return self.minTabWidth, self.maxTabWidth;
end

function TabSystemMixin:GetTabButton(tabID)
	return self.tabs[tabID];
end

function TabSystemMixin:PlayTabSelectSound()
	if self.tabSelectSound then
		PlaySound(self.tabSelectSound);
	end
end
]] },
{ 'Blizzard_SharedXML\\Shared\\TabSystem\\TabSystemOwner.lua', [[

TabSystemTrackerMixin = {};

function TabSystemTrackerMixin:OnLoad()
	self:Init();
end

function TabSystemTrackerMixin:Init()
	self.tabbedElements = {};
	self.tabIDToElementSet = {};
	self.tabIDToTabCallback = {};
	self.tabIDToTabDeselectCallback = {};
end

function TabSystemTrackerMixin:AddTab(tabID, ...)
	self.tabIDToElementSet[tabID] = {};

	for i = 1, select("#", ...) do
		self:AddElementToTab(tabID, select(i, ...));
	end
end

function TabSystemTrackerMixin:AddElementToTab(tabID, element)
	table.insert(self.tabbedElements, element);

	local elementSet = GetOrCreateTableEntry(self.tabIDToElementSet, tabID);
	elementSet[element] = true;
end

function TabSystemTrackerMixin:SetTabCallback(tabID, callback)
	self.tabIDToTabCallback[tabID] = callback;
end

function TabSystemTrackerMixin:SetTabDeselectCallback(tabID, callback)
	self.tabIDToTabDeselectCallback[tabID] = callback;
end

function TabSystemTrackerMixin:SetTab(tabID, isUserAction)
	if self.tabID and tabID ~= self.tabID then
		local deselectCallback = self.tabIDToTabDeselectCallback[self.tabID];
		if deselectCallback then
			deselectCallback(isUserAction);
		end
	end

	self.tabID = tabID;

	local elementSet = self.tabIDToElementSet[tabID];
	for i, tabbedElement in ipairs(self.tabbedElements) do
		tabbedElement:SetShown(elementSet and elementSet[tabbedElement]);
	end

	local tabCallback = self.tabIDToTabCallback[tabID];
	if tabCallback then
		tabCallback(isUserAction);
	end
end

function TabSystemTrackerMixin:GetTab()
	return self.tabID;
end

function TabSystemTrackerMixin:GetTabSet()
	return GetKeysArray(self.tabIDToElementSet);
end

function TabSystemTrackerMixin:GetElementsForTab(tabID)
	return GetKeysArray(self.tabIDToElementSet[tabID]);
end


TabSystemOwnerMixin = {};

function TabSystemOwnerMixin:OnLoad()
	self.internalTabTracker = CreateAndInitFromMixin(TabSystemTrackerMixin);
end

function TabSystemOwnerMixin:SetTabSystem(tabSystem)
	self.tabSystem = tabSystem;
	tabSystem:SetTabSelectedCallback(GenerateClosure(self.SetTab, self));
end

function TabSystemOwnerMixin:AddNamedTab(tabName, ...)
	local tabID = self.tabSystem:AddTab(tabName);
	self.internalTabTracker:AddTab(tabID, ...);

	return tabID;
end

function TabSystemOwnerMixin:SetTabCallback(tabID, callback)
	self.internalTabTracker:SetTabCallback(tabID, callback);
end

function TabSystemOwnerMixin:SetTabDeselectCallback(tabID, callback)
	self.internalTabTracker:SetTabDeselectCallback(tabID, callback);
end

function TabSystemOwnerMixin:SetTab(tabID, isUserAction)
	self.internalTabTracker:SetTab(tabID, isUserAction);
	self.tabSystem:SetTabVisuallySelected(tabID);
end

function TabSystemOwnerMixin:GetTab()
	return self.internalTabTracker:GetTab();
end

