end

function ScrollBoxSelectorMixin:GetStride()
	return self.customStride or 10;
end

function ScrollBoxSelectorMixin:SetCustomPadding(top, bottom, left, right, horizontalSpacing, verticalSpacing)
	self.top = top;
	self.bottom = bottom;
	self.left = left;
	self.right = right;
