			useMin = ry <= uy;
		else
			useMin = rx <= ux;
		end
		if useMin then
			targetPoint = min(self.flippedTargetPoint, targetPoint);
		else
			targetPoint = max(self.flippedTargetPoint, targetPoint);
		end
	end

	self:AnchorAndRotate(targetPoint, targetAlignment);
