{ 'Blizzard_SharedXML\\Mainline\\SharedCollectionUtil.lua', [[
SharedCollectionUtil = {};

function SharedCollectionUtil.ShowWarbandSceneEntryTooltip(tooltip, warbandSceneInfo, isOwned)
	-- Assumes that anchoring will be handled by calling location.
	local colorData = ColorManager.GetColorDataForItemQuality(warbandSceneInfo.quality);
	if colorData then
		GameTooltip_AddColoredLine(tooltip, warbandSceneInfo.name, colorData.color);
	else
		GameTooltip_AddHighlightLine(tooltip, warbandSceneInfo.name);
	end

	-- Random entry doesn't show certain parts of normal tooltip info.
	local isRandomEntry = warbandSceneInfo.warbandSceneID == C_WarbandScene.GetRandomEntryID();

	if not isRandomEntry then
		GameTooltip_AddColoredLine(tooltip, ACCOUNT_LEVEL_SCENE, ACCOUNT_WIDE_FONT_COLOR);
	end

	if warbandSceneInfo.description and warbandSceneInfo.description ~= "" then
		GameTooltip_AddBlankLineToTooltip(tooltip);
		GameTooltip_AddNormalLine(tooltip, warbandSceneInfo.description);
	end

	if not isRandomEntry and not isOwned and warbandSceneInfo.source and warbandSceneInfo.source ~= "" then
		GameTooltip_AddBlankLineToTooltip(tooltip);
		GameTooltip_AddHighlightLine(tooltip, warbandSceneInfo.source);
	end

	tooltip:Show();
end]] },
{ 'Blizzard_SharedXML\\Mainline\\SharedCollectionTemplates.lua', [[
WarbandSceneEntryMixin = {};

function WarbandSceneEntryMixin:OnMouseUp(button, upInside)
	local warbandSceneID = self:GetWarbandSceneID();
	if button == "RightButton" and upInside and warbandSceneID and warbandSceneID ~= C_WarbandScene.GetRandomEntryID() and self:GetIsOwned() then
		MenuUtil.CreateContextMenu(self, function(owner, rootDescription)
			rootDescription:SetTag("MENU_WARBANDSCENE_FAVORITE");

			local isFavorite = self:GetIsFavorite();
			if isFavorite then
				rootDescription:CreateButton(BATTLE_PET_UNFAVORITE, function()
					self:SetIsFavorite(false);
				end);
			else
				rootDescription:CreateButton(BATTLE_PET_FAVORITE, function()
					self:SetIsFavorite(true);
				end);
			end
		end);
	end
end

function WarbandSceneEntryMixin:OnEnter()
	if self.warbandSceneInfo then
		local tooltip = GetAppropriateTooltip();
		tooltip:SetOwner(self, "ANCHOR_RIGHT");
		SharedCollectionUtil.ShowWarbandSceneEntryTooltip(tooltip, self.warbandSceneInfo, self:GetIsOwned());
	end
end

function WarbandSceneEntryMixin:OnLeave()
	local tooltip = GetAppropriateTooltip();
	tooltip:Hide();
end

function WarbandSceneEntryMixin:Init(elementData)
	self.elementData = elementData;
	self:UpdateWarbandSceneData();
end

function WarbandSceneEntryMixin:UpdateWarbandSceneData()
	if not self.elementData then
		return;
	end

	self.warbandSceneInfo = C_WarbandScene.GetWarbandSceneEntry(self.elementData.warbandSceneID);

	if self.warbandSceneInfo then
		self.Name:SetText(self.warbandSceneInfo.name);
		self.Icon:SetAtlas(self.warbandSceneInfo.textureKit, TextureKitConstants.UseAtlasSize);
		self.Icon:SetDesaturated(not self:GetIsOwned());
		self.SlotFavorite:SetShown(self:GetIsFavorite());
	end
end

function WarbandSceneEntryMixin:GetWarbandSceneID()
	if self.warbandSceneInfo then
		return self.warbandSceneInfo.warbandSceneID;
	end
	return nil;
end

function WarbandSceneEntryMixin:GetIsOwned()
	return self.warbandSceneInfo and C_WarbandScene.HasWarbandScene(self.warbandSceneInfo.warbandSceneID);
end

function WarbandSceneEntryMixin:GetIsFavorite()
	return self.warbandSceneInfo and C_WarbandScene.IsFavorite(self.warbandSceneInfo.warbandSceneID);
end

function WarbandSceneEntryMixin:SetIsFavorite(state)
	if self.warbandSceneInfo then
		C_WarbandScene.SetFavorite(self.warbandSceneInfo.warbandSceneID, state);
	end
end]] },
{ 'Blizzard_SharedXML\\CustomBindingButtonMixin.lua', [=[
--[[
CustomBindingButtonMixin: Utility to mimic game action-binding functionality, while allowing metakeys to be recognized on their own.

Never executes actual bindings, just informs the CustomBindingManager about changes the user made.  The  system than manages the custom
command can choose the appropriate action via CustomBindingManager notifications.

While this mixin could be made to adjust in-game bindings, on its own it has nothing to do with that system, this allows other systems
that exist in parallel to run commands without using the keybind system.

It's currently not allowed for addons to add custom binding types, but that should only prevent this button from appearing in
the keybinds window, it's still permitted that addons can make their own systems that leverage these bindings.

The rules from Blizzard_BindingUI are (mostly) followed, including but not limited to these exceptions
- PrintScreen is bindable

Other caveats are that LMB/RMB aren't bindable, both of them will activate and cancel binding mode.
--]]

CustomBindingButtonMixin = {};

--[[private]] function CustomBindingButtonMixin:OnLoad()
	local preventBindingManagerUpdate = true;
	self:SetBindingModeActive(false, preventBindingManagerUpdate);
	self:EnableKeyboard(false);
end

--[[private]] function CustomBindingButtonMixin:OnClick(button, isDown)
	local isBindingModeButton = self:IsBindingModeButton(button);
	local isButtonRelease = not isDown;

	if isButtonRelease and isBindingModeButton and self.cancelBindingModeOnRelease then
		self.cancelBindingModeOnRelease = false;
		self:NotifyBindingCompleted(false);
		self:EnableKeyboard(false);
	else
		if self:IsBindingModeActive() then
			if isBindingModeButton then
				self.cancelBindingModeOnRelease = true;
			else
				self:OnInput(button, isDown);
			end
		elseif isButtonRelease then
			if isBindingModeButton and not self.cancelBindingModeOnRelease then
				self:SetBindingModeActive(true);
			end

			self.cancelBindingModeOnRelease = nil;
		end
	end
end

--[[private]] function CustomBindingButtonMixin:OnMouseWheel(delta)
	-- Current custom systems don't support mouse wheel events, prevent this from doing anything
	-- event handler exists to prevent event from falling through to next frame.
end

--[[private]] function CustomBindingButtonMixin:OnKeyDown(key)
	self:OnInput(key, true);
end

--[[private]] function CustomBindingButtonMixin:OnKeyUp(key)
	self:OnInput(key, false);
end

--[[private]] function CustomBindingButtonMixin:OnInput(key, isDown)
	local isButtonRelease = not isDown;

	if not self:IsBindingModeActive() then
		-- Receiving an up event after bindings are disabled should disable bind-handling
		if isButtonRelease then
			self:EnableKeyboard(false);
		end

		-- But always return if binding mode wasn't active
		return;
	end

	key = GetConvertedKeyOrButton(key);

	if isDown then
		if key == "ESCAPE" then
			self:CancelBinding();
			return;
		end
		
		if not IsMetaKey(key) then
			self.receivedNonMetaKeyInput = true;
		end

		table.insert(self.keys, key);
	end

	CustomBindingManager:SetPendingBind(self:GetCustomBindingType(), self.keys);

	if self.receivedNonMetaKeyInput or isButtonRelease then
		self:NotifyBindingCompleted(true, self.keys);

		if isButtonRelease then
			self:EnableKeyboard(false);
		end
	end
end

--[[private]] function CustomBindingButtonMixin:IsBindingModeButton(button)
	return IsLeftMouseButton(button) or IsRightMouseButton(button);
end

--[[private]] function CustomBindingButtonMixin:SetBindingModeActive(isActive, preventBindingManagerUpdate)
	self.isBindingModeActive = isActive;
	self.receivedNonMetaKeyInput = false;
	self.keys = {};

	BindingButtonTemplate_SetSelected(self, isActive);

	if isActive then
		self:RegisterForClicks("AnyDown", "AnyUp");
		self:EnableKeyboard(true); -- Only enable here, disable later so that this button continues to see keyboard events through the entire key press/release cycle.
	else
		self:RegisterForClicks("LeftButtonUp", "RightButtonUp");
	end

	if not preventBindingManagerUpdate then
		CustomBindingManager:OnBindingModeActive(self, isActive);
	end
end

--[[private]] function CustomBindingButtonMixin:NotifyBindingCompleted(completedSuccessfully, keys)
	CustomBindingManager:OnBindingCompleted(self, completedSuccessfully, keys);
	self:SetBindingModeActive(false);
end

--[[private]] function CustomBindingButtonMixin:SetCustomBindingType(customBindingType)
	self.customBindingType = customBindingType;
end

--[[public]] function CustomBindingButtonMixin:GetCustomBindingType()
	return self.customBindingType;
end

--[[public]] function CustomBindingButtonMixin:SetCustomBindingHandler(handler)
	self.handler = handler;
end

--[[public]] function CustomBindingButtonMixin:GetCustomBindingHandler()
	return self.handler;
end

--[[public, virtual]] function CustomBindingButtonMixin:OnBindingTextChanged(bindingText)
	self:SetText(bindingText);
end

--[[public]] function CustomBindingButtonMixin:IsBindingModeActive()
	return self.isBindingModeActive;
end

--[[public]] function CustomBindingButtonMixin:GetKeys()
	return self.keys;
end

--[[public]] function CustomBindingButtonMixin:CancelBinding()
	self:NotifyBindingCompleted(false);
	self:EnableKeyboard(false);
end]=] },
{ 'Blizzard_SharedXML\\Shared\\Tabs\\MinimalTab.lua', [[
MinimalTabMixin = {};

function MinimalTabMixin:OnLoad()
	SelectableButtonMixin.OnLoad(self);

	self.Text:SetText(self.tabText);
	self:SetWidth(self.Text:GetStringWidth() + 40);

	self:OnSelected(false);
end

function MinimalTabMixin:GetAtlas()
	if self:IsSelected() then
		return self.selectedLeftTexture, self.selectedRightTexture, self.selectedMiddleTexture;
	end

	if self.over then
		return self.overLeftTexture, self.overRightTexture, self.overMiddleTexture;
	end
	return self.upLeftTexture, self.upRightTexture, self.upMiddleTexture;
end

function MinimalTabMixin:UpdateAtlas()
	local leftAtlas, rightAtlas, middleAtlas = self:GetAtlas();
	self.Left:SetAtlas(leftAtlas, TextureKitConstants.UseAtlasSize);
	self.Right:SetAtlas(rightAtlas, TextureKitConstants.UseAtlasSize);
	self.Middle:SetAtlas(middleAtlas, TextureKitConstants.UseAtlasSize);
end

function MinimalTabMixin:OnSelected(newSelected)
	self:UpdateAtlas();

	if newSelected then
		self.Text:SetPoint("BOTTOM", 0, 6);
		self.Text:SetFontObject("GameFontHighlightSmall");
	else
		self.Text:SetPoint("BOTTOM", 0, 4);
		self.Text:SetFontObject(self.over and "GameFontHighlightSmall" or "GameFontNormalSmall");
	end
end

function MinimalTabMixin:OnEnter()
	self.over = true;
	self:UpdateAtlas();
	if not self:IsSelected() then
		self.Text:SetFontObject("GameFontHighlightSmall");
	end
end

function MinimalTabMixin:OnLeave()
	self.over = nil;
	self:UpdateAtlas();
	if not self:IsSelected() then
		self.Text:SetFontObject("GameFontNormalSmall");
	end
end

function MinimalTabMixin:OnEnable()
	self:UpdateAtlas();
end

function MinimalTabMixin:OnDisable()
	self:UpdateAtlas();
end]] },
