{ 'Blizzard_SharedXML\\ListTemplates.lua', [[
CollapseButtonMixin = { };

function CollapseButtonMixin:UpdatePressedState(pressed)
	if pressed then
		self.Icon:AdjustPointsOffset(1, -1);
	else
		self.Icon:AdjustPointsOffset(-1, 1);
	end
end

function CollapseButtonMixin:UpdateCollapsedState(collapsed)
	self.collapsed = collapsed;
	local atlas = collapsed and "common-button-list-plus" or "common-button-list-minus";
	self.Icon:SetAtlas(atlas, true);
	self:SetHighlightAtlas(atlas);
end

ListHeaderVisualMixin = {};

function ListHeaderVisualMixin:GetTitleRegion()
	return self.ButtonText or self.Text;
end

function ListHeaderVisualMixin:AdjustTextOffset(x, y)
	local title = self:GetTitleRegion();
	if title then
		title:AdjustPointsOffset(x, y);
	end
end

function ListHeaderVisualMixin:GetTitleColor(useHighlight)
	local color = self.titleColors and self.titleColors[useHighlight];
	if color then
		return color;
	end

	return useHighlight and HIGHLIGHT_FONT_COLOR or DISABLED_FONT_COLOR;
end

function ListHeaderVisualMixin:SetTitleColor(useHighlight, color)
	if not self.titleColors then
		self.titleColors = {};
	end

	self.titleColors[useHighlight] = color;
end

function ListHeaderVisualMixin:CheckHighlightTitle(isMouseOver)
	if isMouseOver == nil then
		isMouseOver = self:IsMouseMotionFocus();
	end

	local color = self:GetTitleColor(isMouseOver);
	self:GetTitleRegion():SetTextColor(color:GetRGB());
end

function ListHeaderVisualMixin:SetHeaderText(text)
	self:GetTitleRegion():SetText(text);
	self:CheckHighlightTitle(nil);
end

function ListHeaderVisualMixin:IsTruncated()
	return self:GetTitleRegion():IsTruncated();
end

function ListHeaderVisualMixin:GetCollapseButton()
	return self.CollapseButton;
end

ListHeaderMixin = {};

function ListHeaderMixin:OnLoad()
	local isMouseOver = false;
	self:CheckHighlightTitle(isMouseOver);
	self:SetPushedTextOffset(1, -1);
end

function ListHeaderMixin:OnClick(button)
	if self.customClickHandler then
		self.customClickHandler(self, button);
	end
end

function ListHeaderMixin:SetClickHandler(handler)
	self.customClickHandler = handler;
end

function ListHeaderMixin:SetTooltipText(tooltipText)
	self.tooltipText = tooltipText;
	self:CheckUpdateTooltip(self:IsMouseMotionFocus());
end

function ListHeaderMixin:OnEnter()
	local isMouseOver = true;
	self:CheckHighlightTitle(isMouseOver);
	self:CheckUpdateTooltip(isMouseOver);

	local collapseButton = self:GetCollapseButton();
	if collapseButton then
		collapseButton:LockHighlight();
	end
end

function ListHeaderMixin:OnLeave()
	local isMouseOver = false;
	self:CheckHighlightTitle(isMouseOver);
	self:CheckUpdateTooltip(isMouseOver);

	local collapseButton = self:GetCollapseButton();
	if collapseButton then
		collapseButton:UnlockHighlight();
	end
end

function ListHeaderMixin:CheckUpdateTooltip(isMouseOver)
	local tooltip = GetAppropriateTooltip();

	if (self:IsTruncated() or self.tooltipText) and isMouseOver then
		tooltip:ClearAllPoints();
		tooltip:SetOwner(self, "ANCHOR_RIGHT");
		if self:IsTruncated() then
			GameTooltip_SetTitle(tooltip, self:GetTitleRegion():GetText(), nil, true);
		end
		if self.tooltipText then
			GameTooltip_AddNormalLine(tooltip, self.tooltipText);
		end
		tooltip:Show();
	else
		tooltip:Hide();
	end
end

function ListHeaderMixin:OnMouseDown()
	self:AdjustTextOffset(1, -1);

	local collapseButton = self:GetCollapseButton();
	if collapseButton then
		local pressed = true;
		collapseButton:UpdatePressedState(pressed);
	end
end

function ListHeaderMixin:OnMouseUp()
	self:AdjustTextOffset(-1, 1);

	local collapseButton = self:GetCollapseButton();
	if collapseButton then
		local pressed = false;
		collapseButton:UpdatePressedState(pressed);
	end
end

function ListHeaderMixin:UpdateCollapsedState(collapsed)
	local collapseButton = self:GetCollapseButton();
	if collapseButton then
		collapseButton:UpdateCollapsedState(collapsed);
	end
end

ListHeaderThreeSliceMixin = CreateFromMixins(ListHeaderVisualMixin);

function ListHeaderThreeSliceMixin:OnLoad()
	-- override if necessary
end

function ListHeaderThreeSliceMixin:GetTitleRegion()
	return self.Name;
end

function ListHeaderThreeSliceMixin:UpdateCollapsedState(collapsed)
	self.Right:SetAtlas(collapsed and "Options_ListExpand_Right" or "Options_ListExpand_Right_Expanded", TextureKitConstants.UseAtlasSize);
	self.HighlightRight:SetAtlas(collapsed and "Options_ListExpand_Right" or "Options_ListExpand_Right_Expanded", TextureKitConstants.UseAtlasSize);
end
]] },
{ 'Blizzard_SharedXML\\MoneyFormatter.lua', [[
local DenominationOrderDescending = {
	Enum.CurrencyType.Gold,
	Enum.CurrencyType.Silver,
	Enum.CurrencyType.Copper,
};

MoneyFormatterDisplayMode = {
	Texture = 1, -- Prefer coin texture atlases for denominations. If the colorblindMode CVar is 1, Abbreviated style is used instead.
	Abbreviated = 2, -- Prefer abbreviated symbols for denominations ('1g').
	Full = 3, -- Prefer full names for denominations ('1 Gold').
};

MoneyFormatterZeroDisplayMode = {
	Collapse = 1, -- Avoid rendering zero values for any denominations (10001 -> '1g 1c', 0 -> '').
	ShowLower = 2, -- Show zero values for denominations below the first denomination with a non-zero value (100 -> '1s 0c').
	ShowAll = 3, -- Show zero values for all denominations (0 -> '0g 0s 0c').
};

MoneyFormatterConfigMixin = {};

MoneyFormatterConfigMixin.DenominationAtlases = {
	[Enum.CurrencyType.Copper] = "coin-copper",
	[Enum.CurrencyType.Silver] = "coin-silver",
	[Enum.CurrencyType.Gold] = "coin-gold",
};

MoneyFormatterConfigMixin.DenominationAbbreviations = {
	-- Note that these are not format strings - they need to be concatenated onto the end of the value.
	[Enum.CurrencyType.Copper] = COPPER_AMOUNT_SYMBOL,
	[Enum.CurrencyType.Silver] = SILVER_AMOUNT_SYMBOL,
	[Enum.CurrencyType.Gold] = GOLD_AMOUNT_SYMBOL,
};

MoneyFormatterConfigMixin.DenominationFullTexts = {
	[Enum.CurrencyType.Copper] = COPPER_AMOUNT,
	[Enum.CurrencyType.Silver] = SILVER_AMOUNT,
	[Enum.CurrencyType.Gold] = GOLD_AMOUNT,
};

function MoneyFormatterConfigMixin:Init()
	self.displayMode = MoneyFormatterDisplayMode.Texture;
	self.zeroDisplayMode = MoneyFormatterZeroDisplayMode.Collapse;
	self.valueFormatter = nil; -- Optional formatter invoked with (value, denomination).
	self.zeroDisplayText = nil; -- Optional static override specifically for rawCopper == 0.
	self.showMinDenominationAtZero = false; -- If true, rawCopper == 0 renders the minimum denomination with a zero value.
	self.minDenomination = Enum.CurrencyType.Copper; -- Minimum denomination unit to render.
	-- Parameters for texture/atlas markup formatting.
	self.textureWidth = 14;
	self.textureHeight = 14;
	self.textureOffsetX = 2;
	self.textureOffsetY = 0;
end

function MoneyFormatterConfigMixin:GetDisplayMode()
	return self.displayMode;
end

function MoneyFormatterConfigMixin:SetDisplayMode(mode)
	self.displayMode = mode;
end

function MoneyFormatterConfigMixin:GetMinDenomination()
	return self.minDenomination;
end

function MoneyFormatterConfigMixin:SetMinDenomination(denomination)
	self.minDenomination = denomination;
end

function MoneyFormatterConfigMixin:GetValueFormatter()
	return self.valueFormatter;
end

function MoneyFormatterConfigMixin:SetValueFormatter(func)
	self.valueFormatter = func;
end

function MoneyFormatterConfigMixin:GetZeroDisplayMode()
	return self.zeroDisplayMode;
end

function MoneyFormatterConfigMixin:SetZeroDisplayMode(mode)
	self.zeroDisplayMode = mode;
end

function MoneyFormatterConfigMixin:GetZeroDisplayText()
	return self.zeroDisplayText;
end

function MoneyFormatterConfigMixin:SetZeroDisplayText(text)
	self.zeroDisplayText = text;
end

function MoneyFormatterConfigMixin:GetShowMinDenominationAtZero()
	return self.showMinDenominationAtZero;
end

function MoneyFormatterConfigMixin:SetShowMinDenominationAtZero(showAtZero)
	self.showMinDenominationAtZero = showAtZero;
end

function MoneyFormatterConfigMixin:GetTextureMarkupOptions()
	return self.textureWidth, self.textureHeight, self.textureOffsetX, self.textureOffsetY;
end

function MoneyFormatterConfigMixin:SetTextureMarkupOptions(textureWidth, textureHeight, textureOffsetX, textureOffsetY)
	self.textureWidth = textureWidth;
	self.textureHeight = textureHeight;
	self.textureOffsetX = textureOffsetX or 0;
	self.textureOffsetY = textureOffsetY or 0;
end

function MoneyFormatterConfigMixin:GetDenominationAbbreviation(denomination)
	return self.DenominationAbbreviations[denomination];
end

function MoneyFormatterConfigMixin:GetDenominationAtlas(denomination)
	return self.DenominationAtlases[denomination];
end

function MoneyFormatterConfigMixin:GetDenominationFullText(denomination)
	return self.DenominationFullTexts[denomination];
end

MoneyFormatterUtil = {};

function MoneyFormatterUtil.CreateFormatterConfig()
	return CreateAndInitFromMixin(MoneyFormatterConfigMixin);
end

function MoneyFormatterUtil.GetAppropriateDisplayMode(config)
	local displayMode = config:GetDisplayMode();

	if displayMode == MoneyFormatterDisplayMode.Texture then
		if CVarCallbackRegistry:GetCVarValueBool("colorblindMode") then
			return MoneyFormatterDisplayMode.Abbreviated;
		end
	end

	return displayMode;
end

function MoneyFormatterUtil.GetDenominationAmount(rawCopper, denomination)
	if denomination == Enum.CurrencyType.Gold then
		return math.floor(rawCopper / (COPPER_PER_SILVER * SILVER_PER_GOLD));
	elseif denomination == Enum.CurrencyType.Silver then
		return math.floor(rawCopper / COPPER_PER_SILVER) % SILVER_PER_GOLD;
	elseif denomination == Enum.CurrencyType.Copper then
		return math.fmod(rawCopper, COPPER_PER_SILVER);
	end

	assertsafe(false, "attempted to get value for an unsupported denomination");
	return 0;
end

function MoneyFormatterUtil.FormatDenominationValue(config, denomination, amount)
	local valueFormatter = config:GetValueFormatter();
	local formattedValue;

	if valueFormatter ~= nil then
		formattedValue = valueFormatter(amount, denomination);
	end

	if formattedValue == nil then
		formattedValue = tostring(amount);
	end

	return formattedValue;
end

function MoneyFormatterUtil.FormatTextureDenomination(config, denomination, formattedValue)
	return formattedValue .. CreateAtlasMarkup(config:GetDenominationAtlas(denomination), config:GetTextureMarkupOptions());
end

function MoneyFormatterUtil.FormatAbbreviatedDenomination(config, denomination, formattedValue)
	return formattedValue .. config:GetDenominationAbbreviation(denomination);
end

function MoneyFormatterUtil.FormatFullDenomination(config, denomination, formattedValue)
	return string.format(config:GetDenominationFullText(denomination), formattedValue);
end

function MoneyFormatterUtil.FormatDenomination(config, denomination, amount)
	local formattedValue = MoneyFormatterUtil.FormatDenominationValue(config, denomination, amount);
	local displayMode = MoneyFormatterUtil.GetAppropriateDisplayMode(config);

	if displayMode == MoneyFormatterDisplayMode.Texture then
		return MoneyFormatterUtil.FormatTextureDenomination(config, denomination, formattedValue);
	elseif displayMode == MoneyFormatterDisplayMode.Abbreviated then
		return MoneyFormatterUtil.FormatAbbreviatedDenomination(config, denomination, formattedValue);
	elseif displayMode == MoneyFormatterDisplayMode.Full then
		return MoneyFormatterUtil.FormatFullDenomination(config, denomination, formattedValue);
	end

	assertsafe(false, "attempted to format denomination with an unsupported display mode");
	return formattedValue;
end

function MoneyFormatterUtil.ShouldIncludeDenomination(config, denomination, amount, hasStartedOutput, rawCopper)
	local shouldInclude = false;
	local zeroDisplayMode = config:GetZeroDisplayMode();

	if zeroDisplayMode == MoneyFormatterZeroDisplayMode.ShowAll then
		shouldInclude = true;
	elseif zeroDisplayMode == MoneyFormatterZeroDisplayMode.Collapse then
		shouldInclude = amount > 0;
	elseif zeroDisplayMode == MoneyFormatterZeroDisplayMode.ShowLower then
		shouldInclude = amount > 0 or hasStartedOutput;
	else
		assertsafe(false, "attempted to evaluate inclusion for an unsupported zero display mode");
		shouldInclude = amount > 0;
	end

	-- Technically, this logic could be done first. But, keeping it this way
	-- ensures that we consistently triggerName assertsafe validation of the
	-- zeroDisplayMode rather than have it be skipped for some inputs.
	if rawCopper == 0 and config:GetShowMinDenominationAtZero() and denomination == config:GetMinDenomination() then
		shouldInclude = true;
	end

	return shouldInclude;
end

function MoneyFormatterUtil.FormatMoney(rawCopper, config)
	if not assertsafe(rawCopper >= 0, "attempted to format a negative copper value") then
		-- Negative amount formatting is not presently supported. Format such values as zero instead.
		rawCopper = 0;
	end

	if rawCopper == 0 then
		local zeroDisplayText = config:GetZeroDisplayText();

		if zeroDisplayText then
			return zeroDisplayText;
		end
	end

	local parts = {};
	local hasStartedOutput = false;

	for _, denomination in ipairs(DenominationOrderDescending) do
		if denomination >= config:GetMinDenomination() then
			local amount = MoneyFormatterUtil.GetDenominationAmount(rawCopper, denomination);

			if MoneyFormatterUtil.ShouldIncludeDenomination(config, denomination, amount, hasStartedOutput, rawCopper) then
				table.insert(parts, MoneyFormatterUtil.FormatDenomination(config, denomination, amount));
				hasStartedOutput = true;
			end
		end
	end

	return table.concat(parts, " ");
end

function MoneyFormatterUtil.BreakUpLargeNumbers(amount, denomination)
	if denomination == Enum.CurrencyType.Gold then
		return BreakUpLargeNumbers(amount);
	else
		return tostring(amount);
	end
end

MoneyFormatterPresets = {};

-- Formats a compact representation of money with zero denominations omitted (10001 -> "1g 1c", 0 -> "").
MoneyFormatterPresets.Compact = MoneyFormatterUtil.CreateFormatterConfig();
MoneyFormatterPresets.Compact:SetDisplayMode(MoneyFormatterDisplayMode.Texture);
MoneyFormatterPresets.Compact:SetZeroDisplayMode(MoneyFormatterZeroDisplayMode.Collapse);
MoneyFormatterPresets.Compact:SetValueFormatter(MoneyFormatterUtil.BreakUpLargeNumbers);

-- Formats a compact representation of money with zero denominations omitted, except at zero itself (10001 -> "1g 1c", 0 -> "0c").
MoneyFormatterPresets.CompactWithZero = MoneyFormatterUtil.CreateFormatterConfig();
MoneyFormatterPresets.CompactWithZero:SetDisplayMode(MoneyFormatterDisplayMode.Texture);
MoneyFormatterPresets.CompactWithZero:SetZeroDisplayMode(MoneyFormatterZeroDisplayMode.Collapse);
MoneyFormatterPresets.CompactWithZero:SetShowMinDenominationAtZero(true);
MoneyFormatterPresets.CompactWithZero:SetValueFormatter(MoneyFormatterUtil.BreakUpLargeNumbers);

-- Formats money while showing lower denominations after the first shown denomination (10001 -> "1g 0s 1c", 100 -> "1s 0c", 0 -> "0c").
MoneyFormatterPresets.ShowLowerWithZero = MoneyFormatterUtil.CreateFormatterConfig();
MoneyFormatterPresets.ShowLowerWithZero:SetDisplayMode(MoneyFormatterDisplayMode.Texture);
MoneyFormatterPresets.ShowLowerWithZero:SetZeroDisplayMode(MoneyFormatterZeroDisplayMode.ShowLower);
MoneyFormatterPresets.ShowLowerWithZero:SetShowMinDenominationAtZero(true);
MoneyFormatterPresets.ShowLowerWithZero:SetValueFormatter(MoneyFormatterUtil.BreakUpLargeNumbers);

-- Formats an expanded representation of money with all zero denominations included (10001 -> "1g 0s 1c", 0 -> "0g 0s 0c").
MoneyFormatterPresets.ShowAll = MoneyFormatterUtil.CreateFormatterConfig();
MoneyFormatterPresets.ShowAll:SetDisplayMode(MoneyFormatterDisplayMode.Texture);
MoneyFormatterPresets.ShowAll:SetZeroDisplayMode(MoneyFormatterZeroDisplayMode.ShowAll);
MoneyFormatterPresets.ShowAll:SetValueFormatter(MoneyFormatterUtil.BreakUpLargeNumbers);
]] },
{ 'Blizzard_SharedXML\\MarchingAnts.lua', [=[
MarchingAntsMixin = CreateFromMixins(DirtiableMixin);

function MarchingAntsMixin:OnLoad()
	self:SetDirtyMethod(self.Clean);
	self:SetupAssets();
end

function MarchingAntsMixin:OnShow()
	self:RegisterEvent("UI_SCALE_CHANGED");
	self:RegisterEvent("DISPLAY_SIZE_CHANGED");
	self:CheckResumePlaying();
end

function MarchingAntsMixin:OnHide()
	self:UnregisterEvent("UI_SCALE_CHANGED");
	self:UnregisterEvent("DISPLAY_SIZE_CHANGED");
	self:Stop();
end

function MarchingAntsMixin:OnEvent(event, ...)
	self:MarkDirty();
end

function MarchingAntsMixin:Clean()
	self:Stop();
	self:SetupAssets();
	self:CheckResumePlaying();
end

function MarchingAntsMixin:CheckResumePlaying()
	if self:IsVisible() and (self:GetSpeed() > 0) then
		self:Play();
	end
end

function MarchingAntsMixin:Play()
	self.MarchingAnim:Play();
end

function MarchingAntsMixin:Pause()
	self.MarchingAnim:Pause();
end

function MarchingAntsMixin:Stop()
	self.MarchingAnim:Stop();
end

function MarchingAntsMixin:GetHorizontalAsset()
	return self.horizontalAsset or [[UI-RaidFrames-SingleAnt-Horiz]];
end

function MarchingAntsMixin:SetHorizontalAsset(asset)
	self.horizontalAsset = asset;
	self:MarkDirty();
end

function MarchingAntsMixin:GetVerticalAsset()
	return self.verticalAsset or [[UI-RaidFrames-SingleAnt-Vertical]];
end

function MarchingAntsMixin:SetVerticalAsset(asset)
	self.verticalAsset = asset;
	self:MarkDirty();
end

function MarchingAntsMixin:GetCornersAsset()
	-- This is optional, the region will hide if not set.
	return self.cornersAsset;
end

function MarchingAntsMixin:SetCornersAsset(asset)
	self.cornersAsset = asset;
	self:MarkDirty();
end

function MarchingAntsMixin:GetSpeed()
	return self.animSpeed or 1;
end

function MarchingAntsMixin:SetSpeed(speed)
	-- Speeds of 0 will pause the animation, different speeds will resume the animation at the desired rate.
	-- FIXME: Adding checks to protect against
	self.animSpeed = math.max(speed or 1, 0);

	if self.animSpeed == 0 then
		self:Pause();
	elseif self.animSpeed > 0 then
		self.MarchingAnim:SetAnimationSpeedMultiplier(self.animSpeed);
		self:CheckResumePlaying();
	end
end

local elementSetupData =
{
	Left = { addressModeH = TextureKitConstants.AddressModeClamp, addressModeV = TextureKitConstants.AddressModeWrap, point1 = "TOPLEFT", point2 = "BOTTOMLEFT", keyOffsetP1X = "leftOffsetP1X", keyOffsetP1Y = "leftOffsetP1Y", keyOffsetP2X = "leftOffsetP2X", keyOffsetP2Y = "leftOffsetP2Y" },
	Right = { addressModeH = TextureKitConstants.AddressModeClamp, addressModeV = TextureKitConstants.AddressModeWrap, point1 = "TOPRIGHT", point2 = "BOTTOMRIGHT", keyOffsetP1X = "rightOffsetP1X", keyOffsetP1Y = "rightOffsetP1Y", keyOffsetP2X = "rightOffsetP2X", keyOffsetP2Y = "rightOffsetP2Y" },
	Top = { addressModeH = TextureKitConstants.AddressModeWrap, addressModeV = TextureKitConstants.AddressModeClamp, point1 = "TOPLEFT", point2 = "TOPRIGHT", keyOffsetP1X = "topOffsetP1X", keyOffsetP1Y = "topOffsetP1Y", keyOffsetP2X = "topOffsetP2X", keyOffsetP2Y = "topOffsetP2Y" },
	Bottom = { addressModeH = TextureKitConstants.AddressModeWrap, addressModeV = TextureKitConstants.AddressModeClamp, point1 = "BOTTOMLEFT", point2 = "BOTTOMRIGHT", keyOffsetP1X = "bottomOffsetP1X", keyOffsetP1Y = "bottomOffsetP1Y", keyOffsetP2X = "bottomOffsetP2X", keyOffsetP2Y = "bottomOffsetP2Y" },
	Corners = { point1 = "TOPLEFT", point2 = "BOTTOMRIGHT", keyOffsetP1X = "cornerOffsetP1X", keyOffsetP1Y = "cornerOffsetP1Y", keyOffsetP2X = "cornerOffsetP2X", keyOffsetP2Y = "cornerOffsetP2Y" },
}

local function AnchorElement(container, elementKey)
	local data = elementSetupData[elementKey];
	local element = container[elementKey];
	element:ClearAllPoints();
	element:SetPoint(data.point1, container, data.point1, container[data.keyOffsetP1X] or 0, container[data.keyOffsetP1Y] or 0);
	element:SetPoint(data.point2, container, data.point2, container[data.keyOffsetP2X] or 0, container[data.keyOffsetP2Y] or 0);
end

local function SetupElement(container, elementKey, asset)
	local data = elementSetupData[elementKey];
	if data.addressModeH and data.addressModeV then
		SetTextureWithAddressModeOptions(container[elementKey], asset, TextureKitConstants.UseAtlasSize, data.addressModeH, data.addressModeV, true);
	else
		container[elementKey]:SetAtlas(asset);
	end

	AnchorElement(container, elementKey);
end

function MarchingAntsMixin:SetupAssets()
	SetupElement(self, "Top", self:GetHorizontalAsset());
	SetupElement(self, "Bottom", self:GetHorizontalAsset());
	SetupElement(self, "Left", self:GetVerticalAsset());
	SetupElement(self, "Right", self:GetVerticalAsset());

	local cornersAsset = self:GetCornersAsset();
	if cornersAsset then
		SetupElement(self, "Corners", cornersAsset);
		self.Corners:Show();
	else
		self.Corners:Hide();
	end
end

function MarchingAntsMixin:SetColor(color)
	local r, g, b, a = color:GetRGBA();
	self.Corners:SetVertexColor(r, g, b, a);
	self.Top:SetVertexColor(r, g, b, a);
	self.Left:SetVertexColor(r, g, b, a);
	self.Right:SetVertexColor(r, g, b, a);
	self.Bottom:SetVertexColor(r, g, b, a);
end

function MarchingAntsMixin:SetGradient(orientation, startColor, endColor)
	-- TODO: Add direction
	local startR, startG, startB, startA = startColor:GetRGBA();
	local endR, endG, endB, endA = endColor:GetRGBA();

	-- Gradients are apparently backwards, so reverse arguments as needed in the internal calls to make it work like this:
	-- horizontal: start = left side, end = right side
	-- vertical: start = top side, end = bottom side.

	self.Corners:SetGradient(orientation, endColor, startColor);

	if orientation == "HORIZONTAL" then
		self.Top:SetGradient(orientation, startColor, endColor);
		self.Bottom:SetGradient(orientation, startColor, endColor);

		-- TODO: Interpolate the sides that don't get the full gradient
		self.Left:SetVertexColor(startR, startG, startB, startA);
		self.Right:SetVertexColor(endR, endG, endB, endA);
	else
		self.Left:SetGradient(orientation, endColor, startColor);
		self.Right:SetGradient(orientation, endColor, startColor);

		-- TODO: Interpolate the sides that don't get the full gradient
		self.Top:SetVertexColor(startR, startG, startB, startA);
		self.Bottom:SetVertexColor(endR, endG, endB, endA);
	end
end

local function SetInsetsInternal(container, element, elementKey, p1x, p1y, p2x, p2y)
	local points = elementSetupData[elementKey];
	self[points.keyOffsetP1X] = p1x;
	self[points.keyOffsetP1Y] = p1y;
	self[points.keyOffsetP2X] = p2x;
	self[points.keyOffsetP2Y] = p2y;
	AnchorElement(container, element, elementKey);
end

function MarchingAntsMixin:SetInsetCorners(left, top, right, bottom)
	SetInsetsInternal(self, self.Corners, "Corners", left, top, right, bottom);
end

function MarchingAntsMixin:SetInsetLeft(left, top, right, bottom)
	SetInsetsInternal(self, self.Left, "Left", left, top, right, bottom);
end

function MarchingAntsMixin:SetInsetRight(left, top, right, bottom)
	SetInsetsInternal(self, self.Right, "Right", left, top, right, bottom);
end

function MarchingAntsMixin:SetInsetBottom(left, top, right, bottom)
	SetInsetsInternal(self, self.Bottom, "Bottom", left, top, right, bottom);
end

function MarchingAntsMixin:SetLineThickness(width, height)
	self.Left:SetWidth(width);
	self.Right:SetWidth(width);
	self.Top:SetHeight(height);
	self.Bottom:SetHeight(height);
end

function MarchingAntsMixin:AnchorAroundTarget(target, optPaddingHorizontal, optPaddingVertical)
	if target then
		local paddingH = optPaddingHorizontal or 0;
		local paddingV = optPaddingVertical or 0;
		self:ClearAllPoints();
		self:SetPoint("TOPLEFT", target, "TOPLEFT", -paddingH, paddingV);
		self:SetPoint("BOTTOMRIGHT", target, "BOTTOMRIGHT", paddingH, -paddingV);
	end
end

function MarchingAnts_CreateAsChildOf(parent, optTemplate, optParentKey)
	-- First check if it already exists and use that element:
	local parentKey = optParentKey or "MarchingAnts";
	if parent and parent[parentKey] then
		return parent[parentKey];
	end

	local ants = CreateFrame("Frame", nil, parent, optTemplate or "MarchingAntsTemplate");
	if parent then
		ants:SetParentKey(parentKey);
	end

	return ants;
end

function MarchingAnts_Create(parent, width, height, optTemplate, optAnchor, optParentKey)
	local ants = MarchingAnts_CreateAsChildOf(parent, optTemplate, optParentKey);
	if width and height then
		ants:SetSize(width, height);
	end

	if optAnchor then
		local clearAllPoints = true;
		optAnchor:SetPoint(ants, clearAllPoints);
	end

	return ants;
end

function MarchingAnts_CreateForTarget(target, optTemplate, optPaddingHorizontal, optPaddingVertical, optParentKey)
	local ants = MarchingAnts_CreateAsChildOf(target, optTemplate, optParentKey);
	ants:AnchorAroundTarget(target, optPaddingHorizontal, optPaddingVertical);
	return ants;
end
