{ 'Blizzard_FrameXMLBase\\AnimatedStatusBar.lua', [[
AnimatedStatusBarMixin = {};

local DEFAULT_ACCUMULATION_TIMEOUT_SEC = .1;

function AnimatedStatusBarMixin:OnLoad()
	if self:GetStatusBarTexture() then
		self:GetStatusBarTexture():SetDrawLayer("BORDER");
	end
	self.OnFinishedCallback = function(...) self:OnAnimFinished(...); end;
	self.OnSetStatusBarAnimUpdateCallback = function(...) self:OnSetStatusBarAnimUpdate(...); end;
	self.accumulationTimeoutInterval = DEFAULT_ACCUMULATION_TIMEOUT_SEC;
	self.matchLevelOnFirstWrap = true;
	self.matchBarValueToAnimation = false;

	self:Reset();
end

function AnimatedStatusBarMixin:Reset()
	self.pendingReset = true;
end

function AnimatedStatusBarMixin:SetMatchLevelOnFirstWrap(matchLevelOnFirstWrap)
	self.matchLevelOnFirstWrap = matchLevelOnFirstWrap;
end

function AnimatedStatusBarMixin:GetMatchLevelOnFirstWrap()
	return self.matchLevelOnFirstWrap;
end

-- If set to false then the status bar's value will immediately pop to the end and the animation will cover it, otherwise the bar's value will smoothly animate under the leading edge
function AnimatedStatusBarMixin:SetMatchBarValueToAnimation(matchBarValueToAnimation)
	self.matchBarValueToAnimation = matchBarValueToAnimation;
end

function AnimatedStatusBarMixin:GetMatchBarValueToAnimation()
	return self.matchBarValueToAnimation;
end

function AnimatedStatusBarMixin:SetOnAnimatedValueChangedCallback(animatedValueChangedCallback)
	self.animatedValueChangedCallback = animatedValueChangedCallback;
end

function AnimatedStatusBarMixin:SetDeferAnimationCallback(deferAnimationCallback)
	self.DeferAnimation = deferAnimationCallback;
end

function AnimatedStatusBarMixin:GetOnAnimatedValueChangedCallback()
	return self.animatedValueChangedCallback;
end

local function SetAnimatedTextureColorsHelper(self, r, g, b)
	if self.ColorableTextures then
		for i, texture in ipairs(self.ColorableTextures) do
			texture:SetVertexColor(r, g, b);
		end
	end
end

function AnimatedStatusBarMixin:SetAnimatedTextureColors(r, g, b)
	self.animatedTextureColors = { r, g, b };
	SetAnimatedTextureColorsHelper(self, r, g, b);
end

-- Instead of using SetMinMaxValues or SetValue use this method instead
-- Optionally specify level for wrappable status bars like for XP or rep,
--	this will allow the animation to correctly reach the end of the bar and wrap back around
function AnimatedStatusBarMixin:SetAnimatedValues(value, min, max, level)
	if self.pendingValue ~= value then
		self.pendingValue = value;
		self:MarkDirty();
	end
	if self.pendingMin ~= min or self.pendingMax ~= max then
		self.pendingMin = min;
		self.pendingMax = max;
		self:MarkDirty();
	end
	if level and self.level ~= level then
		self.pendingLevel = level;
		self:MarkDirty();
	end
end

function AnimatedStatusBarMixin:MarkDirty(instant)
	self.accumulationTimeout = instant and 0 or self.accumulationTimeoutInterval;
end

function AnimatedStatusBarMixin:GetTargetValue()
	if self.pendingValue then
		return self.pendingValue;
	end
	return self.targetValue or self:GetValue();
end

-- Discrete value
function AnimatedStatusBarMixin:GetAnimatedValue()
	return self.animatedValue or self:GetValue();
end

function AnimatedStatusBarMixin:GetContinuousAnimatedValue()
	return self.continuousAnimatedValue or self:GetValue();
end

function AnimatedStatusBarMixin:OnUpdate(elapsed)
	if not self:IsAnimating() and self.accumulationTimeout and (not self.DeferAnimation or not self.DeferAnimation()) then
		if self.pendingReset then
			self:ProcessChangesInstantly();
			self.accumulationTimeout = nil;
		elseif self.accumulationTimeout <= elapsed then
			self:ProcessChanges();
			self.accumulationTimeout = nil;
		else
			self.accumulationTimeout = self.accumulationTimeout - elapsed;
		end
	end
end

function AnimatedStatusBarMixin:IsAnimating()
	return self.Anim:IsPlaying();
end

function AnimatedStatusBarMixin:ProcessChangesInstantly()
	self.pendingReset = false;
	if self.pendingMin or self.pendingMax then
		self:SetMinMaxValues(self.pendingMin, self.pendingMax);
		self.pendingMin = nil;
		self.pendingMax = nil;
	end
	if self.pendingLevel then
		self.level = self.pendingLevel;
		self.pendingLevel = nil;
	end
	if self.pendingValue then
		self:SetValue(self.pendingValue);
		self.pendingValue = nil;
		self:OnValueChanged();
	end
end

local function GetPercentageBetween(min, max, value)
	if max == min then
		return 0;
	end
	return (value - min) / (max - min);
end

function AnimatedStatusBarMixin:ProcessChanges()
	local levelIsIncreasing = false;
	if self.pendingLevel then
		if not self.level then
			-- Assume that it was already on the pending level, do nothing special
			self.level = self.pendingLevel;
			self.pendingLevel = nil;
		elseif self.pendingLevel > self.level then
			-- Going up some levels
			levelIsIncreasing = true;
		elseif self.pendingLevel == self.level then
			-- Same level now, start from nothing
			self.pendingLevel = nil;
		else
			-- Unleveling, just instantly reset everything
			return self:ProcessChangesInstantly();
		end
	end
	if not levelIsIncreasing and (self.pendingMin or self.pendingMax) then
		local min, max = self:GetMinMaxValues();
		local oldRange = max - min;
		local newRange = self.pendingMax - self.pendingMin;
		if oldRange ~= 0 and newRange ~= 0 and oldRange ~= newRange then
			local ratio = oldRange / newRange;
			local currentValue = self:GetValue();
			self:SetMinMaxValues(self.pendingMin, self.pendingMax);
			self:SetValue(currentValue * ratio);
			self.animatedValue = nil;
			self.continuousAnimatedValue = nil;
			self:OnValueChanged();
		else
			self:SetMinMaxValues(self.pendingMin, self.pendingMax);
		end
		self.pendingMin = nil;
		self.pendingMax = nil;
	end

	local min, max = self:GetMinMaxValues();

	local newValue;
	if levelIsIncreasing then
		newValue = max;
	elseif self.pendingValue then
		newValue = self.pendingValue;
		self.pendingValue = nil;
	else
		return;
	end

	local oldValue = self:GetValue();
	if not levelIsIncreasing and oldValue == newValue then return; end
	
	if newValue > max then
		newValue = max;
	end

	local oldValueAsPercent = GetPercentageBetween(min, max, oldValue);
	local deltaAsPercent = GetPercentageBetween(min, max, newValue) - oldValueAsPercent;

	self.animatedValue = nil;
	self.continuousAnimatedValue = nil;

	-- No backward animations
	if deltaAsPercent < 0 then
		self:SetValue(newValue);
		self:OnValueChanged();
		return;
	end

	self.startValue = oldValue;
	self.targetValue = newValue;
	self.levelIsIncreasing = levelIsIncreasing;

	if deltaAsPercent == 0 then
		self:OnAnimFinished();
	else
		self:SetupAnimationGroupForValueChange(self.Anim, oldValueAsPercent, deltaAsPercent);
		self:StartTilingAnimation(oldValueAsPercent, deltaAsPercent);
	end
end

local function SetupAnimationGroupForValueChangeHelper(self, startingPercent, percentChange, ...)
	for i = 1, select("#", ...) do
		self:SetupAnimationForValueChange(select(i, ...), startingPercent, percentChange);
	end
end

function AnimatedStatusBarMixin:SetupAnimationGroupForValueChange(animationGroup, startingPercent, percentChange)
	SetupAnimationGroupForValueChangeHelper(self, startingPercent, percentChange, animationGroup:GetAnimations());

	animationGroup:SetScript("OnFinished", self.OnFinishedCallback);

	animationGroup:Play();
end

function AnimatedStatusBarMixin:SetupAnimationForValueChange(anim, startingPercent, percentChange)
	local objectType = anim:GetObjectType();

	if anim.adjustAnchors then
		for i = 1, anim:GetTarget():GetNumPoints() do
			local point, relativeTo, relativePoint, offsetX, offsetY = anim:GetTarget():GetPoint(i);
			anim:GetTarget():SetPoint(point, relativeTo, relativePoint, startingPercent * self:GetWidth(), offsetY);
		end
	end

	if anim.durationPerDistance then
		anim:SetDuration(self:GetWidth() * percentChange * anim.durationPerDistance);
	end

	if anim.delayPerDistance then
		anim:SetStartDelay(self:GetWidth() * percentChange * anim.delayPerDistance);
	end

	if objectType == "Translation" then
		if anim.adjustOffsetX then
			anim:SetOffset(percentChange * self:GetWidth(), 0);
		end
	elseif objectType == "Scale" then
		if anim.adjustScaleTo then
			anim:SetScaleTo(percentChange * self:GetWidth() * (anim.scaleFactor or 1), 1);
		end
	end

	if anim.setStatusBarOnUpdate then
		anim:SetScript("OnUpdate", self.OnSetStatusBarAnimUpdateCallback);
	end
end

function AnimatedStatusBarMixin:OnSetStatusBarAnimUpdate(anim, elapsed)
	self.continuousAnimatedValue = self.startValue + (self.targetValue - self.startValue) * anim:GetProgress();
	self.animatedValue = math.floor(self.continuousAnimatedValue);

	if self:GetMatchBarValueToAnimation() then
		self:SetValue(self.animatedValue);
	else
		self:SetValue(self.targetValue);
	end
	self:OnValueChanged();
end

function AnimatedStatusBarMixin:OnValueChanged()
	if self.animatedValueChangedCallback then
		self.animatedValueChangedCallback(self, self:GetAnimatedValue());
	end
end

function AnimatedStatusBarMixin:OnAnimFinished()
	if self.levelIsIncreasing then
		if self.matchLevelOnFirstWrap then
			self.level = self.pendingLevel;
		else
			self.level = self.level + 1;
		end
		self:SetValue(0);
		self:MarkDirty(true);
		self:OnValueChanged();
	else
		self:SetValue(self.targetValue);
		self:OnValueChanged();
	end	

	self.levelIsIncreasing = nil;
	self.targetValue = nil;
	self.animatedValue = nil;
	self.continuousAnimatedValue = nil;
	self.startValue = nil;
end

function AnimatedStatusBarMixin:AcquireTileTemplate()
	self.numUsedTileTemplates = (self.numUsedTileTemplates or 0) + 1;
	if not self.tileTemplates then
		self.tileTemplates = {};
	end
	if not self.tileTemplates[self.numUsedTileTemplates] then
		self.tileTemplates[self.numUsedTileTemplates] = CreateFrame("FRAME", nil, self:GetParent(), self.tileTemplate);
	end

	if self.animatedTextureColors then
		SetAnimatedTextureColorsHelper(self.tileTemplates[self.numUsedTileTemplates], unpack(self.animatedTextureColors));
	end
	return self.numUsedTileTemplates, self.tileTemplates[self.numUsedTileTemplates];
end

function AnimatedStatusBarMixin:ReleaseAllTileTemplate()
	if self.tileTemplates then
		for i, tileTemplate in ipairs(self.tileTemplates) do
			tileTemplate.Anim:Stop();
			tileTemplate:ClearAllPoints();
			tileTemplate:Hide();
		end
		self.numUsedTileTemplates = 0;
	end
end

local function ApplyDelayToAllAnims(delay, ...)
	for i = 1, select("#", ...) do
		local anim = select(i, ...);
		if anim:GetOrder() == 1 then
			anim:SetStartDelay(delay);
		end
	end
end

function AnimatedStatusBarMixin:StartTilingAnimation(startingPercent, percentChange)
	if self.tileTemplate and self.tileTemplateWidth and self.tileTemplateOverlap then
		self:ReleaseAllTileTemplate();

		assert(self.tileTemplateWidth > self.tileTemplateOverlap); -- Or we'd never stop tiling

		local width = self:GetWidth();
		local startingX = width * startingPercent;
		local barWidthLeft = width * percentChange;
		while barWidthLeft > self.tileTemplateOverlap do
			local tileTemplateIndex, tileTemplate = self:AcquireTileTemplate();
			tileTemplate:Show();
			tileTemplate:SetPoint("LEFT", self, "LEFT", startingX + (tileTemplateIndex - 1) * self.tileTemplateWidth + (tileTemplateIndex - 2) * -self.tileTemplateOverlap, 0);
			if self.tileTemplateDelay then
				ApplyDelayToAllAnims((tileTemplateIndex - 1) * self.tileTemplateDelay, tileTemplate.Anim:GetAnimations());
			end
			
			tileTemplate:SetWidth(math.min(self.tileTemplateWidth, math.max(barWidthLeft, self.tileTemplateWidth / 2)));
			tileTemplate.Anim:Play();

			barWidthLeft = barWidthLeft - (self.tileTemplateWidth - self.tileTemplateOverlap);
		end
	end
end]] },
{ 'Blizzard_FrameXMLBase\\GradualAnimatedStatusBar.lua', [[

GradualAnimatedStatusBarMixin = {};

function GradualAnimatedStatusBarMixin:OnLoad()
	if self:GetStatusBarTexture() then
		self:GetStatusBarTexture():SetDrawLayer("BORDER");
	end

	-- Gotta set this point OnLoad since self.BarTexture isn't fully setup until now
	self.GainFlareAnimationTexture:ClearAllPoints();
	self.GainFlareAnimationTexture:SetPoint("RIGHT", self.BarTexture, "RIGHT", 1, 0);

	-- Default values so bar is initialized
	-- Otherwise bar will return 0 from GetValue even though it isn't actually showing at 0
	self:SetMinMaxValues(0, 1);
	self:SetValue(0);

	self:Reset();
end

function GradualAnimatedStatusBarMixin:Reset()
	self.pendingReset = true;
end

function GradualAnimatedStatusBarMixin:SetDeferAnimationCallback(deferAnimationCallback)
	self.DeferAnimation = deferAnimationCallback;
end

function GradualAnimatedStatusBarMixin:SetOnAnimatedValueChangedCallback(animatedValueChangedCallback)
	self.animatedValueChangedCallback = animatedValueChangedCallback;
end

function GradualAnimatedStatusBarMixin:GetOnAnimatedValueChangedCallback()
	return self.animatedValueChangedCallback;
end

-- Give frames the opportunity to override the max level alpha animation so they can fade out their entire bar should they choose to
function GradualAnimatedStatusBarMixin:SetLevelUpMaxAlphaAnimation(animation)
	self.overrideLevelUpMaxAlphaAnimation = animation;
end

function GradualAnimatedStatusBarMixin:SetBarTexture(barTexture, deferUntilNextLevel)
	if deferUntilNextLevel then
		self.pendingBarTexture = barTexture;
	else
		self:SetStatusBarTexture(barTexture);
	end
end

function GradualAnimatedStatusBarMixin:SetAnimationTextures(gainFlareAtlas, levelUpAtlas, deferUntilNextLevel)
	if deferUntilNextLevel then
		self.pendingGainFlareAnimationTexture = gainFlareAtlas;
		self.pendingLevelUpTexture = levelUpAtlas;
	else
		self.GainFlareAnimationTexture:SetAtlas(gainFlareAtlas);
		self.LevelUpTexture:SetAtlas(levelUpAtlas);
	end
end

function GradualAnimatedStatusBarMixin:OnValueChanged()
	if self.animatedValueChangedCallback then
		self.animatedValueChangedCallback(self, self:GetAnimatedValue());
	end
end

-- Instead of using SetMinMaxValues or SetValue use this method instead
-- Optionally specify level for wrappable status bars like for XP or rep,
--	this will allow the animation to correctly reach the end of the bar and wrap back around
function GradualAnimatedStatusBarMixin:SetAnimatedValues(value, min, max, level, maxLevel)
	local areValuesCurrentlyChanging = self:IsDirty() or self:IsAnimating();

	-- Check if current value changed
	if (areValuesCurrentlyChanging or self:GetValue() ~= value) and self.pendingValue ~= value then
		self.pendingValue = value;
		self:MarkDirty();
	end

	-- Check if min or max changed
	local currentMin, currentMax = self:GetMinMaxValues();
	local shouldUpdateMin = (areValuesCurrentlyChanging or currentMin ~= min) and self.pendingMin ~= min;
	local shouldUpdateMax = (areValuesCurrentlyChanging or currentMax ~= max) and self.pendingMax ~= max;
	if shouldUpdateMin or shouldUpdateMax then
		self.pendingMin = min;
		self.pendingMax = max;
		self:MarkDirty();
	end

	-- Check if level changed
	if level and self.level ~= level then
		self.pendingLevel = level;
		self:MarkDirty();
	end
	self.maxLevel = maxLevel;

	if not self:IsVisible() then
		self:ProcessChangesInstantly();
	end
end

function GradualAnimatedStatusBarMixin:SubscribeToOnClean(subscribingFrame, onCleanCallback)
	if not self.onCleanCallbacks then
		self.onCleanCallbacks = {};
	end

	self.onCleanCallbacks[subscribingFrame] = onCleanCallback;
end

function GradualAnimatedStatusBarMixin:UnsubscribeFromOnClean(subscribingFrame)
	if not self.onCleanCallbacks then
		return;
	end

	self.onCleanCallbacks[subscribingFrame] = nil;
end

function GradualAnimatedStatusBarMixin:IsDirty()
	return self.isDirty;
end

function GradualAnimatedStatusBarMixin:MarkDirty(instant)
	self.isDirty = true;
	self.accumulationTimeout = instant and 0 or self.accumulationTimeoutInterval;
end

function GradualAnimatedStatusBarMixin:ClearDirty()
	self.isDirty = false;
	self.accumulationTimeout = nil;

	if self.onCleanCallbacks then
		for i, callback in pairs(self.onCleanCallbacks) do
			callback(self);
		end
	end
end

function GradualAnimatedStatusBarMixin:GetTargetValue()
	if self.pendingValue then
		return self.pendingValue;
	end
	return self.targetValue or self:GetValue();
end

function GradualAnimatedStatusBarMixin:GetAnimatedValue()
	return self.animatedValue or self:GetValue();
end

function GradualAnimatedStatusBarMixin:OnUpdate(elapsed)
	self:OnUpdateGainAnimation();

	if not self:IsAnimating() and self:IsDirty() and (not self.DeferAnimation or not self.DeferAnimation()) then
		if self.pendingReset then
			self:ProcessChangesInstantly();
		elseif self.accumulationTimeout <= elapsed then
			self:ProcessChanges();
		else
			self.accumulationTimeout = self.accumulationTimeout - elapsed;
		end
	end
end

function GradualAnimatedStatusBarMixin:SetIsMaxLevelFunctionOverride(overrideFunction)
	self.overrideIsAtMaxLevel = overrideFunction;
end

function GradualAnimatedStatusBarMixin:IsAtMaxLevel()
	if self.overrideIsAtMaxLevel then
		return self.overrideIsAtMaxLevel();
	end

	return self.maxLevel and self.level and self.level >= self.maxLevel;
end

function GradualAnimatedStatusBarMixin:IsAnimating()
	return self.targetValue and self:GetValue() < self.targetValue
		or self.gainFinishedAnimation and self.gainFinishedAnimation:IsPlaying()
		or self.LevelUpMaxAlphaAnimation:IsPlaying()
		or self.overrideLevelUpMaxAlphaAnimation and self.overrideLevelUpMaxAlphaAnimation:IsPlaying();
end

function GradualAnimatedStatusBarMixin:SubscribeToOnFinishedAnimating(subscribingFrame, onFinishedCallback)
	if not self.animationFinishedCallbacks then
		self.animationFinishedCallbacks = {};
	end

	self.animationFinishedCallbacks[subscribingFrame] = onFinishedCallback;
end

function GradualAnimatedStatusBarMixin:UnsubscribeFromOnFinishedAnimating(subscribingFrame)
	if not self.animationFinishedCallbacks then
		return;
	end

	self.animationFinishedCallbacks[subscribingFrame] = nil;
end

function GradualAnimatedStatusBarMixin:OnFinishedAnimating()
	if self.animationFinishedCallbacks then
		for i, callback in pairs(self.animationFinishedCallbacks) do
			callback(self);
		end
	end
end

function GradualAnimatedStatusBarMixin:ProcessChangesInstantly()
	self:ClearDirty();

	-- Stop all animations
	self:ClearGainAnimationValues();
	self:FinishAnimationInstantly(self.GainFlareAnimation);
	self:FinishAnimationInstantly(self.LevelUpRolloverAnimation);
	self:FinishAnimationInstantly(self.LevelUpMaxAnimation);
	self:FinishAnimationInstantly(self.overrideLevelUpMaxAlphaAnimation);

	-- Instantly assign all pending values
	self.pendingReset = false;
	if self.pendingMin or self.pendingMax then
		self:SetMinMaxValues(self.pendingMin, self.pendingMax);
		self.pendingMin = nil;
		self.pendingMax = nil;
	end

	if self.pendingLevel then
		self.level = self.pendingLevel;
		self.pendingLevel = nil;
	end

	self:ApplyPendingTextures();

	if self.pendingValue then
		self:SetValue(self.pendingValue);
		self.pendingValue = nil;
		self:OnValueChanged();
	end
end

function GradualAnimatedStatusBarMixin:ApplyPendingTextures()
	if self.pendingBarTexture then
		self:SetBarTexture(self.pendingBarTexture);
		self.pendingBarTexture = nil;
	end

	if self.pendingGainFlareAnimationTexture or self.pendingLevelUpTexture then
		self:SetAnimationTextures(self.pendingGainFlareAnimationTexture, self.pendingLevelUpTexture);
		self.pendingGainFlareAnimationTexture = nil;
		self.pendingLevelUpTexture = nil;
	end
end

local function GetPercentageBetween(min, max, value)
	if max == min then
		return 0;
	end
	return (value - min) / (max - min);
end

function GradualAnimatedStatusBarMixin:ProcessChanges()
	local levelIsIncreasing = false;
	if self.pendingLevel then
		if not self.level then
			-- Assume that it was already on the pending level, do nothing special
			self.level = self.pendingLevel;
			self.pendingLevel = nil;
		elseif self.pendingLevel > self.level then
			-- Going up some levels
			levelIsIncreasing = true;
		elseif self.pendingLevel == self.level then
			-- Same level now, start from nothing
			self.pendingLevel = nil;
		else
			-- Unleveling, just instantly reset everything
			self:ProcessChangesInstantly();
			return;
		end
	end

	if not levelIsIncreasing and (self.pendingMin or self.pendingMax) then
		local min, max = self:GetMinMaxValues();
		local oldRange = max - min;
		local newRange = self.pendingMax - self.pendingMin;
		if oldRange ~= 0 and newRange ~= 0 and oldRange ~= newRange then
			local ratio = oldRange / newRange;
			local currentValue = self:GetValue();
			self:SetMinMaxValues(self.pendingMin, self.pendingMax);
			self:SetValue(currentValue * ratio);
			self.animatedValue = nil;
			self:OnValueChanged();
		else
			self:SetMinMaxValues(self.pendingMin, self.pendingMax);
		end
		self.pendingMin = nil;
		self.pendingMax = nil;
	end

	local min, max = self:GetMinMaxValues();

	local newValue;
	if levelIsIncreasing then
		newValue = max;
	elseif self.pendingValue then
		newValue = self.pendingValue;
		self.pendingValue = nil;
	else
		self:OnFinishedAnimating();
		self:ClearDirty();
		return;
	end

	local oldValue = self:GetValue();
	if not levelIsIncreasing and oldValue == newValue then return; end

	if newValue > max then
		newValue = max;
	end

	local oldValueAsPercent = GetPercentageBetween(min, max, oldValue);
	local deltaAsPercent = GetPercentageBetween(min, max, newValue) - oldValueAsPercent;

	self.animatedValue = nil;

	-- No backward animations
	if deltaAsPercent < 0 then
		self:SetValue(newValue);
		self:OnValueChanged();
		self:OnFinishedAnimating();
		self:ClearDirty();
		return;
	end

	self.startValue = oldValue;
	self.targetValue = newValue;
	self.levelIsIncreasing = levelIsIncreasing;
	self.gainAnimationStartTime = GetTime();
	self.gainAnimationDuration = self:GetWidth() * deltaAsPercent * self.gainAnimationDurationPerDistance;
	self:ClearDirty();
end

function GradualAnimatedStatusBarMixin:FinishAnimationInstantly(animation)
	if animation and animation:IsPlaying() then
		-- Set animation to be at it's end so it finishes instantly and calls it's OnFinished and such
		local isReverseNo = false;
		animation:Restart(isReverseNo, animation:GetDuration());
	end
end

function GradualAnimatedStatusBarMixin:ClearGainAnimationValues()
	self.gainAnimationStartTime = nil;
	self.gainAnimationDuration = nil;
	self.levelIsIncreasing = nil;
	self.targetValue = nil;
	self.animatedValue = nil;
	self.continuousAnimatedValue = nil;
	self.startValue = nil;
end

function GradualAnimatedStatusBarMixin:OnUpdateGainAnimation()
	if not self.targetValue then
		return;
	end

	if self:GetValue() >= self.targetValue then
		self:OnGainAnimationFinished();
		return;
	end

	local elapsedAnimationTime = GetTime() - self.gainAnimationStartTime;
	local animationProgress = math.min(elapsedAnimationTime / self.gainAnimationDuration, 1);
	self.animatedValue = self.startValue + (self.targetValue - self.startValue) * animationProgress;
	self.animatedValue = math.floor(self.animatedValue);
	self.animatedValue = math.min(self.targetValue, self.animatedValue);
	self:SetValue(self.animatedValue);
	self:OnValueChanged();
end

function GradualAnimatedStatusBarMixin:OnGainAnimationFinished()
	if self.levelIsIncreasing then
		self.level = self.pendingLevel;
		self:SetValue(self:IsAtMaxLevel() and self.targetValue or 0);
		self:MarkDirty(true);
		self:OnValueChanged();
	else
		self:SetValue(self.targetValue);
		self:OnValueChanged();
	end

	-- Play the gain complete animation
	if self.levelIsIncreasing then
		if self:IsAtMaxLevel() then
			self.gainFinishedAnimation = self.LevelUpMaxAnimation;
		else
			self.gainFinishedAnimation = self.LevelUpRolloverAnimation;
		end
	else
		local _, maxValue = self:GetMinMaxValues();
		if self:GetValue() >= maxValue then
			self.gainFinishedAnimation = self.LevelUpMaxAnimation;
		else
			self.gainFinishedAnimation = self.GainFlareAnimation;
		end
	end
	self.gainFinishedAnimation:Restart();

	-- Reset values
	self:ClearGainAnimationValues();
end

GainFlareAnimationMixin = {};

function GainFlareAnimationMixin:OnPlay()
	self:GetParent().GainFlareAnimationTexture:Show();
end

function GainFlareAnimationMixin:OnFinished()
	local parent = self:GetParent();
	parent.GainFlareAnimationTexture:Hide();
	parent:OnFinishedAnimating();
end

LevelUpRolloverAnimationMixin = {};

function LevelUpRolloverAnimationMixin:OnPlay()
	self:GetParent().LevelUpTexture:Show();
end

function LevelUpRolloverAnimationMixin:OnFinished()
	local parent = self:GetParent();
	parent.LevelUpTexture:Hide();
	parent:ApplyPendingTextures();
	parent:OnFinishedAnimating();
end

LevelUpMaxAnimationMixin = {};

function LevelUpMaxAnimationMixin:OnPlay()
	local parent = self:GetParent();
	parent.LevelUpTexture:Show();

	local alphaAnimation = parent.overrideLevelUpMaxAlphaAnimation or parent.LevelUpMaxAlphaAnimation;
	alphaAnimation:Restart();
end

function LevelUpMaxAnimationMixin:OnFinished()
	local parent = self:GetParent();
	parent.LevelUpTexture:Hide();
	parent:ApplyPendingTextures();
	parent:OnFinishedAnimating();
end
]] },
{ 'Blizzard_FrameXMLBase\\PowerDependencyLine.lua', [[
PowerDependencyLineMixin = {};

PowerDependencyLineMixin.LINE_STATE_CONNECTED = 1;
PowerDependencyLineMixin.LINE_STATE_DISCONNECTED = 2;
PowerDependencyLineMixin.LINE_STATE_LOCKED = 3;

PowerDependencyLineMixin.LINE_FADE_ANIM_TYPE_CONNECTED = 1;
PowerDependencyLineMixin.LINE_FADE_ANIM_TYPE_UNLOCKED = 2;
PowerDependencyLineMixin.LINE_FADE_ANIM_TYPE_LOCKED = 3;

function PowerDependencyLineMixin:IsDeprecated()
	-- Optionally override in your mixin
	return false;
end

function PowerDependencyLineMixin:SetThickness(thickness)
	self.Background:SetThickness(thickness);
	self.Fill:SetThickness(thickness);
	self.FillScroll1:SetThickness(thickness);
	if not self.isCurved then
		self.FillScroll2:SetThickness(thickness);
	end
end

function PowerDependencyLineMixin:SetState(lineState)
	self.lineState = lineState;
	if lineState == self.LINE_STATE_CONNECTED then
		self:SetConnected();
	elseif lineState == self.LINE_STATE_DISCONNECTED then
		self:SetDisconnected();
	elseif lineState == self.LINE_STATE_LOCKED then
		self:SetLocked();
	end
end

function PowerDependencyLineMixin:SetConnected()
	self.Fill:SetVertexColor(self.connectedColor:GetRGB());
	self.FillScroll1:SetVertexColor(self.connectedColor:GetRGB());
	if not self.isCurved then
		self.FillScroll2:SetVertexColor(self.connectedColor:GetRGB());
	end

	self:PlayLineFadeAnim(self.LINE_FADE_ANIM_TYPE_CONNECTED);
end

function PowerDependencyLineMixin:SetDisconnected()
	self.Fill:SetVertexColor(self.disconnectedColor:GetRGB());

	self:PlayLineFadeAnim(self.LINE_FADE_ANIM_TYPE_UNLOCKED);
end

function PowerDependencyLineMixin:SetLocked()
	self.Fill:SetVertexColor(self.connectedColor:GetRGB());

	self:PlayLineFadeAnim(self.LINE_FADE_ANIM_TYPE_LOCKED);
end

function PowerDependencyLineMixin:PlayLineFadeAnim(lineAnimType)
	self.FadeAnim:Finish();

	self.FadeAnim.Background:SetFromAlpha(self.Background:GetAlpha());
	self.FadeAnim.Fill:SetFromAlpha(self.Fill:GetAlpha());
	self.FadeAnim.FillScroll1:SetFromAlpha(self.FillScroll1:GetAlpha());
	if not self.isCurved then
		self.FadeAnim.FillScroll2:SetFromAlpha(self.FillScroll2:GetAlpha());
	end

	local itemDeprecated = self:IsDeprecated();
	if itemDeprecated then
		self.FillScroll1:SetDesaturated(true);
		if not self.isCurved then
			self.FillScroll2:SetDesaturated(true);
		end
	end

	if lineAnimType == self.LINE_FADE_ANIM_TYPE_CONNECTED then
		if itemDeprecated then
			self.ScrollAnim:Stop();
		else
			self.ScrollAnim:Play(false, self.scrollElapsedOffset);
		end

		self.FadeAnim.Background:SetToAlpha(0.0);
		self.FadeAnim.Fill:SetToAlpha(1.0);
		self.FadeAnim.FillScroll1:SetToAlpha(1.0);
		if not self.isCurved then
			self.FadeAnim.FillScroll2:SetToAlpha(1.0);
		end
	elseif lineAnimType == self.LINE_FADE_ANIM_TYPE_UNLOCKED then
		self.ScrollAnim:Stop();

		self.FadeAnim.Background:SetToAlpha(1.0);
		self.FadeAnim.Fill:SetToAlpha(1.0);
		self.FadeAnim.FillScroll1:SetToAlpha(0.0);
		if not self.isCurved then
			self.FadeAnim.FillScroll2:SetToAlpha(0.0);
		end

	elseif lineAnimType == self.LINE_FADE_ANIM_TYPE_LOCKED then
		self.ScrollAnim:Stop();

		self.FadeAnim.Background:SetToAlpha(0.85);
		self.FadeAnim.Fill:SetToAlpha(0.0);
		self.FadeAnim.FillScroll1:SetToAlpha(0.0);
		if not self.isCurved then
			self.FadeAnim.FillScroll2:SetToAlpha(0.0);
		end
	end
	self.animType = lineAnimType;
	self.FadeAnim:Play();
end

function PowerDependencyLineMixin:SetEndPoints(fromButton, toButton)
	if self.isCurved then
		self.Fill:SetSize(2, 2);
		self.Fill:ClearAllPoints();
		self.Fill:SetPoint("CENTER", fromButton);

		self.Background:SetSize(2, 2);
		self.Background:ClearAllPoints();
		self.Background:SetPoint("CENTER", fromButton);

		self.FillScroll1:SetSize(2, 2);
		self.FillScroll1:ClearAllPoints();
		self.FillScroll1:SetPoint("CENTER", fromButton);
	else
		self.Fill:SetStartPoint("CENTER", fromButton);
		self.Fill:SetEndPoint("CENTER", toButton);

		self.Background:SetStartPoint("CENTER", fromButton);
		self.Background:SetEndPoint("CENTER", toButton);

		self.FillScroll1:SetStartPoint("CENTER", fromButton);
		self.FillScroll1:SetEndPoint("CENTER", toButton);

		self.FillScroll2:SetStartPoint("CENTER", fromButton);
		self.FillScroll2:SetEndPoint("CENTER", toButton);
	end
end

function PowerDependencyLineMixin:SetConnectedColor(color)
	self.connectedColor = color;
end

function PowerDependencyLineMixin:SetDisconnectedColor(color)
	self.disconnectedColor = color;
end

do
	local function OnLineRevealFinished(animGroup)
		local lineContainer = animGroup:GetParent();
		lineContainer:OnRevealFinished();
	end

	function PowerDependencyLineMixin:BeginReveal(delay, duration)
		if not self.RevealAnim then
			return;
		end
		self:SetAlpha(0.0);

		self.RevealAnim.Start1:SetEndDelay(delay);
		self.RevealAnim.Start2:SetEndDelay(delay);

		self.RevealAnim.LineScale:SetDuration(duration);

		self.RevealAnim:SetScript("OnFinished", OnLineRevealFinished);
		self.RevealAnim:Play();
	end
end

function PowerDependencyLineMixin:OnRevealFinished()
	if self.animType then
		self:PlayLineFadeAnim(self.animType);
	end
end

function PowerDependencyLineMixin:IsRevealing()
	return self.RevealAnim and self.RevealAnim:IsPlaying();
end

function PowerDependencyLineMixin:GetRevealDelay()
	return self.RevealAnim and self.RevealAnim.Start1:GetEndDelay() or 0.0;
end

function PowerDependencyLineMixin:SetScrollAnimationProgressOffset(progress)
	self.scrollElapsedOffset = (1 - progress) * self.ScrollAnim:GetDuration();
end

function PowerDependencyLineMixin:CalculateTiling(length)
	local TEXTURE_WIDTH = 128;
	local tileAmount = length / TEXTURE_WIDTH;
	self.Fill:SetTexCoord(0, tileAmount, 0, 1);
	self.Background:SetTexCoord(0, tileAmount, 0, 1);
	self.FillScroll1:SetTexCoord(0, tileAmount, 0, 1);
	if not self.isCurved then
		self.FillScroll2:SetTexCoord(0, tileAmount, 0, 1);
	end
end

function PowerDependencyLineMixin:SetVertexOffset(vertexIndex, x, y)
	self.Fill:SetVertexOffset(vertexIndex, x, y);
	self.Background:SetVertexOffset(vertexIndex, x, y);
	self.FillScroll1:SetVertexOffset(vertexIndex, x, y);
	if not self.isCurved then
		self.FillScroll2:SetVertexOffset(vertexIndex, x, y);
	end
end

function PowerDependencyLineMixin:SetAlpha(alpha, continueAnimating)
	if not continueAnimating then
		self.ScrollAnim:Stop();
		self.FadeAnim:Stop();
		if self.RevealAnim then
			self.RevealAnim:Stop();
		end
	end

	self.Background:SetAlpha(alpha);
	self.Fill:SetAlpha(alpha);
	self.FillScroll1:SetAlpha(alpha);
	if not self.isCurved then
		self.FillScroll2:SetAlpha(alpha);
	end
end

function PowerDependencyLineMixin:OnReleased()
	self.animType = nil;
	self:SetAlpha(0.0);
end
]] },
{ 'Blizzard_FrameXMLBase\\FlowContainer.lua', [[
function FlowContainer_Initialize(container)
	FlowContainer_RemoveAllObjects(container);

	--Default orientation to horizontal for now.
	FlowContainer_SetOrientation(container, "horizontal");

	--So far, we haven't actually used any space.
	container.flowMaxPrimaryUsed = 0;
	container.flowMaxSecondaryUsed = 0;
end

function FlowContainer_PauseUpdates(container)
	container.flowPauseUpdates = true;
end

function FlowContainer_ResumeUpdates(container)
	container.flowPauseUpdates = false;
	FlowContainer_DoLayout(container);
end

function FlowContainer_SetOrientation(container, orientation)	--"vertical" or "horizontal". This is the direction it tries to fill first.
	container.flowOrientation = orientation;
	FlowContainer_DoLayout(container);
end

function FlowContainer_SetMaxPerLine(container, maxPerLine)	--nil means we fit as much as possible.
	container.flowMaxPerLine = maxPerLine;
	FlowContainer_DoLayout(container);
end

function FlowContainer_SetHorizontalSpacing(container, horizontalSpacing)
	container.flowHorizontalSpacing = horizontalSpacing;
	FlowContainer_DoLayout(container);
end

function FlowContainer_SetVerticalSpacing(container, verticalSpacing)
	container.flowVerticalSpacing = verticalSpacing;
	FlowContainer_DoLayout(container);
end

function FlowContainer_AddObject(container, object)
	tinsert(container.flowFrames, object);	--Do we want to let people choose where it will appear?
	tinsert(container.flowFrameTypes, "object");
	FlowContainer_DoLayout(container);
end

function FlowContainer_AddLineBreak(container)
	tinsert(container.flowFrames, "linebreak");
	tinsert(container.flowFrameTypes, "linebreak");
	FlowContainer_DoLayout(container);
end

function FlowContainer_AddSpacer(container, spacerSize)
	tinsert(container.flowFrames, spacerSize);
	tinsert(container.flowFrameTypes, "spacer");
	FlowContainer_DoLayout(container);
end

function FlowContainer_AddPrimarySpacer(container, spacerSize)
	tinsert(container.flowFrames, spacerSize);
	tinsert(container.flowFrameTypes, "primarySpacer");
	FlowContainer_DoLayout(container);
end

function FlowContainer_BeginAtomicAdd(container)
	tinsert(container.flowFrames, "beginatomic");
	tinsert(container.flowFrameTypes, "beginatomic");
	FlowContainer_DoLayout(container);
end

function FlowContainer_EndAtomicAdd(container)
	tinsert(container.flowFrames, "endatomic");
	tinsert(container.flowFrameTypes, "endatomic");
	FlowContainer_DoLayout(container);
end

function FlowContainer_RemoveObject(container, object)
	assert(type(object) == "table");	--For now, Remove can't be used with non-widgets.
	for i=1, #container.flowFrames do	--Used instead of tRemoveItem to eliminate dependencies.
		if ( container.flowFrames[i] == object ) then
			tremove(container.flowFrames, i);
			tremove(container.flowFrameTypes, i);
			break;
		end
	end
	FlowContainer_DoLayout(container);
end

function FlowContainer_RemoveAllObjects(container)
	container.flowFrames = {};
	container.flowFrameTypes = {};
end

function FlowContainer_GetUsedBounds(container)	--Return x, y
	if ( container.flowOrientation == "horizontal" ) then
		return container.flowMaxSecondaryUsed, container.flowMaxPrimaryUsed;
	else
		return container.flowMaxPrimaryUsed, container.flowMaxSecondaryUsed;
	end
end

function FlowContainer_SetStartingOffset(container, xOffset, yOffset)
	if ( container.flowOrientation == "horizontal" ) then
		container.startingSecondaryOffset = xOffset;
		container.startingPrimaryOffset = -yOffset;
	else
		container.startingSecondaryOffset = -yOffset;
		container.startingPrimaryOffset = xOffset;
	end
end

local function isFrameTypeExemptFromFlowCount(frameType)
	return frameType == "flagged" or frameType == "target";
end

local function GetStartingPrimaryOffset(container)
	return (container.startingPrimaryOffset or 0);
end

local function GetStartingSecondaryOffset(container)
	return (container.startingSecondaryOffset or 0);
end

--:GetWidth() and :GetHeight() are used in this function. --meta-comment: Comment added in case anyone ever searches all files for these.
function FlowContainer_DoLayout(container)
	if ( container.flowPauseUpdates ) then
		return;
	end

	local primaryDirection, secondaryDirection;
	local primarySpacing, secondarySpacing;
	if ( container.flowOrientation == "horizontal" ) then
		primaryDirection = "GetWidth";
		secondaryDirection = "GetHeight";
		primarySpacing = container.flowHorizontalSpacing or 0;
		secondarySpacing = container.flowVerticalSpacing or 0;
	else
		primaryDirection = "GetHeight";
		secondaryDirection = "GetWidth";
		primarySpacing = container.flowVerticalSpacing or 0;
		secondarySpacing = container.flowHorizontalSpacing or 0;
	end

	--To make things easier to understand, I'll comment this as if it was horizontal. To see the vertical comments, just turn your head 90 degrees.
	local currentSecondaryLine, currentPrimaryLine = 1, 1;
	local currentSecondaryOffset, currentPrimaryOffset = GetStartingSecondaryOffset(container), GetStartingPrimaryOffset(container);
	local lineMaxSize = 0;
	local maxSecondaryOffset = 0;
	local atomicAddStart = nil;
	local atomicAtBeginning = nil;
	local i = 1;
	local targetVerticalOffset = nil;
	local lastObject = nil;
	local lastObjectType = nil;
	while ( i <= #container.flowFrames ) do
		local object = container.flowFrames[i];
		local objectType = container.flowFrameTypes[i];
		local doContinue = false;

		--If it doesn't fit on the current row, move to the next.
		if ( objectType == "linebreak" or	--Force a new line
			objectType == "object" and	--Make sure this is an actual object before checking further.
				(object.isFlowGroup or -- Always break if object is a group
				(lastObject and lastObjectType == "object" and lastObject.isFlowGroup) or -- Always break if the last object was a group
				(container.flowMaxPerLine and currentPrimaryLine > container.flowMaxPerLine) or	--We went past the max number of columns
					currentSecondaryOffset + object[primaryDirection](object) > container[primaryDirection](container)) ) then	--We went past the max pixel width.

				if ( not (atomicAddStart and atomicAtBeginning) ) then	--If we're in an atomic add and we started at the beginning of the line, wrapping won't help us
					currentSecondaryOffset = GetStartingSecondaryOffset(container);	--Move back all the way to the left
					currentPrimaryLine = 1;	--Reset column count
					currentPrimaryOffset = currentPrimaryOffset + lineMaxSize + secondarySpacing;	--Move down by the size of the biggest object in the last row
					currentSecondaryLine = currentSecondaryLine + 1;	--Move to the next row.
					lineMaxSize = 0;
					if ( atomicAddStart ) then
						--We wrapped around. So we want to move back to the first item in the atomic add and continue from the position we're leaving off (the new line).
						i = atomicAddStart;
						atomicAtBeginning = true;
						doContinue = true;
					end
				end
		end

		if ( not doContinue ) then
			if ( objectType == "object" ) then
				--Did we completely run out of room? Assert for now. --Scratch that, we're just going to keep growing. When we have time, we'll probably want a "didn't fit" callback.
				--assert(currentPrimaryOffset + object[secondaryDirection](object) < container[secondaryDirection](container));

				--Add it.
				object:ClearAllPoints();
				if container.flowOrientation == "horizontal" then
					object:SetPoint("TOPLEFT", container, "TOPLEFT", currentSecondaryOffset, -currentPrimaryOffset - (targetVerticalOffset or 0));

					if object.frameType == "target" and not targetVerticalOffset then
						targetVerticalOffset = object[secondaryDirection](object);
					else
						targetVerticalOffset = nil;
					end
				else
					object:SetPoint("TOPLEFT", container, "TOPLEFT", currentPrimaryOffset, -currentSecondaryOffset);
				end

				if not targetVerticalOffset then
					currentSecondaryOffset = currentSecondaryOffset + object[primaryDirection](object) + primarySpacing;
				end

				if ( not atomicAddStart ) then	--If we're in the middle of an atomic add, we'll save off the last part when we finish the add.
					maxSecondaryOffset = max(maxSecondaryOffset, currentSecondaryOffset);
				end

				if not isFrameTypeExemptFromFlowCount(object.frameType) then
					currentPrimaryLine = currentPrimaryLine + 1;
				end

				lineMaxSize = max(lineMaxSize, object[secondaryDirection](object));
			elseif ( objectType == "spacer" ) then
				currentSecondaryOffset = currentSecondaryOffset + object;
			elseif ( objectType == "primarySpacer" ) then
				currentPrimaryOffset = currentPrimaryOffset + object;
			elseif ( objectType == "beginatomic" ) then
				if ( currentSecondaryOffset == 0 ) then
					atomicAtBeginning = true;		--If we're already at the top, we don't want to move anything to the next row. (There's no way it would help.)
				end
				atomicAddStart = i + 1;
			elseif ( objectType == "endatomic" ) then
				maxSecondaryOffset = max(maxSecondaryOffset, currentSecondaryOffset);	--We weren't updating the max offset while in an atomic add, so we have to do it now.
				atomicAddStart = nil;
				atomicAtBeginning = nil;
			end

			i = i + 1;
		end

		lastObject = object;
		lastObjectType = objectType;
	end

	--Save off how much we actually used.
	container.flowMaxPrimaryUsed = currentPrimaryOffset + lineMaxSize;
	container.flowMaxSecondaryUsed = maxSecondaryOffset;
end
]] },
{ 'Blizzard_FrameXMLBase\\PlayerMovementFrameFader.lua', [[
local FrameFaderDriver;
local fadingFrames;
local deferredFadingFrames;

local function OnUpdate(self, elapsed)
	local isMoving = IsPlayerMoving();
	for frame, setting in pairs(fadingFrames) do
		local fadeOut = isMoving and (not setting.fadePredicate or setting.fadePredicate());
		frame:SetAlpha(DeltaLerp(frame:GetAlpha(), fadeOut and setting.minAlpha or setting.maxAlpha, .1, elapsed));
	end
end

local function MergeDeferredEvents()
	if deferredFadingFrames then
		for frame, setting in pairs(deferredFadingFrames) do
			fadingFrames[frame] = setting;
		end
		deferredFadingFrames = nil;
	end
end

local function OnEvent(self, event, ...)
	if event == "PLAYER_STARTED_MOVING" 
	or event == "PLAYER_STOPPED_MOVING" 
	or event == "PLAYER_IS_GLIDING_CHANGED" 
	or event == "PLAYER_IMPULSE_APPLIED" then
		MergeDeferredEvents();
	end
end

local function InitializeDriver()
	if not FrameFaderDriver then
		fadingFrames = {};

		FrameFaderDriver = CreateFrame("FRAME");
		FrameFaderDriver:SetScript("OnUpdate", OnUpdate);
		FrameFaderDriver:SetScript("OnEvent", OnEvent);
		FrameFaderDriver:RegisterEvent("PLAYER_STARTED_MOVING");
		FrameFaderDriver:RegisterEvent("PLAYER_STOPPED_MOVING");
		FrameFaderDriver:RegisterEvent("PLAYER_IS_GLIDING_CHANGED");
		FrameFaderDriver:RegisterEvent("PLAYER_IMPULSE_APPLIED");
	end
end

local function PackFadeData(minAlpha, maxAlpha, durationSec, fadePredicate)
	return { minAlpha = minAlpha or .5, maxAlpha = maxAlpha or 1, durationSec = durationSec or 1, fadePredicate = fadePredicate };
end

local function RemoveFrameInternal(frame)
	if fadingFrames then
		fadingFrames[frame] = nil;
	end
	if deferredFadingFrames then
		deferredFadingFrames[frame] = nil;
	end
end

PlayerMovementFrameFader = {};

function PlayerMovementFrameFader.AddFrame(frame, minAlpha, maxAlpha, durationSec, fadePredicate)
	RemoveFrameInternal(frame);

	InitializeDriver();
	fadingFrames[frame] = PackFadeData(minAlpha, maxAlpha, durationSec, fadePredicate);
end

-- The fading won't take effect until the player stops or starts moving again
function PlayerMovementFrameFader.AddDeferredFrame(frame, minAlpha, maxAlpha, durationSec, fadePredicate)
	InitializeDriver();
	RemoveFrameInternal(frame);

	if not deferredFadingFrames then
		deferredFadingFrames = {};
	end
	deferredFadingFrames[frame] = PackFadeData(minAlpha, maxAlpha, durationSec, fadePredicate);
end

function PlayerMovementFrameFader.RemoveFrame(frame)
	local maxAlpha = fadingFrames and fadingFrames[frame] and fadingFrames[frame].maxAlpha;
	if maxAlpha then
		frame:SetAlpha(maxAlpha);
	end

	RemoveFrameInternal(frame, restoreAlpha);
end]] },
