function QuestUtils_GetQuestName(questID)
	-- TODO: Make unified API for this?
	return C_TaskQuest.GetQuestInfoByQuestID(questID) or C_QuestLog.GetTitleForQuestID(questID) or "";
end

local function ShouldShowWarModeBonus(questID, currencyID, firstInstance)
	if not C_PvP.IsWarModeDesired() then
		return false;
	end

	local warModeBonusApplies, limitOncePerTooltip = C_CurrencyInfo.DoesWarModeBonusApply(currencyID);
	if not warModeBonusApplies or (limitOncePerTooltip and not firstInstance) then
		return false;
	end

	return QuestUtils_IsQuestWorldQuest(questID) and C_QuestLog.QuestCanHaveWarModeBonus(questID) and not C_CurrencyInfo.GetFactionGrantedByCurrency(currencyID);
end

function QuestUtils_GetQuestDecorationLink(linkType, questID, icon, width, height)
	return ("|H%s:%d|h%s|h"):format(linkType, questID, CreateAtlasMarkup(icon, width, height));
end

function QuestUtils_GetReplayQuestDecoration(questID, useLargeIcon)
	local linkType = "questReplay";

	if useLargeIcon then
		return QuestUtils_GetQuestDecorationLink(linkType, questID, "QuestSharing-ReplayIcon", 18, 16);
	else
		return QuestUtils_GetQuestDecorationLink(linkType, questID, "QuestSharing-QuestLog-Replay", 19, 16);
	end
end

function QuestUtils_GetDisabledQuestDecoration(questID, useLargeIcon)
	local linkType = "questDisabled";
	if useLargeIcon then
		return QuestUtils_GetQuestDecorationLink(linkType, questID, "QuestSharing-QuestDetails-Padlock", 10, 10);
	else
		return QuestUtils_GetQuestDecorationLink(linkType, questID, "QuestSharing-QuestDetails-Padlock", 20, 20);
	end
end

-- TODO: Replace booleans with flags?
function QuestUtils_DecorateQuestText(questID, text, useLargeIcon, ignoreReplayable, ignoreDisabled, ignoreTypes)
	if not text then
		return "";
	end

	local output = "";
	if not ignoreReplayable and C_QuestLog.IsQuestReplayable(questID) then
		output = QuestUtils_GetReplayQuestDecoration(questID, useLargeIcon);
	elseif not ignoreDisabled and C_QuestLog.IsQuestDisabledForSession(questID) then
		output = QuestUtils_GetDisabledQuestDecoration(questID, useLargeIcon);
	end

	if not ignoreTypes then
		local textureSize = 14;
		local tagID, tagText, tagAtlas = QuestUtil.GetQuestTypeDetails(questID);
		if tagID == Enum.QuestTag.Dungeon or tagID == Enum.QuestTag.Raid or tagID == Enum.QuestTag.Raid10 or tagID == Enum.QuestTag.Raid25 then
			local link = QuestUtils_GetQuestDecorationLink(tagText, questID, tagAtlas, textureSize, textureSize);
			output = output .. link.. " ";
		else
			local skipFormatting = true;
			local classification, classificationText, classificationAtlas, _size = QuestUtil.GetQuestClassificationDetails(questID, skipFormatting);
			if classification and classification ~= Enum.QuestClassification.Normal then
				if classification == Enum.QuestClassification.Campaign then
					-- deembiggen campaign atlas
					textureSize = 11;
				end
				local link = QuestUtils_GetQuestDecorationLink(classificationText, questID, classificationAtlas, textureSize, textureSize);
				output = output .. link.. " ";
			end
		end
	end

	return output .. text;
end



function QuestUtils_AddQuestRewardsToTooltip(tooltip, questID, style, context)
	local hasAnySingleLineRewards = false;
	local isWarModeDesired = C_PvP.IsWarModeDesired();
	local questHasWarModeBonus = C_QuestLog.QuestCanHaveWarModeBonus(questID);

	-- xp
	local totalXp, baseXp = GetQuestLogRewardXP(questID);
	if ( baseXp > 0 ) then
		GameTooltip_AddColoredLine(tooltip, BONUS_OBJECTIVE_EXPERIENCE_FORMAT:format(baseXp), HIGHLIGHT_FONT_COLOR);
		if (isWarModeDesired and questHasWarModeBonus) then
			tooltip:AddLine(WAR_MODE_BONUS_PERCENTAGE_XP_FORMAT:format(C_PvP.GetWarModeRewardBonus()));
		end
		hasAnySingleLineRewards = true;
	end
	local artifactXP = GetQuestLogRewardArtifactXP(questID);
	if ( artifactXP > 0 ) then
		GameTooltip_AddColoredLine(tooltip, BONUS_OBJECTIVE_ARTIFACT_XP_FORMAT:format(artifactXP), HIGHLIGHT_FONT_COLOR);
		hasAnySingleLineRewards = true;
	end

	-- favor
	local favor = C_QuestInfoSystem.GetQuestLogRewardFavor(questID, style.clampFavorToCycleCap);
	if ( favor > 0 ) then
		local initiativeTaskID = context and context.initiativeTaskID;
		if initiativeTaskID then
			favor = C_NeighborhoodInitiative.GetInitiativeTaskRewardScaling(initiativeTaskID, favor);
		end
		GameTooltip_AddColoredLine(tooltip, BONUS_OBJECTIVE_HOUSING_FAVOR_FORMAT:format(favor, HOUSING_DASHBOARD_REWARD_ESTATE_XP), HIGHLIGHT_FONT_COLOR);
		hasAnySingleLineRewards = true;
	end

	-- currency
	local mainRewardIsFirstTimeReputationBonus = false;
	local secondaryRewardsContainFirstTimeRepBonus = false;
	if not style.atLeastShowAzerite then
		local numAddedQuestCurrencies, usingCurrencyContainer, primaryCurrencyRewardInfo = QuestUtils_AddQuestCurrencyRewardsToTooltip(questID, tooltip, tooltip.ItemTooltip, context);
		if ( numAddedQuestCurrencies > 0 ) then
			hasAnySingleLineRewards = not usingCurrencyContainer or numAddedQuestCurrencies > 1;
		end

		if primaryCurrencyRewardInfo then
			local isFirstTimeReward = primaryCurrencyRewardInfo.questRewardContextFlags and FlagsUtil.IsSet(primaryCurrencyRewardInfo.questRewardContextFlags, Enum.QuestRewardContextFlags.FirstCompletionBonus);
			mainRewardIsFirstTimeReputationBonus = isFirstTimeReward and (C_CurrencyInfo.GetFactionGrantedByCurrency(primaryCurrencyRewardInfo.currencyID) ~= nil) or false;
		elseif C_QuestLog.QuestContainsFirstTimeRepBonusForPlayer(questID) then
			secondaryRewardsContainFirstTimeRepBonus = true;
		end
	end

	-- honor
	local honorAmount = GetQuestLogRewardHonor(questID);
	if ( honorAmount > 0 ) then
		GameTooltip_AddColoredLine(tooltip, BONUS_OBJECTIVE_REWARD_WITH_COUNT_FORMAT:format("Interface\\ICONS\\Achievement_LegionPVPTier4", honorAmount, HONOR), HIGHLIGHT_FONT_COLOR);
		hasAnySingleLineRewards = true;
	end

	-- money
	local money = GetQuestLogRewardMoney(questID);
	if ( money > 0 ) then
		GameTooltip_AddMoneyLine(tooltip, money);
		if (isWarModeDesired and QuestUtils_IsQuestWorldQuest(questID) and questHasWarModeBonus) then
			tooltip:AddLine(WAR_MODE_BONUS_PERCENTAGE_FORMAT:format(C_PvP.GetWarModeRewardBonus()));
		end
		hasAnySingleLineRewards = true;
	end

	-- items
	local showRetrievingData = false;
	local numQuestRewards = GetNumQuestLogRewards(questID);
	if numQuestRewards > 0 and (not style.prioritizeCurrencyOverItem or C_QuestInfoSystem.HasQuestRewardCurrencies(questID)) then
		if style.fullItemDescription then
			-- we want to do a full item description
			local itemIndex, rewardType = QuestUtils_GetBestQualityItemRewardIndex(questID);  -- Only support one item reward currently
			if not EmbeddedItemTooltip_SetItemByQuestReward(tooltip.ItemTooltip, itemIndex, questID, rewardType, style.showCollectionText) then
				showRetrievingData = true;
			end
			-- check for item compare input of flag
			if not showRetrievingData then
				if TooltipUtil.ShouldDoItemComparison(tooltip.ItemTooltip.Tooltip) then
					GameTooltip_ShowCompareItem(tooltip.ItemTooltip.Tooltip, tooltip.BackdropFrame);
				else
					for i, shoppingTooltip in ipairs(tooltip.ItemTooltip.Tooltip.shoppingTooltips) do
						shoppingTooltip:Hide();
					end
				end
			end
		else
			-- we want to do an abbreviated item description
			local name, texture, numItems, quality, isUsable = GetQuestLogRewardInfo(1, questID);
			local text;
			if numItems > 1 then
				text = string.format(BONUS_OBJECTIVE_REWARD_WITH_COUNT_FORMAT, texture, HIGHLIGHT_FONT_COLOR:WrapTextInColorCode(numItems), name);
			elseif texture and name then
				text = string.format(BONUS_OBJECTIVE_REWARD_FORMAT, texture, name);
			end
			if text then
				local colorData = ColorManager.GetColorDataForItemQuality(quality);
				if colorData then
					tooltip:AddLine(text, colorData.r, colorData.g, colorData.b);
				else
					tooltip:AddLine(text);
				end
			end
		end
	end

	-- spells
	if not tooltip.ItemTooltip:IsShown() and EmbeddedItemTooltip_SetSpellByFirstQuestReward(tooltip.ItemTooltip, questID) then
		showRetrievingData = true;
	end

	-- atLeastShowAzerite: show azerite if nothing else is awarded
	-- and in the case of double azerite, only show the currency container one
	if style.atLeastShowAzerite and not hasAnySingleLineRewards and not tooltip.ItemTooltip:IsShown() then
		local numAddedQuestCurrencies, usingCurrencyContainer = QuestUtils_AddQuestCurrencyRewardsToTooltip(questID, tooltip, tooltip.ItemTooltip);
		if ( numAddedQuestCurrencies > 0 ) then
			hasAnySingleLineRewards = not usingCurrencyContainer or numAddedQuestCurrencies > 1;
			if usingCurrencyContainer and numAddedQuestCurrencies > 1 then
				EmbeddedItemTooltip_Clear(tooltip.ItemTooltip);
				EmbeddedItemTooltip_Hide(tooltip.ItemTooltip);
				tooltip:Show();
			end
		end
	end

	if style.showFirstTimeRepRewardNotice and (mainRewardIsFirstTimeReputationBonus or secondaryRewardsContainFirstTimeRepBonus) then
		local bestTooltipForLine = tooltip.ItemTooltip:IsShown() and tooltip.ItemTooltip.Tooltip or tooltip;
		GameTooltip_AddBlankLineToTooltip(bestTooltipForLine);

		local wrapText = false;
		local noticeText = mainRewardIsFirstTimeReputationBonus and QUEST_REWARDS_IS_ONE_TIME_REP_BONUS or QUEST_REWARDS_CONTAINS_ONE_TIME_REP_BONUS;
		GameTooltip_AddColoredLine(bestTooltipForLine, noticeText, QUEST_REWARD_CONTEXT_FONT_COLOR, wrapText);

		if bestTooltipForLine == tooltip.ItemTooltip.Tooltip then
			tooltip.ItemTooltip.Tooltip:Show();
		end
	end

	return hasAnySingleLineRewards, showRetrievingData;
end

--currencyContainerTooltip should be an InternalEmbeddedItemTooltipTemplate
function QuestUtils_AddQuestCurrencyRewardsToTooltip(questID, tooltip, currencyContainerTooltip, context)
	local currencies = { };
	local uniqueCurrencyIDs = { };
	local currencyRewards = C_QuestLog.GetQuestRewardCurrencies(questID);
	for index, currencyReward in ipairs(currencyRewards) do
		local rarity = C_CurrencyInfo.GetCurrencyInfo(currencyReward.currencyID).quality;
		local firstInstance = not uniqueCurrencyIDs[currencyReward.currencyID];
		if firstInstance then
			uniqueCurrencyIDs[currencyReward.currencyID] = true;
		end
		local currencyInfo = { name = currencyReward.name,
							   texture = currencyReward.texture,
							   numItems = currencyReward.totalRewardAmount,
							   currencyID = currencyReward.currencyID,
							   questRewardContextFlags = currencyReward.questRewardContextFlags,
							   rarity = rarity,
							   firstInstance = firstInstance,
							};
		if(currencyInfo.currencyID ~= ECHOS_OF_NYLOTHA_CURRENCY_ID or #currencyRewards == 1) then
			tinsert(currencies, currencyInfo);
		end
	end

	table.sort(currencies,
		function(currency1, currency2)
			if currency1.rarity ~= currency2.rarity then
				return currency1.rarity > currency2.rarity;
			end
			return currency1.currencyID > currency2.currencyID;
		end
	);

	local addedQuestCurrencies = 0;
	local alreadyUsedCurrencyContainerId = 0; --In the case of multiple currency containers needing to displayed, we only display the first.
	local alreadyUsedCurrencyContainerInfo = nil;  --In the case of multiple currency containers needing to displayed, we only display the first.
	local warModeBonus = C_PvP.GetWarModeRewardBonus();
	local initiativeTaskID = context and context.initiativeTaskID;

	for i, currencyInfo in ipairs(currencies) do
		local numItems = currencyInfo.numItems;
		if initiativeTaskID then
			numItems = C_NeighborhoodInitiative.GetInitiativeTaskRewardScaling(initiativeTaskID, numItems);
		end
		local isCurrencyContainer = C_CurrencyInfo.IsCurrencyContainer(currencyInfo.currencyID, numItems);
		if ( currencyContainerTooltip and isCurrencyContainer and (alreadyUsedCurrencyContainerId == 0) ) then
			if ( EmbeddedItemTooltip_SetCurrencyByID(currencyContainerTooltip, currencyInfo.currencyID, numItems) ) then
				if ShouldShowWarModeBonus(questID, currencyInfo.currencyID, currencyInfo.firstInstance) then
					currencyContainerTooltip.Tooltip:AddLine(WAR_MODE_BONUS_PERCENTAGE_FORMAT:format(warModeBonus));
					currencyContainerTooltip.Tooltip:Show();
				end

				if ( not tooltip ) then
					break;
				end

				addedQuestCurrencies = addedQuestCurrencies + 1;
				alreadyUsedCurrencyContainerId = currencyInfo.currencyID;
				alreadyUsedCurrencyContainerInfo = currencyInfo;
			end
		elseif ( tooltip ) then
			if( alreadyUsedCurrencyContainerId ~= currencyInfo.currencyID ) then --if there's already a currency container of this same type skip it entirely
				if isCurrencyContainer then
					local name, texture, quantity, quality = CurrencyContainerUtil.GetCurrencyContainerInfo(currencyInfo.currencyID, numItems);
					local text = BONUS_OBJECTIVE_REWARD_FORMAT:format(texture, name);

					local colorData = ColorManager.GetColorDataForItemQuality(quality);
					if colorData then
						tooltip:AddLine(text, colorData.r, colorData.g, colorData.b);
					else
						tooltip:AddLine(text);
					end
				else
					local text = BONUS_OBJECTIVE_REWARD_WITH_COUNT_FORMAT:format(currencyInfo.texture, numItems, currencyInfo.name);
					local currencyColor = GetColorForCurrencyReward(currencyInfo.currencyID, numItems);
					tooltip:AddLine(text, currencyColor:GetRGB());
				end

				if ShouldShowWarModeBonus(questID, currencyInfo.currencyID, currencyInfo.firstInstance) then
					tooltip:AddLine(WAR_MODE_BONUS_PERCENTAGE_FORMAT:format(warModeBonus));
				end

				addedQuestCurrencies = addedQuestCurrencies + 1;
			end
		end
	end
	return addedQuestCurrencies, alreadyUsedCurrencyContainerId > 0, alreadyUsedCurrencyContainerInfo;
end

function QuestUtils_GetCurrentQuestLineQuest(questLineID)
	local quests = C_QuestLine.GetQuestLineQuests(questLineID);
	local currentQuestID = 0;
	for i, questID in ipairs(quests) do
		if C_QuestLog.IsOnQuest(questID) then
			currentQuestID = questID;
			break;
		end
	end
	return currentQuestID;
end

function QuestUtils_GetQuestLogRewardInfo(itemIndex, questID, rewardType)
	if rewardType == "choice" then
		return GetQuestLogChoiceInfo(itemIndex, questID);
	else
		return GetQuestLogRewardInfo(itemIndex, questID);
	end
end

function QuestUtils_GetBestQualityItemRewardIndex(questID)
	local index, rewardType;
	local bestQuality = -1;
	local numQuestRewards = GetNumQuestLogRewards(questID);
	for i = 1, numQuestRewards do
		local itemName, itemTexture, quantity, quality, isUsable, itemID = GetQuestLogRewardInfo(i, questID);
		if quality > bestQuality then
			index = i;
			bestQuality = quality;
			rewardType = "reward";
		end
	end
	local numQuestChoices = GetNumQuestLogChoices(questID);
	for i = 1, numQuestChoices do
		local itemName, itemTexture, quantity, quality, isUsable, itemID = GetQuestLogChoiceInfo(i, questID);
		if quality > bestQuality then
			index = i;
			bestQuality = quality;
			rewardType = "choice";
		end
	end
	return index, rewardType;
end

function QuestUtils_IsQuestWithinTimeThreshold(questID, threshold)
	local secondsRemaining = C_TaskQuest.GetQuestTimeLeftSeconds(questID);
	return secondsRemaining and secondsRemaining <= threshold or false;
end

function QuestUtils_IsQuestWithinLowTimeThreshold(questID)
	return QuestUtils_IsQuestWithinTimeThreshold(questID, MinutesToSeconds(WORLD_QUESTS_TIME_LOW_MINUTES));
end

function QuestUtils_IsQuestWithinCriticalTimeThreshold(questID)
	return QuestUtils_IsQuestWithinTimeThreshold(questID, MinutesToSeconds(WORLD_QUESTS_TIME_CRITICAL_MINUTES));
end

function QuestUtils_GetQuestTimeColor(secondsRemaining)
	local isWithinCriticalTime = secondsRemaining <= MinutesToSeconds(WORLD_QUESTS_TIME_CRITICAL_MINUTES);
	return isWithinCriticalTime and RED_FONT_COLOR or HIGHLIGHT_FONT_COLOR;
end

function QuestUtils_ShouldDisplayExpirationWarning(questID)
	local info = C_QuestLog.GetQuestTagInfo(questID);
	return not info or info.displayExpiration;
end

function QuestUtils_GetNumPartyMembersOnQuest(questID)
	local count = 0;
	for i = 1, GetNumSubgroupMembers() do
		if C_QuestLog.IsUnitOnQuest("party"..i, questID) then
			count = count + 1;
		end
	end

	return count;
end

function QuestUtils_IsQuestWatched(questID)
	return questID and C_QuestLog.GetQuestWatchType(questID) ~= nil;
end

]] },
{ 'Blizzard_FrameXMLUtil\\AchievementUtil.lua', [[

AchievementUtil = {};

local CRITERIA_TYPE_ACHIEVEMENT_EARNED = 8;
local CRITERIA_TYPE_REPUTATION_GAINED = 46;
local COUNT_HIDDEN_CRITERIA = true;

function AchievementUtil.IsCriteriaAchievementEarned(achievementID, criteriaIndex)
	local criteriaString, criteriaType, completed, quantity, reqQuantity, charName, flags, assetID, quantityString = GetAchievementCriteriaInfo(achievementID, criteriaIndex);
	return criteriaType == CRITERIA_TYPE_ACHIEVEMENT_EARNED;
end

function AchievementUtil.IsCriteriaReputationGained(achievementID, criteriaIndex, checkCriteriaAchievement, countHiddenCriteria)
	local criteriaString, criteriaType, completed, quantity, reqQuantity, charName, flags, assetID, quantityString = GetAchievementCriteriaInfo(achievementID, criteriaIndex, countHiddenCriteria);
	if criteriaType == CRITERIA_TYPE_REPUTATION_GAINED then
		return true;
	end
	if checkCriteriaAchievement and criteriaType == CRITERIA_TYPE_ACHIEVEMENT_EARNED then
		local numCriteria = GetAchievementNumCriteria(assetID, COUNT_HIDDEN_CRITERIA);
		for i = 1, numCriteria do
			if AchievementUtil.IsCriteriaReputationGained(assetID, i, checkCriteriaAchievement, COUNT_HIDDEN_CRITERIA) then
				return true;
			end
		end
	end
	return false;
end

local FEAT_OF_STRENGTH_ID = 81;
local GUILD_FEAT_OF_STRENGTH_ID = 15093;

function AchievementUtil.IsCategoryFeatOfStrength(category)
	if category == FEAT_OF_STRENGTH_ID or category == GUILD_FEAT_OF_STRENGTH_ID then
		return true;
	end

	local _, parentCategory = GetCategoryInfo(category);
	return parentCategory and AchievementUtil.IsCategoryFeatOfStrength(parentCategory) or false;
end

function AchievementUtil.IsFeatOfStrength(achievementID)
	local category = GetAchievementCategory(achievementID);
	return category and AchievementUtil.IsCategoryFeatOfStrength(category) or false;
end]] },
{ 'Blizzard_FrameXMLUtil\\Mainline\\MapUtil.lua', [[

local SHADOWLANDS_CONTINENT_MAP_ID = 1550;
local ORIBOS_UI_MAP_IDS = { 1670, 1671, 1672, 1673 };


MapUtil = {};

function MapUtil.IsMapTypeZone(mapID)
	local mapInfo = C_Map.GetMapInfo(mapID);
	return mapInfo and mapInfo.mapType == Enum.UIMapType.Zone;
end

function MapUtil.GetMapParentInfo(mapID, mapType, topMost)
	local candidate;
	local mapInfo = C_Map.GetMapInfo(mapID);
	while mapInfo do
		if ( mapInfo.mapType == mapType ) then
			if ( topMost ) then
				candidate = mapInfo;
			else
				return mapInfo;
			end
		end
		mapInfo = C_Map.GetMapInfo(mapInfo.parentMapID);
	end
	return candidate;
end

function MapUtil.ShouldMapTypeShowQuests(mapType)
	return mapType ~= Enum.UIMapType.World and mapType ~= Enum.UIMapType.Continent and mapType ~= Enum.UIMapType.Cosmic;
end

function MapUtil.ShouldShowTask(mapID, info)
	if (info.isQuestStart and info.inProgress) then
		return false
	end
	if not HaveQuestData(info.questID) then
		return false;
	end
	-- callings are allowed on other maps if they are zone maps 
	if C_QuestLog.IsQuestCalling(info.questID) and MapUtil.IsMapTypeZone(mapID) then
		return true;
	end
	return mapID == info.mapID;
end

function MapUtil.MapHasUnlockedBounties(mapID)
	local displayLocation, lockedQuestID, bountySetID = C_QuestLog.GetBountySetInfoForMapID(mapID);
	if displayLocation and (not lockedQuestID or not C_QuestLog.IsOnQuest(lockedQuestID)) then
		local bounties = C_QuestLog.GetBountiesForMapID(mapID);
		return bounties and #bounties > 0;
	end

	return false;
end

function MapUtil.MapHasEmissaries(mapID)
	local displayLocation, lockedQuestID, bountySetID = C_QuestLog.GetBountySetInfoForMapID(mapID);
	return displayLocation ~= nil;
end

function MapUtil.FindBestAreaNameAtMouse(mapID, normalizedCursorX, normalizedCursorY)
	local exploredAreaIDs = C_MapExplorationInfo.GetExploredAreaIDsAtPosition(mapID, CreateVector2D(normalizedCursorX, normalizedCursorY));
	if exploredAreaIDs then
		for i, areaID in ipairs(exploredAreaIDs) do
			local name = C_Map.GetAreaInfo(areaID);
			if name then
				return name;
			end
		end
	end
	return nil;
end

function MapUtil.GetDisplayableMapForPlayer()
	local mapID = C_Map.GetBestMapForUnit("player");
	if mapID then
		repeat
			if C_Map.MapHasArt(mapID) then
				return mapID;
			end
			local mapInfo = C_Map.GetMapInfo(mapID);
			mapID = mapInfo and mapInfo.parentMapID or 0;
		until mapID == 0;
	end
	return C_Map.GetFallbackWorldMapID();
end

function MapUtil.GetBountySetMaps(bountySetID)
	if not MapUtil.bountySetMaps then
		MapUtil.bountySetMaps = { };
	end
	local bountySetMaps = MapUtil.bountySetMaps[bountySetID];
	if not bountySetMaps then
		bountySetMaps = C_Map.GetBountySetMaps(bountySetID);
		MapUtil.bountySetMaps[bountySetID] = bountySetMaps;
	end
	return bountySetMaps;
end

function MapUtil.GetMapCenterOnMap(mapID, topMapID)
	local left, right, top, bottom = C_Map.GetMapRectOnMap(mapID, topMapID);
	if left == nil then
		return nil, nil;
	end

	local centerX = left + (right - left) * .5;
	local centerY = top + (bottom - top) * .5;
	return centerX, centerY;
end

function MapUtil.IsChildMap(mapID, ancestorMapID)
	local mapInfo = C_Map.GetMapInfo(mapID);
	while (mapInfo ~= nil) and (mapInfo.parentMapID ~= nil) do
		if mapInfo.parentMapID == ancestorMapID then
			return true;
		end

		mapInfo = C_Map.GetMapInfo(mapInfo.parentMapID);
	end

	return false;
end

local g_childMapCache = { };

function MapUtil.IsChildMapCached(mapID, ancestorMapID)
	local key = mapID * 100000 + ancestorMapID;
	local result = g_childMapCache[key];
	if result ~= nil then
		return result;
	end

	result = MapUtil.IsChildMap(mapID, ancestorMapID);
	g_childMapCache[key] = result;
	return result;
end

function MapUtil.IsOribosMap(mapID)
	return tContains(ORIBOS_UI_MAP_IDS, mapID);
end

function MapUtil.IsShadowlandsZoneMap(mapID)
	if mapID == SHADOWLANDS_CONTINENT_MAP_ID or MapUtil.IsOribosMap(mapID) then
		return true;
	end

	local mapInfo = C_Map.GetMapInfo(mapID);
	if (mapInfo.mapType ~= Enum.UIMapType.Zone) and (mapInfo.mapType ~= Enum.UIMapType.Continent) then
		return false;
	end

	return MapUtil.IsChildMap(mapID, SHADOWLANDS_CONTINENT_MAP_ID);
end

function MapUtil.MapShouldShowWorldQuestFilters(mapID)
	return MapUtil.MapHasEmissaries(mapID) or MapUtil.IsShadowlandsZoneMap(mapID);
end
]] },
{ 'Blizzard_FrameXMLUtil\\AzeriteUtil.lua', [[
AzeriteUtil = {};

do
	local function AzeriteEmpoweredItemIterator(_, equipSlotIndex)
		equipSlotIndex = equipSlotIndex + 1;

		if equipSlotIndex <= INVSLOT_LAST_EQUIPPED then
			local itemLocation = ItemLocation:CreateEmpty();
			while equipSlotIndex <= INVSLOT_LAST_EQUIPPED do
				itemLocation:SetEquipmentSlot(equipSlotIndex);

				if C_Item.DoesItemExist(itemLocation) and C_AzeriteEmpoweredItem.IsAzeriteEmpoweredItem(itemLocation) then
					return equipSlotIndex, itemLocation;
				end

				equipSlotIndex = equipSlotIndex + 1;
			end
		end
	end

	function AzeriteUtil.EnumerateEquipedAzeriteEmpoweredItems()
		return AzeriteEmpoweredItemIterator, nil, INVSLOT_FIRST_EQUIPPED - 1;
	end
end

function AzeriteUtil.AreAnyAzeriteEmpoweredItemsEquipped()
	for equipSlotIndex, itemLocation in AzeriteUtil.EnumerateEquipedAzeriteEmpoweredItems() do -- luacheck: ignore 512 (loop is executed at most once)
		return true;
	end
	return false;
end

function AzeriteUtil.DoEquippedItemsHaveUnselectedPowers()
	for equipSlotIndex, itemLocation in AzeriteUtil.EnumerateEquipedAzeriteEmpoweredItems() do
		if C_AzeriteEmpoweredItem.HasAnyUnselectedPowers(itemLocation) then
			return true;
		end
	end
	return false;
end

function AzeriteUtil.GetEquippedItemsUnselectedPowersCount()
	local count = 0; 
	for equipSlotIndex, itemLocation in AzeriteUtil.EnumerateEquipedAzeriteEmpoweredItems() do
		if C_AzeriteEmpoweredItem.HasAnyUnselectedPowers(itemLocation) then
			count = count + 1; 
		end
	end
	return count;
end

function AzeriteUtil.GenerateRequiredSpecTooltipLine(powerID)
	local specs = C_AzeriteEmpoweredItem.GetSpecsForPower(powerID);
	if not specs then
		return nil;
	end

	local playerSex = UnitSex("player");
	local _, _, playerClassID = UnitClass("player");
	local playerSpecID = C_SpecializationInfo.GetSpecializationInfo(C_SpecializationInfo.GetSpecialization());

	local validSpecs;
	for i, specInfo in ipairs(specs) do
		if specInfo.classID == playerClassID then
			if specInfo.specID == playerSpecID then
				return nil; -- Nothing to show, we match this spec
			end
			validSpecs = validSpecs or {};
			local _, specName = GetSpecializationInfoByID(specInfo.specID, playerSex);
			table.insert(validSpecs, specName);
		end
	end

	if not validSpecs then
		return nil;
	end

	if #validSpecs > 1 then
		return REQUIRES_OR_SPECIALIZATIONS:format(table.concat(validSpecs, PLAYER_LIST_DELIMITER, 1, #validSpecs - 1), validSpecs[#validSpecs]);
	end
	return REQUIRES_SPECIALIZATION:format(table.concat(validSpecs, PLAYER_LIST_DELIMITER));
end

function AzeriteUtil.FindAzeritePowerTier(azeriteEmpoweredItemSource, powerID)
	for tierIndex, tierInfo in ipairs(azeriteEmpoweredItemSource:GetAllTierInfo()) do
		for powerIndex, azeritePowerID in ipairs(tierInfo.azeritePowerIDs) do
			if powerID == azeritePowerID then
				return tierIndex;
			end
		end
	end

	return nil;
end

function AzeriteUtil.GetSelectedAzeritePowerInTier(azeriteEmpoweredItemSource, tierIndex)
	local allTierInfo = azeriteEmpoweredItemSource:GetAllTierInfo();
	local tierInfo = allTierInfo[tierIndex];
	if tierInfo then
		for powerIndex, azeritePowerID in ipairs(tierInfo.azeritePowerIDs) do
			if azeriteEmpoweredItemSource:IsPowerSelected(azeritePowerID) then
				return azeritePowerID;
			end
		end
	end

	return nil;
end

function AzeriteUtil.HasSelectedAnyAzeritePower(azeriteEmpoweredItemSource)
	local allTierInfo = azeriteEmpoweredItemSource:GetAllTierInfo();
	for tierIndex, tierInfo in ipairs(allTierInfo) do
		for powerIndex, azeritePowerID in ipairs(tierInfo.azeritePowerIDs) do
			if azeriteEmpoweredItemSource:IsPowerSelected(azeritePowerID) then
				return true;
			end
		end
	end

	return nil;
end

function AzeriteUtil.DoesBagContainAnyAzeriteEmpoweredItems(bagID)
	local itemLocation = ItemLocation:CreateEmpty();
	for slotIndex = 1, ContainerFrame_GetContainerNumSlots(bagID) do
		itemLocation:SetBagAndSlot(bagID, slotIndex);
		if C_Item.DoesItemExist(itemLocation) and C_AzeriteEmpoweredItem.IsAzeriteEmpoweredItem(itemLocation) then
			return true;
		end
	end

	return false;
end

function AzeriteUtil.IsAzeriteItemLocationBankTab(azeriteItemLocation)
	return azeriteItemLocation and azeriteItemLocation.bagID and azeriteItemLocation.bagID >= NUM_TOTAL_EQUIPPED_BAG_SLOTS;
end]] },
{ 'Blizzard_FrameXMLUtil\\AzeriteEssenceUtil.lua', [[
AzeriteEssenceUtil = {};

function AzeriteEssenceUtil.HasAnyUnlockableMilestones()
	if not C_AzeriteEssence.CanOpenUI() then
		return false;
	end

	local milestones = C_AzeriteEssence.GetMilestones();
	if milestones then
		for i, milestoneInfo in ipairs(milestones) do
			if milestoneInfo.canUnlock then
				local firstUnlockableIsSlot = milestoneInfo.slot and true or false;
				return true, firstUnlockableIsSlot;
			end
		end
	end
	return false, nil;
end

function AzeriteEssenceUtil.GetMilestoneAtPowerLevel(powerLevel)
	if not C_AzeriteEssence.CanOpenUI() then
		return nil;
	end

	local milestones = C_AzeriteEssence.GetMilestones();
	if milestones then
		for i, milestoneInfo in ipairs(milestones) do
			if milestoneInfo.requiredLevel == powerLevel then
				return milestoneInfo;
			end
			-- only supporting 1 ranked milestone
			if milestoneInfo.requiredLevel < powerLevel and milestoneInfo.rank then
				return milestoneInfo;
			end
		end
	end
	return nil;
end

function AzeriteEssenceUtil.GetMilestoneSpellInfo(milestoneID)
	local spellID = C_AzeriteEssence.GetMilestoneSpell(milestoneID);
	local spellInfo = C_Spell.GetSpellInfo(spellID);
	return spellInfo.name, spellInfo.iconID;
end]] },
{ 'Blizzard_FrameXMLUtil\\AuraUtil.lua', [[
DEFAULT_AURA_DURATION_FONT = "GameFontNormalSmall";
BUFF_DURATION_WARNING_TIME = 90;

local DEBUFF_DISPLAY_INFO = {
	["Magic"] = { color = DEBUFF_TYPE_MAGIC_COLOR, abbreviation = DEBUFF_SYMBOL_MAGIC, basicAtlas = "ui-debuff-border-magic-noicon", dispelAtlas = "ui-debuff-border-magic-icon", dispelIconAtlas = "RaidFrame-Icon-DebuffMagic" },
	["Curse"] = { color = DEBUFF_TYPE_CURSE_COLOR, abbreviation = DEBUFF_SYMBOL_CURSE, basicAtlas = "ui-debuff-border-curse-noicon", dispelAtlas = "ui-debuff-border-curse-icon", dispelIconAtlas = "RaidFrame-Icon-DebuffCurse" },
	["Disease"] = { color = DEBUFF_TYPE_DISEASE_COLOR, abbreviation = DEBUFF_SYMBOL_DISEASE, basicAtlas = "ui-debuff-border-disease-noicon", dispelAtlas = "ui-debuff-border-disease-icon", dispelIconAtlas = "RaidFrame-Icon-DebuffDisease" },
	["Poison"] = { color = DEBUFF_TYPE_POISON_COLOR, abbreviation = DEBUFF_SYMBOL_POISON, basicAtlas = "ui-debuff-border-poison-noicon", dispelAtlas = "ui-debuff-border-poison-icon", dispelIconAtlas = "RaidFrame-Icon-DebuffPoison" },
	["Bleed"] = { color = DEBUFF_TYPE_BLEED_COLOR, abbreviation = DEBUFF_SYMBOL_BLEED, basicAtlas = "ui-debuff-border-bleed-noicon", dispelAtlas = "ui-debuff-border-bleed-icon", dispelIconAtlas = "RaidFrame-Icon-DebuffBleed" },
	["None"] = { color = DEBUFF_TYPE_NONE_COLOR, abbreviation = "", basicAtlas = "ui-debuff-border-default-noicon" },
};

CVarCallbackRegistry:SetCVarCachable("showCastableBuffs");
CVarCallbackRegistry:SetCVarCachable("showDispelDebuffs");

AuraUtil = {};

local AuraUtilDataProvider = C_UnitAuras;
function AuraUtil.SetDataProvider(dataProvider)
	AuraUtilDataProvider = dataProvider;
end

function AuraUtil.ClearDataProvider()
	AuraUtil.SetDataProvider(C_UnitAuras);
end

local function CallDataProviderMethod(methodName, ...)
	return AuraUtilDataProvider[methodName](...);
end

function AuraUtil.GetAuraDataByAuraInstanceID(...)
	return CallDataProviderMethod("GetAuraDataByAuraInstanceID", ...);
end

function AuraUtil.GetUnitAuras(...)
	return CallDataProviderMethod("GetUnitAuras", ...);
end

-- For backwards compatibility with old APIs, this helper function returns aura data values unpacked in the same order as before.
function AuraUtil.UnpackAuraData(auraData)
	if not auraData then
		return nil;
	end

	return auraData.name,
		auraData.icon,
		auraData.applications,
		auraData.dispelName,
		auraData.duration,
		auraData.expirationTime,
		auraData.sourceUnit,
		auraData.isStealable,
		auraData.nameplateShowPersonal,
		auraData.spellId,
		auraData.canApplyAura,
		auraData.isBossAura,
		auraData.isFromPlayerOrPlayerPet,
		auraData.nameplateShowAll,
		auraData.timeMod,
		unpack(auraData.points);
end

local function FindAuraRecurse(predicate, unit, filter, auraIndex, predicateArg1, predicateArg2, predicateArg3, ...)
	if ... == nil then
		return nil; -- Not found
	end
	if predicate(predicateArg1, predicateArg2, predicateArg3, ...) then
		return ...;
	end
	auraIndex = auraIndex + 1;
	return FindAuraRecurse(predicate, unit, filter, auraIndex, predicateArg1, predicateArg2, predicateArg3, AuraUtil.UnpackAuraData(CallDataProviderMethod("GetAuraDataByIndex", unit, auraIndex, filter)));
end

-- Find an aura by any predicate, you can pass in up to 3 predicate specific parameters
-- The predicate will also receive all aura params, if the aura data matches return true
function AuraUtil.FindAura(predicate, unit, filter, predicateArg1, predicateArg2, predicateArg3)
	local auraIndex = 1;
	return FindAuraRecurse(predicate, unit, filter, auraIndex, predicateArg1, predicateArg2, predicateArg3, AuraUtil.UnpackAuraData(CallDataProviderMethod("GetAuraDataByIndex", unit, auraIndex, filter)));
end

-- Finds the first aura that matches the name
-- Notes:
--		aura names are not unique!
--		aura names are localized, what works in one locale might not work in another
--			consider that in English two auras might have different names, but once localized they have the same name, so even using the localized aura name in a search it could result in different behavior
--		the unit could have multiple auras with the same name, this will only find the first
function AuraUtil.FindAuraByName(auraName, unit, filter)
	return AuraUtil.UnpackAuraData(CallDataProviderMethod("GetAuraDataBySpellName", unit, auraName, filter));
end

do
	local function ForEachAuraHelper(unit, filter, func, usePackedAura, continuationToken, ...)
		-- continuationToken is the first return value of UnitAuraSlots()
		local n = select('#', ...);
		for i=1, n do
			local slot = select(i, ...);
			local done;
			local auraInfo = CallDataProviderMethod("GetAuraDataBySlot", unit, slot);

			-- Protect against GetAuraDataBySlot desyncing with GetAuraSlots
			if auraInfo then
				if usePackedAura then
					done = func(auraInfo);
				else
					done = func(AuraUtil.UnpackAuraData(auraInfo));
				end
			end
			if done then
				-- if func returns true then no further slots are needed, so don't return continuationToken
				return nil;
			end
		end
		return continuationToken;
	end

	function AuraUtil.ForEachAura(unit, filter, batchSize, func, usePackedAura)
		if batchSize and batchSize <= 0 then
			return;
		end
		local continuationToken;
		repeat
			-- continuationToken is the first return value of UnitAuraSlots
			continuationToken = ForEachAuraHelper(unit, filter, func, usePackedAura, CallDataProviderMethod("GetAuraSlots", unit, filter, batchSize, continuationToken));
		until continuationToken == nil;
	end
end

local function IsAuraFromPlayer(auraData)
	return (auraData.sourceUnit ~= nil) and UnitIsUnit("player", auraData.sourceUnit) or false;
end

local function GetExpirationTimeForSort(auraData)
	if auraData.expirationTime == nil or auraData.expirationTime == 0 then
		return math.huge;
	end

	return auraData.expirationTime;
end

function AuraUtil.DefaultAuraCompare(a, b)
	local aFromPlayer = (a.sourceUnit ~= nil) and UnitIsUnit("player", a.sourceUnit) or false;
	local bFromPlayer = (b.sourceUnit ~= nil) and UnitIsUnit("player", b.sourceUnit) or false;
	if aFromPlayer ~= bFromPlayer then
		return aFromPlayer;
	end

	if a.isPriorityAura ~= b.isPriorityAura then
		return a.isPriorityAura;
	end

	if a.canApplyAura ~= b.canApplyAura then
		return a.canApplyAura;
	end

	return a.auraInstanceID < b.auraInstanceID;
end

function AuraUtil.BigDefensiveAuraCompare(a, b)
	-- Comparison rules, note that everything that's compared in here should be known to be a "big defensive" already.
	-- The longest duration that is NOT yours has the highest priority, then another defensive that is not yours even at shorter duration should be next priority,
	-- then show yours in center if there are no other defensives on the target.

	-- Keeping the "is player caster" in sync with DefaultAuraCompare:
	local aFromPlayer = (a.sourceUnit ~= nil) and UnitIsUnit("player", a.sourceUnit) or false;
	local bFromPlayer = (b.sourceUnit ~= nil) and UnitIsUnit("player", b.sourceUnit) or false;
	if aFromPlayer ~= bFromPlayer then
		return not aFromPlayer; -- Big difference from above, we prefer showing things that are not cast by the player
	end

	if a.expirationTime ~= b.expirationTime then
		return a.expirationTime > b.expirationTime;
	end

	return a.auraInstanceID < b.auraInstanceID;
end

function AuraUtil.UnitFrameDebuffComparator(a, b)
	if a.debuffType ~= b.debuffType then
		return a.debuffType < b.debuffType;
	end

	return AuraUtil.DefaultAuraCompare(a, b);
end

function AuraUtil.ImportantOnlyAuraCompare(auraA, auraB)
	local aImportant = auraA.spellId ~= nil and C_Spell.IsSpellImportant(auraA.spellId);
	local bImportant = auraB.spellId ~= nil and C_Spell.IsSpellImportant(auraB.spellId);

	if aImportant ~= bImportant then
		return aImportant;
	end

	return auraA.auraInstanceID < auraB.auraInstanceID;
end

function AuraUtil.ExpirationAuraCompare(auraA, auraB)
	local aFromPlayer = IsAuraFromPlayer(auraA);
	local bFromPlayer = IsAuraFromPlayer(auraB);
	if aFromPlayer ~= bFromPlayer then
		return aFromPlayer;
	end

	if auraA.isPriorityAura ~= auraB.isPriorityAura then
		return auraA.isPriorityAura;
	end

	if auraA.canApplyAura ~= auraB.canApplyAura then
		return auraA.canApplyAura;
	end

	-- Permanent auras sort after timed auras.
	local aExpirationTime = GetExpirationTimeForSort(auraA);
	local bExpirationTime = GetExpirationTimeForSort(auraB);
	if aExpirationTime ~= bExpirationTime then
		return aExpirationTime < bExpirationTime;
	end

	return auraA.auraInstanceID < auraB.auraInstanceID;
end

function AuraUtil.ExpirationOnlyAuraCompare(auraA, auraB)
	-- Permanent auras sort after timed auras.
	local aExpirationTime = GetExpirationTimeForSort(auraA);
	local bExpirationTime = GetExpirationTimeForSort(auraB);
	if aExpirationTime ~= bExpirationTime then
		return aExpirationTime < bExpirationTime;
	end

	return auraA.auraInstanceID < auraB.auraInstanceID;
end

function AuraUtil.NameAuraCompare(auraA, auraB)
	local aFromPlayer = IsAuraFromPlayer(auraA);
	local bFromPlayer = IsAuraFromPlayer(auraB);
	if aFromPlayer ~= bFromPlayer then
		return aFromPlayer;
	end

	if auraA.isPriorityAura ~= auraB.isPriorityAura then
		return auraA.isPriorityAura;
	end

	if auraA.canApplyAura ~= auraB.canApplyAura then
		return auraA.canApplyAura;
	end

	local aName = auraA.name or "";
	local bName = auraB.name or "";
	if aName ~= bName then
		return aName < bName;
	end

	return auraA.auraInstanceID < auraB.auraInstanceID;
end

function AuraUtil.NameOnlyAuraCompare(auraA, auraB)
	local aName = auraA.name or "";
	local bName = auraB.name or "";
	if aName ~= bName then
		return aName < bName;
	end

	return auraA.auraInstanceID < auraB.auraInstanceID;
end

function AuraUtil.AuraInstanceIDOnlyAuraCompare(auraA, auraB)
	return auraA.auraInstanceID < auraB.auraInstanceID;
end

AuraUtil.AuraFilters =
{
	Helpful = "HELPFUL",								-- Include only helpful auras (buffs)
	Harmful = "HARMFUL",								-- Include only harmful auras (debuffs)
	Player = "PLAYER",									-- Include only auras that were cast by the player, or by the player's pet or vehicle
	Raid = "RAID",										-- Include only helpful auras the player can apply and harmful auras the player can dispel
	Cancelable = "CANCELABLE",							-- Include only auras that can be canceled by the player
	-- NotCancelable ("NOT_CANCELABLE") was removed; use "!"..AuraUtil.AuraFilters.Cancelable ("!CANCELABLE").
	-- A temporary fallback is provided by Blizzard_DeprecatedAuraFilters.
	IncludeNameplateOnly = "INCLUDE_NAME_PLATE_ONLY",	-- When set, auras that are flagged as being nameplate-only will be included. When not set, nameplate-only auras will be filtered out.
	Maw = "MAW",										-- When set, ONLY Torghast auras will be returned. When not set, Torghast auras will be filtered out.
	ExternalDefensive = "EXTERNAL_DEFENSIVE",			-- Include only auras that are external defensives
	CrowdControl = "CROWD_CONTROL",						-- Include only auras that have a crowd control effect (stun, fear, etc.)
	RaidInCombat = "RAID_IN_COMBAT",					-- Include only auras flagged to show on raid frames in combat. Combine with Player & Helpful to return self-cast HoTs
	RaidPlayerDispellable = "RAID_PLAYER_DISPELLABLE",	-- Include only auras someone in the player's raid can dispel (including helpful enrages on enemies)
	BigDefensive = "BIG_DEFENSIVE",						-- Include only auras that are big defensives
	Important = "IMPORTANT",							-- Include only auras that are flagged as important (helpful auras that show on enemy nameplates even if non-stealable)
	Dispellable = "DISPELLABLE",						-- Include only auras that are dispellable, regardless of whether the player's raid can dispel them
};

function AuraUtil.CreateFilterString(...)
	return string.join("|", ...);
end

-- A leading "!" negates a filter component, e.g. "!PLAYER" returns auras NOT cast by the player.
-- IncludeNameplateOnly and Maw filters are not negatable (negation will be ignored if applied)
AuraUtil.AuraFilterNegationPrefix = "!";

function AuraUtil.IsValidFilterString(filterString)
	-- Splitting here intentionally tokenizes on "|" and space characters to
	-- permit callers to "TYPE | OUT | THEIR | STRINGS". This requires skipping
	-- empty components as strsplit's tokenizer doesn't skip chains of delimiters.
	for _index, component in ipairs({ string.split("| ", filterString) }) do
		local negated = component:sub(1, 1) == AuraUtil.AuraFilterNegationPrefix;
		if negated then
			component = component:sub(2);
		end

		-- A bare "!" (negation prefix with nothing after it) is invalid; genuine empty components
		-- from delimiter chains (e.g. "HELPFUL|PLAYER") are still skipped below.
		if negated and component == "" then
			return false, "A negation prefix ('!') must be followed by a filter component.";
		end

		if component ~= "" and not EnumUtil.IsValid(AuraUtil.AuraFilters, component) then
			return false, string.format("Unknown aura filter component: '%s'", component);
		end
	end

	return true;
end

AuraUtil.DispellableDebuffTypes =
{
	Magic = true,
	Curse = true,
	Disease = true,
	Poison = true,
	Bleed = true,
};

AuraUtil.AuraUpdateChangedType = EnumUtil.MakeEnum(
	"None",
	"Debuff",
	"Buff",
	"Dispel"
);

AuraUtil.UnitFrameDebuffType = EnumUtil.MakeEnum(
	"BossDebuff",
	"BossBuff",
	"PriorityDebuff",
	"NonBossRaidDebuff",
	"NonBossDebuff"
);

function AuraUtil.ProcessAura(aura, displayOnlyDispellableDebuffs, ignoreBuffs, ignoreDebuffs, ignoreDispelDebuffs)
	if aura == nil then
		return AuraUtil.AuraUpdateChangedType.None;
	end

	if aura.isNameplateOnly then
		return AuraUtil.AuraUpdateChangedType.None;
	end

	if (aura.isBossAura or AuraUtil.IsRoleAura(aura)) and not aura.isRaid and not ignoreDebuffs then
		aura.debuffType = aura.isHarmful and AuraUtil.UnitFrameDebuffType.BossDebuff or AuraUtil.UnitFrameDebuffType.BossBuff;
		return AuraUtil.AuraUpdateChangedType.Debuff;
	elseif aura.isHarmful and not aura.isRaid and not ignoreDebuffs then
		if AuraUtil.IsPriorityDebuff(aura.spellId) then
			aura.debuffType = AuraUtil.UnitFrameDebuffType.PriorityDebuff;
			return AuraUtil.AuraUpdateChangedType.Debuff;
		elseif not displayOnlyDispellableDebuffs and AuraUtil.ShouldDisplayDebuff(aura.sourceUnit, aura.spellId) then
			aura.debuffType = AuraUtil.UnitFrameDebuffType.NonBossDebuff;
			return AuraUtil.AuraUpdateChangedType.Debuff;
		end
	elseif aura.isHelpful and not ignoreBuffs and AuraUtil.ShouldDisplayBuff(aura.sourceUnit, aura.spellId, aura.canApplyAura) then
		aura.isBuff = true;
		aura.isPriorityAura = AuraUtil.IsPriorityDebuff(aura.spellId); -- TODO: Rename API to IsPriorityAura.
		return AuraUtil.AuraUpdateChangedType.Buff;
	elseif aura.isHarmful and aura.isRaid then
		if displayOnlyDispellableDebuffs and not ignoreDebuffs and not (aura.isBossAura or AuraUtil.IsRoleAura(aura)) and AuraUtil.ShouldDisplayDebuff(aura.sourceUnit, aura.spellId) and not AuraUtil.IsPriorityDebuff(aura.spellId) then
			aura.debuffType = AuraUtil.UnitFrameDebuffType.NonBossRaidDebuff;
			return AuraUtil.AuraUpdateChangedType.Debuff;
		elseif not ignoreDispelDebuffs and AuraUtil.DispellableDebuffTypes[aura.dispelName] ~= nil then
			aura.debuffType = (aura.isBossAura or AuraUtil.IsRoleAura(aura)) and AuraUtil.UnitFrameDebuffType.BossDebuff or AuraUtil.UnitFrameDebuffType.NonBossRaidDebuff;
			return AuraUtil.AuraUpdateChangedType.Dispel;
		end
	end

	return AuraUtil.AuraUpdateChangedType.None;
end

do
	-- Cache securecallfunction in case it changes in the global environment
	local securecallfunction = securecallfunction;

	local hasValidPlayer = false;
	EventRegistry:RegisterFrameEvent("PLAYER_ENTERING_WORLD");
	EventRegistry:RegisterFrameEvent("PLAYER_LEAVING_WORLD");
	EventRegistry:RegisterCallback("PLAYER_ENTERING_WORLD", function()
		hasValidPlayer = true;
	end, {});
	EventRegistry:RegisterCallback("PLAYER_LEAVING_WORLD", function()
		hasValidPlayer = false;
	end, {});

	local cachedVisualizationInfo = {};

	-- Visualization info is specific to the spec it was checked under
	EventRegistry:RegisterFrameEvent("PLAYER_SPECIALIZATION_CHANGED");
	EventRegistry:RegisterCallback("PLAYER_SPECIALIZATION_CHANGED", function()
		cachedVisualizationInfo = {};
	end, {});

	local function GetCachedVisibilityInfo(spellId)
		if cachedVisualizationInfo[spellId] == nil then
			local newInfo = {C_Spell.GetVisibilityInfo(spellId, UnitAffectingCombat("player") and Enum.SpellAuraVisibilityType.RaidInCombat or Enum.SpellAuraVisibilityType.RaidOutOfCombat)};
			if not hasValidPlayer then
				-- Don't cache the info if the player is not valid since we didn't get a valid result
				return unpack(newInfo);
			end
			cachedVisualizationInfo[spellId] = newInfo;
		end

		local info = cachedVisualizationInfo[spellId];
		return unpack(info);
	end

	function AuraUtil.ShouldDisplayDebuff(unitCaster, spellId)
		local hasCustom, alwaysShowMine, showForMySpec = securecallfunction(GetCachedVisibilityInfo, spellId);
		if ( hasCustom ) then
			return showForMySpec or (alwaysShowMine and (unitCaster == "player" or unitCaster == "pet" or unitCaster == "vehicle") );	--Would only be "mine" in the case of something like forbearance.
		else
			return true;
		end
	end

	local cachedSelfBuffChecks = {};
	local function CheckIsSelfBuff(spellId)
		if cachedSelfBuffChecks[spellId] == nil then
			cachedSelfBuffChecks[spellId] = C_Spell.IsSelfBuff(spellId);
		end

		return cachedSelfBuffChecks[spellId];
	end

	function AuraUtil.ShouldDisplayBuff(unitCaster, spellId, canApplyAura)
		local hasCustom, alwaysShowMine, showForMySpec = securecallfunction(GetCachedVisibilityInfo, spellId);

		if ( hasCustom ) then
			return showForMySpec or (alwaysShowMine and (unitCaster == "player" or unitCaster == "pet" or unitCaster == "vehicle"));
		elseif (unitCaster == "player" or unitCaster == "pet" or unitCaster == "vehicle") and canApplyAura then
			return not securecallfunction(CheckIsSelfBuff, spellId);
		else
			return false;
		end
	end

	local cachedPriorityChecks = {};
	function AuraUtil.CheckIsPriorityAura(spellId)
		if cachedPriorityChecks[spellId] == nil then
			cachedPriorityChecks[spellId] = C_Spell.IsPriorityAura(spellId);
		end

		return cachedPriorityChecks[spellId];
	end

	local cachedBigDefensives = {};
	function AuraUtil.IsBigDefensive(aura)
		-- EditMode data support without mocking an entire API
		if aura.isBigDefensive ~= nil then
			return aura.isBigDefensive;
		end

		local spellID = aura.spellId;
		if cachedBigDefensives[spellID] == nil then
			cachedBigDefensives[spellID] = securecallfunction(C_UnitAuras.AuraIsBigDefensive, spellID);
		end

		return cachedBigDefensives[spellID];
	end

	local function DumpCaches()
		cachedVisualizationInfo = {};
		cachedSelfBuffChecks = {};
		cachedPriorityChecks = {};
	end
	EventRegistry:RegisterFrameEvent("PLAYER_REGEN_ENABLED");
	EventRegistry:RegisterFrameEvent("PLAYER_REGEN_DISABLED");
	EventRegistry:RegisterCallback("PLAYER_REGEN_ENABLED", DumpCaches, {});
	EventRegistry:RegisterCallback("PLAYER_REGEN_DISABLED", DumpCaches, {});
end

local function RefreshBuffs(frame, unit, numBuffs, suffix, checkCVar)
	local frameName = frame:GetName();

	frame.hasDispellable = nil;

	numBuffs = numBuffs or MAX_PARTY_BUFFS;
	suffix = suffix or "Buff";

	local unitStatus, statusColor;
	local debuffTotal = 0;

	local filter = ( checkCVar and CVarCallbackRegistry:GetCVarValueBool("showCastableBuffs") and UnitCanAssist("player", unit) ) and "HELPFUL|RAID" or "HELPFUL";
	local numFrames = 0;
	AuraUtil.ForEachAura(unit, filter, numBuffs, function(...)
		local name, icon, count, debuffType, duration, expirationTime = ...;

		-- if we have an icon to show then proceed with setting up the aura
		if ( icon ) then
			numFrames = numFrames + 1;
			local buffName = frameName..suffix..numFrames;

			-- set the icon
			local buffIcon = _G[buffName.."Icon"];
			buffIcon:SetTexture(icon);

			-- setup the cooldown
			local coolDown = _G[buffName.."Cooldown"];
			if ( coolDown ) then
				CooldownFrame_Set(coolDown, expirationTime - duration, duration, true);
			end

			-- show the aura
			_G[buffName]:Show();
		end
		return numFrames >= numBuffs;
	end);

	for i=numFrames + 1,numBuffs do
		local buffName = frameName..suffix..i;
		local buffFrame = _G[buffName];
		if buffFrame then
			buffFrame:Hide();
		else
			break;
		end
	end
end

local function RefreshDebuffs(frame, unit, numDebuffs, suffix, checkCVar)
	local frameName = frame:GetName();
	suffix = suffix or "Debuff";
	local frameNameWithSuffix = frameName..suffix;

	frame.hasDispellable = nil;

	numDebuffs = numDebuffs or MAX_PARTY_DEBUFFS;

	local unitStatus, statusColor;
	local debuffTotal = 0;
	local isEnemy = UnitCanAttack("player", unit);

	local filter = ( checkCVar and CVarCallbackRegistry:GetCVarValueBool("showDispelDebuffs") and UnitCanAssist("player", unit) ) and "HARMFUL|RAID" or "HARMFUL";

	if strsub(unit, 1, 5) == "party" then
		unitStatus = _G[frameName.."Status"];
	end
	AuraUtil.ForEachAura(unit, filter, numDebuffs, function(...)
		local name, icon, count, debuffType, duration, expirationTime, caster = ...;

		if ( icon and ( SHOW_CASTABLE_DEBUFFS == "0" or not isEnemy or caster == "player" ) ) then
			debuffTotal = debuffTotal + 1;
			local debuffName = frameNameWithSuffix..debuffTotal;
			-- if we have an icon to show then proceed with setting up the aura

			-- set the icon
			local debuffIcon = _G[debuffName.."Icon"];
			debuffIcon:SetTexture(icon);

			-- setup the border
			local debuffBorder = _G[debuffName.."Border"];
			AuraUtil.SetAuraBorderColor(debuffBorder, debuffType);

			-- record interesting data for the aura button
			statusColor = debuffColor;
			frame.hasDispellable = 1;

			-- setup the cooldown
			local coolDown = _G[debuffName.."Cooldown"];
			if ( coolDown ) then
				CooldownFrame_Set(coolDown, expirationTime - duration, duration, true);
			end

			-- show the aura
			_G[debuffName]:Show();
		end
		return debuffTotal >= numDebuffs;
	end);

	for i=debuffTotal+1,numDebuffs do
		local debuffName = frameNameWithSuffix..i;
		_G[debuffName]:Hide();
	end

	frame.debuffTotal = debuffTotal;
	-- Reset unitStatus overlay graphic timer
	if ( frame.numDebuffs and debuffTotal >= frame.numDebuffs ) then
		frame.debuffCountdown = 30;
	end
	if ( unitStatus and statusColor ) then
		unitStatus:SetVertexColor(statusColor.r, statusColor.g, statusColor.b);
	end
end

function AuraUtil.RefreshAuras(frame, unit, numAuras, suffix, checkCVar, showBuffs)
	if ( showBuffs ) then
		RefreshBuffs(frame, unit, numAuras, suffix, checkCVar);
	else
		RefreshDebuffs(frame, unit, numAuras, suffix, checkCVar);
	end
end

function AuraUtil.IsRoleAura(aura)
	return aura.isTankRoleAura or aura.isHealerRoleAura or aura.isDPSRoleAura;
end

function AuraUtil.GetAuraBorderColor(dispelType)
	local info = DEBUFF_DISPLAY_INFO[dispelType] or DEBUFF_DISPLAY_INFO["None"];
	return info.color;
end

function AuraUtil.SetAuraBorderColor(borderRegion, dispelType)
	borderRegion:SetVertexColor(AuraUtil.GetAuraBorderColor(dispelType):GetRGBA());
end

function AuraUtil.SetAuraSymbol(fontstring, dispelType)
	if CVarCallbackRegistry:GetCVarValueBool("colorblindMode") then
		local info = DEBUFF_DISPLAY_INFO[dispelType] or DEBUFF_DISPLAY_INFO["None"];
		fontstring:SetText(info.abbreviation);
		fontstring:Show();
	else
		fontstring:Hide();
	end
end

function AuraUtil.GetAuraDispelTypeIcon(dispelType)
	local info = DEBUFF_DISPLAY_INFO[dispelType] or DEBUFF_DISPLAY_INFO["None"];
	return info.dispelIconAtlas;
end

function AuraUtil.SetAuraDispelTypeIcon(texture, dispelType)
	local dispelIconAtlas = AuraUtil.GetAuraDispelTypeIcon(dispelType);

	if not CheckSetAtlas(texture, dispelIconAtlas, TextureKitConstants.IgnoreAtlasSize) then
		texture:SetTexture(nil);
	end
end

function AuraUtil.GetDebuffDisplayInfoTable()
	return DEBUFF_DISPLAY_INFO;
end

function AuraUtil.SetAuraBorderAtlasFromAura(borderRegion, auraData, showDispelType)
	if auraData.isHarmful then
		borderRegion:Show();
		AuraUtil.SetAuraBorderAtlas(borderRegion, auraData.dispelName, showDispelType);
	else
		borderRegion:Hide();
	end
end

local function OnSwitchAuraDataProvider(...)
	local useActualDataProvider = select(2, ...);
	if useActualDataProvider then
		AuraUtil.ClearDataProvider();
	else
		AuraUtil.SetDataProvider(GetEditModeAuraDataProvider());
	end
end

EventRegistry:RegisterFrameEventAndCallback("AURA_DATA_PROVIDER_SWITCH", OnSwitchAuraDataProvider, {});

GroupBuffMixin = {};

function GroupBuffMixin:OnLoad()
	self:RegisterHiddenGroupBuffsChangedEvent();
	self:RefreshHiddenGroupBuffs();
	self:RegisterGroupBuffVisualAlertsChangedEvent();
	self:RefreshGroupBuffVisualAlerts();
end

function GroupBuffMixin:RefreshHiddenGroupBuffs(spellIDs)
	self.hiddenGroupBuffSpellIDs = {};
	for _, spellID in ipairs(spellIDs or C_UnitAuras.GetHiddenGroupBuffs() or {}) do
		self.hiddenGroupBuffSpellIDs[spellID] = true;
	end
end

function GroupBuffMixin:IsGroupBuffHidden(spellID)
	if spellID and self.hiddenGroupBuffSpellIDs then
		return not not self.hiddenGroupBuffSpellIDs[spellID];
	end

	return false;
end

function GroupBuffMixin:OnHiddenGroupBuffsChanged(...)
	local spellIDs = ...;
	self:RefreshHiddenGroupBuffs(spellIDs);
end

function GroupBuffMixin:RegisterHiddenGroupBuffsChangedEvent()
	EventRegistry:RegisterFrameEventAndCallback("HIDDEN_GROUP_BUFFS_CHANGED", self.OnHiddenGroupBuffsChanged, self);
end

function GroupBuffMixin:UnregisterHiddenGroupBuffsChangedEvent()
	EventRegistry:UnregisterFrameEventAndCallback("HIDDEN_GROUP_BUFFS_CHANGED", self);
end

function GroupBuffMixin:RefreshGroupBuffVisualAlerts(visualAlerts)
	self.groupBuffVisualAlerts = {};
	for _, info in ipairs(visualAlerts or C_UnitAuras.GetGroupBuffVisualAlerts() or {}) do
		self.groupBuffVisualAlerts[info.spellID] = info.visualValue;
	end
end

function GroupBuffMixin:GetGroupBuffVisualAlert(spellID)
	if spellID and self.groupBuffVisualAlerts then
		return self.groupBuffVisualAlerts[spellID];
	end
end

function GroupBuffMixin:OnGroupBuffVisualAlertsChanged(...)
	local visualAlerts = ...;
	self:RefreshGroupBuffVisualAlerts(visualAlerts);
end

function GroupBuffMixin:RegisterGroupBuffVisualAlertsChangedEvent()
	EventRegistry:RegisterFrameEventAndCallback("GROUP_BUFF_VISUAL_ALERTS_CHANGED", self.OnGroupBuffVisualAlertsChanged, self);
end

function GroupBuffMixin:UnregisterGroupBuffVisualAlertsChangedEvent()
	EventRegistry:UnregisterFrameEventAndCallback("GROUP_BUFF_VISUAL_ALERTS_CHANGED", self);
end
