local auraIconDataProvider;
local function GetSampleAuraIcon()
	if not auraIconDataProvider then
		local spellIconsOnly = true;
		auraIconDataProvider = CreateAndInitFromMixin(IconDataProviderMixin, IconDataProviderExtraType.Spellbook, spellIconsOnly);
	end

	local iconDataProviderNumIcons = auraIconDataProvider:GetNumIcons();
	return auraIconDataProvider:GetIconByIndex(math.random(1, iconDataProviderNumIcons));
end

local editModeAurasByInstanceID;
local editModeAurasBySlot;
local editModeAuraSlots;

local nextInstanceID = 1;
local nextSpellID = 500;
local function CreateAura(name, dispelName, sourceUnit, isHelpful, isHarmful, isRaid, isBoss, canActivePlayerDispel)
	local aura =
	{
		auraInstanceID = nextInstanceID, name = name, icon = GetSampleAuraIcon(), applications = 1, dispelName = dispelName, duration = 0, expirationTime = 0, sourceUnit = sourceUnit,
		isStealable = false, nameplateShowPersonal = false, spellId = nextSpellID, canApplyAura = true, isBossAura = isBoss, isHarmful = isHarmful, isHelpful = isHelpful, isRaid = isRaid,
		isFromPlayerOrPlayerPet = true, nameplateShowAll = false, timeMod = 1, points = {}, canActivePlayerDispel = canActivePlayerDispel,
	};

	nextInstanceID = nextInstanceID + 1;
	nextSpellID = nextSpellID + 1;
	return aura;
end

local function AddAura(...)
	local aura = CreateAura(...);
	table.insert(editModeAurasBySlot, aura);
	table.insert(editModeAuraSlots, #editModeAurasBySlot);
	editModeAurasByInstanceID[aura.auraInstanceID] = aura;
	return aura;
end

local function CreateAuras()
	if editModeAurasBySlot then
		return;
	end

	editModeAurasBySlot = {};
	editModeAurasByInstanceID = {};
	editModeAuraSlots = {};

	--		name			dispelName		sourceUnit		isHelpful		isHarmful		isRaid		isBoss	canActivePlayerDispel
	AddAura("Poison 1", 	"Poison", 		"player", 		false, 			true, 			false, 		true,	false);
	AddAura("Magic 1", 		"Magic", 		"player", 		false, 			true, 			false, 		false,	false);
	AddAura("Curse 1", 		"Curse", 		"player", 		false, 			true, 			false, 		false,	false);
	AddAura("Disease 1", 	"Disease", 		"player", 		false, 			true, 			false, 		false,	false);
	AddAura("Bleed 1", 		"Bleed", 		"player", 		false, 			true, 			true, 		false,	true);
	AddAura("Buff 1", 		nil, 			"player", 		true, 			false, 			false, 		false,	false);
	AddAura("Buff 2", 		nil, 			"player", 		true, 			false, 			false, 		false,	false);
	AddAura("Buff 3", 		nil, 			"player", 		true, 			false, 			false, 		false,	false);
	AddAura("Buff 4", 		nil, 			"player", 		true, 			false, 			false, 		false,	false);
	AddAura("Buff 5", 		nil, 			"player", 		true, 			false, 			false, 		false,	false);
	AddAura("Buff 6", 		nil, 			"player", 		true, 			false, 			false, 		false,	false);

	local bigDefensive =
	AddAura("BigDefensive",	nil, 			"player", 		true, 			false, 			false, 		false,	false);
	bigDefensive.isBigDefensive = true; -- EditMode specific data, actual check uses AuraUtil.IsBigDefensive.
end

local function BuildAuraSlotsFromFilter(filter)
	local slots = {};

	local wantsHarmful = string.find(filter, AuraUtil.AuraFilters.Harmful, 1, true) ~= nil;
	local wantsHelpful = string.find(filter, AuraUtil.AuraFilters.Helpful, 1, true) ~= nil;
	local wantsRaid = string.find(filter, AuraUtil.AuraFilters.Raid, 1, true) ~= nil;

	for i, aura in ipairs(editModeAurasBySlot) do
		if wantsHarmful == aura.isHarmful and wantsHelpful == aura.isHelpful and wantsRaid == aura.isRaid then
			table.insert(slots, i);
		end
	end

	return slots;
end

local editModeAuraDataProvider =
{
	GetAuraSlots = function(unit, filter, batchSize, continuationToken)
		CreateAuras();
		local slots = BuildAuraSlotsFromFilter(filter);
		return continuationToken, unpack(slots);
	end,

	GetAuraDataBySlot = function(unit, slot)
		CreateAuras();
		local auraData = editModeAurasBySlot[slot];
		assertsafe(auraData ~= nil, "EditMode SampleAura indexed by invalid slot: %s", tostring(slot));
		local shallow = false;
		return CopyTable(auraData, shallow);
	end,

	GetAuraDataByAuraInstanceID = function(unit, auraInstanceID)
		CreateAuras();
		return editModeAurasByInstanceID[auraInstanceID];
	end,

	GetUnitAuras = function(unit, filter, maxCount)
		CreateAuras();
		local slots = BuildAuraSlotsFromFilter(filter);
		local auras = {};

		for index, slot in ipairs(slots) do
			if maxCount ~= nil and index > maxCount then
				break;
			end

			local shallow = false;
			table.insert(auras, CopyTable(editModeAurasBySlot[slot], shallow));
		end

		return auras;
	end,
};

function GetEditModeAuraDataProvider()
	return editModeAuraDataProvider;
end
]] },
{ 'Blizzard_FrameXMLUtil\\GameTimeUtil.lua', [[
local GAMETIME_AM = true;
local GAMETIME_PM = false;

local date = date;
local format = format;
local GetCVarBool = GetCVarBool;
local tonumber = tonumber;

function GameTime_GetFormattedTime(hour, minute, wantAMPM)
	if ( GetCVarBool("timeMgrUseMilitaryTime") ) then
		return format(TIMEMANAGER_TICKER_24HOUR, hour, minute);
	else
		if ( wantAMPM ) then
			local timeFormat = TIME_TWELVEHOURAM;
			if ( hour == 0 ) then
				hour = 12;
			elseif ( hour == 12 ) then
				timeFormat = TIME_TWELVEHOURPM;
			elseif ( hour > 12 ) then
				timeFormat = TIME_TWELVEHOURPM;
				hour = hour - 12;
			end
			return format(timeFormat, hour, minute);
		else
			if ( hour == 0 ) then
				hour = 12;
			elseif ( hour > 12 ) then
				hour = hour - 12;
			end
			return format(TIMEMANAGER_TICKER_12HOUR, hour, minute);
		end
	end
end

function GameTime_ComputeMinutes(hour, minute, militaryTime, am)
	local minutes;
	if ( militaryTime ) then
		minutes = minute + hour*60;
	else
		local h = hour;
		if ( am ) then
			if ( h == 12 ) then
				h = 0;
			end
		else
			if ( h ~= 12 ) then
				h = h + 12;
			end
		end
		minutes = minute + h*60;
	end
	return minutes;
end

-- GameTime_ComputeStandardTime assumes the given time is military (24 hour)
function GameTime_ComputeStandardTime(hour)
	if ( hour > 12 ) then
		return hour - 12, GAMETIME_PM;
	elseif ( hour == 0 ) then
		return 12, GAMETIME_AM;
	else
		return hour, GAMETIME_AM;
	end
end

-- GameTime_ComputeMilitaryTime assumes the given time is standard (12 hour)
function GameTime_ComputeMilitaryTime(hour, am)
	if ( am and hour == 12 ) then
		return 0;
	elseif ( not am and hour < 12 ) then
		return hour + 12;
	else
		return hour;
	end
end

function GameTime_GetLocalTime(wantAMPM)
	local hour, minute = tonumber(date("%H")), tonumber(date("%M"));
	return GameTime_GetFormattedTime(hour, minute, wantAMPM), hour, minute;
end

function GameTime_GetGameTime(wantAMPM)
	local hour, minute = GetGameTime();
	return GameTime_GetFormattedTime(hour, minute, wantAMPM), hour, minute;
end

function GameTime_GetTime(showAMPM)
	if ( GetCVarBool("timeMgrUseLocalTime") ) then
		return GameTime_GetLocalTime(showAMPM);
	else
		return GameTime_GetGameTime(showAMPM);
	end
end

function GameTime_UpdateTooltip()
	GameTooltip:AddLine(TIMEMANAGER_TOOLTIP_TITLE, HIGHLIGHT_FONT_COLOR.r, HIGHLIGHT_FONT_COLOR.g, HIGHLIGHT_FONT_COLOR.b);
	GameTooltip:AddDoubleLine(
		TIMEMANAGER_TOOLTIP_REALMTIME,
		GameTime_GetGameTime(true),
		NORMAL_FONT_COLOR.r, NORMAL_FONT_COLOR.g, NORMAL_FONT_COLOR.b,
		HIGHLIGHT_FONT_COLOR.r, HIGHLIGHT_FONT_COLOR.g, HIGHLIGHT_FONT_COLOR.b);
	GameTooltip:AddDoubleLine(
		TIMEMANAGER_TOOLTIP_LOCALTIME,
		GameTime_GetLocalTime(true),
		NORMAL_FONT_COLOR.r, NORMAL_FONT_COLOR.g, NORMAL_FONT_COLOR.b,
		HIGHLIGHT_FONT_COLOR.r, HIGHLIGHT_FONT_COLOR.g, HIGHLIGHT_FONT_COLOR.b);
end]] },
{ 'Blizzard_FrameXMLUtil\\CalendarUtil.lua', [[

CalendarUtil = {};

function CalendarUtil.GetCalendarInviteStatusInfo(inviteStatus)
	return CALENDAR_INVITESTATUS_INFO[inviteStatus] or CALENDAR_INVITESTATUS_INFO["UNKNOWN"];
end

local function InternalGetEventBroadcastText(event, ongoing)
	local startTime = GameTime_GetFormattedTime(event.startTime.hour, event.startTime.minute, true);
	local inviteStatusInfo = CalendarUtil.GetCalendarInviteStatusInfo(event.inviteStatus);
	local eventIndexInfo = C_Calendar.GetEventIndexInfo(event.eventID, nil, event.monthDay);
	local eventLinkText = GetCalendarEventLink(eventIndexInfo.offsetMonths, eventIndexInfo.monthDay, eventIndexInfo.eventIndex);
	local eventLink = LINK_FONT_COLOR:WrapTextInColorCode(COMMUNITIES_CALENDAR_CHAT_EVENT_TITLE_FORMAT:format(eventLinkText));
	local inviteStatus = inviteStatusInfo.color:WrapTextInColorCode(inviteStatusInfo.name);
	local eventTime = nil;
	if ongoing then
		eventTime = YELLOW_FONT_COLOR:WrapTextInColorCode(COMMUNITIES_CALENDAR_ONGOING_EVENT_PREFIX);
	else
		local currentCalendarTime = C_DateAndTime.GetCurrentCalendarTime();
		local weekday = currentCalendarTime.weekday == event.startTime.weekday and COMMUNITIES_CALENDAR_TODAY or CALENDAR_WEEKDAY_NAMES[event.startTime.weekday];
		eventTime = YELLOW_FONT_COLOR:WrapTextInColorCode(COMMUNITIES_CALENDAR_EVENT_FORMAT:format(weekday, startTime));
	end
	return COMMUNITIES_CALENDAR_CHAT_EVENT_BROADCAST_FORMAT:format(eventTime, eventLink, inviteStatus);
end

function CalendarUtil.GetEventBroadcastText(event)
	local ongoing = false;
	return InternalGetEventBroadcastText(event, ongoing);
end

function CalendarUtil.GetOngoingEventBroadcastText(event)
	local ongoing = true;
	return InternalGetEventBroadcastText(event, ongoing);
end

function CalendarUtil.FormatCalendarTimeWeekday(messageDate)
	return FULLDATE_NO_YEAR:format(CALENDAR_WEEKDAY_NAMES[messageDate.weekday], CALENDAR_FULLDATE_MONTH_NAMES[messageDate.month], messageDate.monthDay);
end

function CalendarUtil.AreDatesEqual(firstCalendarTime, secondCalendarTime)
	return firstCalendarTime.month == secondCalendarTime.month and
			firstCalendarTime.monthDay == secondCalendarTime.monthDay and
			firstCalendarTime.year == secondCalendarTime.year;
end
]] },
{ 'Blizzard_FrameXMLUtil\\CommunitiesUtil.lua', [[

CommunitiesUtil = {};

function CommunitiesUtil.GetMemberRGB(memberInfo)
	if memberInfo.classID then
		local classInfo = C_CreatureInfo.GetClassInfo(memberInfo.classID);
		if classInfo then
			local classColor = RAID_CLASS_COLORS[classInfo.classFile];
			return classColor.r, classColor.g, classColor.b;
		end
	end
	
	return BATTLENET_FONT_COLOR:GetRGB();
end

function CommunitiesUtil.SortClubs(clubs)
	table.sort(clubs, function(lhsClub, rhsClub)
		if lhsClub.clubType == Enum.ClubType.Guild or rhsClub.clubType == Enum.ClubType.Guild then
			return lhsClub.clubType == Enum.ClubType.Guild;
		elseif lhsClub.favoriteTimeStamp ~= nil and rhsClub.favoriteTimeStamp ~= nil then
			return lhsClub.favoriteTimeStamp < rhsClub.favoriteTimeStamp;
		elseif lhsClub.favoriteTimeStamp ~= nil or rhsClub.favoriteTimeStamp ~= nil then
			return lhsClub.favoriteTimeStamp ~= nil;
		elseif lhsClub.clubType ~= rhsClub.clubType then
			return lhsClub.clubType == Enum.ClubType.Character;
		elseif lhsClub.joinTime ~= nil and rhsClub.joinTime ~= nil then
			return lhsClub.joinTime > rhsClub.joinTime;
		else
			return lhsClub.joinTime ~= nil;
		end
	end);
end

local STREAM_TYPE_SORT_ORDER = {
	[Enum.ClubStreamType.Guild] = 1,
	[Enum.ClubStreamType.General] = 2,
	[Enum.ClubStreamType.Officer] = 3,
	[Enum.ClubStreamType.Discord] = 4,
	[Enum.ClubStreamType.Other] = 5,
};

local function CompareStreams(lhsStream, rhsStream)
	if lhsStream.streamType ~= rhsStream.streamType then
		return STREAM_TYPE_SORT_ORDER[lhsStream.streamType] < STREAM_TYPE_SORT_ORDER[rhsStream.streamType];
	else
		return lhsStream.creationTime < rhsStream.creationTime;
	end
end

function CommunitiesUtil.SortStreams(streams)
	table.sort(streams, CompareStreams);
end

local PRESENCE_SORT_ORDER = {
	[Enum.ClubMemberPresence.Online] = 1,
	[Enum.ClubMemberPresence.OnlineMobile] = 2,
	[Enum.ClubMemberPresence.Away] = 3,
	[Enum.ClubMemberPresence.Busy] = 4,
	[Enum.ClubMemberPresence.Offline] = 5,
	[Enum.ClubMemberPresence.Unknown] = 6,
};

local function CompareMembers(lhsMemberInfo, rhsMemberInfo)
	if lhsMemberInfo.presence ~= rhsMemberInfo.presence then
		return PRESENCE_SORT_ORDER[lhsMemberInfo.presence] < PRESENCE_SORT_ORDER[rhsMemberInfo.presence];
	elseif lhsMemberInfo.level and rhsMemberInfo.level and lhsMemberInfo.level ~= rhsMemberInfo.level then
		return lhsMemberInfo.level > rhsMemberInfo.level;
	elseif lhsMemberInfo.guildRankOrder and rhsMemberInfo.guildRankOrder and lhsMemberInfo.guildRankOrder ~= rhsMemberInfo.guildRankOrder then
		return lhsMemberInfo.guildRankOrder < rhsMemberInfo.guildRankOrder;
	elseif lhsMemberInfo.role ~= rhsMemberInfo.role then
		return lhsMemberInfo.role < rhsMemberInfo.role;
	elseif lhsMemberInfo.name and rhsMemberInfo.name then
		return lhsMemberInfo.name < rhsMemberInfo.name;
	elseif lhsMemberInfo.name or rhsMemberInfo.name then
		return lhsMemberInfo.name ~= nil;
	else
		return lhsMemberInfo.memberId < rhsMemberInfo.memberId;
	end
end

local function GenerateCompareMemberLambda(clubId)
	local clubInfo = clubId and C_Club.GetClubInfo(clubId);
	if clubInfo and clubInfo.clubType == Enum.ClubType.BattleNet then
		local function CompareBNetMembers(lhsMemberInfo, rhsMemberInfo)
			if lhsMemberInfo.presence ~= rhsMemberInfo.presence then
				return PRESENCE_SORT_ORDER[lhsMemberInfo.presence] < PRESENCE_SORT_ORDER[rhsMemberInfo.presence];
			elseif lhsMemberInfo.role ~= rhsMemberInfo.role then
				return lhsMemberInfo.role < rhsMemberInfo.role;
			else
				local nameComparison = C_Club.CompareBattleNetDisplayName(clubId, lhsMemberInfo.memberId, rhsMemberInfo.memberId);
				if nameComparison ~= 0 then
					return nameComparison < 0;
				else
					return lhsMemberInfo.memberId < rhsMemberInfo.memberId;
				end
			end
		end
		
		return CompareBNetMembers;
	else
		return CompareMembers;
	end
end

function CommunitiesUtil.SortMemberInfo(clubId, memberInfoArray)
	table.sort(memberInfoArray, GenerateCompareMemberLambda(clubId));
	return memberInfoArray;
end

function CommunitiesUtil.GetMemberIdsSortedByName(clubId, streamId)
	return clubId and C_Club.GetClubMembers(clubId, streamId) or {};
end

function CommunitiesUtil.GetMemberInfo(clubId, memberIds)
	local memberInfoArray = {};

	for _, memberId in ipairs(memberIds) do
		local memberInfo = C_Club.GetMemberInfo(clubId, memberId);
		if memberInfo then
			table.insert(memberInfoArray, memberInfo);
		end
	end

	return memberInfoArray;
end

function CommunitiesUtil.GetMemberInfoLookup(memberInfoArray)
	local memberInfoLookup = {};
	
	for _, memberInfo in ipairs(memberInfoArray) do
		memberInfoLookup[memberInfo.memberId] = memberInfo;
	end

	return memberInfoLookup;
end

function CommunitiesUtil.GetOnlineMembers(memberInfoArray)
	local onlineMemberInfoArray = {};
	for _, memberInfo in ipairs(memberInfoArray) do
		local couldBeOffline = memberInfo.presence == Enum.ClubMemberPresence.Offline or memberInfo.presence == Enum.ClubMemberPresence.Unknown;
		if not couldBeOffline then
			table.insert(onlineMemberInfoArray, memberInfo);
		end
	end

	return onlineMemberInfoArray;
end

function CommunitiesUtil.SortMembersByList(memberInfoLookup, memberIds)
	local memberInfoArray = {};

	for _, memberId in ipairs(memberIds) do
		local memberInfo = memberInfoLookup[memberId];
		if memberInfo then
			table.insert(memberInfoArray, memberInfo);
		end
	end

	return memberInfoArray;
end

-- Leave streamId as nil if you want all members in the club
function CommunitiesUtil.GetAndSortMemberInfo(clubId, streamId, filterOffline)
	local memberIdArray = CommunitiesUtil.GetMemberIdsSortedByName(clubId, streamId);
	local memberInfoArray = CommunitiesUtil.GetMemberInfo(clubId, memberIdArray);
	if filterOffline then
		memberInfoArray = CommunitiesUtil.GetOnlineMembers(memberInfoArray);
	end
	memberInfoArray = CommunitiesUtil.SortMemberInfo(clubId, memberInfoArray);
	return memberInfoArray;
end

function CommunitiesUtil.SortMemberInfoWithOverride(clubId, memberInfoArray, overrideCompare)
	local baseCompare = GenerateCompareMemberLambda(clubId);
	table.sort(memberInfoArray, function (lhsMemberInfo, rhsMemberInfo)
		local overrideCompareResult = overrideCompare(lhsMemberInfo, rhsMemberInfo);
		if overrideCompareResult == nil then
			return baseCompare(lhsMemberInfo, rhsMemberInfo);
		else
			return overrideCompareResult;
		end
	end);
end

function CommunitiesUtil.DoesAnyCommunityHaveUnreadMessages()
	return C_Club.DoesAnyCommunityHaveUnreadMessages();
end

function CommunitiesUtil.DoesOtherCommunityHaveUnreadMessages(ignoreClubId)
	local clubs = C_Club.GetSubscribedClubs();
	for i, club in ipairs(clubs) do
		if club.clubId ~= ignoreClubId then
			if CommunitiesUtil.DoesCommunityHaveUnreadMessages(club.clubId) then
				return true;
			end
		end
	end
end

function CommunitiesUtil.DoesCommunityHaveUnreadMessages(clubId)
	return CommunitiesUtil.DoesCommunityHaveOtherUnreadMessages(clubId, nil);
end

function CommunitiesUtil.DoesCommunityHaveOtherUnreadMessages(clubId, ignoreStreamId)	
	local streamToNotificationSetting = CommunitiesUtil.GetStreamNotificationSettingsLookup(clubId);
	for i, stream in ipairs(C_Club.GetStreams(clubId)) do
		if stream.streamId ~= ignoreStreamId and streamToNotificationSetting[stream.streamId] == Enum.ClubStreamNotificationFilter.All then
			if CommunitiesUtil.DoesCommunityStreamHaveUnreadMessages(clubId, stream.streamId) then
				return true;
			end
		end
	end
end

function CommunitiesUtil.GetStreamNotificationSettingsLookup(clubId)
	local streamNotificationSettings = C_Club.GetClubStreamNotificationSettings(clubId);
	local streamToNotificationSetting = {};
	for i, streamNotificationSetting in ipairs(streamNotificationSettings) do
		streamToNotificationSetting[streamNotificationSetting.streamId] = streamNotificationSetting.filter;
	end
	
	return streamToNotificationSetting;
end

function CommunitiesUtil.DoesCommunityStreamHaveUnreadMessages(clubId, streamId)
	return C_Club.GetStreamViewMarker(clubId, streamId) ~= nil;
end

function CommunitiesUtil.CanKickClubMember(clubPrivileges, memberInfo)
	return tContains(clubPrivileges.kickableRoleIds, memberInfo.role);
end

function CommunitiesUtil.ClearAllUnreadNotifications(clubId)
	local streams = C_Club.GetStreams(clubId);
	for i, stream in ipairs(streams) do
		C_Club.AdvanceStreamViewMarker(clubId, stream.streamId);
	end
end

function CommunitiesUtil.OpenInviteDialog(clubId, streamId)
	local clubInfo = C_Club.GetClubInfo(clubId);
	if not clubInfo then
		return;
	end
	
	local privileges = C_Club.GetClubPrivileges(clubId);
	if clubInfo.clubType == Enum.ClubType.Guild then
		if(ClubFinderDoesSelectedClubHaveActiveListing(clubId) and C_ClubFinder.IsEnabled()) then 
			StaticPopup_Show("ADD_GUILDMEMBER_WITH_FINDER_LINK", nil, nil, {clubId = clubId});
		else 
			StaticPopup_Show("ADD_GUILDMEMBER", nil, nil, {clubId = clubId});
		end 
	elseif privileges.canCreateTicket then
		StaticPopup_Show("INVITE_COMMUNITY_MEMBER_WITH_INVITE_LINK", nil, nil, { clubId = clubId, streamId = streamId, });
	else
		StaticPopup_Show("INVITE_COMMUNITY_MEMBER", nil, nil, { clubId = clubId, streamId = streamId, });
	end
end

function CommunitiesUtil.FindCommunityAndStreamByName(communityName, streamName)
	local communityID, streamID;
	if communityName then
		communityName = string.lower(communityName);
		local clubs = C_Club.GetSubscribedClubs();
		if clubs then
			for _, club in ipairs(clubs) do
				if string.lower(club.name) == communityName then
					communityID = club.clubId;
					break;
				end
			end

			if communityID then
				local streams = C_Club.GetStreams(communityID);
				if streams then
					if streamName then
						streamName = string.lower(streamName);
						for _, stream in ipairs(streams) do
							if streamName == string.lower(stream.name) then
								streamID = stream.streamId;
								break;
							end
						end
					else
						for _, stream in ipairs(streams) do
							if stream.streamType == Enum.ClubStreamType.General then
								streamID = stream.streamId;
								break;
							end
						end
					end
				end
			end
		end
	end
	return communityID, streamID;
end

function CommunitiesUtil.FindGuildStreamByType(clubStreamType)
	if clubStreamType ~= Enum.ClubStreamType.Guild and clubStreamType ~= Enum.ClubStreamType.Officer and clubStreamType ~= Enum.ClubStreamType.Discord then
		return;
	end

	local communityID, streamID;
	communityID = C_Club.GetGuildClubId();
	if communityID then
		local streams = C_Club.GetStreams(communityID);
		if streams then
			for _, stream in ipairs(streams) do
				if stream.streamType == clubStreamType then
					streamID = stream.streamId;
					break;
				end
			end
		end
	end
	return communityID, streamID;
end

function CommunitiesUtil.GetRoleSpecClassLine(classID, specID)
	local className, classTag = GetClassInfo(classID);
	local color = CreateColor(GetClassColor(classTag));

	local _, specName, _, _, role = GetSpecializationInfoForSpecID(specID);
	local texture;
	if (role == "TANK") then
		texture = CreateAtlasMarkup("roleicon-tiny-tank");
	elseif (role == "DAMAGER") then
		texture = CreateAtlasMarkup("roleicon-tiny-dps");
	elseif (role == "HEALER") then
		texture = CreateAtlasMarkup("roleicon-tiny-healer");
	end

	return color:WrapTextInColorCode(CLUB_FINDER_LOOKING_FOR_CLASS_SPEC_WITH_ROLE:format(texture, specName, className));
end

function CommunitiesUtil.AddLookingForLines(tooltip, recruitingSpecIds, recruitingSpecIdMap, playerSpecs)
	GameTooltip_AddNormalLine(GameTooltip, CLUB_FINDER_LOOKING_FOR);
	
	local isRecruitingAllSpecs = #recruitingSpecIds == 0 or #recruitingSpecIds == CLUB_FINDER_MAX_NUM_SPECIALIZATIONS;
	if (isRecruitingAllSpecs) then 
		GameTooltip_AddColoredLine(GameTooltip, CLUB_FINDER_RECRUITING_ALL_SPECS, HIGHLIGHT_FONT_COLOR);
	else
		local isRecruitingPlayerSpec = false;
		local classDisplayName, classTag, classID = UnitClass("player");
		for _, playerSpecID in ipairs(playerSpecs) do 
			if (recruitingSpecIdMap[playerSpecID]) then
				GameTooltip_AddNormalLine(GameTooltip, CommunitiesUtil.GetRoleSpecClassLine(classID, playerSpecID));
				isRecruitingPlayerSpec = true;
			end
		end

		if (not isRecruitingPlayerSpec) then 
			GameTooltip_AddColoredLine(GameTooltip, CLUB_FINDER_APPLICANT_LIST_NO_MATCHING_SPECS, RED_FONT_COLOR); 
		end
	end
end
]] },
{ 'Blizzard_FrameXMLUtil\\RuneforgeUtil.lua', [[

RuneforgeCovenantSigilMixin = {};

function RuneforgeCovenantSigilMixin:OnPowerSet(oldPowerID, powerID)
	local hasPowerID = powerID ~= nil;
	local powerInfo = hasPowerID and self:GetParent():GetPowerInfo();
	local covenantID = powerInfo and (powerInfo.covenantID) or nil;
	local isCovenantPower = covenantID ~= nil;
	self:SetShown(isCovenantPower);
	if isCovenantPower then
		local isAvailable = (powerInfo.state == Enum.RuneforgePowerState.Available);
		if isCovenantPower then
			local sigilInfo = RuneforgeUtil.GetSigilInfoForCovenant(covenantID);
			self:SetScale(sigilInfo.scale);
			self.Icon:SetAtlas(sigilInfo.atlas, TextureKitConstants.UseAtlasSize);
			self.Icon:SetDesaturated(not isAvailable or not powerInfo.matchesCovenant);
			self.UnavailableMask:SetAtlas(sigilInfo.mask);

			if isAvailable and powerInfo.matchesCovenant then
				self.DimOverlay:SetAlpha(0);
			elseif not isAvailable then
				self.DimOverlay:SetAlpha(sigilInfo.uncollectedDim);
			else -- not powerInfo.matchesCovenant
				self.DimOverlay:SetAlpha(sigilInfo.inaccessibleDim);
			end
		end
	end
end


RuneforgePowerBaseMixin = {};

function RuneforgePowerBaseMixin:OnHide()
	self:UnregisterEvent("RUNEFORGE_POWER_INFO_UPDATED");
end

function RuneforgePowerBaseMixin:OnEvent(event, ...)
	if event == "RUNEFORGE_POWER_INFO_UPDATED" then
		local powerID = ...;
		if powerID == self:GetPowerID() then
			self:SetPowerID(powerID);

			if self:IsMouseOver() then
				self:OnEnter();
			end
		end
	end
end

function RuneforgePowerBaseMixin:OnEnter()
	local powerInfo = self:GetPowerInfo();
	if powerInfo then
		GameTooltip:SetOwner(self, "ANCHOR_RIGHT");

		local powerInfoNameColor = HIGHLIGHT_FONT_COLOR;
		local colorData = ColorManager.GetColorDataForItemQuality(Enum.ItemQuality.Legendary);
		if colorData then
			powerInfoNameColor = colorData.color;
		end

		GameTooltip_SetTitle(GameTooltip, powerInfo.name, powerInfoNameColor);

		GameTooltip_AddColoredLine(GameTooltip, RUNEFORGE_LEGENDARY_POWER_LABEL, BRIGHTBLUE_FONT_COLOR);

		GameTooltip_AddColoredLine(GameTooltip, powerInfo.description, GREEN_FONT_COLOR);

		if not self.slotNames then
			self.slotNames = C_LegendaryCrafting.GetRuneforgePowerSlots(self:GetPowerID());
		end

		if #self.slotNames > 0 then
			GameTooltip_AddBlankLineToTooltip(GameTooltip);

			local slotNames = HIGHLIGHT_FONT_COLOR:WrapTextInColorCode(table.concat(self.slotNames, LIST_DELIMITER));
			GameTooltip_AddNormalLine(GameTooltip, RUNEFORGE_LEGENDARY_POWER_TOOLTIP_SLOT_HEADER:format(slotNames));
		end

		if not self:ShouldHideSource() and powerInfo.source then
			GameTooltip_AddBlankLineToTooltip(GameTooltip);

			local sourceText = HIGHLIGHT_FONT_COLOR:WrapTextInColorCode(powerInfo.source);
			GameTooltip_AddNormalLine(GameTooltip, RUNEFORGE_LEGENDARY_POWER_SOURCE_FORMAT:format(sourceText));
		end

		if self:ShouldShowUnavailableError() and (powerInfo.state ~= Enum.RuneforgePowerState.Available) then
			GameTooltip_AddBlankLineToTooltip(GameTooltip);
			GameTooltip_AddErrorLine(GameTooltip, RUNEFORGE_LEGENDARY_POWER_TOOLTIP_NOT_COLLECTED);
		end

		local specName = powerInfo.specName;
		local isSpecPower = (specName ~= nil);
		local isCovenantPower = (powerInfo.covenantID ~= nil);
		if isSpecPower or isCovenantPower then
			GameTooltip_AddBlankLineToTooltip(GameTooltip);

			local covenantData = isCovenantPower and C_Covenants.GetCovenantData(powerInfo.covenantID) or nil;
			local covenantName = covenantData and covenantData.name or "";

			local matchesRequirement = (isSpecPower and powerInfo.matchesSpec) or (isCovenantPower and powerInfo.matchesCovenant);
			local requirementText = isCovenantPower and covenantName or specName;
			if matchesRequirement then
				local requiresText = RUNEFORGE_LEGENDARY_POWER_REQUIRES_SPEC_FORMAT:format(HIGHLIGHT_FONT_COLOR:WrapTextInColorCode(requirementText));
				GameTooltip_AddNormalLine(GameTooltip, requiresText);
			else
				GameTooltip_AddErrorLine(GameTooltip, RUNEFORGE_LEGENDARY_POWER_REQUIRES_SPEC_FORMAT:format(requirementText));
			end
		end


		GameTooltip:Show();
	end
end

function RuneforgePowerBaseMixin:OnLeave()
	GameTooltip_Hide();
end

function RuneforgePowerBaseMixin:OnSelected()
	if IsModifiedClick("CHATLINK") then
		local powerInfo = self:GetPowerInfo();
		if powerInfo == nil then
			return false;
		end

		ChatFrameUtil.InsertLink(C_Spell.GetSpellLink(powerInfo.descriptionSpellID));
		return true;
	end

	return false;
end

function RuneforgePowerBaseMixin:SetPowerID(powerID)
	local oldPowerID = self.powerID;

	self.powerID = powerID;
	self.slotNames = nil;

	local hasPowerID = powerID ~= nil;
	self.powerInfo = hasPowerID and C_LegendaryCrafting.GetRuneforgePowerInfo(powerID) or nil;
	if hasPowerID then
		self:RegisterEvent("RUNEFORGE_POWER_INFO_UPDATED");
	else
		self:UnregisterEvent("RUNEFORGE_POWER_INFO_UPDATED");
	end

	self:OnPowerSet(oldPowerID, powerID);

	if self.CovenantSigil then
		self.CovenantSigil:OnPowerSet(oldPowerID, powerID);
	end
end

function RuneforgePowerBaseMixin:ShouldHideSource()
	local powerInfo = self:GetPowerInfo();
	return (powerInfo == nil) or (powerInfo.state == Enum.RuneforgePowerState.Available);
end

function RuneforgePowerBaseMixin:GetPowerID()
	return self.powerID;
end

function RuneforgePowerBaseMixin:GetPowerInfo()
	return self.powerInfo;
end

function RuneforgePowerBaseMixin:OnPowerSet(oldPowerID, newPowerID)
	-- override in your mixin.
end

function RuneforgePowerBaseMixin:ShouldShowUnavailableError()
	-- override in your mixin.
	return false;
end


RuneforgeEffectOwnerMixin = {};

function RuneforgeEffectOwnerMixin:GetRuneforgeFrame()
	return self;
end

function RuneforgeEffectOwnerMixin:AddEffectData(effectKey, effectID, effectTarget, effectLevel)
	self[effectKey] = { effectID = effectID, effectTarget = effectTarget, effectLevel = effectLevel };
end

function RuneforgeEffectOwnerMixin:GetFrameFromEffectTarget(effectTarget)
	if effectTarget == RuneforgeUtil.EffectTarget.ItemSlot then
		return self, self:GetRuneforgeFrame().CraftingFrame.BaseItemSlot;
	elseif effectTarget == RuneforgeUtil.EffectTarget.ReverseItemSlot then
		return self:GetRuneforgeFrame().CraftingFrame.BaseItemSlot, self;
	elseif effectTarget == RuneforgeUtil.EffectTarget.None then
		return self, nil;
	else
		error("Unknown effect target: "..effectTarget);
	end
end

function RuneforgeEffectOwnerMixin:SetEffectShown(effectKey, shown)
	local effectData = self[effectKey];
	local controller = effectData.controller;
	if shown and not controller then
		local source, target = self:GetFrameFromEffectTarget(effectData.effectTarget);
		effectData.controller = self:GetRuneforgeFrame():AddEffect(effectData.effectLevel, effectData.effectID, source, target);
	elseif not shown and controller then
		controller:CancelEffect();
		effectData.controller = nil;
	end
end


RuneforgeSystemMixin = CreateFromMixins(RuneforgeEffectOwnerMixin);

local RefreshEventNames = {
	"BaseItemChanged",
	"PowerSelected",
	"ModifiersChanged",
};

function RuneforgeSystemMixin:GetRuneforgeFrame()
	return self:GetParent():GetParent();
end

function RuneforgeSystemMixin:IsRuneforgeCrafting()
	return self:GetRuneforgeFrame():IsRuneforgeCrafting();
end

function RuneforgeSystemMixin:IsRuneforgeUpgrading()
	return self:GetRuneforgeFrame():IsRuneforgeUpgrading();
end

function RuneforgeSystemMixin:RegisterRefreshMethod(refreshMethod)
	local runeforgeFrame = self:GetRuneforgeFrame();
	for i, eventName in ipairs(RefreshEventNames) do
		runeforgeFrame:RegisterCallback(RuneforgeFrameMixin.Event[eventName], GenerateClosure(refreshMethod, self, eventName), self);
	end
end

function RuneforgeSystemMixin:UnregisterRefreshMethod()
	local runeforgeFrame = self:GetRuneforgeFrame();
	for i, eventName in ipairs(RefreshEventNames) do
		runeforgeFrame:UnregisterCallback(RuneforgeFrameMixin.Event[eventName], self);
	end
end


