{ 'Blizzard_FrameXMLUtil\\DifficultyUtil_Shared.lua', [[
function DifficultyUtil.GetDifficultyName(difficultyID)
	return DifficultyUtil.DifficultyNames[difficultyID];
end

function DifficultyUtil.IsPrimaryRaid(difficultyID)
	return tContains(DifficultyUtil.PrimaryRaids, difficultyID);
end

function DifficultyUtil.GetNextPrimaryRaidDifficultyID(difficultyID)
	for i, id in ipairs(DifficultyUtil.PrimaryRaids) do
		if id == difficultyID then
			return DifficultyUtil.PrimaryRaids[i + 1];
		end
	end
	return nil;
end

function DifficultyUtil.InStoryRaid()
	if not DifficultyUtil.StoryRaidDifficultyID then
		return false;
	end

	local difficultyID = select(3, GetInstanceInfo());
	return difficultyID == DifficultyUtil.StoryRaidDifficultyID;
end

function DifficultyUtil.DoesCurrentRaidDifficultyMatch(compareDifficultyID)
	local instanceDifficultyID, _, _, _, isDynamicInstance = select(3, GetInstanceInfo());

	-- Ensure we are using base difficulties for comparisons
	instanceDifficultyID = GetBaseDifficultyID(instanceDifficultyID);
	compareDifficultyID = GetBaseDifficultyID(compareDifficultyID);
	local raidDifficultyID = GetBaseDifficultyID(GetRaidDifficultyID());

	if isDynamicInstance then
		if IsLegacyDifficulty(instanceDifficultyID) then
			local validNormalSize = instanceDifficultyID == DifficultyUtil.ID.Raid10Normal or instanceDifficultyID == DifficultyUtil.ID.Raid25Normal;
			if validNormalSize and compareDifficultyID == DifficultyUtil.ID.PrimaryRaidNormal then
				return true;
			end

			local validHeroicSize = instanceDifficultyID == DifficultyUtil.ID.Raid10Heroic or instanceDifficultyID == DifficultyUtil.ID.Raid25Heroic;
			if validHeroicSize and compareDifficultyID == DifficultyUtil.ID.PrimaryRaidHeroic then
				return true;
			end
		elseif instanceDifficultyID == compareDifficultyID then
			return true;
		end
	elseif raidDifficultyID == compareDifficultyID then
		return true;
	end
	return false;
end

function DifficultyUtil.IsRaidDifficultyEnabled(compareDifficultyID)
	if IsInInstance() then
		return false;
	end

	if IsInGroup() and not UnitIsGroupLeader("player") then
		return false;
	end

	if IsInGroup(LE_PARTY_CATEGORY_INSTANCE) then
		return false;
	end

	local difficultyID, _, _, _, isDynamicInstance = select(3, GetInstanceInfo());
	if isDynamicInstance and CanChangePlayerDifficulty() then
		local toggleDifficultyID = select(7, GetDifficultyInfo(difficultyID));
		if toggleDifficultyID then
			return CheckToggleDifficulty(toggleDifficultyID, compareDifficultyID);
		end
	end

	return true;
end

function DifficultyUtil.IsDungeonDifficultyEnabled(difficultyID)
	-- difficultyID not currently checked. Dungeon difficulties are collectively enabled or disabled.
	local inInstance, instanceType = IsInInstance();
	if inInstance then
		return false;
	end

	if instanceType == "raid" then
		return false;
	end

	if IsInGroup() and not UnitIsGroupLeader("player") then
		return false;
	end

	return not UnitPopupSharedUtil.HasLFGRestrictions();
end

local difficultyToMaxPlayersMap = { };
function DifficultyUtil.GetMaxPlayers(difficultyID)
	local maxPlayers = difficultyToMaxPlayersMap[difficultyID];
	if not maxPlayers then
		maxPlayers = select(10, GetDifficultyInfo(difficultyID));
		difficultyToMaxPlayersMap[difficultyID] = maxPlayers;
	end
	return maxPlayers;
end

function DifficultyUtil.GetWorldTierDifficultyName()
	if not DifficultyUtil.WorldTierDifficultyNames then
		return nil;
	end

	local worldTierDifficulty = C_DelvesUI.GetWorldTierDifficultyForActivePlayer();
	return DifficultyUtil.WorldTierDifficultyNames[worldTierDifficulty];
end]] },
{ 'Blizzard_FrameXMLUtil\\Mainline\\DifficultyUtil.lua', [[
function DifficultyUtil.GetDifficultyColor(difficulty)
	if (difficulty == Enum.RelativeContentDifficulty.Trivial) then
		return QuestDifficultyColors["trivial"], QuestDifficultyHighlightColors["trivial"];
	elseif (difficulty == Enum.RelativeContentDifficulty.Easy) then
		return QuestDifficultyColors["standard"], QuestDifficultyHighlightColors["standard"];
	elseif (difficulty == Enum.RelativeContentDifficulty.Fair) then
		return QuestDifficultyColors["difficult"], QuestDifficultyHighlightColors["difficult"];
	elseif (difficulty == Enum.RelativeContentDifficulty.Difficult) then
		return QuestDifficultyColors["verydifficult"], QuestDifficultyHighlightColors["verydifficult"];
	elseif (difficulty == Enum.RelativeContentDifficulty.Impossible) then
		return QuestDifficultyColors["impossible"], QuestDifficultyHighlightColors["impossible"];
	else
		return QuestDifficultyColors["difficult"], QuestDifficultyHighlightColors["difficult"];
	end
end

function DifficultyUtil.GetQuestDifficultyColor(level, isScaling, optQuestID)
	if optQuestID and C_QuestLog.IsQuestDisabledForSession(optQuestID) then
		return QuestDifficultyColors["disabled"], QuestDifficultyHighlightColors["disabled"];
	end

	if (isScaling) then
		return DifficultyUtil.GetScalingQuestDifficultyColor(level);
	end

	return DifficultyUtil.GetRelativeDifficultyColor(UnitEffectiveLevel("player"), level);
end

function DifficultyUtil.GetCreatureDifficultyColor(level)
	return DifficultyUtil.GetRelativeDifficultyColor(UnitEffectiveLevel("player"), level);
end

function DifficultyUtil.GetRelativeDifficultyColor(unitLevel, challengeLevel)
	local levelDiff = challengeLevel - unitLevel;
	if ( levelDiff >= 5 ) then
		return QuestDifficultyColors["impossible"], QuestDifficultyHighlightColors["impossible"];
	elseif ( levelDiff >= 3 ) then
		return QuestDifficultyColors["verydifficult"], QuestDifficultyHighlightColors["verydifficult"];
	elseif ( levelDiff >= -4 ) then
		return QuestDifficultyColors["difficult"], QuestDifficultyHighlightColors["difficult"];
	elseif ( -levelDiff <= UnitQuestTrivialLevelRange("player") ) then
		return QuestDifficultyColors["standard"], QuestDifficultyHighlightColors["standard"];
	else
		return QuestDifficultyColors["trivial"], QuestDifficultyHighlightColors["trivial"];
	end
end

function DifficultyUtil.GetScalingQuestDifficultyColor(questLevel)
	local playerLevel = UnitEffectiveLevel("player");
	local levelDiff = questLevel - playerLevel;
	if ( levelDiff >= 5 ) then
		return QuestDifficultyColors["impossible"], QuestDifficultyHighlightColors["impossible"];
	elseif ( levelDiff >= 3 ) then
		return QuestDifficultyColors["verydifficult"], QuestDifficultyHighlightColors["verydifficult"];
	elseif ( levelDiff >= 0 ) then
		return QuestDifficultyColors["difficult"], QuestDifficultyHighlightColors["difficult"];
	elseif ( -levelDiff <= UnitQuestTrivialLevelRangeScaling("player") ) then
		return QuestDifficultyColors["standard"], QuestDifficultyHighlightColors["standard"];
	else
		return QuestDifficultyColors["trivial"], QuestDifficultyHighlightColors["trivial"];
	end
end

function GetDifficultyColor(difficulty)
	return DifficultyUtil.GetDifficultyColor(difficulty);
end

function GetQuestDifficultyColor(level, isScaling, optQuestID)
	return DifficultyUtil.GetQuestDifficultyColor(level, isScaling, optQuestID);
end

function GetCreatureDifficultyColor(level)
	return DifficultyUtil.GetCreatureDifficultyColor(level);
end

function GetRelativeDifficultyColor(unitLevel, challengeLevel)
	return DifficultyUtil.GetRelativeDifficultyColor(unitLevel, challengeLevel);
end

function GetScalingQuestDifficultyColor(questLevel)
	return DifficultyUtil.GetScalingQuestDifficultyColor(questLevel);
end]] },
{ 'Blizzard_FrameXMLUtil\\RenownRewardUtil.lua', [[
RenownRewardUtil = {};

function RenownRewardUtil.GetRenownRewardDisplayData(rewardInfo, onItemUpdateCallback)
	if not rewardInfo then
		return;
	end

	if rewardInfo.itemID then
		local item = Item:CreateFromItemID(rewardInfo.itemID);
		local icon, name;
		if item:IsItemDataCached() then
			icon = item:GetItemIcon();
			name = item:GetItemName();
		else
			item:ContinueOnItemLoad(onItemUpdateCallback);
		end
		return icon, name, RENOWN_REWARD_ITEM_NAME_FORMAT, RENOWN_REWARD_ITEM_DESCRIPTION;
	elseif rewardInfo.mountID then
		local name, spellID, icon = C_MountJournal.GetMountInfoByID(rewardInfo.mountID);
		return icon, name, RENOWN_REWARD_MOUNT_NAME_FORMAT, RENOWN_REWARD_MOUNT_DESCRIPTION;
	elseif rewardInfo.spellID then
		local spellInfo = C_Spell.GetSpellInfo(rewardInfo.spellID);
		return spellInfo.iconID, spellInfo.name, RENOWN_REWARD_SPELL_NAME_FORMAT, RENOWN_REWARD_SPELL_DESCRIPTION;
	elseif rewardInfo.titleMaskID then
		local name = TitleUtil.GetNameFromTitleMaskID(rewardInfo.titleMaskID);
		return nil, name, RENOWN_REWARD_TITLE_NAME_FORMAT, RENOWN_REWARD_TITLE_DESCRIPTION;
	elseif rewardInfo.transmogID then
		local itemID = C_Transmog.GetItemIDForSource(rewardInfo.transmogID);
		local item = Item:CreateFromItemID(itemID);
		local icon, name;
		if item:IsItemDataCached() then
			icon = item:GetItemIcon();
			name = item:GetItemName();
		else
			item:ContinueOnItemLoad(onItemUpdateCallback);
		end
		return icon, name, RENOWN_REWARD_TRANSMOG_NAME_FORMAT, RENOWN_REWARD_TRANSMOG_DESCRIPTION;
	elseif rewardInfo.transmogSetID then
		local icon = TransmogUtil.GetSetIcon(rewardInfo.transmogSetID);
		local setInfo = C_TransmogSets.GetSetInfo(rewardInfo.transmogSetID);
		if setInfo then
			return icon, setInfo.name, RENOWN_REWARD_TRANSMOGSET_NAME_FORMAT, RENOWN_REWARD_TRANSMOGSET_DESCRIPTION;
		end
	elseif rewardInfo.garrFollowerID then
		local followerInfo = C_Garrison.GetFollowerInfo(rewardInfo.garrFollowerID);
		return followerInfo.portraitIconID, followerInfo.name, RENOWN_REWARD_FOLLOWER_NAME_FORMAT, RENOWN_REWARD_FOLLOWER_DESCRIPTION;
	elseif rewardInfo.transmogIllusionSourceID then
		local illusionInfo = C_TransmogCollection.GetIllusionInfo(rewardInfo.transmogIllusionSourceID);
		if illusionInfo then
			local name = C_TransmogCollection.GetIllusionStrings(rewardInfo.transmogIllusionSourceID);
			return illusionInfo.icon, name, RENOWN_REWARD_ILLUSION_NAME_FORMAT, RENOWN_REWARD_ILLUSION_DESCRIPTION;
		end
	end
end

function RenownRewardUtil.GetUnformattedRenownRewardInfo(rewardInfo, onItemUpdateCallback)
	if not rewardInfo then
		return;
	end

	local icon, name, formatString, description = RenownRewardUtil.GetRenownRewardDisplayData(rewardInfo, onItemUpdateCallback);
	return (rewardInfo.icon or icon), (rewardInfo.name or name), formatString, (rewardInfo.description or description);
end

function RenownRewardUtil.GetRenownRewardInfo(rewardInfo, onItemUpdateCallback)
	if not rewardInfo then
		return;
	end

	local icon, name, formatString, description = RenownRewardUtil.GetUnformattedRenownRewardInfo(rewardInfo, onItemUpdateCallback);
	return icon, name and formatString and formatString:format(name) or name, description;
end

function RenownRewardUtil.AddRenownRewardsToTooltip(tooltip, renownRewards, callback)
	GameTooltip_AddHighlightLine(GameTooltip, MAJOR_FACTION_BUTTON_TOOLTIP_NEXT_REWARDS);

	for i, rewardInfo in ipairs(renownRewards) do
		local renownRewardString;
		local icon, name = RenownRewardUtil.GetRenownRewardInfo(rewardInfo, callback);
		if icon then
			local file, width, height = icon, 16, 16;
			local rewardTexture = CreateSimpleTextureMarkup(file, width, height);
			renownRewardString = rewardTexture .. " " .. name;
		end
		local wrapText = false;
		GameTooltip_AddNormalLine(tooltip, renownRewardString, wrapText);
	end
end

-- Adds a quick summary of your current progress with the faction
-- Used in the Expansion Landing Page
function RenownRewardUtil.AddMajorFactionLandingPageSummaryToTooltip(tooltip, factionID, callback)
	callback = callback or nop;

	local majorFactionData = C_MajorFactions.GetMajorFactionData(factionID);
	if not majorFactionData then
		return;
	end

	GameTooltip_SetTitle(tooltip, majorFactionData.name, HIGHLIGHT_FONT_COLOR);
	ReputationUtil.TryAppendAccountReputationLineToTooltip(GameTooltip, factionID);
	if not C_MajorFactions.HasMaximumRenown(factionID) then
		GameTooltip_AddNormalLine(tooltip, MAJOR_FACTION_RENOWN_CURRENT_PROGRESS:format(majorFactionData.renownReputationEarned, majorFactionData.renownLevelThreshold));
		GameTooltip_AddBlankLineToTooltip(tooltip);
		local nextRenownRewards = C_MajorFactions.GetRenownRewardsForLevel(factionID, C_MajorFactions.GetCurrentRenownLevel(factionID) + 1);
		if #nextRenownRewards > 0 then
			RenownRewardUtil.AddRenownRewardsToTooltip(tooltip, nextRenownRewards, callback);
			GameTooltip_AddBlankLineToTooltip(tooltip);
		end
	end
end

-- Adds an overview of your progress with the faction, with details on how the renown system works
-- Used in the Reputation Panel and Encounter Journal
function RenownRewardUtil.AddMajorFactionToTooltip(tooltip, factionID, callback)
	callback = callback or nop;

	local majorFactionData = C_MajorFactions.GetMajorFactionData(factionID);
	if not majorFactionData then
		return;
	end

	GameTooltip_SetTitle(tooltip, majorFactionData.name, HIGHLIGHT_FONT_COLOR);
	ReputationUtil.TryAppendAccountReputationLineToTooltip(tooltip, majorFactionData.factionID);
	GameTooltip_AddHighlightLine(tooltip, RENOWN_LEVEL_LABEL:format(majorFactionData.renownLevel));

	GameTooltip_AddBlankLineToTooltip(tooltip);
	GameTooltip_AddNormalLine(tooltip, MAJOR_FACTION_RENOWN_TOOLTIP_PROGRESS:format(majorFactionData.name));
	GameTooltip_AddBlankLineToTooltip(tooltip);

	local nextRenownRewards = C_MajorFactions.GetRenownRewardsForLevel(majorFactionData.factionID, C_MajorFactions.GetCurrentRenownLevel(majorFactionData.factionID) + 1);
	if #nextRenownRewards > 0 then
		RenownRewardUtil.AddRenownRewardsToTooltip(tooltip, nextRenownRewards, callback);
	end
end
]] },
