{ 'Blizzard_FrameXMLUtil\\AdventureGuideUtil.lua', [[

-- A note on naming:
-- Adventure Guide refers to the UI panel that contains:
-- C_AdventureJournal for the "suggested content" tab
-- C_EncounterJournal is for dungeons and raids tabs
-- C_PerksActivities is for traveler's log tab

AdventureGuideUtil = {};

function AdventureGuideUtil.IsAvailable()
	return not Kiosk.IsEnabled() and C_AdventureJournal.CanBeShown();
end

function AdventureGuideUtil.OpenHyperLink(tag, journalType, id, difficultyID)
	if not AdventureGuideUtil.IsAvailable() then
		return;
	end

	AdventureGuideUtil.OpenJournalLink(tonumber(journalType), tonumber(id), tonumber(difficultyID));
end

function AdventureGuideUtil.OpenJournalLink(journalType, id, difficultyID)
	if not EncounterJournal then
		EncounterJournal_LoadUI();
	end

	local instanceID, encounterID, sectionID, tierIndex = EJ_HandleLinkPath(journalType, id);
	EncounterJournal_OpenJournal(difficultyID, instanceID, encounterID, sectionID, nil, nil, tierIndex);
end

function AdventureGuideUtil.GetCurrentJournalInstance()
	local currentMapID = select(8, GetInstanceInfo());
	return currentMapID and C_EncounterJournal.GetInstanceForGameMap(currentMapID) or nil;
end

function AdventureGuideUtil.IsInInstance(journalInstanceID)
	local journalInstanceMapID = select(10, EJ_GetInstanceInfo(journalInstanceID));
	local currentMapID = select(8, GetInstanceInfo());
	return journalInstanceMapID == currentMapID;
end
]] },
{ 'Blizzard_FrameXMLUtil\\ProfessionsUtil.lua', [[
ProfessionsUtil = {};

do
	local function Matches(lhs, rhs)
		return lhs and (lhs ~= 0) and (lhs == rhs);
	end
	
	function ProfessionsUtil.CraftingReagentMatches(reagent1, reagent2)
		return Matches(reagent1.itemID, reagent2.itemID) or 
			Matches(reagent1.currencyID, reagent2.currencyID);
	end
end

do
	-- Returns the quantity required by the slot, or a variable quantity determined by
	-- the reagent.
	local function GetQuantityRequired(reagentSlotSchematic, reagent)
		for index, variableQuantity in ipairs(reagentSlotSchematic.variableQuantities) do
			if ProfessionsUtil.CraftingReagentMatches(reagent, variableQuantity.reagent) then
				return variableQuantity.quantity;
			end
		end

		return reagentSlotSchematic.quantityRequired;
	end

	local function HasVariableQuantities(reagentSlotSchematic)
		return #reagentSlotSchematic.variableQuantities > 0;
	end

	local function IsVariableQuantityReagent(reagentSlotSchematic, reagent)
		for index, variableQuantity in ipairs(reagentSlotSchematic.variableQuantities) do
			if ProfessionsUtil.CraftingReagentMatches(reagent, reagent) then
				return true;
			end
		end
		return false;
	end

	local function GetVariableQuantityRange(reagentSlotSchematic, reagent)
		local min, max = math.huge, 0;
		for index, variableQuantity in ipairs(reagentSlotSchematic.variableQuantities) do
			local quantity = variableQuantity.quantity;
			min = math.min(min, quantity);
			max = math.max(max, quantity)
		end
		return min, max;
	end

	function ProfessionsUtil.GetRecipeSchematic(...)
		local recipeSchematic = C_TradeSkillUI.GetRecipeSchematic(...);
	
		for slotIndex, reagentSlotSchematic in ipairs(recipeSchematic.reagentSlotSchematics) do
			reagentSlotSchematic.GetQuantityRequired = GetQuantityRequired;
			reagentSlotSchematic.HasVariableQuantities = HasVariableQuantities;
			reagentSlotSchematic.IsVariableQuantityReagent = IsVariableQuantityReagent;
			reagentSlotSchematic.GetVariableQuantityRange = GetVariableQuantityRange;
		end
	
		return recipeSchematic;
	end
end

local isCraftingMinimized = false;
function ProfessionsUtil.SetCraftingMinimized(minimized)
	local changed = isCraftingMinimized ~= minimized;
	isCraftingMinimized = minimized;

	if changed then
		EventRegistry:TriggerEvent("ProfessionsFrame.Minimized");
	end
end

function ProfessionsUtil.IsCraftingMinimized()
	return isCraftingMinimized;
end

function ProfessionsUtil.OpenProfessionFrameToRecipe(recipeID)
    local tradeSkillID, skillLineName, parentTradeSkillID = C_TradeSkillUI.GetTradeSkillLineForRecipe(recipeID);
    if tradeSkillID then
        local skillLineID = tradeSkillID;
        tradeSkillID = parentTradeSkillID or tradeSkillID;

        ProfessionsFrame_LoadUI();

        local currBaseProfessionInfo = C_TradeSkillUI.GetBaseProfessionInfo();
        local currentSkillLineInfo = C_TradeSkillUI.GetChildProfessionInfo();
        if currentSkillLineInfo ~= nil and currentSkillLineInfo.professionID == skillLineID then
            local recipeInfo = C_TradeSkillUI.GetRecipeInfo(recipeID);
            ProfessionsFrame:SetTab(ProfessionsFrame.recipesTabID);
            EventRegistry:TriggerEvent("ProfessionsRecipeListMixin.Event.OnRecipeSelected", recipeInfo, nilRecipeList);
            return true;
        elseif currBaseProfessionInfo ~= nil and currBaseProfessionInfo.professionID == tradeSkillID then
            C_TradeSkillUI.SetProfessionChildSkillLineID(skillLineID);
            local professionInfo = C_TradeSkillUI.GetChildProfessionInfo();
            professionInfo.openRecipeID = recipeID;
            EventRegistry:TriggerEvent("Professions.ProfessionSelected", professionInfo);
            return true;
        else
            ProfessionsFrame:SetOpenRecipeResponse(skillLineID, recipeID);
            return C_TradeSkillUI.OpenTradeSkill(tradeSkillID);
        end
    end
    return false;
end

function ProfessionsUtil.CreateRecipeReagentListByPredicate(recipeID, predicate)
	local reagents = {};
	local isRecraft = false;
	local recipeSchematic = ProfessionsUtil.GetRecipeSchematic(recipeID, isRecraft);
	for _, reagentSlotSchematic in ipairs(recipeSchematic.reagentSlotSchematics) do
		if predicate(reagentSlotSchematic) then
			tAppendAll(reagents, reagentSlotSchematic.reagents);
		end
	end
	return reagents;
end

function ProfessionsUtil.CreateRecipeReagentsForAllBasicReagents(recipeID, predicate)
	local function IsBasicReagent(reagentSlotSchematic)
		return reagentSlotSchematic.reagentType == Enum.CraftingReagentType.Basic;
	end
	return ProfessionsUtil.CreateRecipeReagentListByPredicate(recipeID, IsBasicReagent);
end

-- This is wrapped in a function because the implementation backing "required" here is likely to change
-- after a planned slot description refactor.
function ProfessionsUtil.IsReagentSlotRequired(reagentSlotSchematic)
	return reagentSlotSchematic.required;
end

function ProfessionsUtil.IsReagentSlotBasicRequired(reagentSlotSchematic)
	return reagentSlotSchematic.reagentType == Enum.CraftingReagentType.Basic and ProfessionsUtil.IsReagentSlotRequired(reagentSlotSchematic);
end

function ProfessionsUtil.IsReagentSlotModifyingRequired(reagentSlotSchematic)
	return reagentSlotSchematic.reagentType == Enum.CraftingReagentType.Modifying and ProfessionsUtil.IsReagentSlotRequired(reagentSlotSchematic);
end

function ProfessionsUtil.GetReagentQuantityInPossession(reagent, characterInventoryOnly)
	if reagent.itemID then
		return ItemUtil.GetCraftingReagentCount(reagent.itemID, characterInventoryOnly);
	elseif reagent.currencyID then
		local currencyInfo = C_CurrencyInfo.GetCurrencyInfo(reagent.currencyID);
		return currencyInfo.quantity;
	end
	assert(false);
end

function ProfessionsUtil.AccumulateReagentsInPossession(reagents, characterInventoryOnly)
	return AccumulateOp(reagents, function(reagent)
		return ProfessionsUtil.GetReagentQuantityInPossession(reagent, characterInventoryOnly);
	end);
end

function ProfessionsUtil.CreateProfessionsRecipeTransactionFromCraftingOrder(order)
	local recipeSchematic = ProfessionsUtil.GetRecipeSchematic(order.spellID, order.isRecraft);
	local transaction = CreateProfessionsRecipeTransaction(recipeSchematic);
	for _, reagentInfo in ipairs(order.reagents) do
		local allocations = transaction:GetAllocations(reagentInfo.slotIndex);
		allocations:Allocate(reagentInfo.reagentInfo.reagent, reagentInfo.reagentInfo.quantity);
	end
	return transaction;
end
]] },
{ 'Blizzard_FrameXMLUtil\\CampaignUtil.lua', [[
CampaignUtil = {};

function CampaignUtil.BuildChapterProgressText(campaign, formatString, canHideChapters, hideChaptersFormatString)
	local chapterCount = campaign:GetChapterCount();
	local completedChapterCount = campaign:GetCompletedChapterCount();

	if canHideChapters and campaign.hideFutureChapters then
		local percentage = 0;
		if chapterCount > 0 then
			percentage = math.floor((completedChapterCount / chapterCount) * 100);
		end
		return (hideChaptersFormatString or formatString or CAMPAIGN_PROGRESS_CHAPTERS_PERCENT):format(percentage);
	else
		return (formatString or CAMPAIGN_PROGRESS_CHAPTERS):format(completedChapterCount, chapterCount);
	end
end

function CampaignUtil.GetSingleChapterText(chapterID, lineSpacing, hideFutureChapters)
	local chapter = CampaignChapterCache:Get(chapterID);
	if chapter:IsComplete() then
		return CreateTextureMarkup("Interface/Scenarios/ScenarioIcon-Check", 16, 16, 16, 16, 0, 1, 0, 1, 0, -lineSpacing) .. " " .. GREEN_FONT_COLOR:WrapTextInColorCode(chapter.name);
	else
		local isInProgress = chapter:IsInProgress();
		if not isInProgress and hideFutureChapters then
			return nil;
		else
			local color = isInProgress and HIGHLIGHT_FONT_COLOR or LIGHTGRAY_FONT_COLOR;
			return color:WrapTextInColorCode(chapter.name);
		end
	end
end

function CampaignUtil.BuildAllChaptersText(campaign, lineSpacing, canHideChapters)
	local hideFutureChapters = canHideChapters and campaign.hideFutureChapters;
	local chapterText = {};
	for index, chapterID in ipairs(campaign.chapterIDs) do
		table.insert(chapterText, CampaignUtil.GetSingleChapterText(chapterID, lineSpacing, hideFutureChapters));
	end

	-- show at least 1 chapter
	if #chapterText == 0 and hideFutureChapters and campaign:GetChapterCount() > 0 then
		local chapterID = campaign.chapterIDs[1];
		table.insert(chapterText, CampaignUtil.GetSingleChapterText(chapterID, lineSpacing));
	end

	return table.concat(chapterText, "\n");
end
]] },
{ 'Blizzard_FrameXMLUtil\\CollectionsUtil.lua', [[
CollectionWardrobeUtil = {};

function CollectionWardrobeUtil.GetDefaultSourceIndex(sources, primarySourceID)
	local collectedSourceIndex;
	local unusableSourceIndex;
	local uncollectedSourceIndex;
	-- default sourceIndex is, in order of preference:
	-- 1. primarySourceID, if collected and usable
	-- 2. collected and usable
	-- 3. unusable primarySourceID
	-- 4. unusable
	-- 5. uncollected primarySourceID
	-- 6. uncollected
	for i, sourceInfo in ipairs(sources) do
		if ( sourceInfo.isCollected ) then
			if sourceInfo.useError then
				if not unusableSourceIndex or primarySourceID == sourceInfo.sourceID then
					unusableSourceIndex = i;
				end
			else
				if primarySourceID == sourceInfo.sourceID then
					-- found #1
					collectedSourceIndex = i;
					break;
				elseif not collectedSourceIndex then
					collectedSourceIndex = i;
					if primarySourceID == Constants.Transmog.NoTransmogID then
						-- done
						break;
					end
				end
			end
		else
			if not uncollectedSourceIndex or primarySourceID == sourceInfo.sourceID then
				uncollectedSourceIndex = i;
			end
		end
	end
	return collectedSourceIndex or unusableSourceIndex or uncollectedSourceIndex or 1;
end

function CollectionWardrobeUtil.SortSources(sources, primaryVisualID, primarySourceID)
	local comparison = function(source1, source2)
		-- if a primary visual is given, sources for that are grouped by themselves above all others
		if ( primaryVisualID and source1.visualID ~= source2.visualID ) then
			return source1.visualID == primaryVisualID;
		end

		if source1.isCollected ~= source2.isCollected then
			return source1.isCollected;
		end

		if source1.isValidSourceForPlayer ~= source2.isValidSourceForPlayer then
			return source1.isValidSourceForPlayer;
		end

		if primarySourceID then
			local source1IsPrimary = (source1.sourceID == primarySourceID);
			local source2IsPrimary = (source2.sourceID == primarySourceID);
			if source1IsPrimary ~= source2IsPrimary then
				return source1IsPrimary;
			end
		end

		if source1.quality and source2.quality then
			if source1.quality ~= source2.quality then
				return source1.quality > source2.quality;
			end
		else
			return source1.quality;
		end

		return source1.sourceID > source2.sourceID;
	end
	table.sort(sources, comparison);
	return sources;
end

function CollectionWardrobeUtil.GetSortedAppearanceSources(visualID, category, transmogLocation)
	local sources = C_TransmogCollection.GetAppearanceSources(visualID, category, transmogLocation:GetData());
	assertsafe(sources ~= nil, "No appearance sources found for visualID %d", visualID);

	if sources == nil then
		sources = {};
		return sources;
	end

	return CollectionWardrobeUtil.SortSources(sources);
end

function CollectionWardrobeUtil.GetSortedAppearanceSourcesForClass(visualID, classID, category, transmogLocation)
	local sources = C_TransmogCollection.GetValidAppearanceSourcesForClass(visualID, classID, category, transmogLocation:GetData());
	assertsafe(sources ~= nil, "No appearance sources found for visualID %d, classID %d", visualID, classID);

	if sources == nil then
		sources = {};
		return sources;
	end

	return CollectionWardrobeUtil.SortSources(sources);
end

function CollectionWardrobeUtil.GetSlotFromCategoryID(categoryID)
	local slot;
	for key, transmogSlot in pairs(TRANSMOG_SLOTS) do
		if categoryID == transmogSlot.armorCategoryID then
			slot = transmogSlot.location:GetSlotName();
			break;
		end
	end
	if not slot then
		local name, isWeapon, canEnchant, canMainHand, canOffHand = C_TransmogCollection.GetCategoryInfo(categoryID);
		if canMainHand then
			slot = "MAINHANDSLOT";
		elseif canOffHand then
			slot = "SECONDARYHANDSLOT";
		end
	end
	return slot;
end

function CollectionWardrobeUtil.GetValidIndexForNumSources(index, numSources)
	index = index - 1;
	if index < 0 then
		index = numSources + index;
	end
	return mod(index, numSources) + 1;
end

function CollectionWardrobeUtil.GetAppearanceNameTextAndColor(appearanceInfo, inLegionArtifactCategory)
	local text, color;
	if appearanceInfo.name then
		text = appearanceInfo.name;

		local colorData = ColorManager.GetColorDataForItemQuality(appearanceInfo.quality);
		if colorData then
			color = colorData.color;
		else
			color = WHITE_FONT_COLOR;
		end
	else
		text = RETRIEVING_ITEM_INFO;
		color = RED_FONT_COLOR;
	end
	if inLegionArtifactCategory then
		local artifactName = C_TransmogCollection.GetArtifactAppearanceStrings(appearanceInfo.sourceID);
		if artifactName then
			text = artifactName;
		end
	end
	return text, color;
end

function CollectionWardrobeUtil.GetAppearanceSourceTextAndColor(appearanceInfo)
	local text, color;
	if appearanceInfo.isCollected then
		text = TRANSMOG_COLLECTED;
		color = GREEN_FONT_COLOR;
	else
		if appearanceInfo.sourceType then
			text = _G["TRANSMOG_SOURCE_"..appearanceInfo.sourceType];
		elseif not appearanceInfo.name then
			text = "";
		end
		color = HIGHLIGHT_FONT_COLOR;
	end
	return text, color;
end

function CollectionWardrobeUtil.IsAppearanceUsable(appearanceInfo, inLegionArtifactCategory)
	if not appearanceInfo.useErrorType then
		return true;
	end
	if appearanceInfo.useErrorType == Enum.TransmogUseErrorType.ArtifactSpec then
		-- artifact appearances don't need to match spec when in normal weapon categories
		return not inLegionArtifactCategory;
	end
	return false;
end

function CollectionWardrobeUtil.SetAppearanceTooltip(tooltip, appearanceData)
	local sources = appearanceData.sources;
	local primarySourceID = appearanceData.primarySourceID;
	local selectedIndex = appearanceData.selectedIndex
	local showUseError = appearanceData.showUseError;
	local inLegionArtifactCategory = appearanceData.inLegionArtifactCategory;
	local subheaderString = appearanceData.subheaderString;
	local warningString = appearanceData.warningString;
	local showTrackingInfo = appearanceData.showTrackingInfo;
	local slotType = appearanceData.slotType;

	local canCycle = false;
	for i = 1, #sources do
		if sources[i].isHideVisual then
			GameTooltip_SetTitle(tooltip, sources[i].name, NORMAL_FONT_COLOR);
			tooltip:Show();
			return;
		end
	end

	local firstVisualID = sources[1].visualID;
	local passedFirstVisualID = false;

	local headerIndex;
	if not selectedIndex then
		headerIndex = CollectionWardrobeUtil.GetDefaultSourceIndex(sources, primarySourceID);
	else
		headerIndex = CollectionWardrobeUtil.GetValidIndexForNumSources(selectedIndex, #sources);
	end
	local headerSourceID = sources[headerIndex].sourceID;

	local name, nameColor = CollectionWardrobeUtil.GetAppearanceNameTextAndColor(sources[headerIndex], inLegionArtifactCategory);
	local sourceText, sourceColor = CollectionWardrobeUtil.GetAppearanceSourceTextAndColor(sources[headerIndex]);
	GameTooltip_SetTitle(tooltip, name, nameColor);
	if subheaderString then
		GameTooltip_AddHighlightLine(tooltip, subheaderString);
	end

	if slotType then
		GameTooltip_AddNormalLine(tooltip, slotType);
	end

	local sourceLocation, sourceDifficulties;

	local appearanceCollected = sources[headerIndex].isCollected
	if sources[headerIndex].sourceType == TRANSMOG_SOURCE_BOSS_DROP and not appearanceCollected then
		local drops = C_TransmogCollection.GetAppearanceSourceDrops(headerSourceID);
		if drops and #drops > 0 then
			local showDifficulty = false;
			if #drops == 1 then
				sourceLocation = WARDROBE_TOOLTIP_ENCOUNTER_SOURCE:format(drops[1].encounter, drops[1].instance);
				showDifficulty = true;
			else
				-- check if the drops are the same instance
				local sameInstance = true;
				local firstInstance = drops[1].instance;
				for i = 2, #drops do
					if drops[i].instance ~= firstInstance then
						sameInstance = false;
						break;
					end
				end
				-- ok, if multiple instances check if it's the same tier if the drops have a single tier
				local sameTier = true;
				local firstTier = drops[1].tiers[1];
				if not sameInstance and #drops[1].tiers == 1 then
					for i = 2, #drops do
						if #drops[i].tiers > 1 or drops[i].tiers[1] ~= firstTier then
							sameTier = false;
							break;
						end
					end
				end
				-- if same instance or tier, check if we have same difficulties and same instanceType
				local sameDifficulty = false;
				local sameInstanceType = false;
				if sameInstance or sameTier then
					sameDifficulty = true;
					sameInstanceType = true;
					for i = 2, #drops do
						if drops[1].instanceType ~= drops[i].instanceType then
							sameInstanceType = false;
						end
						if #drops[1].difficulties ~= #drops[i].difficulties then
							sameDifficulty = false;
						else
							for j = 1, #drops[1].difficulties do
								if drops[1].difficulties[j] ~= drops[i].difficulties[j] then
									sameDifficulty = false;
									break;
								end
							end
						end
					end
				end
				-- override sourceText if sameInstance or sameTier
				if sameInstance then
					sourceLocation = firstInstance;
					showDifficulty = sameDifficulty;
				elseif sameTier then
					local location = firstTier;
					if sameInstanceType then
						if drops[1].instanceType == INSTANCE_TYPE_DUNGEON then
							location = string.format(WARDROBE_TOOLTIP_DUNGEONS, location);
						elseif drops[1].instanceType == INSTANCE_TYPE_RAID then
							location = string.format(WARDROBE_TOOLTIP_RAIDS, location);
						end
					end
					sourceLocation = location;
				end
			end

			if showDifficulty then
				local drop = drops[1];
				if drop.difficulties[1] then
					sourceDifficulties = table.concat(drop.difficulties, PLAYER_LIST_DELIMITER);
				end
			end
		end
	end

	if warningString then
		GameTooltip_AddNormalLine(tooltip, warningString);
	end

	local useError;
	if showUseError and not CollectionWardrobeUtil.IsAppearanceUsable(sources[headerIndex], inLegionArtifactCategory) then
		useError = sources[headerIndex].useError;
		GameTooltip_AddErrorLine(tooltip, useError);
	end

	if not appearanceCollected then
		if sourceLocation then
			if sourceDifficulties then
				sourceText = WARDROBE_TOOLTIP_BOSS_DROP_FORMAT_WITH_DIFFICULTIES:format(sourceLocation, sourceDifficulties);
			else
				sourceText = WARDROBE_TOOLTIP_BOSS_DROP_FORMAT:format(sourceLocation);
			end
		end
		GameTooltip_AddColoredLine(tooltip, sourceText, sourceColor);
	end

	if #sources > 1 and not appearanceCollected then
		-- only add "Other items using this appearance" if we're continuing to the same visualID
		if firstVisualID == sources[2].visualID then
			GameTooltip_AddBlankLineToTooltip(tooltip);
			GameTooltip_AddNormalLine(tooltip, WARDROBE_OTHER_ITEMS);
		end
		for i = 1, #sources do
			-- first time we transition to a different visualID, add "Other items that unlock this slot"
			if not passedFirstVisualID and firstVisualID ~= sources[i].visualID then
				passedFirstVisualID = true;
				GameTooltip_AddBlankLineToTooltip(tooltip);
				GameTooltip_AddHighlightLine(tooltip, WARDROBE_ALTERNATE_ITEMS);
			end

			name, nameColor = CollectionWardrobeUtil.GetAppearanceNameTextAndColor(sources[i], inLegionArtifactCategory);
			sourceText, sourceColor = CollectionWardrobeUtil.GetAppearanceSourceTextAndColor(sources[i]);
			if i == headerIndex then
				name = WARDROBE_TOOLTIP_CYCLE_ARROW_ICON..name;
			else
				name = WARDROBE_TOOLTIP_CYCLE_SPACER_ICON..name;
			end
			if showTrackingInfo and ContentTrackingUtil.IsContentTrackingEnabled() and C_ContentTracking.IsTracking(Enum.ContentTrackingType.Appearance, sources[i].sourceID) then
				name = name..CreateAtlasMarkup("checkmark-minimal", 15, 15, 0, -2);
			end
			GameTooltip_AddColoredDoubleLine(tooltip, name, sourceText, nameColor, sourceColor);
		end
		if showTrackingInfo then
			GameTooltip_AddBlankLineToTooltip(tooltip);
			CollectionWardrobeUtil.AddTrackingTooltipLine(tooltip, sources[headerIndex].sourceID); 
		end
		GameTooltip_AddColoredLine(tooltip, WARDROBE_TOOLTIP_CYCLE, GRAY_FONT_COLOR);
		canCycle = true;
	else
		if showTrackingInfo then
			GameTooltip_AddBlankLineToTooltip(tooltip);
			CollectionWardrobeUtil.AddTrackingTooltipLine(tooltip, sources[headerIndex].sourceID);
		end
	end

	if appearanceCollected and not useError then
		if not C_Transmog.IsAtTransmogNPC() then
			GameTooltip_AddColoredLine(tooltip, WARDROBE_TOOLTIP_TRANSMOGRIFIER, GRAY_FONT_COLOR);
		end

		local holidayName = C_TransmogCollection.GetSourceRequiredHoliday(headerSourceID);
		if holidayName then
			GameTooltip_AddColoredLine(tooltip, TRANSMOG_APPEARANCE_USABLE_HOLIDAY:format(holidayName), LIGHTBLUE_FONT_COLOR);
		end
	end

	tooltip:Show();

    EventRegistry:TriggerEvent("CollectionWardrobe.SetAppearanceTooltip", tooltip, sources, primarySourceID, selectedIndex, showUseError, inLegionArtifactCategory, subheaderString);
	return headerIndex, canCycle;
end

function CollectionWardrobeUtil.AddTrackingTooltipLine(tooltip, sourceID)
	if ( not ContentTrackingUtil.IsContentTrackingEnabled() ) then
		GameTooltip_AddColoredLine(tooltip, CONTENT_TRACKING_DISABLED_TOOLTIP_PROMPT, GRAY_FONT_COLOR);
		return;
	end

	local hasData, canCollect = C_TransmogCollection.PlayerCanCollectSource(sourceID);
	if ( canCollect and C_ContentTracking.IsTrackable(Enum.ContentTrackingType.Appearance, sourceID) ) then
		if ( C_ContentTracking.IsTracking(Enum.ContentTrackingType.Appearance, sourceID) ) then
			GameTooltip_AddColoredLine(tooltip, CreateAtlasMarkup("waypoint-mappin-minimap-untracked", 16, 16, -3, 0)..CONTENT_TRACKING_UNTRACK_TOOLTIP_PROMPT, GREEN_FONT_COLOR);
		else
			GameTooltip_AddColoredLine(tooltip, CreateAtlasMarkup("waypoint-mappin-minimap-untracked", 16, 16, -3, 0)..CONTENT_TRACKING_TRACKABLE_TOOLTIP_PROMPT, GREEN_FONT_COLOR);
		end
	else
		GameTooltip_AddColoredLine(tooltip, CreateAtlasMarkup("waypoint-mappin-minimap-untracked", 16, 16, -3, 0, 120, 150, 180)..CONTENT_TRACKING_UNTRACKABLE_TOOLTIP_PROMPT, GRAY_FONT_COLOR);
	end
end
-- if the sourceID is not collectable, this will try to find a collectable one that has the same appearance
-- returns: preferredSourceID, hasAllDataAvailable, canCollect
-- if all data was not available, calling this after TRANSMOG_COLLECTION_ITEM_UPDATE and TRANSMOG_SOURCE_COLLECTABILITY_UPDATE events may result in a better sourceID returned
function CollectionWardrobeUtil.GetPreferredSourceID(initialSourceID, appearanceInfo, category, transmogLocation)
	if not appearanceInfo then
		appearanceInfo = C_TransmogCollection.GetAppearanceInfoBySource(initialSourceID);
	end

	local hasAllData = true;
	if not appearanceInfo then
		-- either uncollected with all sources HiddenUntilCollected or uncollectable
		local hasData, canCollect = C_TransmogCollection.PlayerCanCollectSource(initialSourceID);
		if canCollect then
			return initialSourceID, hasData, canCollect;
		end
		-- the initialSourceID is not collectable, try to find another one
		local appearanceSourceInfo = C_TransmogCollection.GetAppearanceSourceInfo(initialSourceID);
		if appearanceSourceInfo and appearanceSourceInfo.itemAppearanceID then
			local sourceIDs = C_TransmogCollection.GetAllAppearanceSources(appearanceSourceInfo.itemAppearanceID);
			for i, sourceID in pairs(sourceIDs) do
				-- we've already checked initialSourceID
				if sourceID ~= initialSourceID then
					hasData, canCollect = C_TransmogCollection.PlayerCanCollectSource(sourceID);
					if canCollect then
						return sourceID, hasData, canCollect;
					end
					if not hasData then
						hasAllData = false;
					end
				end
			end
		end
		-- couldn't find a valid one for player
		return initialSourceID, hasAllData, false;
	elseif not appearanceInfo.isAnySourceValidForPlayer then
		return initialSourceID, hasAllData, false;
	else
		-- if initialSourceID is known and the collection state matches, we're good
		if appearanceInfo.sourceIsKnown and appearanceInfo.appearanceIsCollected == appearanceInfo.sourceIsCollected then
			return initialSourceID, hasAllData, true;
		end
		-- If we're here, there are 2 possibilities:
		-- 1. the initialSourceID is not known (HiddenUntilCollected or not available to player)
		-- 2. the appearance is collected but the initialSourceID is not
		-- In either case, grab the first valid one from the list
		local sourceInfos = CollectionWardrobeUtil.GetSortedAppearanceSources(appearanceInfo.appearanceID, category, transmogLocation);
		for i, sourceInfo in ipairs(sourceInfos) do
			if not sourceInfo.name then
				hasAllData = false;
			end
		end
		return sourceInfos[1].sourceID, hasAllData, true;
	end
end

function CollectionWardrobeUtil.GetSlotVisibilityWarning(model, transmogLocation)
	if transmogLocation and model then
		local slotID = transmogLocation.slotID;
		if model:IsGeoReady() then
			local slotAllowed = model:IsSlotAllowed(slotID);
			if slotAllowed and not model:IsSlotVisible(slotID) then
				return TRANSMOG_DRACTHYR_APPEARANCE_INVISIBLE;
			elseif not slotAllowed and transmogLocation:GetArmorCategoryID() then
				return TRANSMOG_SLOT_APPEARANCE_INVISIBLE;
			end			
		end
	end
	return nil;
end

function CollectionWardrobeUtil.AreAllSourcesDisplayableOnPlayer(sources)
	if sources then
		for _index, sourceInfo in ipairs(sources) do
			if not sourceInfo.canDisplayOnPlayer then
				return false;
			end
		end
	end

	return true;
end

function CollectionWardrobeUtil.GetAppearanceVisibilityWarning(sources)
	if not CollectionWardrobeUtil.AreAllSourcesDisplayableOnPlayer(sources) then
		return TRANSMOG_SLOT_APPEARANCE_INVISIBLE;
	end

	return nil;
end

function CollectionWardrobeUtil.GetBestVisibilityWarning(model, transmogLocation, sources)
	return CollectionWardrobeUtil.GetAppearanceVisibilityWarning(sources) or CollectionWardrobeUtil.GetSlotVisibilityWarning(model, transmogLocation);
end

function CollectionWardrobeUtil.GetPage(entryIndex, pageSize)
	return floor((entryIndex-1) / pageSize) + 1;
end

function CollectionWardrobeUtil.GetAppearanceItemHyperlink(appearanceInfo, preferArtifact)
	local itemLink;

	local appearanceSourceInfo = C_TransmogCollection.GetAppearanceSourceInfo(appearanceInfo.sourceID);
	if appearanceSourceInfo then
		itemLink = appearanceSourceInfo.itemLink;
		if preferArtifact then
			local _artifactName, artifactLink = C_TransmogCollection.GetArtifactAppearanceStrings(appearanceInfo.sourceID);
			if artifactLink then
				itemLink = artifactLink;
			end
		end
	end

	return itemLink;
end]] },
{ 'Blizzard_FrameXMLUtil\\CurrencyUtil.lua', [[

CurrencyCallbackRegistry = CreateFromMixins(CallbackRegistryMixin);
CurrencyCallbackRegistry:GenerateCallbackEvents(
	{
		"OnCurrencyDisplayUpdate",
	}
);

function CurrencyCallbackRegistry:OnLoad()
	CallbackRegistryMixin.OnLoad(self);

	self.cachable = {};
	self.cvarValueCache = {};

	self:SetScript("OnEvent", self.OnEvent);

	self:RegisterEvent("CURRENCY_DISPLAY_UPDATE");
end

function CurrencyCallbackRegistry:OnEvent(event, ...)
	if event == "CURRENCY_DISPLAY_UPDATE" then
		local currency = ...;
		local args = select(2, ...);

		self:TriggerEvent(CurrencyCallbackRegistry.Event.OnCurrencyDisplayUpdate, currency, args);
		self:TriggerEvent(tostring(currency), args);
	end
end

function CurrencyCallbackRegistry:RegisterCurrencyDisplayUpdateCallback(func, owner, ...)
	return self:RegisterCallback(CVarCallbackRegistry.Event.OnCurrencyDisplayUpdate, func, owner, ...);
end

CurrencyCallbackRegistry = Mixin(CreateFrame("Frame"), CurrencyCallbackRegistry);
CurrencyCallbackRegistry:OnLoad();
CurrencyCallbackRegistry:SetUndefinedEventsAllowed(true);
]] },
{ 'Blizzard_FrameXMLUtil\\Mainline\\RAFUtil.lua', [[
RAFUtil = {};

local rafVersionColors = {
	[Enum.RecruitAFriendRewardsVersion.VersionTwo] = RAF_VERSION_TWO_COLOR,
	[Enum.RecruitAFriendRewardsVersion.VersionThree] = RAF_VERSION_THREE_COLOR,
};

