{ 'Blizzard_FrameXMLUtil\\Mainline\\Blizzard_QuestSuperTracking.lua', [[
local SuperTrackEventFrame = nil;

local SuperTrackEventMixin = {};

function SuperTrackEventMixin:OnLoad()
	self:SetScript("OnEvent", SuperTrackEventMixin.OnEvent);
	self:RegisterEvent("SUPER_TRACKING_CHANGED");
	self:RegisterEvent("QUEST_ACCEPTED");
	self:RegisterEvent("QUEST_WATCH_LIST_CHANGED");
	self:RegisterEvent("QUEST_TURNED_IN");

	self:CacheCurrentSuperTrackInfo();
end

function SuperTrackEventMixin:OnEvent(event, ...)
	if event == "SUPER_TRACKING_CHANGED" then
		self:CacheCurrentSuperTrackInfo();
	elseif event == "QUEST_ACCEPTED" then
		local questID = ...;
		self:OnQuestAccepted(questID);
	elseif event == "QUEST_WATCH_LIST_CHANGED" then
		local questID, tracked = ...;
		self:OnQuestWatchChanged(questID, tracked);
	elseif event == "QUEST_TURNED_IN" then
		local questID, xp, money = ...;
		self:OnQuestTurnedIn(questID);
	end
end

function SuperTrackEventMixin:ClearMatchingSuperTrackedQuest(questID)
	if questID == C_SuperTrack.GetSuperTrackedQuestID() then
		C_SuperTrack.SetSuperTrackedQuestID(0);
	end
end

function SuperTrackEventMixin:OnQuestTurnedIn(questID)
	self:ClearMatchingSuperTrackedQuest(questID);
end

function SuperTrackEventMixin:CacheCurrentSuperTrackInfo()
	self.isComplete = nil;
	self.uiMapID = nil;
	self.worldQuests = nil;
	self.worldQuestsElite = nil;
	self.dungeons = nil;
	self.treasures = nil;

	local superTrackedQuestID = C_SuperTrack.GetSuperTrackedQuestID();
	self.superTrackedQuestID = superTrackedQuestID;
	self.superTrackedMapPinType, self.superTrackedMapPinTypeID = C_SuperTrack.GetSuperTrackedMapPin();
	self.superTrackedVignetteGUID = C_SuperTrack.GetSuperTrackedVignette();
	self.superTrackedContentType, self.superTrackedContentID = C_SuperTrack.GetSuperTrackedContent();

	if superTrackedQuestID then
		self.isComplete = C_QuestLog.ReadyForTurnIn(superTrackedQuestID);
		self.uiMapID, self.worldQuests, self.worldQuestsElite, self.dungeons, self.treasures = C_QuestLog.GetQuestAdditionalHighlights(superTrackedQuestID);
	end

	EventRegistry:TriggerEvent("Supertracking.OnChanged", self);
end

function SuperTrackEventMixin:GetSuperTrackedMapPin()
	return self.superTrackedMapPinType, self.superTrackedMapPinTypeID;
end

function SuperTrackEventMixin:GetSuperTrackedQuestID()
	return self.superTrackedQuestID;
end

function SuperTrackEventMixin:GetSuperTrackedVignette()
	return self.superTrackedVignetteGUID;
end

function SuperTrackEventMixin:GetSuperTrackedContent()
	return self.superTrackedContentType, self.superTrackedContentID;
end

function SuperTrackEventMixin:OnQuestAccepted(questID)
	local superTrackType, superTrackID = C_SuperTrack.GetSuperTrackedMapPin();
	if superTrackType == Enum.SuperTrackingMapPinType.QuestOffer and superTrackID == questID then
		C_SuperTrack.ClearSuperTrackedMapPin();
	end

	QuestUtil.CheckAutoSuperTrackQuest(questID);
end

function SuperTrackEventMixin:OnQuestWatchChanged(questID, tracked)
	-- These can be nil, explicitly checking
	if tracked == false then
		self:ClearMatchingSuperTrackedQuest(questID);
	end
end

-- Global query functions that prefer to use a supertrack cache, but will fall back to the Lua binding
local function GetSupertrackedData(supertracker, apiName)
	if supertracker then
		return supertracker[apiName](supertracker);
	end

	return C_SuperTrack[apiName]();
end

function QuestSuperTracking_GetSuperTrackedQuestID(supertracker)
	return GetSupertrackedData(supertracker, "GetSuperTrackedQuestID");
end

function QuestSuperTracking_GetSuperTrackedContent(supertracker)
	return GetSupertrackedData(supertracker, "GetSuperTrackedContent");
end

function QuestSuperTracking_GetSuperTrackedMapPin(supertracker)
	return GetSupertrackedData(supertracker, "GetSuperTrackedMapPin");
end

function QuestSuperTracking_GetSuperTrackedVignette(supertracker)
	return GetSupertrackedData(supertracker, "GetSuperTrackedVignette");
end

function QuestSuperTracking_ShouldHighlightWorldQuests(uiMapID)
	return SuperTrackEventFrame.uiMapID == uiMapID and SuperTrackEventFrame.worldQuests;
end

function QuestSuperTracking_ShouldHighlightWorldQuestsElite(uiMapID)
	return SuperTrackEventFrame.uiMapID == uiMapID and SuperTrackEventFrame.worldQuestsElite;
end

function QuestSuperTracking_ShouldHighlightDungeons(uiMapID)
	return SuperTrackEventFrame.uiMapID == uiMapID and SuperTrackEventFrame.dungeons;
end

function QuestSuperTracking_ShouldHighlightTreasures(uiMapID)
	return SuperTrackEventFrame.uiMapID == uiMapID and SuperTrackEventFrame.treasures;
end

function QuestSuperTracking_Initialize()
	assert(SuperTrackEventFrame == nil);
	SuperTrackEventFrame = Mixin(CreateFrame("FRAME"), SuperTrackEventMixin);
	SuperTrackEventFrame:OnLoad();
end

QuestSuperTracking_Initialize(); -- TODO: Rewrite, use EventRegistry]] },
{ 'Blizzard_FrameXMLUtil\\FadingFrame.lua', [[

function FadingFrame_SetFadeInTime(fadingFrame, time)
	fadingFrame.fadeInTime = time;
end

function FadingFrame_SetHoldTime(fadingFrame, time)
	fadingFrame.holdTime = time;
end

function FadingFrame_SetFadeOutTime(fadingFrame, time)
	fadingFrame.fadeOutTime = time;
end

function FadingFrame_OnLoad(fadingFrame)
	assert(fadingFrame);
	fadingFrame.fadeInTime = 0;
	fadingFrame.holdTime = 0;
	fadingFrame.fadeOutTime = 0;
	fadingFrame:Hide();
end

function FadingFrame_Show(fadingFrame)
	assert(fadingFrame);
	fadingFrame.startTime = GetTime();
	fadingFrame:Show();
end

function FadingFrame_OnUpdate(fadingFrame)
	assert(fadingFrame);
	local elapsed = GetTime() - fadingFrame.startTime;
	local fadeInTime = fadingFrame.fadeInTime;
	if ( elapsed < fadeInTime ) then
		local alpha = (elapsed / fadeInTime);
		fadingFrame:SetAlpha(alpha);
		return;
	end
	local holdTime = fadingFrame.holdTime;
	if ( elapsed < (fadeInTime + holdTime) ) then
		fadingFrame:SetAlpha(1.0);
		return;
	end
	local fadeOutTime = fadingFrame.fadeOutTime;
	if ( elapsed < (fadeInTime + holdTime + fadeOutTime) ) then
		local alpha = 1.0 - ((elapsed - holdTime - fadeInTime) / fadeOutTime);
		fadingFrame:SetAlpha(alpha);
		return;
	end
	fadingFrame:Hide();
end

function FadingFrame_GetRemainingTime(fadingFrame)
	local elapsed = GetTime() - fadingFrame.startTime;
	return (fadingFrame.holdTime + fadingFrame.fadeInTime + fadingFrame.fadeOutTime - elapsed);
end

function FadingFrame_SetTextScaling(fadingFrame, minHeight, maxHeight, scaleUpTime, scaleDownTime)
	fadingFrame.textScalingMinHeight = minHeight;
	fadingFrame.textScalingMaxHeight = maxHeight;
	fadingFrame.textScalingUpTime = scaleUpTime;
	fadingFrame.textScalingDownTime = scaleDownTime;
end

function FadingFrame_GetTextScalingMinHeight(fadingFrame)
	return fadingFrame.textScalingMinHeight;
end

function FadingFrame_StartTextScaling(fadingFrame)
	fadingFrame.textScalingTime = 0;
end

function FadingFrame_StopTextScaling(fadingFrame)
	fadingFrame.textScalingTime = nil;
end

function FadingFrame_CopyTextScalingTime(sourceFadingFrame, targetFadingFrame)
	targetFadingFrame.textScalingTime = sourceFadingFrame.textScalingTime;
end

function FadingFrame_UpdateTextScaling(fadingFrame, elapsedTime)
	if not fadingFrame.textScalingTime then
		return;
	end

	fadingFrame.textScalingTime = fadingFrame.textScalingTime + elapsedTime;

	local minHeight = fadingFrame.textScalingMinHeight;
	local maxHeight = fadingFrame.textScalingMaxHeight;

	if fadingFrame.textScalingTime <= fadingFrame.textScalingUpTime then
		fadingFrame:SetTextHeight(math.floor(minHeight + ((maxHeight - minHeight) * fadingFrame.textScalingTime / fadingFrame.textScalingUpTime)));
	elseif fadingFrame.textScalingTime <= fadingFrame.textScalingDownTime then
		fadingFrame:SetTextHeight(math.floor(maxHeight - ((maxHeight - minHeight) * (fadingFrame.textScalingTime - fadingFrame.textScalingUpTime) / (fadingFrame.textScalingDownTime - fadingFrame.textScalingUpTime))));
	else
		fadingFrame:SetTextHeight(minHeight);
		fadingFrame.textScalingTime = nil;
	end
end

-- Initializes a fading text slot with text scaling animation. This shared
-- animation style originated with the RaidWarning system.
-- You will need to use both FadingFrame_Show and FadingFrame_StartTextScaling
-- You will also need both FadingFrame_UpdateTextScaling and FadingFrame_OnUpdate.
function FadingFrame_InitSlot(fadingFrame, fadeInTime, fadeOutTime, minHeight, maxHeight, scaleUpTime, scaleDownTime)
	FadingFrame_OnLoad(fadingFrame);
	FadingFrame_SetFadeInTime(fadingFrame, fadeInTime);
	FadingFrame_SetHoldTime(fadingFrame, fadeInTime);
	FadingFrame_SetFadeOutTime(fadingFrame, fadeOutTime);
	FadingFrame_SetTextScaling(fadingFrame, minHeight, maxHeight, scaleUpTime, scaleDownTime);
end

-- Copies fade timing only. Use FadingFrame_CopyTextScalingTime separately if needed.
function FadingFrame_CopyTimes(sourceFadingFrame, targetFadingFrame)
	targetFadingFrame.fadeInTime = sourceFadingFrame.fadeInTime;
	targetFadingFrame.holdTime = sourceFadingFrame.holdTime;
	targetFadingFrame.fadeOutTime = sourceFadingFrame.fadeOutTime;
	targetFadingFrame.startTime = sourceFadingFrame.startTime;
end
]] },
{ 'Blizzard_FrameXMLUtil\\Cooldown.lua', [[

function CooldownFrame_Set(self, start, duration, enable, forceShowDrawEdge, modRate)
	if enable and enable ~= 0 and start > 0 and duration > 0 then
		self:SetDrawEdge(not not forceShowDrawEdge);
		self:SetCooldown(start, duration, modRate);
	else
		CooldownFrame_Clear(self);
	end
end

function CooldownFrame_Clear(self)
	self:Clear();
end

function CooldownFrame_SetDisplayAsPercentage(self, percentage, seconds)
	seconds = seconds or 100;	-- Any number, really. Default to 100 if seconds not provided for cleaner percentages.
	self:Pause();
	self:SetCooldown(GetTime() - (seconds * Saturate(percentage)), seconds);
end
]] },
{ 'Blizzard_FrameXMLUtil\\DragonridingUtil.lua', [[
DragonridingUtil = {};

function DragonridingUtil.IsDragonridingUnlocked()
	return C_MountJournal.IsDragonridingUnlocked();
end

function DragonridingUtil.IsDragonridingTreeOpen()
	if not GenericTraitFrame or not GenericTraitFrame:IsShown()then
		return false;
	end

	return GenericTraitFrame:GetConfigID() == C_Traits.GetConfigIDBySystemID(Constants.MountDynamicFlightConsts.TRAIT_SYSTEM_ID);
end

function DragonridingUtil.CanSpendDragonridingGlyphs()
	if not DragonridingUtil.IsDragonridingUnlocked() then
		return false;
	end

	local dragonridingConfigID = C_Traits.GetConfigIDBySystemID(Constants.MountDynamicFlightConsts.TRAIT_SYSTEM_ID);
	if not dragonridingConfigID then
		return false;
	end
	
	local excludeStagedChanges = false;
	local treeCurrencies = C_Traits.GetTreeCurrencyInfo(dragonridingConfigID, Constants.MountDynamicFlightConsts.TREE_ID, excludeStagedChanges);
	if #treeCurrencies <= 0 then
		return false;
	end

	local unspentGlyphCount = treeCurrencies[1].quantity;
	local hasUnspentDragonridingGlyphs = unspentGlyphCount > 0;
	if not hasUnspentDragonridingGlyphs then
		return false;
	end

	-- We have unspent glyphs, but can we actually purchase something?
	local dragonridingNodeIDs = C_Traits.GetTreeNodes(Constants.MountDynamicFlightConsts.TREE_ID);
	for _, nodeID in ipairs(dragonridingNodeIDs) do
		local nodeCosts = C_Traits.GetNodeCost(dragonridingConfigID, nodeID);
		local canAffordNode = (#nodeCosts == 0) or (unspentGlyphCount >= nodeCosts[1].amount);
		if canAffordNode then
			-- Some nodes give you multiple choices and let you pick one, let's see if you can purchase any of them
			local nodeInfo = C_Traits.GetNodeInfo(dragonridingConfigID, nodeID);
			for _, entryID in ipairs(nodeInfo.entryIDs) do
				if C_Traits.CanPurchaseRank(dragonridingConfigID, nodeID, entryID) then
					-- We can spend our glyphs on something!
					return true;
				end
			end
		end
	end

	return false;
end
]] },
{ 'Blizzard_FrameXMLUtil\\Mainline\\MinimapUtil.lua', [[
MinimapUtil = {};

local MINIMAP_FILTER_SETTINGS_ENTRY = {
	[Enum.MinimapTrackingFilter.AccountCompletedQuests] = "PROXY_ACCOUNT_COMPLETED_QUEST_FILTERING",
	[Enum.MinimapTrackingFilter.TrivialQuests] = "PROXY_TRIVIAL_QUEST_FILTERING",
};

local function HasSettingsEntry(filterID)
	return MINIMAP_FILTER_SETTINGS_ENTRY[filterID] ~= nil;
end

local function SetSettingsEntry(filterID, selected)
    local settingsEntry = MINIMAP_FILTER_SETTINGS_ENTRY[filterID];
	if not settingsEntry or not Settings.GetSetting(settingsEntry) then
		return;
	end

	Settings.SetValue(settingsEntry, selected);
end

function MinimapUtil.GetFilterIndexForFilterID(filterID)
    for filterIndex = 1, C_Minimap.GetNumTrackingTypes() do
        local trackingFilter = C_Minimap.GetTrackingFilter(filterIndex);
        if trackingFilter and trackingFilter.filterID == filterID then
            return filterIndex;
        end
    end
end

function MinimapUtil.SetTrackingFilterByFilterID(filterID, set)
    -- Some filters have dedicated entries in the "Options" panel
    -- In those cases we should go through the Settings system instead to ensure it is properly updated
    if HasSettingsEntry(filterID) then
		SetSettingsEntry(filterID, set);
        return;
	end

    local filterIndex = MinimapUtil.GetFilterIndexForFilterID(filterID);
    if filterIndex then
        C_Minimap.SetTracking(filterIndex, set);
    end
end

function MinimapUtil.SetTrackingFilterByFilterIndex(filterIndex, set)
    local filter = C_Minimap.GetTrackingFilter(filterIndex);
    if filter and filter.filterID and HasSettingsEntry(filter.filterID) then
        SetSettingsEntry(filter.filterID, set);
    end

    C_Minimap.SetTracking(filterIndex, set);
end]] },
{ 'Blizzard_FrameXMLUtil\\AreaPoiUtil.lua', [[
AreaPoiUtil = {};

function AreaPoiUtil.TryShowTooltip(region, anchor, poiInfo, customFn)
	local hasDescription = poiInfo.description and poiInfo.description ~= "";
	local isTimed, hideTimer = C_AreaPoiInfo.IsAreaPOITimed(poiInfo.areaPoiID);
	local showTimer = not poiInfo.forceHideTimer and (poiInfo.secondsLeft or (isTimed and not hideTimer));
	local hasWidgetSet = poiInfo.tooltipWidgetSet ~= nil;

	local hasTooltip = hasDescription or showTimer or hasWidgetSet;
	local addedTooltipLine = false;

	if hasTooltip then
		local tooltip = GetAppropriateTooltip();
		local verticalPadding = nil;

		tooltip:SetOwner(region, anchor);
		if region:HasDisplayName() then
			GameTooltip_SetTitle(tooltip, region:GetDisplayName(), HIGHLIGHT_FONT_COLOR);
			addedTooltipLine = true;
		end

		if hasDescription then
			GameTooltip_AddNormalLine(tooltip, poiInfo.description);
			addedTooltipLine = true;
		end

		if showTimer then
			local secondsLeft = poiInfo.secondsLeft or C_AreaPoiInfo.GetAreaPOISecondsLeft(poiInfo.areaPoiID);
			if secondsLeft and secondsLeft > 0 then
				local timeString = SecondsToTime(secondsLeft);
				timeString = HIGHLIGHT_FONT_COLOR:WrapTextInColorCode(timeString);
				GameTooltip_AddNormalLine(tooltip, MAP_TOOLTIP_TIME_LEFT:format(timeString));
				addedTooltipLine = true;
			end
		end

		if poiInfo.textureKit == "OribosGreatVault" then
			GameTooltip_AddBlankLineToTooltip(tooltip);
			GameTooltip_AddInstructionLine(tooltip, ORIBOS_GREAT_VAULT_POI_TOOLTIP_INSTRUCTIONS, false);
			addedTooltipLine = true;
		end

		if hasWidgetSet then
			local overflow = GameTooltip_AddWidgetSet(tooltip, poiInfo.tooltipWidgetSet, addedTooltipLine and poiInfo.addPaddingAboveTooltipWidgets and 10);
			if overflow then
				verticalPadding = -overflow;
			end
		end

		if poiInfo.textureKit then
			local backdropStyle = GAME_TOOLTIP_TEXTUREKIT_BACKDROP_STYLES[poiInfo.textureKit];
			if (backdropStyle) then
				SharedTooltip_SetBackdropStyle(tooltip, backdropStyle);
			end
		end

		if customFn then
			customFn(tooltip);
		end

		tooltip:Show();

		-- need to set padding after Show or else there will be a flicker
		if verticalPadding then
			tooltip:SetPadding(0, verticalPadding);
		end

		return true;
	end

	return false;
end
]] },
{ 'Blizzard_FrameXMLUtil\\Mainline\\ReputationUtil.lua', [[
ReputationUtil = {};

function ReputationUtil.TryAppendAccountReputationLineToTooltip(tooltip, factionID)
	if not tooltip or not factionID or not C_Reputation.IsAccountWideReputation(factionID) then
		return;
	end

	local wrapText = false;
	GameTooltip_AddColoredLine(tooltip, REPUTATION_TOOLTIP_ACCOUNT_WIDE_LABEL, ACCOUNT_WIDE_FONT_COLOR, wrapText);
end

function ReputationUtil.AddParagonRewardsToTooltip(tooltip, factionID)
	if not C_Reputation.IsFactionParagonForCurrentPlayer(factionID) then
		return;
	end

	local factionStandingtext;
	local factionData = C_Reputation.GetFactionDataByID(factionID);
	local reputationInfo = C_GossipInfo.GetFriendshipReputation(factionID);
	if reputationInfo and reputationInfo.friendshipFactionID > 0 then
		factionStandingtext = reputationInfo.reaction;
	elseif C_Reputation.IsMajorFaction(factionID) then
		factionStandingtext = MAJOR_FACTION_MAX_RENOWN_REACHED;
	else
		local gender = UnitSex("player");
		factionStandingtext = GetText("FACTION_STANDING_LABEL"..factionData.reaction, gender);
	end

	local currentValue, threshold, rewardQuestID, hasRewardPending, tooLowLevelForParagon = C_Reputation.GetFactionParagonInfo(factionID);
	if tooLowLevelForParagon then
		GameTooltip_SetTitle(tooltip, PARAGON_REPUTATION_TOOLTIP_TEXT_LOW_LEVEL, NORMAL_FONT_COLOR);
	else
		GameTooltip_SetTitle(tooltip, factionStandingtext, HIGHLIGHT_FONT_COLOR);

		ReputationUtil.TryAppendAccountReputationLineToTooltip(tooltip, factionID);
		GameTooltip_AddBlankLineToTooltip(tooltip);

		local description = PARAGON_REPUTATION_TOOLTIP_TEXT:format(factionData.name);
		if hasRewardPending then
			local questIndex = C_QuestLog.GetLogIndexForQuestID(rewardQuestID);
			local text = GetQuestLogCompletionText(questIndex);
			if text and text ~= "" then
				description = text;
			end
		end
		GameTooltip_AddNormalLine(tooltip, description);
		if not hasRewardPending and currentValue and threshold then
			local value = mod(currentValue, threshold);
			-- show overflow if reward is pending
			if hasRewardPending then
				value = value + threshold;
			end
			GameTooltip_ShowProgressBar(tooltip, 0, threshold, value, REPUTATION_PROGRESS_FORMAT:format(value, threshold));
		end
		GameTooltip_AddQuestRewardsToTooltip(tooltip, rewardQuestID);
	end
end
]] },
{ 'Blizzard_FrameXMLUtil\\Mainline\\TraitUtil.lua', [[

local traitFramePredicatePairs = {};
local treeIDToCallback = {};

TraitUtil = {};

function TraitUtil.OpenTraitFrame(treeID)
	local treeIDCallback = treeIDToCallback[treeID];
	if treeIDCallback then
		treeIDCallback(treeID);
		return;
	end

	for _i, predicatePair in ipairs(traitFramePredicatePairs) do
		local predicate = predicatePair[1];
		if predicate(treeID) then
			local predicateCallback = predicatePair[2];
			predicateCallback(treeID);
			return;
		end
	end

	GenericTraitUI_LoadUI();
	GenericTraitFrame:SetTreeID(treeID);
	ShowUIPanel(GenericTraitFrame);
end

function TraitUtil.RegisterTraitFrameCallbackByPredicate(predicate, callback)
	table.insert(traitFramePredicatePairs, { predicate, callback });
end

function TraitUtil.RegisterTraitFrameCallbackByTreeID(treeID, callback)
	treeIDToCallback[treeID] = callback;
end

-- Add static registrations below here.

local function CheckForDelvesCompanionTraitFrame(treeID)
	return C_DelvesUI.IsTraitTreeForCompanion(treeID);
end

local function OpenDelvesCompanionTraitFrame()
	ShowUIPanel(DelvesCompanionConfigurationFrame);
end

TraitUtil.RegisterTraitFrameCallbackByPredicate(CheckForDelvesCompanionTraitFrame, OpenDelvesCompanionTraitFrame);
]] },
