	return "/" .. localID;
end

function ChatFrameUtil.RegisterForStickyFocus(frame)
	stickyFocusFrames[frame] = true;
end

function ChatFrameUtil.UnregisterForStickyFocus(frame)
	stickyFocusFrames[frame] = nil;
