function ChatFrameUtil.FlashTabIfNotShown(chatFrame, info, type, chatGroup, chatTarget)
	if ( not chatFrame:IsShown() ) then
		if ( (chatFrame == DEFAULT_CHAT_FRAME and info.flashTabOnGeneral) or (chatFrame ~= DEFAULT_CHAT_FRAME and info.flashTab) ) then
			if ( type == "WHISPER" or type == "BN_WHISPER" ) then	--BN_WHISPER FIXME
				if (not FCFManager_ShouldSuppressMessageFlash(chatFrame, chatGroup, chatTarget) ) then
					FCF_StartAlertFlash(chatFrame);
				end
			end
		end
	end
end

function ChatFrameUtil.GetDecoratedSenderName(event, ...)
	local text, senderName, languageName, channelName, playerName2, specialFlags, zoneChannelID, channelIndex, channelBaseName, languageID, lineID, senderGUID, bnSenderID, isMobile, discordInfo = ...;
	local chatType = string.sub(event, 10);

	if string.find(chatType, "^WHISPER") then
		chatType = "WHISPER";
	end

	if string.find(chatType, "^CHANNEL") then
		chatType = "CHANNEL" .. channelIndex;
	end

	local chatTypeInfo = ChatTypeInfo[chatType];
	local decoratedPlayerName = senderName;

	-- Ambiguate guild chat names
	if Ambiguate then
		if chatType == "GUILD" then
			decoratedPlayerName = Ambiguate(decoratedPlayerName, "guild");
		else
			decoratedPlayerName = Ambiguate(decoratedPlayerName, "none");
		end
	end

	if (discordInfo and discordInfo.userID ~= 0) then
		local shouldShowGlobalName = discordInfo.type == Enum.DiscordDisplayNameType.GlobalName;
		if(discordInfo.globalName and shouldShowGlobalName) then
		-- Names of user from Discord have a fixed color
			return ChatFrameUtil.DiscordNameColorize(discordInfo.globalName);
		end
		senderGUID = discordInfo.lastOnlineGUID;
		decoratedPlayerName = discordInfo.lastOnlineName;
	end

	-- Add timerunning icon when necessary based on player guid
	if senderGUID and C_ChatInfo.IsTimerunningPlayer(senderGUID) then
		decoratedPlayerName = TimerunningUtil.AddSmallIcon(decoratedPlayerName);
	end

	if senderGUID and chatTypeInfo and ChatFrameUtil.ShouldColorChatByClass(chatTypeInfo) and GetPlayerInfoByGUID ~= nil then
		local localizedClass, englishClass, localizedRace, englishRace, sex = GetPlayerInfoByGUID(senderGUID);

		if englishClass then
			local classColor = RAID_CLASS_COLORS[englishClass];

			if classColor then
				decoratedPlayerName = classColor:WrapTextInColorCode(decoratedPlayerName);
			end
		end
	end

	decoratedPlayerName = ChatFrameUtil.ProcessSenderNameFilters(event, decoratedPlayerName, ...);
	return decoratedPlayerName;
end

function ChatFrameUtil.DiscordNameColorize(discordName)
	-- there is probably a better way to do this
	local colorInfo = C_ChatInfo.GetColorForChatType("DISCORD_PLAYER_NAME");
	if(colorInfo) then
		return WrapTextInColorCode(discordName, CreateColor(colorInfo.r, colorInfo.g, colorInfo.b, 1):GenerateHexColor())
	end

	return WrapTextInColorCode(discordName, CreateColor(224, 227, 255, 1):GenerateHexColor());
end

function ChatFrameUtil.GetNameForDiscordMessage(discordInfo)
	-- if we are explictly trying to use globalname, then use that, otherwise try and use the character name first
	if( discordInfo.type ~= Enum.DiscordDisplayNameType.GlobalName ) then
		if ( discordInfo.lastOnlineName and discordInfo.lastOnlineGUID ) then
			local localizedClass, englishClass, localizedRace, englishRace, sex = GetPlayerInfoByGUID(discordInfo.lastOnlineGUID)

			if ( englishClass ) then
				local classColorTable = RAID_CLASS_COLORS[englishClass];
				if ( classColorTable ) then
					return WrapTextInColorCode(discordInfo.lastOnlineName, classColorTable.colorStr)
				end
			end

			return discordInfo.lastOnlineName;
		end
	end

	return ChatFrameUtil.DiscordNameColorize(discordInfo.globalName);
end

function ChatFrameUtil.FormatDiscordMessage(discordInfo, message)
	if discordInfo and discordInfo.fromDiscord then
		local modifiedMessage = message;

		if discordInfo.hasAttachment then
			modifiedMessage = YELLOW_FONT_COLOR:WrapTextInColorCode(DISCORD_MESSAGE_ATTACHMENT).." "..modifiedMessage;
		end

		if discordInfo.hasPoll then
			modifiedMessage = YELLOW_FONT_COLOR:WrapTextInColorCode(DISCORD_MESSAGE_POLL).." "..modifiedMessage;
		end

		if discordInfo.hasEmbed then
			modifiedMessage = YELLOW_FONT_COLOR:WrapTextInColorCode(DISCORD_MESSAGE_EMBED).." "..modifiedMessage;
		end

		if discordInfo.hasSticker then
			modifiedMessage = YELLOW_FONT_COLOR:WrapTextInColorCode(DISCORD_MESSAGE_STICKER).." "..modifiedMessage;
		end

		if discordInfo.hasEmoji then
			modifiedMessage = YELLOW_FONT_COLOR:WrapTextInColorCode(DISCORD_MESSAGE_EMOJI).." "..modifiedMessage;
		end

		if discordInfo.hasForwardedMessage then
			modifiedMessage = YELLOW_FONT_COLOR:WrapTextInColorCode(DISCORD_MESSAGE_FORWARD).." "..discordInfo.forwardedMessage;
		end

		if discordInfo.hasError then
			modifiedMessage = RED_FONT_COLOR:WrapTextInColorCode(DISCORD_MESSAGE_FAILED_TO_SEND);
		end

		return modifiedMessage;
	end

	return message;
end

function GetRandomArgument(...)
	return (select(random(select("#", ...)), ...));
end

function RemoveExtraSpaces(str)
	return string.gsub(str, "     +", "    ");	--Replace all instances of 5+ spaces with only 4 spaces.
end

function RemoveNewlines(str)
	return string.gsub(str, "\n", "");
end

function SecureCmdItemParse(item)
	if ( not item ) then
		return nil, nil, nil;
	end
	local bag, slot = strmatch(item, "^(%d+)%s+(%d+)$");
	if ( not bag ) then
		slot = strmatch(item, "^(%d+)$");
	end
	if ( bag ) then
		item = C_Container.GetContainerItemLink(bag, slot);
	elseif ( slot ) then
		item = GetInventoryItemLink("player", slot);
	end
	return item, bag, slot;
end

function SecureCmdUseItem(name, bag, slot, target)
	if ( bag ) then
		C_Container.UseContainerItem(bag, slot, target);
	elseif ( slot ) then
		UseInventoryItem(slot, target);
	else
		C_Item.UseItemByName(name, target);
	end
end



]] },
}

local _G = _G
local env = setmetatable({}, { __index = _G })
local log = ModernUI_Log or function() end

-- Enum and Constants groups of newer clients that this one lacks read as tables of placeholder numbers
-- inside the shared code, so a lookup table keyed by one does not stop a whole file from loading.
local sentinel = -100000
local function placeholders()
	return setmetatable({}, { __index = function(t, key)
		sentinel = sentinel - 1
		rawset(t, key, sentinel)
		return sentinel
	end })
end
local function softGroups(real)
	return setmetatable({}, { __index = function(t, key)
		local value = real and real[key]
		if value == nil then
			value = placeholders()
		end
		rawset(t, key, value)
		return value
	end })
end
local private = { Enum = true, Constants = true }
rawset(env, "Enum", softGroups(_G.Enum))
rawset(env, "Constants", softGroups(_G.Constants))

for _, source in ipairs(sources) do
	local name, text = source[1], source[2]
	local chunk, err = loadstring(text, "@Interface\\ModernUI\\Blizzard\\" .. name)
	if chunk then
		setfenv(chunk, env)
		local ok, runErr = pcall(chunk, "Blizzard", {})
		if not ok then
			log("ModernUI: Blizzard shared code " .. name .. " stopped part-way: " .. tostring(runErr))
		end
	else
		log("ModernUI: Blizzard shared code " .. name .. " did not compile: " .. tostring(err))
	end
end

local added = 0
for key, value in pairs(env) do
	if not private[key] and rawget(_G, key) == nil then
		_G[key] = value
		added = added + 1
	end
end
_G.ModernUI_BlizzardSharedEnvironment = env
sources = nil
